INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('EvanBacon/crispy/reusable-ui-components', 'community', 'EvanBacon', 'crispy', 'EvanBacon/crispy', 'reusable-ui-components', 0, 0, 57, '2026-03-08T01:57:15.358Z', '2026-03-08T02:04:05.614Z', 'cbd21eb5a4d48659dd06b0175c6c2f3a701b8e3db03105085ec7dd1a7ab2d318', '{"id":"EvanBacon/crispy/reusable-ui-components","name":"reusable-ui-components","description":{"en":"The reusable-ui-components skill provides free UI components for building Expo Router apps, following iOS San Francisco design guidelines and prioritizing native primitives. It benefits developers building cross-platform applications.","zh":"本指南介绍如何构建可复用 UI 组件，用于 Expo Router 应用，遵循 iOS San Francisco 设计指南和液体玻璃美学","ja":"このガイドでは、Expo Router アプリ用の再利用可能な UI コンポーネントを構築する方法を紹介します。iOS San Francisco デザイン ガイドラインと液体グラス エステティクスに基づいています","ko":"본 가이드는 Expo Router 애플리케이션용 재사용 가능한 UI 컴포넌트를 구축하는 방법을介绍합니다. iOS San Francisco 디자인 가이드라인 및 액체 유리 미학을 따릅니다","es":"Componentes UI reutilizables para Expo Router, inspirados en shadcn/ui, Base UI, Radix y Konsta UI, con un enfoque en diseño nativo y caídas elegantes","fr":"Composants UI réutilisables pour Expo Router, inspirés de shadcn/ui, Base UI, Radix et Konsta UI, avec un focus sur la conception native et les retours élégants","de":"Wiederverwendbare UI-Komponenten für Expo Router, inspiriert von shadcn/ui, Base UI, Radix und Konsta UI, mit einem Fokus auf natives Design und elegante Fallbacks","pt":"Componentes UI reutilizáveis para Expo Router inspirados em shadcn/ui, Base UI, Radix e Konsta UI","ru":"Переиспользуемые компоненты UI для Expo Router, вдохновленные shadcn/ui, Base UI, Radix и Konsta UI","ar":"مكونات واجهة المستخدم القابلة لإعادة الاستخدام للطريق Expo مستوحاة من shadcn/ui و Base UI و Radix و Konsta UI"},"seo":{"title":{"en":"reusable-ui-components: Expo Router UI Setup Guide | AI A...","zh":"可复用 UI 组件集成指南 - AIエージェント","ja":"再利用可能なUIコンポーネントのセットアップガイド - AIエージェント","ko":"재사용 가능한 UI 컴포넌트 설정 가이드 - AI 에이전트","es":"Componentes UI reutilizables: Guía de configuración para ...","fr":"Composants UI réutilisables: Guide de démarrage pour Expo...","de":"Wiederverwendbare UI-Komponenten: Einrichtungsleitfaden f...","pt":"Guia de Configuração de Componentes UI Reutilizáveis para...","ru":"ИИ Агенты: Руководство по Созданию Переиспользуемых Компо...","ar":"اداة الذكاء الاصطناعي: دليل إعداد المكونات واجهة المستخدم..."},"description":{"en":"Discover how to build production-quality UI components for Expo Router apps with our reusable-ui-components skill. Get started with native-first and portable...","zh":"学习如何使用可复用 UI 组件构建 Expo Router 应用，包括 iOS San Francisco 设计指南和液体玻璃美学","ja":"Expo Router アプリを構築するために、再利用可能な UI コンポーネントを使用する方法を学びます。iOS San Francisco デザイン ガイドラインと液体グラス エステティクスを含みます","ko":"Expo Router 애플리케이션을 구축하기 위해 재사용 가능한 UI 컴포넌트를 사용하는 방법을 학습하십시오. iOS San Francisco 디자인 가이드ライン 및 액체 유리 미학을 포함합니다","es":"Descubre cómo crear componentes UI portátiles y personalizados para Expo Router con nuestra guía de mejores prácticas","fr":"Découvrez comment créer des composants UI portables et personnalisés pour Expo Router avec notre guide de meilleures pratiques","de":"Erfahren Sie, wie Sie portable und anpassbare UI-Komponenten für Expo Router mit unserem Leitfaden für Best Practices erstellen","pt":"Aprenda a criar componentes UI reutilizáveis de alta qualidade para Expo Router com este guia passo a passo","ru":"Изучите, как создать переиспользуемые компоненты UI высокого качества для Expo Router с помощью этого пошагового руководства","ar":"تعلم كيفية إنشاء مكونات واجهة المستخدم القابلة لإعادة الاستخدام عالية الجودة للطريق Expo باستخدام هذا الدليل الخطوة بخطوة"},"definition":{"en":"reusable-ui-components is a collection of portable UI components inspired by shadcn/ui, Base UI, Radix, and Konsta UI, designed for Expo Router apps with a native-first approach.","zh":"可复用 UI 组件是指可以在多个项目中复用和集成的 UI 组件，具有可移植性和本地优先性","ja":"再利用可能な UI コンポーネントとは、複数のプロジェクトで再利用および統合可能な UI コンポーネントであり、移植性とネイティブ優先性を持つ","ko":"재사용 가능한 UI 컴포넌트는 여러 프로젝트에서 재사용 및 통합할 수 있는 UI 컴포넌트를 말하며, 이식성 및 네이티브 우선성을具有합니다","es":"Componentes UI reutilizables son elementos de interfaz de usuario portátiles y personalizados que se pueden copiar y pegar entre proyectos","fr":"Les composants UI réutilisables sont des éléments d''interface utilisateur portables et personnalisés qui peuvent être copiés et collés entre les projets","de":"Wiederverwendbare UI-Komponenten sind portable und anpassbare Benutzeroberflächenelemente, die zwischen Projekten kopiert und eingefügt werden können","pt":"Componentes UI reutilizáveis são elementos de interface do usuário que podem ser facilmente copiados e reutilizados em diferentes projetos","ru":"Переиспользуемые компоненты UI - это элементы пользовательского интерфейса, которые можно легко копировать и повторно использовать в разных проектах","ar":"المكونات القابلة لإعادة الاستخدام واجهة المستخدم هي عناصر واجهة المستخدم التي يمكن نسخها بسهولة وإعادة استخدامها في مشاريع مختلفة"},"features":{"en":["Portable & Copy-Paste Ready components for easy project integration","Native-First design approach with graceful fallbacks for cross-platform compatibility","Inspired by popular UI libraries such as shadcn/ui, Base UI, Radix, and Konsta UI","Follows iOS San Francisco design guidelines with liquid glass aesthetics","Prioritizes native primitives for optimal performance and user experience"],"zh":["遵循 iOS San Francisco 设计指南","液体玻璃美学","本地优先性","可移植性","支持 Expo Router 应用"],"ja":["iOS San Francisco デザイン ガイドラインに基づく","液体グラス エステティクス","ネイティブ優先性","移植性","Expo Router アプリをサポート"],"ko":["iOS San Francisco 디자인 가이드라인을 따름","액체 유리 미학","네이티브 우선성","이식성","Expo Router 애플리케이션을 지원"],"es":["Diseño inspirado en shadcn/ui, Base UI, Radix y Konsta UI","Enfoque en diseño nativo con caídas elegantes","Componentes portátiles y copiables entre proyectos","Compatibilidad con Expo Router","Estilo de diseño iOS San Francisco con estética de vidrio líquido"],"fr":["Conception inspirée de shadcn/ui, Base UI, Radix et Konsta UI","Focus sur la conception native avec des retours élégants","Composants portables et copiables entre les projets","Compatibilité avec Expo Router","Style de conception iOS San Francisco avec une esthétique de verre liquide"],"de":["Design inspiriert von shadcn/ui, Base UI, Radix und Konsta UI","Fokus auf natives Design mit eleganten Fallbacks","Komponenten sind portabel und zwischen Projekten kopierbar","Kompatibilität mit Expo Router","Designstil iOS San Francisco mit einer Ästhetik aus flüssigem Glas"],"pt":["Componentes inspirados em shadcn/ui, Base UI, Radix e Konsta UI","Seguem as diretrizes de design do iOS San Francisco com estética de vidro líquido","Priorizam primitivos nativos com fallbacks elegantes","São portáteis e prontos para copiar e colar entre projetos"],"ru":["Компоненты, вдохновленные shadcn/ui, Base UI, Radix и Konsta UI","Следуют руководящим принципам дизайна iOS San Francisco с эстетикой жидкого стекла","Отдают приоритет родным примитивам с элегантными fallbacks","Являются портативными и готовыми для копирования и вставки между проектами"],"ar":["المكونات المستوحاة من shadcn/ui و Base UI و Radix و Konsta UI","تتبع إرشادات التصميم الخاصة بآيفون سان فرانسيسكو مع جمالية الزجاج السائل","تؤمن الأولوية للمكونات الأصلية مع عمليات سقوط لطيفة","تكون قابلة للنقل وجاهزة للنسخ واللصق بين المشاريع"]},"keywords":{"en":["how to use reusable-ui-components","reusable-ui-components alternative","reusable-ui-components setup guide","what is reusable-ui-components","reusable-ui-components vs shadcn/ui","reusable-ui-components install for Expo Router"],"zh":["可复用 UI 组件","Expo Router","iOS San Francisco 设计指南","液体玻璃美学","本地优先性","可移植性","AIエージェント","UI 组件集成"],"ja":["再利用可能な UI コンポーネント","Expo Router","iOS San Francisco デザイン ガイドライン","液体グラス エステティクス","ネイティブ優先性","移植性","AIエージェント","UI コンポーネント統合"],"ko":["재사용 가능한 UI 컴포넌트","Expo Router","iOS San Francisco 디자인 가이드라인","액체 유리 미학","네이티브 우선성","이식성","AI 에이전트","UI 컴포넌트 통합"],"es":["componentes UI reutilizables","Expo Router","diseño nativo","caídas elegantes","shadcn/ui","Base UI","Radix","Konsta UI","iOS San Francisco","vidrio líquido"],"fr":["composants UI réutilisables","Expo Router","conception native","retours élégants","shadcn/ui","Base UI","Radix","Konsta UI","iOS San Francisco","verre liquide"],"de":["wiederverwendbare UI-Komponenten","Expo Router","natives Design","elegante Fallbacks","shadcn/ui","Base UI","Radix","Konsta UI","iOS San Francisco","flüssiges Glas"],"pt":["componentes ui reutilizáveis","expo router","shadcn/ui","base ui","radix","konsta ui","ios san francisco design","liquid glass aesthetics","primitivos nativos","fallbacks elegantes"],"ru":["переиспользуемые компоненты ui","expo router","shadcn/ui","base ui","radix","konsta ui","дизайн ios san francisco","эстетика жидкого стекла","родные примитивы","элегантные fallbacks"],"ar":["مكونات واجهة المستخدم القابلة لإعادة الاستخدام","الطريق إكسبو","shadcn/ui","بايس يو آي","راديوكس","كونستا يو آي","تصميم آيفون سان فرانسيسكو","جمالية الزجاج السائل","المكونات الأصلية","عمليات السقوط اللطيفة"]}},"owner":"EvanBacon","repo":"crispy","repoPath":"EvanBacon/crispy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.358Z","topics":[],"category":"community","skillMd":{"name":"reusable-ui-components","description":"Guidelines for creating reusable, portable UI components with native-first design, compound patterns, and accessibility","bodyPreview":"# Creating Reusable UI Components for Expo Router\n\nThis guide covers building production-quality, portable UI components inspired by shadcn/ui, Base UI, Radix, and Konsta UI. Components follow iOS San Francisco design guidelines with liquid glass aesthetics and prioritize native primitives with graceful fallbacks.\n\n## Philosophy\n\n### Core Principles\n\n1. **Portable & Copy-Paste Ready** - Components should be self-contained and easy to copy between projects\n2. **Native-First** - Always check for E","body":"# Creating Reusable UI Components for Expo Router\n\nThis guide covers building production-quality, portable UI components inspired by shadcn/ui, Base UI, Radix, and Konsta UI. Components follow iOS San Francisco design guidelines with liquid glass aesthetics and prioritize native primitives with graceful fallbacks.\n\n## Philosophy\n\n### Core Principles\n\n1. **Portable & Copy-Paste Ready** - Components should be self-contained and easy to copy between projects\n2. **Native-First** - Always check for Expo Router primitives before building custom solutions\n3. **iOS Design Language** - Use San Francisco style guide as the baseline for all platforms\n4. **Compound Components** - Break complex components into composable sub-components\n5. **CSS Variables for Customization** - Use design tokens for theming, not hardcoded values\n6. **Accessibility Built-In** - Keyboard handling, safe areas, and screen reader support by default\n\n### Inspiration Sources\n\n| Library | Learn From |\n|---------|-----------|\n| **shadcn/ui** | Component structure, copy-paste architecture |\n| **Radix UI** | Compound component patterns, accessibility primitives |\n| **Base UI** | Headless component APIs, composition patterns |\n| **Konsta UI** | iOS liquid glass aesthetics, platform-adaptive styling |\n\n## Component File Structure\n\n```\nsrc/components/ui/\n├── button.tsx          # Default (shared) implementation\n├── button.ios.tsx      # iOS-specific overrides (optional)\n├── button.web.tsx      # Web-specific overrides (optional)\n└── button.android.tsx  # Android-specific overrides (optional)\n```\n\n**Metro Resolution Priority:**\n1. `.ios.tsx` / `.android.tsx` / `.web.tsx` (platform-specific)\n2. `.native.tsx` (iOS + Android)\n3. `.tsx` (fallback for all platforms)\n\n## Design Tokens & CSS Variables\n\n### Global Theme Variables\n\nDefine customizable design tokens in `src/global.css`:\n\n```css\n@import \"tailwindcss/theme.css\" layer(theme);\n@import \"tailwindcss/preflight.css\" layer(base);\n@import \"tailwindcss/utilities.css\";\n\n/* Import Apple system colors */\n@import \"./css/sf.css\";\n\n@layer theme {\n  @theme {\n    /* Typography Scale */\n    --font-sans: system-ui;\n    --font-mono: ui-monospace;\n    --font-rounded: ui-rounded;\n\n    /* Component Tokens */\n    --component-radius: 12px;\n    --component-radius-lg: 16px;\n    --component-radius-full: 9999px;\n\n    /* Spacing Scale */\n    --spacing-xs: 4px;\n    --spacing-sm: 8px;\n    --spacing-md: 12px;\n    --spacing-lg: 16px;\n    --spacing-xl: 24px;\n\n    /* Animation */\n    --transition-fast: 150ms;\n    --transition-normal: 200ms;\n    --transition-slow: 300ms;\n  }\n}\n\n/* Platform-specific overrides */\n@media ios {\n  :root {\n    --font-sans: system-ui;\n    --font-rounded: ui-rounded;\n    --component-radius: 10px;\n  }\n}\n\n@media android {\n  :root {\n    --font-sans: normal;\n    --font-rounded: normal;\n    --component-radius: 8px;\n  }\n}\n```\n\n### Apple System Colors\n\nCreate platform-adaptive colors in `src/css/sf.css`:\n\n```css\n@layer base {\n  html {\n    color-scheme: light dark;\n  }\n}\n\n:root {\n  /* Primary Colors */\n  --sf-blue: light-dark(rgb(0 122 255), rgb(10 132 255));\n  --sf-green: light-dark(rgb(52 199 89), rgb(48 209 89));\n  --sf-red: light-dark(rgb(255 59 48), rgb(255 69 58));\n  --sf-orange: light-dark(rgb(255 149 0), rgb(255 159 10));\n  --sf-yellow: light-dark(rgb(255 204 0), rgb(255 214 10));\n  --sf-purple: light-dark(rgb(175 82 222), rgb(191 90 242));\n  --sf-pink: light-dark(rgb(255 45 85), rgb(255 55 95));\n\n  /* Gray Scale */\n  --sf-gray: light-dark(rgb(142 142 147), rgb(142 142 147));\n  --sf-gray-2: light-dark(rgb(174 174 178), rgb(99 99 102));\n  --sf-gray-3: light-dark(rgb(199 199 204), rgb(72 72 74));\n  --sf-gray-4: light-dark(rgb(209 209 214), rgb(58 58 60));\n  --sf-gray-5: light-dark(rgb(229 229 234), rgb(44 44 46));\n  --sf-gray-6: light-dark(rgb(242 242 247), rgb(28 28 30));\n\n  /* Text Colors */\n  --sf-text: light-dark(rgb(0 0 0), rgb(255 255 255));\n  --sf-text-2: light-dark(rgb(60 60 67 / 0.6), rgb(235 235 245 / 0.6));\n  --sf-text-3: light-dark(rgb(60 60 67 / 0.3), rgb(235 235 245 / 0.3));\n  --sf-text-placeholder: light-dark(rgb(60 60 67 / 0.3), rgb(235 235 245 / 0.3));\n\n  /* Background Colors */\n  --sf-bg: light-dark(rgb(255 255 255), rgb(0 0 0));\n  --sf-bg-2: light-dark(rgb(242 242 247), rgb(28 28 30));\n  --sf-grouped-bg: light-dark(rgb(242 242 247), rgb(0 0 0));\n  --sf-grouped-bg-2: light-dark(rgb(255 255 255), rgb(28 28 30));\n\n  /* Border & Fill */\n  --sf-border: light-dark(rgb(60 60 67 / 0.12), rgb(84 84 88 / 0.65));\n  --sf-fill: light-dark(rgb(120 120 128 / 0.2), rgb(120 120 128 / 0.32));\n\n  /* Link Color */\n  --sf-link: var(--sf-blue);\n}\n\n/* iOS: Use native platform colors */\n@media ios {\n  :root {\n    --sf-blue: platformColor(systemBlue);\n    --sf-green: platformColor(systemGreen);\n    --sf-red: platformColor(systemRed);\n    --sf-orange: platformColor(systemOrange);\n    --sf-yellow: platformColor(systemYellow);\n    --sf-purple: platformColor(systemPurple);\n    --sf-pink: platformColor(systemPink);\n    --sf-gray: platformColor(systemGray);\n    --sf-gray-2: platformColor(systemGray2);\n    --sf-gray-3: platformColor(systemGray3);\n    --sf-gray-4: platformColor(systemGray4);\n    --sf-gray-5: platformColor(systemGray5);\n    --sf-gray-6: platformColor(systemGray6);\n    --sf-text: platformColor(label);\n    --sf-text-2: platformColor(secondaryLabel);\n    --sf-text-3: platformColor(tertiaryLabel);\n    --sf-text-placeholder: platformColor(placeholderText);\n    --sf-bg: platformColor(systemBackground);\n    --sf-bg-2: platformColor(secondarySystemBackground);\n    --sf-grouped-bg: platformColor(systemGroupedBackground);\n    --sf-grouped-bg-2: platformColor(secondarySystemGroupedBackground);\n    --sf-border: platformColor(separator);\n    --sf-fill: platformColor(tertiarySystemFill);\n    --sf-link: platformColor(link);\n  }\n}\n\n/* Register as Tailwind theme colors */\n@layer theme {\n  @theme {\n    --color-sf-blue: var(--sf-blue);\n    --color-sf-green: var(--sf-green);\n    --color-sf-red: var(--sf-red);\n    --color-sf-orange: var(--sf-orange);\n    --color-sf-yellow: var(--sf-yellow);\n    --color-sf-purple: var(--sf-purple);\n    --color-sf-pink: var(--sf-pink);\n    --color-sf-gray: var(--sf-gray);\n    --color-sf-gray-2: var(--sf-gray-2);\n    --color-sf-gray-3: var(--sf-gray-3);\n    --color-sf-gray-4: var(--sf-gray-4);\n    --color-sf-gray-5: var(--sf-gray-5);\n    --color-sf-gray-6: var(--sf-gray-6);\n    --color-sf-text: var(--sf-text);\n    --color-sf-text-2: var(--sf-text-2);\n    --color-sf-text-3: var(--sf-text-3);\n    --color-sf-text-placeholder: var(--sf-text-placeholder);\n    --color-sf-bg: var(--sf-bg);\n    --color-sf-bg-2: var(--sf-bg-2);\n    --color-sf-grouped-bg: var(--sf-grouped-bg);\n    --color-sf-grouped-bg-2: var(--sf-grouped-bg-2);\n    --color-sf-border: var(--sf-border);\n    --color-sf-fill: var(--sf-fill);\n    --color-sf-link: var(--sf-link);\n  }\n}\n```\n\n### Accessing CSS Variables in JavaScript\n\n```tsx\nimport { useCSSVariable } from \"@/tw\";\n\nfunction MyComponent() {\n  const primaryColor = useCSSVariable(\"--sf-blue\");\n  const borderColor = useCSSVariable(\"--sf-border\");\n\n  return (\n    <View style={{ borderColor }}>\n      <Text style={{ color: primaryColor }}>Hello</Text>\n    </View>\n  );\n}\n```\n\n## Compound Component Pattern\n\nUse compound components for complex, multi-element UI. This provides flexibility while maintaining cohesive behavior.\n\n### Template Structure\n\n```tsx\n\"use client\";\n\nimport React, { createContext, use } from \"react\";\nimport { View, Text, Pressable } from \"@/tw\";\nimport { cn } from \"@/lib/utils\";\nimport type { ViewProps, TextProps } from \"react-native\";\n\n// 1. Define Context for shared state\ninterface ComponentContextValue {\n  variant: \"default\" | \"outline\" | \"ghost\";\n  size: \"sm\" | \"md\" | \"lg\";\n  disabled?: boolean;\n}\n\nconst ComponentContext = createContext<ComponentContextValue | null>(null);\n\nfunction useComponentContext() {\n  const context = use(ComponentContext);\n  if (!context) {\n    throw new Error(\"Component parts must be used within Component.Root\");\n  }\n  return context;\n}\n\n// 2. Root component provides context\ninterface RootProps extends ViewProps {\n  variant?: ComponentContextValue[\"variant\"];\n  size?: ComponentContextValue[\"size\"];\n  disabled?: boolean;\n}\n\nfunction Root({\n  variant = \"default\",\n  size = \"md\",\n  disabled,\n  children,\n  className,\n  ...props\n}: RootProps) {\n  return (\n    <ComponentContext value={{ variant, size, disabled }}>\n      <View\n        {...props}\n        className={cn(\n          \"flex-row items-center\",\n          disabled && \"opacity-50\",\n          className\n        )}\n      >\n        {children}\n      </View>\n    </ComponentContext>\n  );\n}\n\n// 3. Sub-components consume context\nfunction Label({ className, ...props }: TextProps) {\n  const { size } = useComponentContext();\n\n  return (\n    <Text\n      {...props}\n      className={cn(\n        \"text-sf-text\",\n        size === \"sm\" && \"text-sm\",\n        size === \"md\" && \"text-base\",\n        size === \"lg\" && \"text-lg\",\n        className\n      )}\n    />\n  );\n}\n\nfunction Icon({ className, ...props }: ViewProps) {\n  const { size } = useComponentContext();\n\n  const sizeClass = {\n    sm: \"w-4 h-4\",\n    md: \"w-5 h-5\",\n    lg: \"w-6 h-6\",\n  }[size];\n\n  return (\n    <View {...props} className={cn(sizeClass, className)} />\n  );\n}\n\n// 4. Export as compound component\nexport const Component = {\n  Root,\n  Label,\n  Icon,\n};\n\n// 5. Convenience export for simple usage\nexport function SimpleComponent(props: RootProps & { label: string }) {\n  const { label, ...rootProps } = props;\n  return (\n    <Component.Root {...rootProps}>\n      <Component.Label>{label}</Component.Label>\n    </Component.Root>\n  );\n}\n```\n\n## Native-First Component Development\n\n### Check for Expo Router Primitives First\n\nBefore building custom components, check if Expo Router or Expo provides a native primitive:\n\n| Component Need | Check First |\n|----------------|-------------|\n| Navigation Stack | `expo-router` Stack |\n| Tab Navigation | `expo-router` Tabs |\n| Modals/Sheets | `presentation: \"modal\"` or `presentation: \"formSheet\"` |\n| Links | `expo-router` Link |\n| Icons | `expo-symbols` (SF Symbols) |\n| Date Picker | `@react-native-community/datetimepicker` |\n| Segmented Control | `@react-native-segmented-control/segmented-control` |\n| Blur Effects | `expo-blur` or `expo-glass-effect` |\n| Haptics | `expo-haptics` |\n| Safe Areas | `react-native-safe-area-context` |\n\n### Platform Detection\n\n```tsx\n// Check current platform\nif (process.env.EXPO_OS === \"ios\") {\n  // iOS-specific behavior\n} else if (process.env.EXPO_OS === \"android\") {\n  // Android-specific behavior\n} else if (process.env.EXPO_OS === \"web\") {\n  // Web-specific behavior\n}\n\n// Check for specific features\nimport { isLiquidGlassAvailable } from \"expo-glass-effect\";\nconst GLASS = isLiquidGlassAvailable(); // iOS 26+ liquid glass\n```\n\n### Platform-Specific File Example: Switch\n\n**switch.tsx** (default - re-exports native):\n```tsx\nexport { Switch, type SwitchProps } from \"react-native\";\n```\n\n**switch.web.tsx** (web - iOS-styled custom):\n```tsx\n\"use client\";\n\nimport { useState, useRef, useEffect } from \"react\";\nimport {\n  View,\n  Animated,\n  PanResponder,\n  StyleSheet,\n  Pressable,\n} from \"react-native\";\n\nexport type SwitchProps = {\n  value?: boolean;\n  onValueChange?: (value: boolean) => void;\n  disabled?: boolean;\n  thumbColor?: string;\n  trackColor?: { true: string; false: string };\n  ios_backgroundColor?: string;\n};\n\nexport function Switch({\n  value = false,\n  onValueChange,\n  disabled = false,\n  thumbColor = \"#fff\",\n  trackColor = { true: \"#34C759\", false: \"#E9E9EA\" },\n  ios_backgroundColor,\n}: SwitchProps) {\n  const [isOn, setIsOn] = useState(value);\n  const animatedValue = useRef(new Animated.Value(value ? 1 : 0)).current;\n\n  useEffect(() => {\n    setIsOn(value);\n    Animated.spring(animatedValue, {\n      toValue: value ? 1 : 0,\n      useNativeDriver: false,\n      friction: 8,\n      tension: 40,\n    }).start();\n  }, [value, animatedValue]);\n\n  const toggle = () => {\n    if (disabled) return;\n    const newValue = !isOn;\n    setIsOn(newValue);\n    onValueChange?.(newValue);\n  };\n\n  const translateX = animatedValue.interpolate({\n    inputRange: [0, 1],\n    outputRange: [2, 22],\n  });\n\n  const bgColor = animatedValue.interpolate({\n    inputRange: [0, 1],\n    outputRange: [\n      ios_backgroundColor || trackColor.false,\n      trackColor.true,\n    ],\n  });\n\n  return (\n    <Pressable onPress={toggle} disabled={disabled}>\n      <Animated.View\n        style={[\n          styles.track,\n          { backgroundColor: bgColor },\n          disabled && styles.disabled,\n        ]}\n      >\n        <Animated.View\n          style={[\n            styles.thumb,\n            { backgroundColor: thumbColor, transform: [{ translateX }] },\n          ]}\n        />\n      </Animated.View>\n    </Pressable>\n  );\n}\n\nconst styles = StyleSheet.create({\n  track: {\n    width: 51,\n    height: 31,\n    borderRadius: 15.5,\n    justifyContent: \"center\",\n  },\n  thumb: {\n    width: 27,\n    height: 27,\n    borderRadius: 13.5,\n    shadowColor: \"#000\",\n    shadowOffset: { width: 0, height: 2 },\n    shadowOpacity: 0.2,\n    shadowRadius: 2,\n    elevation: 2,\n  },\n  disabled: {\n    opacity: 0.5,\n  },\n});\n```\n\n## Accessibility Patterns\n\n### Keyboard Avoidance\n\nFor forms with text input, proper keyboard handling is critical:\n\n```tsx\nimport {\n  useReanimatedKeyboardAnimation,\n  useKeyboardHandler,\n} from \"react-native-keyboard-controller\";\nimport { useAnimatedStyle } from \"react-native-reanimated\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\n\nfunction KeyboardAwareForm({ children }: { children: React.ReactNode }) {\n  const { bottom } = useSafeAreaInsets();\n  const { height, progress } = useReanimatedKeyboardAnimation();\n\n  const animatedStyle = useAnimatedStyle(() => ({\n    paddingBottom: Math.max(bottom, Math.abs(height.value)),\n  }));\n\n  return (\n    <Animated.View style={[{ flex: 1 }, animatedStyle]}>\n      {children}\n    </Animated.View>\n  );\n}\n```\n\n### Safe Area Handling\n\nAlways account for safe areas on notched devices:\n\n```tsx\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\n\nfunction SafeContainer({ children }: { children: React.ReactNode }) {\n  const { top, bottom, left, right } = useSafeAreaInsets();\n\n  return (\n    <View\n      style={{\n        flex: 1,\n        paddingTop: top,\n        paddingBottom: bottom,\n        paddingLeft: left,\n        paddingRight: right,\n      }}\n    >\n      {children}\n    </View>\n  );\n}\n```\n\n### Form Accessibility Pattern\n\n```tsx\nimport { View, Text, TextInput } from \"@/tw\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { KeyboardAwareScrollView } from \"react-native-keyboard-controller\";\n\ninterface FormFieldProps {\n  label: string;\n  hint?: string;\n  error?: string;\n  children: React.ReactNode;\n}\n\nfunction FormField({ label, hint, error, children }: FormFieldProps) {\n  return (\n    <View className=\"gap-1\">\n      <Text\n        className=\"text-sf-text-2 text-sm font-medium\"\n        accessibilityRole=\"text\"\n      >\n        {label}\n      </Text>\n      {children}\n      {hint && !error && (\n        <Text className=\"text-sf-text-3 text-xs\">{hint}</Text>\n      )}\n      {error && (\n        <Text\n          className=\"text-sf-red text-xs\"\n          accessibilityRole=\"alert\"\n        >\n          {error}\n        </Text>\n      )}\n    </View>\n  );\n}\n\nfunction AccessibleForm() {\n  const { bottom } = useSafeAreaInsets();\n\n  return (\n    <KeyboardAwareScrollView\n      contentContainerStyle={{\n        padding: 16,\n        paddingBottom: bottom + 16,\n        gap: 16,\n      }}\n      keyboardShouldPersistTaps=\"handled\"\n    >\n      <FormField label=\"Email\" hint=\"We''ll never share your email\">\n        <TextInput\n          className=\"bg-sf-fill rounded-xl px-4 py-3 text-sf-text\"\n          placeholder=\"you@example.com\"\n          keyboardType=\"email-address\"\n          autoCapitalize=\"none\"\n          autoComplete=\"email\"\n          textContentType=\"emailAddress\"\n          accessibilityLabel=\"Email address\"\n        />\n      </FormField>\n\n      <FormField label=\"Password\">\n        <TextInput\n          className=\"bg-sf-fill rounded-xl px-4 py-3 text-sf-text\"\n          placeholder=\"••••••••\"\n          secureTextEntry\n          autoComplete=\"password\"\n          textContentType=\"password\"\n          accessibilityLabel=\"Password\"\n        />\n      </FormField>\n    </KeyboardAwareScrollView>\n  );\n}\n```\n\n## iOS Liquid Glass Styling\n\n### Detecting Liquid Glass Support\n\n```tsx\nimport { isLiquidGlassAvailable } from \"expo-glass-effect\";\n\nconst GLASS = isLiquidGlassAvailable();\n\nconst HEADER_OPTIONS = GLASS\n  ? {\n      headerTransparent: true,\n      headerShadowVisible: false,\n      headerBlurEffect: \"none\",\n    }\n  : {\n      headerTransparent: true,\n      headerBlurEffect: \"systemChromeMaterial\",\n      headerShadowVisible: true,\n    };\n```\n\n### Tab Bar with Glass Effect\n\n```tsx\nimport { BlurView } from \"expo-blur\";\n\nfunction GlassTabBarBackground() {\n  return (\n    <BlurView\n      intensity={100}\n      tint=\"systemChromeMaterial\"\n      style={StyleSheet.absoluteFill}\n    />\n  );\n}\n\n// Usage in Tabs\nconst TAB_OPTIONS =\n  process.env.EXPO_OS === \"ios\"\n    ? {\n        tabBarBackground: GlassTabBarBackground,\n        tabBarStyle: { position: \"absolute\" },\n      }\n    : {};\n```\n\n### Glass Card Component\n\n```tsx\nimport { BlurView } from \"expo-blur\";\nimport { View } from \"@/tw\";\nimport { cn } from \"@/lib/utils\";\n\ninterface GlassCardProps extends React.ComponentProps<typeof View> {\n  intensity?: number;\n}\n\nfunction GlassCard({\n  intensity = 50,\n  className,\n  children,\n  ...props\n}: GlassCardProps) {\n  if (process.env.EXPO_OS !== \"ios\") {\n    // Fallback for non-iOS\n    return (\n      <View\n        {...props}\n        className={cn(\n          \"bg-sf-bg-2/80 rounded-2xl overflow-hidden\",\n          className\n        )}\n      >\n        {children}\n      </View>\n    );\n  }\n\n  return (\n    <View\n      {...props}\n      className={cn(\"rounded-2xl overflow-hidden\", className)}\n    >\n      <BlurView\n        intensity={intensity}\n        tint=\"systemChromeMaterial\"\n        style={StyleSheet.absoluteFill}\n      />\n      <View className=\"relative\">{children}</View>\n    </View>\n  );\n}\n```\n\n## Form Components Pattern\n\nThe `Form` compound component demonstrates all principles together:\n\n```tsx\n\"use client\";\n\nimport React, { createContext, use } from \"react\";\nimport { View, Text, TextInput, ScrollView, TouchableHighlight } from \"@/tw\";\nimport { useSafeAreaInsets } from \"react-native-safe-area-context\";\nimport { cn } from \"@/lib/utils\";\nimport { useCSSVariable } from \"@/tw\";\n\n// Context for form styling\nconst FormContext = createContext<{\n  listStyle: \"grouped\" | \"inset\";\n  sheet?: boolean;\n}>({ listStyle: \"inset\" });\n\n// List wrapper with pull-to-refresh\nfunction List({\n  children,\n  listStyle = \"inset\",\n  sheet,\n  ...props\n}: React.ComponentProps<typeof ScrollView> & {\n  listStyle?: \"grouped\" | \"inset\";\n  sheet?: boolean;\n}) {\n  const { bottom } = useSafeAreaInsets();\n\n  return (\n    <FormContext value={{ listStyle, sheet }}>\n      <ScrollView\n        contentContainerStyle={{ paddingVertical: 16, gap: 24 }}\n        contentInsetAdjustmentBehavior=\"automatic\"\n        scrollIndicatorInsets={{ bottom }}\n        className={cn(\n          sheet ? \"bg-transparent\" : \"bg-sf-grouped-bg\",\n          props.className\n        )}\n        {...props}\n      >\n        {children}\n      </ScrollView>\n    </FormContext>\n  );\n}\n\n// Section groups related items\nfunction Section({\n  children,\n  title,\n  footer,\n  ...props\n}: React.ComponentProps<typeof View> & {\n  title?: string;\n  footer?: string;\n}) {\n  const { listStyle, sheet } = use(FormContext);\n  const isInset = listStyle === \"inset\";\n\n  return (\n    <View style={{ paddingHorizontal: isInset ? 16 : 0 }} {...props}>\n      {title && (\n        <Text className=\"uppercase text-sf-text-2 text-sm px-5 pb-2\">\n          {title}\n        </Text>\n      )}\n      <View\n        className={cn(\n          sheet ? \"bg-sf-bg-2\" : \"bg-sf-grouped-bg-2\",\n          isInset ? \"rounded-xl overflow-hidden\" : \"border-y border-sf-border\"\n        )}\n      >\n        {React.Children.map(children, (child, index) => (\n          <>\n            {child}\n            {index < React.Children.count(children) - 1 && (\n              <View className=\"border-b border-sf-border ml-4\" />\n            )}\n          </>\n        ))}\n      </View>\n      {footer && (\n        <Text className=\"text-sf-text-2 text-sm px-5 pt-2\">{footer}</Text>\n      )}\n    </View>\n  );\n}\n\n// Individual form item with optional navigation\nfunction Item({\n  children,\n  onPress,\n  href,\n  ...props\n}: React.ComponentProps<typeof View> & {\n  onPress?: () => void;\n  href?: string;\n}) {\n  const underlayColor = useCSSVariable(\"--sf-gray-4\");\n\n  const content = (\n    <View className=\"flex-row items-center px-4 py-3 min-h-[44px]\" {...props}>\n      {children}\n    </View>\n  );\n\n  if (!onPress && !href) return content;\n\n  return (\n    <TouchableHighlight\n      onPress={onPress}\n      underlayColor={underlayColor}\n      className=\"web:hover:bg-sf-fill web:transition-colors\"\n    >\n      {content}\n    </TouchableHighlight>\n  );\n}\n\n// Text label\nfunction Label({ className, ...props }: React.ComponentProps<typeof Text>) {\n  return (\n    <Text\n      {...props}\n      className={cn(\"text-sf-text text-base flex-1\", className)}\n    />\n  );\n}\n\n// Hint/value on the right\nfunction Hint({ className, ...props }: React.ComponentProps<typeof Text>) {\n  return (\n    <Text\n      {...props}\n      className={cn(\"text-sf-text-2 text-base\", className)}\n    />\n  );\n}\n\n// Export compound component\nexport const Form = {\n  List,\n  Section,\n  Item,\n  Label,\n  Hint,\n};\n```\n\n### Usage\n\n```tsx\n<Form.List>\n  <Form.Section title=\"Account\" footer=\"Your account settings\">\n    <Form.Item href=\"/profile\">\n      <Form.Label>Profile</Form.Label>\n      <Form.Hint>John Doe</Form.Hint>\n      <ChevronRight />\n    </Form.Item>\n    <Form.Item href=\"/email\">\n      <Form.Label>Email</Form.Label>\n      <Form.Hint>john@example.com</Form.Hint>\n      <ChevronRight />\n    </Form.Item>\n  </Form.Section>\n\n  <Form.Section title=\"Preferences\">\n    <Form.Item>\n      <Form.Label>Dark Mode</Form.Label>\n      <Switch value={darkMode} onValueChange={setDarkMode} />\n    </Form.Item>\n  </Form.Section>\n</Form.List>\n```\n\n## Haptic Feedback\n\n### Platform-Safe Haptics\n\n**lib/haptics.ts** (native):\n```tsx\nimport * as Haptics from \"expo-haptics\";\n\nexport const haptics = {\n  light: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light),\n  medium: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Medium),\n  heavy: () => Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Heavy),\n  success: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Success),\n  warning: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Warning),\n  error: () => Haptics.notificationAsync(Haptics.NotificationFeedbackType.Error),\n  selection: () => Haptics.selectionAsync(),\n};\n```\n\n**lib/haptics.web.ts** (web - no-op):\n```tsx\nexport const haptics = {\n  light: () => {},\n  medium: () => {},\n  heavy: () => {},\n  success: () => {},\n  warning: () => {},\n  error: () => {},\n  selection: () => {},\n};\n```\n\n### Usage in Components\n\n```tsx\nimport { haptics } from \"@/lib/haptics\";\n\nfunction HapticButton({ onPress, children }) {\n  const handlePress = () => {\n    haptics.light();\n    onPress?.();\n  };\n\n  return <Pressable onPress={handlePress}>{children}</Pressable>;\n}\n```\n\n## Icon System\n\n### SF Symbol Icons with Fallbacks\n\n```tsx\nimport { SymbolView, SymbolWeight } from \"expo-symbols\";\nimport { MaterialIcons } from \"@expo/vector-icons\";\n\n// Map SF Symbol names to Material Icons\nconst ICON_MAPPING: Record<string, string> = {\n  \"house.fill\": \"home\",\n  \"gear\": \"settings\",\n  \"person.fill\": \"person\",\n  \"magnifyingglass\": \"search\",\n  \"chevron.right\": \"chevron_right\",\n};\n\ninterface IconProps {\n  name: string;\n  size?: number;\n  color?: string;\n  weight?: SymbolWeight;\n}\n\nexport function Icon({ name, size = 24, color, weight }: IconProps) {\n  if (process.env.EXPO_OS === \"ios\") {\n    return (\n      <SymbolView\n        name={name}\n        size={size}\n        tintColor={color}\n        weight={weight}\n      />\n    );\n  }\n\n  const materialName = ICON_MAPPING[name] || name;\n  return <MaterialIcons name={materialName} size={size} color={color} />;\n}\n```\n\n## Component Checklist\n\nWhen creating a new component, ensure:\n\n- [ ] **Portable**: Self-contained, minimal external dependencies\n- [ ] **Typed**: Full TypeScript types for props\n- [ ] **Themed**: Uses CSS variables for colors, not hardcoded values\n- [ ] **Accessible**: Proper accessibility roles and labels\n- [ ] **Keyboard-aware**: Handles keyboard avoidance for inputs\n- [ ] **Safe area-aware**: Respects device safe areas\n- [ ] **Platform-adaptive**: Uses native primitives where available\n- [ ] **Compound structure**: Complex components use compound pattern\n- [ ] **Haptic feedback**: Provides tactile feedback on iOS\n- [ ] **Dark mode**: Supports light and dark color schemes\n- [ ] **Display name**: Set `displayName` in dev for debugging\n\n```tsx\nif (__DEV__) {\n  MyComponent.displayName = \"MyComponent\";\n}\n```\n\n## Dependencies Reference\n\n| Package | Purpose |\n|---------|---------|\n| `react-native-css` | CSS runtime for React Native |\n| `nativewind` | Metro transformer for Tailwind |\n| `tailwindcss` | Utility-first CSS |\n| `@tailwindcss/postcss` | PostCSS plugin for Tailwind v4 |\n| `tailwind-merge` | Merge Tailwind classes safely |\n| `clsx` | Conditional class names |\n| `react-native-safe-area-context` | Safe area handling |\n| `react-native-keyboard-controller` | Keyboard animations |\n| `react-native-reanimated` | Gesture animations |\n| `expo-haptics` | Haptic feedback |\n| `expo-symbols` | SF Symbols |\n| `expo-blur` | Blur effects |\n| `expo-glass-effect` | iOS 26 liquid glass |\n| `@bacons/apple-colors` | Native iOS colors |\n"},"lastSynced":"2026-03-08T02:04:05.614Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing native iOS San Francisco design-inspired UI components for cross-platform Expo Router apps.","zh":"非常适合需要原生iOS San Francisco设计启发的UI组件的前端代理，用于跨平台Expo Router应用。","ja":"クロスプラットフォームのExpo Routerアプリケーション向けに、ネイティブiOS San FranciscoデザインをインスパイアしたUIコンポーネントを必要とするフロントエンドエージェントに最適です。","ko":"크로스 플랫폼 Expo Router 애플리케이션을 위한 네이티브 iOS San Francisco 디자인을启发한 UI 컴포넌트가 필요한 프런트엔드 에이전트에게 최적입니다.","es":"Perfecto para Agentes Frontend que necesitan componentes de interfaz de usuario nativos de iOS con diseño inspirado en San Francisco para aplicaciones de Expo Router multiplataforma.","fr":"Parfait pour les agents Frontend ayant besoin de composants d''interface utilisateur natifs iOS avec une conception inspirée de San Francisco pour les applications Expo Router multiplateformes.","de":"Perfekt für Frontend-Agents, die native iOS-San Francisco-Design-inspirierte Benutzeroberflächenkomponenten für cross-plattform Expo Router-Anwendungen benötigen.","pt":"Perfeito para Agentes Frontend que precisam de componentes de UI inspirados no design San Francisco do iOS para aplicativos cross-platform do Expo Router.","ru":"Идеально подходит для агентов Frontend, которым необходимы компоненты UI с дизайном San Francisco от iOS для кроссплатформенных приложений Expo Router.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى مكونات واجهة المستخدم ذات تصميم سان فرانسيسكو الأصلي من iOS لتطبيقات Expo Router متعددة المنصات."},"recommendation":{"en":"Empowers agents to build production-quality, portable UI components with liquid glass aesthetics, prioritizing native primitives and graceful fallbacks, utilizing libraries like Expo Router and following iOS San Francisco design guidelines.","zh":"赋予代理构建生产质量、可移植的UI组件的能力，具有液态玻璃美学，优先考虑原生原语和优雅的回退，利用如Expo Router的库，并遵循iOS San Francisco设计指南。","ja":"エージェントが、液状ガラスの美学を優先し、ネイティブのプリミティブと優雅なフォールバックを重視して、生産品質の、移植可能なUIコンポーネントを構築できるようにします。Expo Routerなどのライブラリを使用し、iOS San Franciscoデザインガイドラインに従います。","ko":"에이전트가 프로덕션 품질의 이식 가능한 UI 컴포넌트를 구축할 수 있도록 강화하여, 액체 유리 미학을 우선하고, 네이티브 원시값과 우아한 폴백을 우선시하며, Expo Router 등의 라이브러리를 사용하고, iOS San Francisco 디자인 가이드라인을 따릅니다.","es":"Habilita a los agentes a crear componentes de interfaz de usuario de calidad de producción, portátiles, con estética de vidrio líquido, priorizando primitivas nativas y fallbacks elegantes, utilizando bibliotecas como Expo Router y siguiendo las pautas de diseño de iOS San Francisco.","fr":"Permet aux agents de créer des composants d''interface utilisateur de qualité de production, portables, avec une esthétique de verre liquide, en donnant la priorité aux primitives natives et aux fallbacks élégants, en utilisant des bibliothèques comme Expo Router et en suivant les directives de conception d''iOS San Francisco.","de":"Ermöglicht es Agenten, produktionsreife, portable Benutzeroberflächenkomponenten mit flüssigem Glasästhetik zu erstellen, native Primitiven und elegante Fallbacks priorisierend, Bibliotheken wie Expo Router nutzend und den iOS-San-Francisco-Designrichtlinien folgend.","pt":"Habilita os agentes a construir componentes de UI de qualidade de produção, portáteis, com estética de vidro líquido, priorizando primitivos nativos e fallbacks elegantes, utilizando bibliotecas como o Expo Router e seguindo as diretrizes de design do iOS San Francisco.","ru":"Наделяет агентов возможностью создавать компоненты UI высокого качества, портативные, с эффектом жидкого стекла, отдающие приоритет родным примитивам и элегантным fallback''ам, используя библиотеки, такие как Expo Router, и следуя руководящим принципам дизайна iOS San Francisco.","ar":"تمكّن العميل من بناء مكونات واجهة المستخدم من نوع الإنتاج، قابلة للنقل، ذات جمالية زجاجية سائلة، وتعطي الأولوية للمكونات الأصلية والتحويلات الرقيقة، مستخدمة مكتبات مثل Expo Router، والمتوافقة مع إرشادات تصميم iOS San Francisco."},"useCases":{"en":["Building reusable UI components for Expo Router apps","Creating cross-platform applications with native iOS design","Implementing liquid glass aesthetics in UI components"],"zh":["为Expo Router应用构建可重用的UI组件","创建具有原生iOS设计的跨平台应用","在UI组件中实现液态玻璃美学"],"ja":["Expo Routerアプリケーションの再利用可能なUIコンポーネントを構築する","ネイティブのiOSデザインを持つクロスプラットフォームアプリケーションを作成する","UIコンポーネントに液状ガラスの美学を実装する"],"ko":["Expo Router 애플리케이션을 위한 재사용 가능한 UI 컴포넌트 구축","네이티브 iOS 디자인을 갖는 크로스 플랫폼 애플리케이션 생성","UI 컴포넌트에 액체 유리 미학 구현"],"es":["Creación de componentes de interfaz de usuario reutilizables para aplicaciones de Expo Router","Creación de aplicaciones multiplataforma con diseño nativo de iOS","Implementación de estética de vidrio líquido en componentes de interfaz de usuario"],"fr":["Création de composants d''interface utilisateur réutilisables pour les applications Expo Router","Création d''applications multiplateformes avec une conception native iOS","Mise en œuvre d''une esthétique de verre liquide dans les composants d''interface utilisateur"],"de":["Erstellung wiederverwendbarer Benutzeroberflächenkomponenten für Expo Router-Anwendungen","Erstellung von cross-plattform Anwendungen mit nativem iOS-Design","Implementierung von flüssiger Glasästhetik in Benutzeroberflächenkomponenten"],"pt":["Construir componentes de UI reutilizáveis para aplicativos do Expo Router","Criar aplicações cross-platform com design nativo do iOS","Implementar estética de vidro líquido em componentes de UI"],"ru":["Создание многократно используемых компонентов UI для приложений Expo Router","Разработка кроссплатформенных приложений с родным дизайном iOS","Реализация эффекта жидкого стекла в компонентах UI"],"ar":["بناء مكونات واجهة المستخدم القابلة لإعادة الاستخدام لتطبيقات Expo Router","إنشاء تطبيقات متعددة المنصات ذات تصميم أصلية من iOS","تنفيذ جمالية الزجاج السائل في مكونات واجهة المستخدم"]},"limitations":{"en":["Requires Expo Router environment","iOS San Francisco design guidelines only","Prioritizes native primitives over custom designs"],"zh":["需要Expo Router环境","仅限iOS San Francisco设计指南","优先考虑原生原语而非自定义设计"],"ja":["Expo Router環境が必要","iOS San Franciscoデザインガイドラインのみ","カスタムデザインよりもネイティブのプリミティブを優先"],"ko":["Expo Router 환경 필요","iOS San Francisco 디자인 가이드라인만 해당","네이티브 원시값을 커스텀 디자인보다 우선"],"es":["Requiere entorno de Expo Router","Solo pautas de diseño de iOS San Francisco","Prioriza primitivas nativas sobre diseños personalizados"],"fr":["Nécessite un environnement Expo Router","Uniquement les directives de conception d''iOS San Francisco","Donne la priorité aux primitives natives plutôt qu''aux conceptions personnalisées"],"de":["Benötigt Expo Router-Umgebung","Nur iOS-San-Francisco-Designrichtlinien","Priorisiert native Primitiven gegenüber benutzerdefinierten Designs"],"pt":["Requer ambiente do Expo Router","Somente diretrizes de design do iOS San Francisco","Prioriza primitivos nativos em relação a designs personalizados"],"ru":["Требуется среда Expo Router","Только руководящие принципы дизайна iOS San Francisco","Отдаёт приоритет родным примитивам над индивидуальными дизайнами"],"ar":["يتطلب بيئة Expo Router","إرشادات تصميم iOS San Francisco فقط","تعطي الأولوية للمكونات الأصلية أكثر من التصميمات المخصصة"]},"version":4},"contentHash":"cbd21eb5a4d48659dd06b0175c6c2f3a701b8e3db03105085ec7dd1a7ab2d318","qualityScore":57}');
