INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('EvanBacon/crispy/reusable-ui-components', 'reusable-ui-components', 'EvanBacon', 'crispy', 'community', 'reusable-ui-components EvanBacon crispy community The reusable-ui-components skill provides free UI components for building Expo Router apps, following iOS San Francisco design guidelines and prioritizing native primitives. It benefits developers building cross-platform applications. 本指南介绍如何构建可复用 UI 组件，用于 Expo Router 应用，遵循 iOS San Francisco 设计指南和液体玻璃美学 このガイドでは、Expo Router アプリ用の再利用可能な UI コンポーネントを構築する方法を紹介します。iOS San Francisco デザイン ガイドラインと液体グラス エステティクスに基づいています 본 가이드는 Expo Router 애플리케이션용 재사용 가능한 UI 컴포넌트를 구축하는 방법을介绍합니다. iOS San Francisco 디자인 가이드라인 및 액체 유리 미학을 따릅니다 Componentes UI reutilizables para Expo Router, inspirados en shadcn/ui, Base UI, Radix y Konsta UI, con un enfoque en diseño nativo y caídas elegantes Composants UI réutilisables pour Expo Router, inspirés de shadcn/ui, Base UI, Radix et Konsta UI, avec un focus sur la conception native et les retours élégants Wiederverwendbare UI-Komponenten für Expo Router, inspiriert von shadcn/ui, Base UI, Radix und Konsta UI, mit einem Fokus auf natives Design und elegante Fallbacks Componentes UI reutilizáveis para Expo Router inspirados em shadcn/ui, Base UI, Radix e Konsta UI Переиспользуемые компоненты UI для Expo Router, вдохновленные shadcn/ui, Base UI, Radix и Konsta UI مكونات واجهة المستخدم القابلة لإعادة الاستخدام للطريق Expo مستوحاة من shadcn/ui و Base UI و Radix و Konsta UI how to use reusable-ui-components reusable-ui-components alternative reusable-ui-components setup guide what is reusable-ui-components reusable-ui-components vs shadcn/ui reusable-ui-components install for Expo Router 可复用 UI 组件 Expo Router iOS San Francisco 设计指南 液体玻璃美学 本地优先性 可移植性 AIエージェント UI 组件集成 Portable & Copy-Paste Ready components for easy project integration Native-First design approach with graceful fallbacks for cross-platform compatibility Inspired by popular UI libraries such as shadcn/ui, Base UI, Radix, and Konsta UI Follows iOS San Francisco design guidelines with liquid glass aesthetics Prioritizes native primitives for optimal performance and user experience reusable-ui-components is a collection of portable UI components inspired by shadcn/ui, Base UI, Radix, and Konsta UI, designed for Expo Router apps with a native-first approach.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bacoco/EvolveSkill/synapse', 'community', 'bacoco', 'EvolveSkill', 'bacoco/EvolveSkill', 'synapse', 0, 0, 57, '2026-03-08T01:57:15.359Z', '2026-03-08T02:04:07.895Z', 'c82136ee0df66a482f6d5dcd71f1ee7dd0af8ebda2a91e3dd6e01a94076cc1b8', '{"id":"bacoco/EvolveSkill/synapse","name":"synapse","description":{"en":"Synapse analyzes Cortex memory, reads PRD files, and detects recurring patterns to automatically create new skills. It benefits developers by streamlining their workflow.","zh":"Synapse 是一种自动技能生成工具，通过分析工作模式和 Cortex 内存来检测重复模式","ja":"Synapse は、作業パターンと Cortex メモリを分析して反復パターンを検出する自動スキル生成ツールです","ko":"Synapse는 작업 패턴과 Cortex 메모리를 분석하여 반복 패턴을检测하는 자동 스킬 생성 도구입니다","es":"Synapse es un generador de habilidades automáticas que analiza tus patrones de trabajo y crea nuevas habilidades. Analiza la memoria de Cortex y lee tus archivos PRD","fr":"Synapse est un générateur de compétences automatiques qui analyse vos modèles de travail et crée de nouvelles compétences. Il analyse la mémoire de Cortex et lit vos fichiers PRD","de":"Synapse ist ein automatischer Fertigkeitsgenerator, der Ihre Arbeitsmuster analysiert und neue Fertigkeiten erstellt. Er analysiert das Cortex-Speicher und liest Ihre PRD-Dateien","pt":"O Synapse é um agente de IA que analisa padrões de trabalho e gera habilidades automaticamente com base em análise de tarefas e memoria do Cortex","ru":"Synapse - это ИИ агент, который анализирует шаблоны работы и автоматически генерирует навыки на основе анализа задач и памяти Cortex","ar":"مرشد Synapse هو وسيط ذكاء اصطناعي يتحليل أنماط العمل ويولد المهارات تلقائيًا بناءً على تحليل المهام وذاكرة Cortex"},"seo":{"title":{"en":"Synapse: Automatic Skill Generator Setup Guide | AI Agent...","zh":"Synapse 设置指南 - 自动技能生成工具","ja":"Synapse 導入ガイド - AIエージェントによる自動スキル生成","ko":"Synapse 설정 가이드 - 자동 스킬 생성 도구","es":"Guía de configuración de Synapse - Generador de habilidad...","fr":"Guide de configuration de Synapse - Générateur de compéte...","de":"Synapse-Setup-Leitfaden - Automatischer Fertigkeitsgenerator","pt":"Guia de Configuração do Synapse - Geração Automática de H...","ru":"ИИ Агент Synapse: Настройка и Применение Автоматической Г...","ar":"إعداد مرشد Synapse - توليد مهارات تلقائي"},"description":{"en":"Unlock the full potential of Synapse, the AI agent skill that analyzes work patterns and generates new skills automatically. Learn how to set it up and get s...","zh":"Synapse 是一种分析工作模式并自动生成所需技能的工具。了解如何设置和使用 Synapse 来提高开发效率","ja":"Synapse は、作業パターンを分析して必要なスキルを自動生成する AI エージェントです。Synapse の設定と使用方法を学び、開発効率を向上させましょう","ko":"Synapse는 작업 패턴을 분석하여 필요한 스킬을 자동으로 생성하는 도구입니다. Synapse 설정 및 사용 방법을 알아보고 개발 효율성을 높여보세요","es":"Aprende a configurar Synapse, el generador de habilidades automáticas que analiza tus patrones de trabajo y crea nuevas habilidades","fr":"Découvrez comment configurer Synapse, le générateur de compétences automatiques qui analyse vos modèles de travail et crée de nouvelles compétences","de":"Erfahren Sie, wie Sie Synapse konfigurieren, den automatischen Fertigkeitsgenerator, der Ihre Arbeitsmuster analysiert und neue Fertigkeiten erstellt","pt":"Aprenda a configurar o Synapse para gerar habilidades automaticamente com base em padrões de trabalho e análise de tarefas","ru":"Узнайте, как настроить Synapse для автоматического создания навыков на основе анализа шаблонов работы и задач","ar":"تعلم كيفية تكوين مرشد Synapse لتوليد المهارات تلقائيًا بناءً على أنماط العمل وتحليل المهام"},"definition":{"en":"Synapse is an automatic skill generator that analyzes work patterns and creates new skills when patterns emerge, utilizing Cortex memory and PRD files.","zh":"Synapse 是一种自动技能生成工具，通过分析工作模式和 Cortex 内存来检测重复模式","ja":"Synapse は、AI エージェントによる自動スキル生成ツールです","ko":"Synapse는 자동 스킬 생성 도구로, 작업 패턴과 Cortex 메모리를 분석하여 반복 패턴을検出합니다","es":"Synapse es un generador de habilidades automáticas que utiliza análisis unificado de múltiples fuentes","fr":"Synapse est un générateur de compétences automatiques qui utilise une analyse unifiée de multiples sources","de":"Synapse ist ein automatischer Fertigkeitsgenerator, der eine einheitliche Analyse von mehreren Quellen verwendet","pt":"O Synapse é um agente de IA que gera habilidades automaticamente com base em análise de tarefas e memoria do Cortex","ru":"Synapse - это ИИ агент, который автоматически генерирует навыки на основе анализа задач и памяти Cortex","ar":"مرشد Synapse هو وسيط ذكاء اصطناعي يولد المهارات تلقائيًا بناءً على تحليل المهام وذاكرة Cortex"},"features":{"en":["Performs unified analysis from multiple sources, including Cortex memory and PRD files","Reads .cortex_log.md and .cortex_status.json files to detect recurring patterns","Analyzes API calls and data to generate new skills automatically","Creates new skills when patterns emerge, streamlining developer workflow","Utilizes Cortex memory analysis to inform skill generation","Supports detection of recurring patterns in tasks and API calls"],"zh":["Cortex 内存分析","重复模式检测","自动技能生成","多源数据分析","API 调用检测"],"ja":["Cortex メモリ分析","反復パターン検出","自動スキル生成","多源データ分析","API 呼び出し検出"],"ko":["Cortex 메모리 분석","반복 패턴 검출","자동 스킬 생성","다중 소스 데이터 분석","API 호출 검출"],"es":["Análisis de memoria de Cortex","Lectura de archivos PRD","Detección de patrones recurrentes","Creación automática de nuevas habilidades","Análisis unificado de múltiples fuentes","Integración con herramientas de desarrollo"],"fr":["Analyse de la mémoire de Cortex","Lecture de fichiers PRD","Détection de modèles récurrents","Création automatique de nouvelles compétences","Analyse unifiée de multiples sources","Intégration avec des outils de développement"],"de":["Cortex-Speicheranalyse","Lesen von PRD-Dateien","Erkennung von wiederkehrenden Mustern","Automatische Erstellung neuer Fertigkeiten","Einheitliche Analyse von mehreren Quellen","Integration mit Entwicklungstools"],"pt":["Análise unificada de múltiplas fontes","Leitura de arquivos `.cortex_log.md` e `.cortex_status.json`","Detecção de padrões recorrentes em chamadas de API e dados","Geração automática de habilidades com base em análise de tarefas","Integração com memoria do Cortex para análise de padrões de trabalho"],"ru":["Унифицированный анализ нескольких источников","Чтение файлов `.cortex_log.md` и `.cortex_status.json`","Обнаружение повторяющихся шаблонов в вызовах API и данных","Автоматическая генерация навыков на основе анализа задач","Интеграция с памятью Cortex для анализа шаблонов работы"],"ar":["التحليل الموحد لمножة المصادر","قراءة الملفات `.cortex_log.md` و `.cortex_status.json`","التحليل الأنماط المتكررة في استدعاءات API والبيانات","توليد المهارات تلقائيًا بناءً على تحليل المهام","التكامل مع ذاكرة Cortex لتحليل أنماط العمل"]},"keywords":{"en":["how to use synapse","what is synapse","synapse alternative","synapse vs cortex","synapse install","synapse setup guide","synapse automatic skill generator","cortex memory analysis","prd file analysis"],"zh":["Synapse","自动技能生成","Cortex 内存分析","重复模式检测","AI 工具","开发效率","自动化开发"],"ja":["Synapse","自動スキル生成","Cortex メモリ分析","反復パターン検出","AI エージェント","開発効率","自動化開発"],"ko":["Synapse","자동 스킬 생성","Cortex 메모리 분석","반복 패턴 검출","AI 에이전트","개발 효율","자동화 개발"],"es":["Synapse","generador de habilidades automáticas","análisis de patrones","desarrollo de software","herramientas de desarrollo","automatización de tareas","análisis unificado","Cortex","PRD"],"fr":["Synapse","générateur de compétences automatiques","analyse de modèles","développement de logiciels","outils de développement","automatisation de tâches","analyse unifiée","Cortex","PRD"],"de":["Synapse","automatischer Fertigkeitsgenerator","Musteranalyse","Softwareentwicklung","Entwicklungstools","Automatisierung von Aufgaben","einheitliche Analyse","Cortex","PRD"],"pt":["Synapse","IA","Geração automática de habilidades","Análise de tarefas","Memoria do Cortex","Desenvolvimento de habilidades","Tecnologias de IA","Ferramentas de desenvolvimento"],"ru":["Synapse","ИИ","Автоматическая генерация навыков","Анализ задач","Память Cortex","Разработка навыков","Технологии ИИ","Инструменты разработки"],"ar":["مرشد Synapse","الذكاء الاصطناعي","توليد المهارات تلقائيًا","تحليل المهام","ذاكرة Cortex","تطوير المهارات","تكنولوجيا الذكاء الاصطناعي","أدوات التطوير"]}},"owner":"bacoco","repo":"EvolveSkill","repoPath":"bacoco/EvolveSkill","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.359Z","topics":[],"category":"community","skillMd":{"name":"synapse","description":"Pattern detection and automatic skill recommendation system. Activates when analyzing Cortex memory files, detecting recurring work patterns, or determining if new skills are needed. Analyzes .cortex_log.md, PRD files, and task lists to identify patterns (API calls, testing, deployment, etc.) appearing 5+ times. Generates Synapse_RECOMMENDATIONS.md with prioritized skill suggestions. Use when optimizing workflows or identifying automation opportunities.","bodyPreview":"# Synapse - Automatic Skill Generator\n\n**Analyzes your work patterns and automatically generates the skills you need.**\n\nSynapse is the brain of the skill ecosystem. It watches Cortex memory, reads your PRD files, analyzes your tasks, and automatically creates new skills when patterns emerge.\n\n## What Synapse Does\n\nSynapse performs unified analysis from multiple sources:\n\n### 1. Cortex Memory Analysis\n- Reads `.cortex_log.md` and `.cortex_status.json`\n- Detects recurring patterns (API calls, dat","body":"# Synapse - Automatic Skill Generator\n\n**Analyzes your work patterns and automatically generates the skills you need.**\n\nSynapse is the brain of the skill ecosystem. It watches Cortex memory, reads your PRD files, analyzes your tasks, and automatically creates new skills when patterns emerge.\n\n## What Synapse Does\n\nSynapse performs unified analysis from multiple sources:\n\n### 1. Cortex Memory Analysis\n- Reads `.cortex_log.md` and `.cortex_status.json`\n- Detects recurring patterns (API calls, data processing, errors, etc.)\n- Identifies patterns that appear ≥ threshold (default: 5 times)\n- Calculates priority based on frequency\n\n### 2. PRD Analysis\n- Scans for PRD files (`*PRD*.md`, `*REQUIREMENTS*.md`, `*ROADMAP*.md`)\n- Extracts tasks and requirements\n- Classifies by domain (api, testing, deployment, etc.)\n- Counts tasks per domain to identify skill needs\n\n### 3. Task Analysis\n- Reads TODO files and task lists\n- Parses checkboxes, numbered lists, bullets\n- Groups related tasks\n- Identifies skill opportunities\n\n## Automatic Skill Generation\n\n**Synapse runs automatically and generates skills without user intervention:**\n\n- **Periodically**: Every 30 minutes via cron (optional)\n- **On git commit**: Via post-commit hook (optional)\n- **When critical patterns detected**: Immediate generation\n\n**Skills are auto-generated when:**\n- Pattern appears ≥ threshold (default: 5 times)\n- Priority is high or critical\n- Skill doesn''t already exist\n\n## How It Works\n\n```\nYou work normally\n        ↓\nCortex traces everything\n        ↓\nSynapse monitors automatically:\n  - Cortex memory (patterns)\n  - PRD files (requirements)\n  - Task lists (TODO)\n        ↓\nDetects patterns >= threshold\n        ↓\nAuto-generates skills if priority >= high:\n  - Creates .claude/skills/[skill-name]/\n  - Generates SKILL.md with progressive disclosure\n  - Creates scripts with Cortex API integration\n  - Records in Cortex memory\n        ↓\nNew skill ready immediately!\n        ↓\nClaude uses it automatically\n```\n\n**No user intervention needed.**\n\n## Priority Levels\n\nSynapse assigns priorities based on frequency and task count:\n\n- **🔴 CRITICAL**: Pattern appears 2+ times/day → Auto-generate immediately\n- **🟠 HIGH**: Pattern appears 1+ times/day → Auto-generate\n- **🟡 MEDIUM**: Pattern appears 3-7 times/week → Monitor\n- **🟢 LOW**: Pattern appears <3 times/week → Monitor\n\nOnly HIGH and CRITICAL priorities trigger automatic generation.\n\n## Output\n\nSynapse generates `Synapse_RECOMMENDATIONS.md` with prioritized skill recommendations:\n\n```markdown\n# Synapse Skill Recommendations\n\n## Summary\n- Total recommendations: 3\n- High priority: 2\n- Medium priority: 1\n\n## Recommended Skills\n\n### 1. 🔴 api-optimizer (CRITICAL)\n**Pattern:** api_call\n**Frequency:** 3.5 times/day (24 total in 7 days)\n**Reason:** Frequent API operations detected\n...\n```\n\nSee [OUTPUT_FORMAT.md](references/OUTPUT_FORMAT.md) for complete output specification.\n\n## Quick Start\n\n### Automatic Mode (Recommended)\n\nRun auto-generator to analyze and generate skills automatically:\n\n```bash\npython .claude/skills/synapse/scripts/auto_skill_generator.py\n```\n\nSkills with HIGH or CRITICAL priority will be generated automatically.\n\n### Analysis Only\n\nGenerate recommendations without auto-creating skills:\n\n```bash\npython .claude/skills/synapse/scripts/synapse_analyzer.py\n```\n\nThis creates `Synapse_RECOMMENDATIONS.md` for manual review.\n\n### Setup Monitoring\n\nAdd to crontab for automatic periodic checks:\n\n```bash\n# Every 30 minutes\n*/30 * * * * /path/to/.claude/skills/synapse/scripts/synapse_auto_watch.sh\n```\n\nOr use as git hook (see [INSTALLATION.md](references/INSTALLATION.md)).\n\n## Integration with Cortex\n\nSynapse and Cortex work together seamlessly:\n\n1. **Cortex traces** your work and records events\n2. **Synapse analyzes** Cortex memory for patterns\n3. **Synapse generates** skills when patterns reach threshold\n4. **New skills use** Cortex API to record their own events\n5. **Pattern detection improves** as more skills contribute data\n\nThis creates a self-improving system where skills emerge from actual usage patterns.\n\n## Generated Skill Structure\n\nSynapse creates skills following best practices:\n\n```\ngenerated-skill/\n├── SKILL.md (with YAML frontmatter)\n├── scripts/\n│   └── main.py (with Cortex API integration)\n└── references/ (if needed)\n```\n\nAll generated skills:\n- ✅ Follow progressive disclosure principles\n- ✅ Include Cortex API integration\n- ✅ Have concise SKILL.md (<200 lines)\n- ✅ Record their own events for future pattern detection\n- ✅ Work with Claude Code, GPT, and Gemini\n\n## Multi-LLM Support\n\nSynapse works with any CLI-based LLM:\n- ✅ **Claude Code**: Native integration\n- ✅ **GPT/Codex**: Reads `Synapse_RECOMMENDATIONS.md`\n- ✅ **Gemini CLI**: Reads `Synapse_RECOMMENDATIONS.md`\n\nSee [MULTI_LLM.md](references/MULTI_LLM.md) for LLM-specific guides.\n\n## Advanced Features\n\n- **Pattern merging**: Combines Cortex + PRD patterns for higher priority\n- **Duplicate detection**: Never generates skills that already exist\n- **Context preservation**: Recommendations include example usage\n- **Custom thresholds**: Configure sensitivity via command-line args\n\nSee [ADVANCED.md](references/ADVANCED.md) for detailed documentation.\n\n## Configuration\n\nCreate `.synapse_config.json` for custom settings:\n\n```json\n{\n  \"analysis\": {\n    \"threshold\": 5,\n    \"window_days\": 7\n  },\n  \"sources\": {\n    \"cortex_memory\": true,\n    \"prd_files\": true,\n    \"task_lists\": true\n  }\n}\n```\n\nSee [CONFIGURATION.md](references/CONFIGURATION.md) for all options.\n\n## References\n\n- **[INSTALLATION.md](references/INSTALLATION.md)** - Setup and git hooks\n- **[MANUAL_USAGE.md](references/MANUAL_USAGE.md)** - Command-line options\n- **[OUTPUT_FORMAT.md](references/OUTPUT_FORMAT.md)** - Recommendation file format\n- **[EXAMPLES.md](references/EXAMPLES.md)** - Real-world skill generation examples\n- **[ADVANCED.md](references/ADVANCED.md)** - Pattern merging, customization\n- **[CONFIGURATION.md](references/CONFIGURATION.md)** - Complete config reference\n- **[MULTI_LLM.md](references/MULTI_LLM.md)** - Using with GPT, Gemini, etc.\n\n## Part of the Ecosystem\n\n**Cortex** → Remembers everything\n**Synapse** → Analyzes and generates\n**Generated skills** → Solve specific problems\n**Skills use Cortex** → Pattern detection improves\n\nSynapse makes the system intelligent and self-improving.\n\n---\n\n*Synapse - The universal skill recommendation and generation engine*\n"},"lastSynced":"2026-03-08T02:04:07.895Z","agentAnalysis":{"suitability":{"en":"Perfect for Developer Agents needing automated skill generation and workflow streamlining.","zh":"非常适合需要自动化技能生成和工作流优化的开发者代理。","ja":"開発者エージェントが自動スキル生成とワークフローの最適化を必要とする場合に最適です。","ko":"자동화된 스킬 생성과 워크플로우 최적화를 필요로 하는 개발자 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Desarrollador que necesitan generación automática de habilidades y optimización de flujo de trabajo.","fr":"Parfait pour les agents de développement nécessitant une génération automatisée de compétences et une optimisation du flux de travail.","de":"Perfekt für Entwickler-Agenten, die eine automatisierte Fähigkeitsgenerierung und eine Optimierung der Arbeitsabläufe benötigen.","pt":"Perfeito para Agentes de Desenvolvedor que precisam de geração de habilidades automatizada e otimização de fluxo de trabalho.","ru":"Идеально для агентов-разработчиков, которым необходима автоматизированная генерация навыков и оптимизация рабочего процесса.","ar":"مثالي للوكلاء المطورين الذين يحتاجون إلى توليد مهارات آلي وتسهيل سير العمل."},"recommendation":{"en":"Empowers agents to analyze Cortex memory, read PRD files, and detect recurring patterns to automatically create new skills, streamlining their workflow and leveraging unified analysis from multiple sources, including `.cortex_log.md` and `.cortex_status.json` files.","zh":"赋予代理分析 Cortex 内存、读取 PRD 文件和检测重复模式的能力，以自动创建新技能，从而优化工作流，并从多个来源（包括 `.cortex_log.md` 和 `.cortex_status.json` 文件）统一分析。","ja":"エージェントに Cortex メモリを分析し、PRD ファイルを読み、繰り返しパターンを検出して新しいスキルを自動的に作成し、ワークフローを最適化し、`.cortex_log.md` と `.cortex_status.json` ファイルを含む複数のソースからの統一分析を利用する力を与えます。","ko":"에이전트가 Cortex 메모리를 분석하고 PRD 파일을 읽고 반복되는 패턴을 감지하여 새로운 스킬을 자동으로 생성하여 워크플로우를 최적화하고 `.cortex_log.md`와 `.cortex_status.json` 파일을 포함한 여러 소스의 통합 분석을 활용할 수 있도록 합니다.","es":"Habilita a los agentes a analizar la memoria de Cortex, leer archivos PRD y detectar patrones recurrentes para crear automáticamente nuevas habilidades, optimizando su flujo de trabajo y aprovechando el análisis unificado de múltiples fuentes, incluyendo archivos `.cortex_log.md` y `.cortex_status.json`.","fr":"Permet aux agents d''analyser la mémoire Cortex, de lire les fichiers PRD et de détecter des modèles récurrents pour créer automatiquement de nouvelles compétences, optimisant ainsi leur flux de travail et exploitant l''analyse unifiée de plusieurs sources, notamment les fichiers `.cortex_log.md` et `.cortex_status.json`.","de":"Ermöglicht es den Agenten, das Cortex-Speicher zu analysieren, PRD-Dateien zu lesen und wiederkehrende Muster zu erkennen, um automatisch neue Fähigkeiten zu erstellen, ihren Arbeitsablauf zu optimieren und eine einheitliche Analyse aus mehreren Quellen zu nutzen, einschließlich `.cortex_log.md`- und `.cortex_status.json`-Dateien.","pt":"Habilita os agentes a analisar a memória do Cortex, ler arquivos PRD e detectar padrões recorrentes para criar novas habilidades automaticamente, otimizando o fluxo de trabalho e aproveitando a análise unificada de múltiplas fontes, incluindo arquivos `.cortex_log.md` e `.cortex_status.json`.","ru":"Наделяет агентов возможностью анализировать память Cortex, читать файлы PRD и обнаруживать повторяющиеся закономерности для автоматического создания новых навыков, оптимизируя рабочий процесс и используя унифицированный анализ из нескольких источников, включая файлы `.cortex_log.md` и `.cortex_status.json`.","ar":"تمكّن الوكلاء من分析 ذاكرة Cortex، وقراءة ملفات PRD، وتحديد الأنماط المتكررة لإنشاء مهارات جديدة تلقائيًا، وتسهيل سير العمل وتفعيل التحليل الموحد من مصادر متعددة، بما في ذلك ملفات `.cortex_log.md` و `.cortex_status.json`."},"useCases":{"en":["Automating skill generation","Analyzing Cortex memory for recurring patterns","Streamlining developer workflows by detecting API call patterns"],"zh":["自动化技能生成","分析 Cortex 内存以检测重复模式","通过检测 API 调用模式来优化开发者工作流"],"ja":["スキルの自動生成","Cortex メモリを分析して繰り返しパターンを検出","API 呼び出しパターンを検出して開発者のワークフローを最適化"],"ko":["스킬 자동 생성","Cortex 메모리를 분석하여 반복되는 패턴을 감지","API 호출 패턴을 감지하여 개발자 워크플로우 최적화"],"es":["Automatización de la generación de habilidades","Análisis de la memoria de Cortex para patrones recurrentes","Optimización de los flujos de trabajo de los desarrolladores mediante la detección de patrones de llamadas a la API"],"fr":["Automatisation de la génération de compétences","Analyse de la mémoire Cortex pour les modèles récurrents","Optimisation des flux de travail des développeurs en détectant les modèles d''appels d''API"],"de":["Automatisierung der Fähigkeitsgenerierung","Analyse des Cortex-Speichers für wiederkehrende Muster","Optimierung der Arbeitsabläufe der Entwickler durch Erkennung von API-Aufrufmustern"],"pt":["Automação da geração de habilidades","Análise da memória do Cortex para padrões recorrentes","Otimização dos fluxos de trabalho dos desenvolvedores detectando padrões de chamadas de API"],"ru":["Автоматизация генерации навыков","Анализ памяти Cortex для повторяющихся закономерностей","Оптимизация рабочих процессов разработчиков путем обнаружения закономерностей вызовов API"],"ar":["أتمتة توليد المهارات","تحليل ذاكرة Cortex للأنماط المتكررة","تسهيل سير العمل للمطورين بواسطة تحديد أنماط呼و API"]},"limitations":{"en":["Requires access to Cortex memory and PRD files","Limited to analyzing specific file formats (`.cortex_log.md` and `.cortex_status.json`)"],"zh":["需要访问 Cortex 内存和 PRD 文件","仅限分析特定文件格式（`.cortex_log.md` 和 `.cortex_status.json`）"],"ja":["Cortex メモリと PRD ファイルへのアクセスが必要","特定のファイル形式（`.cortex_log.md` と `.cortex_status.json`）のみを分析"],"ko":["Cortex 메모리와 PRD 파일에 접근해야 함","특정 파일 형식(`.cortex_log.md`와 `.cortex_status.json`)만 분석"],"es":["Requiere acceso a la memoria de Cortex y archivos PRD","Limitado a analizar formatos de archivo específicos (`.cortex_log.md` y `.cortex_status.json`)"],"fr":["Nécessite un accès à la mémoire Cortex et aux fichiers PRD","Limité à l''analyse de formats de fichiers spécifiques (`.cortex_log.md` et `.cortex_status.json`)"],"de":["Benötigt Zugriff auf das Cortex-Speicher und PRD-Dateien","Begrenzt auf die Analyse spezifischer Dateiformate (`.cortex_log.md` und `.cortex_status.json`)"],"pt":["Requer acesso à memória do Cortex e arquivos PRD","Limitado à análise de formatos de arquivo específicos (`.cortex_log.md` e `.cortex_status.json`)"],"ru":["Требует доступа к памяти Cortex и файлам PRD","Ограничен анализом конкретных форматов файлов (`.cortex_log.md` и `.cortex_status.json`)"],"ar":["يتطلب الوصول إلى ذاكرة Cortex وملفات PRD","محدود bằng تحليل صيغ ملفات معينة (`.cortex_log.md` و `.cortex_status.json`)"]},"version":4},"contentHash":"c82136ee0df66a482f6d5dcd71f1ee7dd0af8ebda2a91e3dd6e01a94076cc1b8","qualityScore":57}');
