INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bacoco/EvolveSkill/synapse', 'synapse', 'bacoco', 'EvolveSkill', 'community', 'synapse bacoco EvolveSkill community Synapse analyzes Cortex memory, reads PRD files, and detects recurring patterns to automatically create new skills. It benefits developers by streamlining their workflow. Synapse 是一种自动技能生成工具，通过分析工作模式和 Cortex 内存来检测重复模式 Synapse は、作業パターンと Cortex メモリを分析して反復パターンを検出する自動スキル生成ツールです Synapse는 작업 패턴과 Cortex 메모리를 분석하여 반복 패턴을检测하는 자동 스킬 생성 도구입니다 Synapse es un generador de habilidades automáticas que analiza tus patrones de trabajo y crea nuevas habilidades. Analiza la memoria de Cortex y lee tus archivos PRD Synapse est un générateur de compétences automatiques qui analyse vos modèles de travail et crée de nouvelles compétences. Il analyse la mémoire de Cortex et lit vos fichiers PRD Synapse ist ein automatischer Fertigkeitsgenerator, der Ihre Arbeitsmuster analysiert und neue Fertigkeiten erstellt. Er analysiert das Cortex-Speicher und liest Ihre PRD-Dateien O Synapse é um agente de IA que analisa padrões de trabalho e gera habilidades automaticamente com base em análise de tarefas e memoria do Cortex Synapse - это ИИ агент, который анализирует шаблоны работы и автоматически генерирует навыки на основе анализа задач и памяти Cortex مرشد Synapse هو وسيط ذكاء اصطناعي يتحليل أنماط العمل ويولد المهارات تلقائيًا بناءً على تحليل المهام وذاكرة Cortex how to use synapse what is synapse synapse alternative synapse vs cortex synapse install synapse setup guide synapse automatic skill generator cortex memory analysis prd file analysis Synapse 自动技能生成 Cortex 内存分析 重复模式检测 AI 工具 开发效率 自动化开发 Performs unified analysis from multiple sources, including Cortex memory and PRD files Reads .cortex_log.md and .cortex_status.json files to detect recurring patterns Analyzes API calls and data to generate new skills automatically Creates new skills when patterns emerge, streamlining developer workflow Utilizes Cortex memory analysis to inform skill generation Supports detection of recurring patterns in tasks and API calls Synapse is an automatic skill generator that analyzes work patterns and creates new skills when patterns emerge, utilizing Cortex memory and PRD files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Obsidian-Owl/floe/tech-debt-review', 'community', 'Obsidian-Owl', 'floe', 'Obsidian-Owl/floe', 'tech-debt-review', 0, 0, 57, '2026-03-08T01:57:15.360Z', '2026-03-08T02:04:10.888Z', '5fcdae1d9da154c36bb727c29d1794a91ed4e48ea9e1bb7c927b36ecd03aaa1e', '{"id":"Obsidian-Owl/floe/tech-debt-review","name":"tech-debt-review","description":{"en":"tech-debt-review automates code reviews for Data Platforms, supporting modes like PR Review and Full Audit. It benefits developers by streamlining the review process.","zh":"tech-debt-review是一款代码审查和技术债务管理工具，支持PR Review、Full Audit和Targeted三种模式","ja":"tech-debt-reviewはコードレビューとテクニカルデット管理ツールで、PR Review、Full Audit、Targetedの3つのモードをサポート","ko":"tech-debt-review는 코드 리뷰 및 기술 부채 관리 도구로 PR Review, Full Audit, Targeted 3가지 모드를 지원합니다","es":"tech-debt-review es una herramienta para identificar y reducir la deuda técnica en proyectos de desarrollo de software, permitiendo una mayor velocidad y escalabilidad","fr":"tech-debt-review est un outil pour identifier et réduire la dette technique dans les projets de développement de logiciels, permettant une plus grande vitesse et une meilleure scalabilité","de":"tech-debt-review ist ein Tool zur Identifizierung und Reduzierung von technischen Schulden in Software-Entwicklungsprojekten, um eine höhere Geschwindigkeit und Skalierbarkeit zu ermöglichen","pt":"O tech-debt-review é uma ferramenta para revisar dívidas técnicas no código, ajudando a melhorar a qualidade do projeto","ru":"ИИ Агент tech-debt-review анализирует технический долг в коде, giúpая улучшить качество проекта","ar":"أداة tech-debt-review تقوم بمراجعة الديون الفنية في الكود وتساعد على تحسين جودة المشروع"},"seo":{"title":{"en":"tech-debt-review: Automated Code Review Setup Guide | AI ...","zh":"tech-debt-review_SETUP GUIDE：代码审查和技术债务管理","ja":"tech-debt-review セットアップガイド：コードレビューとテクニカルデット管理","ko":"tech-debt-review 설정 가이드: 코드 리뷰 및 기술 부채 관리","es":"Guía de configuración de tech-debt-review para agilizar e...","fr":"Guide d''installation de tech-debt-review pour améliorer l...","de":"Einrichtungsleitfaden für tech-debt-review zur Beschleuni...","pt":"Guia de Configuração do tech-debt-review para Desenvolved...","ru":"ИИ Агент tech-debt-review: Руководство по Настройке","ar":"دليل إعداد أداة tech-debt-review للطورين"},"description":{"en":"Discover how tech-debt-review simplifies code audits with commands like /tech-debt-review and /tech-debt-review --all. Get started with automated PR reviews ...","zh":"了解tech-debt-review的功能和用法，优化代码审查和技术债务管理，提高开发效率","ja":"tech-debt-reviewの機能と使い方を学び、コードレビューとテクニカルデット管理を最適化して開発効率を向上させる","ko":"tech-debt-review의 기능과 사용법을 알아보세요. 코드 리뷰 및 기술 부채 관리를 최적화하여 개발 효율성을 높여보세요","es":"Descubre cómo utilizar tech-debt-review para identificar y reducir la deuda técnica en tus proyectos de desarrollo de software","fr":"Découvrez comment utiliser tech-debt-review pour identifier et réduire la dette technique dans vos projets de développement de logiciels","de":"Erfahren Sie, wie Sie tech-debt-review verwenden können, um die technische Schulden in Ihren Software-Entwicklungsprojekten zu identifizieren und zu reduzieren","pt":"Aprenda a usar o tech-debt-review para revisar dívidas técnicas no seu código e melhorar a qualidade do seu projeto","ru":"Используйте ИИ Агент tech-debt-review для анализа технического долга и улучшения качества вашего проекта","ar":"استخدم أداة tech-debt-review لمراجعة الديون الفنية في كودك وتحسين جودة مشروعك"},"definition":{"en":"tech-debt-review is a skill for automating code reviews, providing features like targeted analysis and category-based reviews.","zh":"tech-debt-review是一款AIエージェント工具，用于代码审查和技术债务管理","ja":"tech-debt-reviewはAIエージェントツールで、コードレビューとテクニカルデット管理に使用","ko":"tech-debt-review는 AI 에이전트 도구로 코드 리뷰 및 기술 부채 관리에 사용됩니다","es":"tech-debt-review es una herramienta de revisión de deuda técnica que ayuda a identificar y priorizar problemas de código","fr":"tech-debt-review est un outil de révision de dette technique qui aide à identifier et à prioriser les problèmes de code","de":"tech-debt-review ist ein Tool zur Überprüfung von technischen Schulden, das hilft, Probleme im Code zu identifizieren und zu priorisieren","pt":"O tech-debt-review é uma ferramenta de revisão de dívidas técnicas que ajuda a identificar problemas no código","ru":"ИИ Агент tech-debt-review - это инструмент для анализа технического долга, помогающий выявить проблемы в коде","ar":"أداة tech-debt-review هي أداة لمراجعة الديون الفنية التي تساعد على تحديد المشاكل في الكود"},"features":{"en":["Supports PR Review mode with /tech-debt-review command","Performs Full Audit of entire codebase with /tech-debt-review --all","Enables targeted analysis of specific directories with /tech-debt-review path/to/dir","Allows category-based reviews with /tech-debt-review command","Compares changed files vs main for streamlined reviews"],"zh":["支持PR Review、Full Audit和Targeted三种模式","可以对代码进行审查和分析","支持命令行界面（CLI）","可以指定特定的目录进行分析","支持--all参数进行全量审查"],"ja":["PR Review、Full Audit、Targetedの3つのモードをサポート","コードをレビューおよび分析可能","コマンドラインインターフェイス（CLI）をサポート","特定のディレクトリを分析可能","--allパラメータを使用して全量レビュー可能"],"ko":["PR Review, Full Audit, Targeted 3가지 모드를 지원","코드를 리뷰 및 분석할 수 있습니다","명령줄 인터페이스(CLI)를 지원","특정 디렉토리를 분석할 수 있습니다","--all 매개 변수를 사용하여 전체 리뷰가 가능합니다"],"es":["Revisión de código en tiempo real","Análisis de deuda técnica en proyectos de desarrollo de software","Compatibilidad con varios modos de uso, incluyendo revisión de PR y auditoría completa","Integración con herramientas de desarrollo como CLI","Análisis de código en directorios específicos","Soporte para la identificación de problemas de código y priorización"],"fr":["Révision de code en temps réel","Analyse de la dette technique dans les projets de développement de logiciels","Compatibilité avec plusieurs modes d''utilisation, notamment la révision de PR et l''audit complet","Intégration avec des outils de développement tels que CLI","Analyse de code dans des répertoires spécifiques","Prise en charge de l''identification des problèmes de code et de la priorisation"],"de":["Echtzeit-Code-Überprüfung","Analyse von technischen Schulden in Software-Entwicklungsprojekten","Kompatibilität mit verschiedenen Nutzungsmodi, einschließlich PR-Überprüfung und vollständiger Audit","Integration mit Entwicklungstools wie CLI","Code-Analyse in bestimmten Verzeichnissen","Unterstützung für die Identifizierung von Code-Problemen und Priorisierung"],"pt":["Revisão de dívidas técnicas em código","Análise de mudanças no código em relação ao branch main","Modos de uso: PR Review, Full Audit e Targeted","Suporte a comandos CLI personalizados","Análise de diretórios específicos"],"ru":["Анализ технического долга в коде","Сравнение изменений в коде с веткой main","Режимы использования: PR Review, Full Audit и Targeted","Поддержка пользовательских команд CLI","Анализ конкретных директорий"],"ar":["مراجعة الديون الفنية في الكود","تحليل التغييرات في الكود بالمقارنة مع الفرع الرئيسي","طرق الاستخدام: مراجعة Pull Request، ومراجعة شاملة، ومركزة","دعم أوامر CLI مخصصة","تحليل الدلائل النوعية"]},"keywords":{"en":["how to use tech-debt-review","tech-debt-review setup guide","tech-debt-review alternative","tech-debt-review vs manual code review","automated code review tools","data platform code audit"],"zh":["tech-debt-review","代码审查","技术债务管理","AIエージェント","代码分析","命令行界面","PR Review","Full Audit","Targeted"],"ja":["tech-debt-review","コードレビュー","テクニカルデット管理","AIエージェント","コード分析","コマンドラインインターフェイス","PR Review","Full Audit","Targeted"],"ko":["tech-debt-review","코드 리뷰","기술 부채 관리","AI 에이전트","코드 분석","명령줄 인터페이스","PR Review","Full Audit","Targeted"],"es":["tech-debt-review","herramientas de desarrollo de software","revisión de código","deuda técnica","desarrollo de software ágil","integración con CLI","análisis de código","priorización de problemas de código","Agilidad en el desarrollo de software"],"fr":["tech-debt-review","outils de développement de logiciels","révision de code","dette technique","développement de logiciels agile","intégration avec CLI","analyse de code","priorisation des problèmes de code","Agilité dans le développement de logiciels"],"de":["tech-debt-review","Software-Entwicklungstools","Code-Überprüfung","technische Schulden","agiles Software-Entwickeln","Integration mit CLI","Code-Analyse","Priorisierung von Code-Problemen","Agilität im Software-Entwickeln"],"pt":["tech-debt-review","revisão de dívidas técnicas","análise de código","qualidade de projeto","ferramentas de desenvolvimento","CLI","PR Review","Full Audit","Targeted"],"ru":["tech-debt-review","ИИ Агент","анализ технического долга","анализ кода","качество проекта","инструменты разработки","CLI","PR Review","Full Audit","Targeted"],"ar":["tech-debt-review","أداة الديون الفنية","مراجعة الكود","جودة المشروع","أدوات التطوير","CLI","مراجعة Pull Request","مراجعة شاملة","مركزة"]}},"owner":"Obsidian-Owl","repo":"floe","repoPath":"Obsidian-Owl/floe","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.360Z","topics":[],"category":"community","skillMd":{"name":"tech-debt-review","description":"Comprehensive technical debt analysis with PR and full-audit modes. Use when reviewing code quality before PR, conducting periodic health checks, or investigating maintainability issues.","bodyPreview":"## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding (if not empty).\n\n## Usage Modes\n\n| Mode | Command | Scope | When to Use |\n|------|---------|-------|-------------|\n| **PR Review** | `/tech-debt-review` | Changed files vs main | Before PR (default) |\n| **Full Audit** | `/tech-debt-review --all` | Entire codebase | Periodic health check |\n| **Targeted** | `/tech-debt-review path/to/dir` | Specific directory | Focused analysis |\n| **Category** | `/tech-d","body":"## User Input\n\n```text\n$ARGUMENTS\n```\n\nYou **MUST** consider the user input before proceeding (if not empty).\n\n## Usage Modes\n\n| Mode | Command | Scope | When to Use |\n|------|---------|-------|-------------|\n| **PR Review** | `/tech-debt-review` | Changed files vs main | Before PR (default) |\n| **Full Audit** | `/tech-debt-review --all` | Entire codebase | Periodic health check |\n| **Targeted** | `/tech-debt-review path/to/dir` | Specific directory | Focused analysis |\n| **Category** | `/tech-debt-review --category=deps` | Single category | Quick specific check |\n| **Combined** | `/tech-debt-review --all --category=complexity` | Full audit, one category | Targeted deep dive |\n\n### Category Filter Values\n\n| Category | Agent(s) Invoked | Focus Area |\n|----------|------------------|------------|\n| `complexity` | code-complexity-analyzer | Cyclomatic/cognitive complexity |\n| `dead-code` | dead-code-detector | Unreachable code, unused symbols |\n| `deps` | dependency-debt-analyzer | Outdated/vulnerable dependencies |\n| `docs` | documentation-debt-analyzer | Missing/stale documentation |\n| `testing` | testing-debt-analyzer, test-duplication-detector | Coverage gaps, test quality |\n| `todos` | todo-archaeology | TODO/FIXME/HACK archaeology |\n| `hotspots` | git-hotspot-analyzer | Code churn, change patterns |\n| `performance` | performance-debt-detector | Performance anti-patterns |\n| `architecture` | code-pattern-reviewer | Coupling, cohesion, design smells |\n\n## Goal\n\nPerform a comprehensive technical debt analysis that answers: **What maintenance burden exists in this code?**\n\nThis skill orchestrates **10 specialized agents** in parallel to analyze:\n- Code complexity and maintainability\n- Dead code and unused symbols\n- Dependency health and security\n- Documentation gaps\n- Testing debt\n- TODO/FIXME archaeology\n- Git hotspots and churn\n- Performance anti-patterns\n- Architecture smells\n\nResults are synthesized into a prioritized, actionable report with trend tracking.\n\n## Operating Constraints\n\n**STRICTLY READ-ONLY**: Do **not** modify any files. Output analysis and recommendations.\n\n**PARALLEL EXECUTION**: Launch all applicable agents in a single message for efficiency.\n\n**TREND TRACKING**: Full audits are saved to `.claude/reviews/` for historical comparison.\n\n## Constitution Alignment\n\nThis skill validates adherence to project principles:\n- **Quality**: Maintain high code quality standards\n- **Maintainability**: Keep technical debt manageable\n- **Security**: No known vulnerabilities in dependencies\n\n## Memory Integration\n\n### After Completion (Full Audit Only)\nSave audit findings for trend analysis:\n```bash\n./scripts/memory-save --decisions \"Tech debt audit: Score {score}/100, {critical} critical issues, top areas: {categories}\" --issues \"{LinearIDs}\"\n```\n\n## Execution Steps\n\n### Phase 0: Scope Determination\n\n**You handle this phase directly.**\n\n**Parse user input to determine mode:**\n\n1. **If `--all` flag present**: Full codebase audit\n   ```bash\n   # Get all Python files\n   find packages/ plugins/ -name \"*.py\" -type f 2>/dev/null | wc -l\n   ```\n\n2. **If specific path provided**: Targeted directory\n   ```bash\n   # Verify path exists and count files\n   find <provided-path> -name \"*.py\" -type f 2>/dev/null | wc -l\n   ```\n\n3. **If `--category=<name>` present**: Extract category for filtering\n\n4. **Default (no args)**: Changed files only\n   ```bash\n   # Get changed Python files\n   git diff --name-only main...HEAD | grep ''\\.py$''\n   ```\n\n**Report mode to user:**\n- `--all` mode: \"Running FULL CODEBASE audit on N Python files\"\n- Specific path: \"Analyzing directory: <path> (N files)\"\n- `--category=X`: \"Running single-category analysis: X\"\n- Default: \"Analyzing N files changed vs main\"\n\nIf no files to analyze in default mode, suggest using `--all` for full audit.\n\n### Phase 1: Check for Prior Audits (Trend Tracking)\n\n**Only for `--all` mode:**\n\n```bash\n# Find most recent audit\nls -t .claude/reviews/tech-debt-*.json 2>/dev/null | head -1\n```\n\nIf prior audit exists, load it for trend comparison in Phase 3.\n\n### Phase 2: Parallel Analysis\n\n**Invoke agents IN PARALLEL (single message, multiple Task calls):**\n\nBased on `--category` filter (or all if no filter):\n\n```\n# Haiku agents (fast, single-file analysis)\nTask(todo-archaeology, \"Analyze TODO/FIXME/HACK comments...\nFiles: [list or scope]\nReturn archaeology report with age analysis.\")\n\nTask(documentation-debt-analyzer, \"Analyze documentation gaps...\nFiles: [list or scope]\nReturn documentation debt report.\")\n\nTask(code-complexity-analyzer, \"Analyze code complexity...\nFiles: [list or scope]\nReturn complexity metrics report.\")\n\n# Sonnet agents (cross-file analysis)\nTask(dead-code-detector, \"Detect unreachable and unused code...\nFiles: [list or scope]\nReturn dead code report.\")\n\nTask(dependency-debt-analyzer, \"Analyze dependency health...\nScope: [package dirs]\nReturn dependency health report.\")\n\nTask(testing-debt-analyzer, \"Analyze test coverage and quality gaps...\nFiles: [list or scope]\nReturn testing debt report.\")\n\nTask(git-hotspot-analyzer, \"Analyze git history for hotspots and churn...\nFiles: [list or scope]\nReturn hotspot analysis report.\")\n\nTask(performance-debt-detector, \"Detect performance anti-patterns...\nFiles: [list or scope]\nReturn performance debt report.\")\n\n# Existing agents (reused)\nTask(code-pattern-reviewer, \"Analyze module patterns and architecture...\nFiles: [list or scope]\nReturn architecture pattern report.\")\n\nTask(test-duplication-detector, \"Detect test duplication...\nFiles: [list or scope]\nReturn test duplication report.\")\n```\n\n**Wait for all agents to return.**\n\n### Phase 3: Synthesis\n\n**You handle this phase directly.**\n\n1. **Aggregate findings** from all agent reports\n2. **Classify by severity** using `.claude/skills/tech-debt-review/references/severity-criteria.md`\n3. **Calculate debt score** (0-100, where 100 = no debt):\n   - Start at 100\n   - CRITICAL issues: -10 each (max -40)\n   - HIGH issues: -5 each (max -30)\n   - MEDIUM issues: -2 each (max -20)\n   - LOW issues: -1 each (max -10)\n4. **Prioritize by** Risk x Impact / Effort (see `references/prioritization.md`)\n5. **Compare trends** if prior audit exists\n\n### Phase 4: Persistence (Full Audit Mode Only)\n\n**Only for `--all` mode:**\n\nSave audit snapshot:\n```bash\n# Generate timestamp\nTIMESTAMP=$(date +%Y%m%d-%H%M%S)\n\n# Save audit to .claude/reviews/tech-debt-${TIMESTAMP}.json\n```\n\n**Storage Format:**\n```json\n{\n  \"timestamp\": \"2026-01-22T10:30:00Z\",\n  \"scope\": \"full-audit\",\n  \"branch\": \"main\",\n  \"commit\": \"<git-hash>\",\n  \"debt_score\": 72,\n  \"categories\": {\n    \"complexity\": {\"issues\": 8, \"critical\": 1, \"high\": 2, \"medium\": 3, \"low\": 2},\n    \"dead_code\": {\"issues\": 3, \"critical\": 0, \"high\": 1, \"medium\": 2, \"low\": 0},\n    \"dependencies\": {\"issues\": 5, \"critical\": 2, \"high\": 1, \"medium\": 1, \"low\": 1},\n    \"documentation\": {\"issues\": 7, \"critical\": 0, \"high\": 0, \"medium\": 4, \"low\": 3},\n    \"testing\": {\"issues\": 12, \"critical\": 0, \"high\": 3, \"medium\": 5, \"low\": 4},\n    \"todos\": {\"issues\": 15, \"critical\": 0, \"high\": 2, \"medium\": 8, \"low\": 5},\n    \"hotspots\": {\"issues\": 4, \"critical\": 1, \"high\": 1, \"medium\": 2, \"low\": 0},\n    \"performance\": {\"issues\": 6, \"critical\": 0, \"high\": 2, \"medium\": 3, \"low\": 1},\n    \"architecture\": {\"issues\": 4, \"critical\": 1, \"high\": 1, \"medium\": 1, \"low\": 1}\n  },\n  \"total_issues\": 64,\n  \"critical_issues\": 5,\n  \"remediation_days\": 15\n}\n```\n\n## Output Format\n\n```markdown\n## Technical Debt Review\n\n**Scope**: [PR: 15 files | Full Audit: 234 files | Directory: path/ (45 files)]\n**Debt Score**: 72/100 (Good)\n**Estimated Remediation**: 15 person-days\n**Trend**: [+5 vs last audit | First audit | N/A for PR mode]\n\n---\n\n### Executive Summary\n\n| Category | Issues | Critical | High | Trend |\n|----------|--------|----------|------|-------|\n| Complexity | 8 | 1 | 2 | [arrow] |\n| Dead Code | 3 | 0 | 1 | [arrow] |\n| Dependencies | 5 | 2 | 1 | [arrow] |\n| Documentation | 7 | 0 | 0 | [arrow] |\n| Testing | 12 | 0 | 3 | [arrow] |\n| TODOs | 15 | 0 | 2 | [arrow] |\n| Hotspots | 4 | 1 | 1 | [arrow] |\n| Performance | 6 | 0 | 2 | [arrow] |\n| Architecture | 4 | 1 | 1 | [arrow] |\n\n**Trend Legend**: [up-arrow] worse | [down-arrow] better | [right-arrow] stable | - no prior data\n\n---\n\n### Priority Actions (Fix These First)\n\n| Priority | Issue | Category | File:Line | Impact | Effort |\n|----------|-------|----------|-----------|--------|--------|\n| P0 | CVE-2024-XXXXX in package X | Dependencies | pyproject.toml | Critical | Low |\n| P0 | God class (15+ methods) | Architecture | compiler.py:45 | High | Medium |\n| P1 | 45% test coverage gap | Testing | service.py | High | High |\n| P1 | N+1 query pattern | Performance | repository.py:123 | High | Medium |\n| P2 | TODO from 2024 | TODOs | utils.py:67 | Medium | Low |\n\n---\n\n### Detailed Findings by Category\n\n#### Code Complexity (8 issues)\n\n[Agent report summary]\n\n**Critical/High Issues:**\n- `file.py:123` - Cyclomatic complexity 25 (threshold: 10)\n- `file.py:456` - Cognitive complexity 32 (threshold: 15)\n\n#### Dead Code (3 issues)\n\n[Agent report summary]\n\n#### Dependencies (5 issues)\n\n[Agent report summary]\n\n**Security Vulnerabilities:**\n- CVE-2024-XXXXX in `package==1.2.3` (CRITICAL)\n\n#### Documentation (7 issues)\n\n[Agent report summary]\n\n#### Testing Debt (12 issues)\n\n[Agent report summary]\n\n#### TODO Archaeology (15 issues)\n\n[Agent report summary]\n\n**Oldest TODOs:**\n- `file.py:45` - \"TODO: Fix this\" (18 months old)\n\n#### Git Hotspots (4 issues)\n\n[Agent report summary]\n\n**High Churn Files:**\n- `compiler.py` - 45 changes in 3 months\n\n#### Performance (6 issues)\n\n[Agent report summary]\n\n#### Architecture (4 issues)\n\n[Agent report summary]\n\n---\n\n### Debt Score Calculation\n\n```\nStarting Score: 100\n- Critical Issues (5 x -10): -50 (capped at -40)\n- High Issues (15 x -5): -75 (capped at -30)\n- Medium Issues (27 x -2): -54 (capped at -20)\n- Low Issues (17 x -1): -17 (capped at -10)\n= Final Score: 72/100 (Good)\n```\n\n**Score Interpretation:**\n| Range | Rating | Action |\n|-------|--------|--------|\n| 90-100 | Excellent | Maintain |\n| 75-89 | Good | Address critical issues |\n| 60-74 | Needs Work | Prioritize debt reduction |\n| 40-59 | Poor | Urgent attention needed |\n| 0-39 | Critical | Stop feature work, fix debt |\n\n---\n\n### Recommendations\n\n1. **Immediate** (this PR/sprint):\n   - Fix CVE-2024-XXXXX by upgrading package X\n   - Address P0 architecture issue in compiler.py\n\n2. **Short-term** (next 2-4 sprints):\n   - Increase test coverage on service.py\n   - Refactor N+1 query patterns\n\n3. **Long-term** (roadmap):\n   - Establish complexity budgets\n   - Implement automated debt tracking\n\n---\n\n### Trend Comparison (Full Audit Only)\n\n**Previous Audit**: 2026-01-15\n**Score Change**: 72 -> 72 (stable)\n\n| Category | Previous | Current | Change |\n|----------|----------|---------|--------|\n| Complexity | 6 | 8 | +2 [up-arrow] |\n| Dead Code | 5 | 3 | -2 [down-arrow] |\n| Dependencies | 5 | 5 | 0 [right-arrow] |\n\n**New Issues Since Last Audit**: 4\n**Resolved Issues Since Last Audit**: 2\n\n---\n\n### Next Steps\n\n- [ ] Address P0 issues before PR\n- [ ] Schedule P1 issues for next sprint\n- [ ] Re-run `/tech-debt-review` to verify fixes\n- [ ] Run `/tech-debt-review --all` monthly for trend tracking\n```\n\n## What This Review Checks\n\n### From Specialized Agents\n\n| Agent | Focus | Key Metrics |\n|-------|-------|-------------|\n| code-complexity-analyzer | Complexity metrics | Cyclomatic >10, cognitive >15, nesting >4 |\n| dead-code-detector | Unused code | Unreachable statements, unused imports/functions |\n| dependency-debt-analyzer | Dependency health | CVEs, outdated packages, unused deps |\n| documentation-debt-analyzer | Documentation gaps | Missing docstrings, stale comments |\n| testing-debt-analyzer | Test quality | Coverage gaps, flaky tests, missing assertions |\n| todo-archaeology | TODO analysis | Age, context, linked issues |\n| git-hotspot-analyzer | Code churn | High-change files, risky commits |\n| performance-debt-detector | Performance issues | N+1 queries, sync blocks, memory leaks |\n| code-pattern-reviewer | Architecture | Coupling, cohesion, circular deps |\n| test-duplication-detector | Test duplication | Redundant tests, parametrization opportunities |\n\n### What This Review Does NOT Check\n\n- **Linting/style**: ruff handles this\n- **Type safety**: mypy handles this\n- **Security**: Aikido/bandit handle this (except dependency CVEs)\n- **Runtime bugs**: Testing handles this\n\n## When to Use\n\n| Situation | Recommended Mode |\n|-----------|------------------|\n| Before creating a PR | `/tech-debt-review` (changed files) |\n| Monthly health check | `/tech-debt-review --all` |\n| Investigating slow area | `/tech-debt-review path/to/module --category=performance` |\n| After major refactor | `/tech-debt-review --all` |\n| Quick dependency check | `/tech-debt-review --category=deps` |\n| Onboarding to codebase | `/tech-debt-review --all` |\n\n## Handoff\n\nAfter completing this skill:\n- **Fix P0 issues**: Address critical issues immediately\n- **Track P1 issues**: Create Linear tickets for high-priority debt\n- **Continue workflow**: Run `/sw-verify` before PR to validate all quality gates\n\n## References\n\n- **`references/debt-taxonomy.md`** - Complete debt category definitions\n- **`references/prioritization.md`** - Risk/impact/effort framework\n- **`references/severity-criteria.md`** - Severity classification rules\n"},"lastSynced":"2026-03-08T02:04:10.888Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Review Agents needing automated tech debt analysis for Data Platforms.","zh":"适合需要自动化技术债分析的代码审查代理，尤其用于数据平台。","ja":"コードレビューエージェントが自動化されたテクニカルデット分析をデータプラットフォームで必要とする場合に適しています。","ko":"데이터 플랫폼에서 자동화된 기술 부채 분석이 필요한 코드 리뷰 에이전트에게 적합합니다.","es":"Perfecto para Agentes de Revisión de Código que necesitan un análisis automatizado de deuda técnica para Data Platforms.","fr":"Parfait pour les Agents de Revue de Code ayant besoin d''une analyse automatisée de la dette technique pour les Data Platforms.","de":"Perfekt für Code-Review-Agents, die eine automatisierte Analyse der technischen Schulden für Data Platforms benötigen.","pt":"Perfeito para Agentes de Revisão de Código que precisam de análise de dívida técnica automatizada para Plataformas de Dados.","ru":"Идеально подходит для агентов рассмотрения кода, которым требуется автоматизированный анализ технического долга для платформ данных.","ar":"مثالي لعميل مراجعة الشفرة الذي يحتاج إلى تحليل الديون الفنية الآلي للمنصات البيانية."},"recommendation":{"en":"Empowers agents to streamline code reviews with automated PR reviews, full audits, and targeted analyses, utilizing modes like PR Review and Full Audit, and supporting specific directories and categories, all while integrating with GitHub protocols and JSON file formats.","zh":"赋予代理人通过自动化PR审查、完全审计和有针对性的分析来简化代码审查的能力，利用PR审查和完全审计等模式，并支持特定的目录和类别，同时集成GitHub协议和JSON文件格式。","ja":"エージェントがPRレビューとフルオーディットなどのモードを利用し、特定のディレクトリとカテゴリをサポートしながら、GitHubのプロトコルとJSONファイル形式を統合してコードレビューを簡素化できるようにします。","ko":"에이전트가 PR 리뷰 및 전체 감사를 포함한 모드를 사용하여 코드 리뷰를 간소화할 수 있도록 하며, 특정 디렉토리 및 카테고리를 지원하며, GitHub 프로토콜 및 JSON 파일 형식을 통합합니다.","es":"Habilita a los agentes a optimizar las revisiones de código con revisiones de PR automatizadas, auditorías completas y análisis dirigidos, utilizando modos como Revisión de PR y Auditoría Completa, y soportando directorios y categorías específicas, todo mientras se integra con los protocolos de GitHub y los formatos de archivo JSON.","fr":"Permet aux agents de rationaliser les revues de code avec des revues de PR automatisées, des audits complets et des analyses ciblées, en utilisant des modes tels que Revue de PR et Audit Complet, et en prenant en charge des répertoires et des catégories spécifiques, le tout en s''intégrant aux protocoles GitHub et aux formats de fichiers JSON.","de":"Ermächtigt die Agenten, Code-Reviews mit automatisierten PR-Reviews, vollständigen Audits und gezielten Analysen zu rationalisieren, indem sie Modi wie PR-Review und Vollaudit verwenden und bestimmte Verzeichnisse und Kategorien unterstützen, all dies während der Integration mit GitHub-Protokollen und JSON-Dateiformaten.","pt":"Habilita os agentes a agilizar as revisões de código com revisões de PR automatizadas, auditorias completas e análises direcionadas, utilizando modos como Revisão de PR e Auditoria Completa, e suportando diretórios e categorias específicas, tudo isso enquanto se integra com os protocolos do GitHub e formatos de arquivo JSON.","ru":"Наделяет агентов возможностью оптимизировать проверку кода с помощью автоматизированных проверок PR, полных аудитов и целевых анализов, используя режимы, такие как Проверка PR и Полный аудит, и поддерживая конкретные директории и категории, все это при интеграции с протоколами GitHub и форматами файлов JSON.","ar":"يُمكّن الوكلاء من تسهيل مراجعة الشفرة باستخدام مراجعات PR الآلية والتدقيقات الكاملة والتحليلات المستهدفة، باستخدام أوضاع مثل مراجعة PR والتدقيق الكامل، ودعم المجلدات والفئات المحددة، وكل ذلك أثناء التكامل مع بروتوكولات GitHub وأشكال ملفات JSON."},"useCases":{"en":["Automating PR reviews for changed files","Performing full audits of entire codebases","Conducting targeted analyses of specific directories"],"zh":["自动化更改文件的PR审查","对整个代码库进行完全审计","对特定目录进行有针对性的分析"],"ja":["変更されたファイルのPRレビューを自動化する","全コードベースの完全な監査を実行する","特定のディレクトリに対するターゲット分析を実行する"],"ko":["변경된 파일의 PR 리뷰를 자동화하는 것","전체 코드베이스에 대한 완전한 감사를 수행하는 것","특정 디렉토리에 대한 목표 분석을 수행하는 것"],"es":["Automatizar las revisiones de PR para archivos modificados","Realizar auditorías completas de todo el código","Realizar análisis dirigidos de directorios específicos"],"fr":["Automatiser les revues de PR pour les fichiers modifiés","Effectuer des audits complets de l''ensemble du code","Effectuer des analyses ciblées de répertoires spécifiques"],"de":["Automatisieren von PR-Reviews für geänderte Dateien","Durchführen von vollständigen Audits des gesamten Code","Durchführen von gezielten Analysen bestimmter Verzeichnisse"],"pt":["Automatizar revisões de PR para arquivos alterados","Realizar auditorias completas de código inteiras","Realizar análises direcionadas de diretórios específicos"],"ru":["Автоматизировать проверки PR для измененных файлов","Проводить полные аудиты всего кода","Проводить целевые анализы конкретных директорий"],"ar":["تأتمة مراجعات PR للملفات المعدلة","إجراء تدقيقات كاملة للشفرة الكاملة","إجراء تحليلات مستهدفة للمجلدات المحددة"]},"limitations":{"en":["Requires access to code repository","Limited to Data Platforms","Needs clear directory paths for targeted analysis"],"zh":["需要访问代码仓库","仅限数据平台","需要明确的目录路径以进行有针对性的分析"],"ja":["コードリポジトリへのアクセスが必要","データプラットフォームのみ","ターゲット分析を実行するには明確なディレクトリパスが必要"],"ko":["코드 저장소에 대한 액세스가 필요함","데이터 플랫폼만 해당함","목표 분석을 수행하려면明確한 디렉토리 경로가 필요함"],"es":["Requiere acceso al repositorio de código","Limitado a Data Platforms","Necesita rutas de directorio claras para el análisis dirigido"],"fr":["Nécessite un accès au référentiel de code","Limité aux Data Platforms","Nécessite des chemins de répertoire clairs pour l''analyse ciblée"],"de":["Benötigt Zugriff auf das Code-Repository","Begrenzt auf Data Platforms","Benötigt klare Verzeichnispfade für die gezielte Analyse"],"pt":["Requer acesso ao repositório de código","Limitado a Plataformas de Dados","Necessita de caminhos de diretório claros para análise direcionada"],"ru":["Требует доступа к хранилищу кода","Ограничен платформами данных","Требует четких путей директорий для целевого анализа"],"ar":["يتطلب الوصول إلى مستودع الشفرة","محدود بالمنصات البيانية","يحتاج إلى مسارات مجلد واضحة للتحليل المستهدف"]},"version":4},"contentHash":"5fcdae1d9da154c36bb727c29d1794a91ed4e48ea9e1bb7c927b36ecd03aaa1e","qualityScore":57}');
