INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Obsidian-Owl/floe/tech-debt-review', 'tech-debt-review', 'Obsidian-Owl', 'floe', 'community', 'tech-debt-review Obsidian-Owl floe community tech-debt-review automates code reviews for Data Platforms, supporting modes like PR Review and Full Audit. It benefits developers by streamlining the review process. tech-debt-review是一款代码审查和技术债务管理工具，支持PR Review、Full Audit和Targeted三种模式 tech-debt-reviewはコードレビューとテクニカルデット管理ツールで、PR Review、Full Audit、Targetedの3つのモードをサポート tech-debt-review는 코드 리뷰 및 기술 부채 관리 도구로 PR Review, Full Audit, Targeted 3가지 모드를 지원합니다 tech-debt-review es una herramienta para identificar y reducir la deuda técnica en proyectos de desarrollo de software, permitiendo una mayor velocidad y escalabilidad tech-debt-review est un outil pour identifier et réduire la dette technique dans les projets de développement de logiciels, permettant une plus grande vitesse et une meilleure scalabilité tech-debt-review ist ein Tool zur Identifizierung und Reduzierung von technischen Schulden in Software-Entwicklungsprojekten, um eine höhere Geschwindigkeit und Skalierbarkeit zu ermöglichen O tech-debt-review é uma ferramenta para revisar dívidas técnicas no código, ajudando a melhorar a qualidade do projeto ИИ Агент tech-debt-review анализирует технический долг в коде, giúpая улучшить качество проекта أداة tech-debt-review تقوم بمراجعة الديون الفنية في الكود وتساعد على تحسين جودة المشروع how to use tech-debt-review tech-debt-review setup guide tech-debt-review alternative tech-debt-review vs manual code review automated code review tools data platform code audit tech-debt-review 代码审查 技术债务管理 AIエージェント 代码分析 命令行界面 PR Review Full Audit Targeted Supports PR Review mode with /tech-debt-review command Performs Full Audit of entire codebase with /tech-debt-review --all Enables targeted analysis of specific directories with /tech-debt-review path/to/dir Allows category-based reviews with /tech-debt-review command Compares changed files vs main for streamlined reviews tech-debt-review is a skill for automating code reviews, providing features like targeted analysis and category-based reviews.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AppleLamps/grokify/rate-limit-setup', 'community', 'AppleLamps', 'grokify', 'AppleLamps/grokify', 'rate-limit-setup', 0, 0, 57, '2026-03-08T01:57:15.363Z', '2026-03-08T02:04:16.393Z', '6eb9d679086bad0cbd3958611506de6448a889d84db57fcddd5653dedb81150a', '{"id":"AppleLamps/grokify/rate-limit-setup","name":"rate-limit-setup","description":{"en":"The rate-limit-setup skill implements database-backed rate limiting, limiting 2 premium images per user per 24 hours. It benefits developers by preventing abuse and ensuring fair usage.","zh":"本文介绍了AI工具的率限设置，包括使用数据库进行跟踪和SHA-256哈希用户识别","ja":"AIエージェントのレート制限設定方法を紹介します。データベースを使用したトラッキングとSHA-256ハッシュによるユーザー識別が含まれます","ko":"AI 에이전트의 레이트 제한 설정 방법을 소개합니다. 데이터베이스를 사용한 추적과 SHA-256 해시를 통한 사용자 식별을 포함합니다","es":"El ajuste de límite de velocidad utiliza una tabla de seguimiento de uso para limitar a 2 imágenes premium por usuario cada 24 horas","fr":"La limitation de débit utilise une table de suivi d''utilisation pour limiter à 2 images premium par utilisateur toutes les 24 heures","de":"Die Rate Limitierung verwendet eine Nutzungsnachverfolgungstabelle, um 2 Premium-Bilder pro Benutzer alle 24 Stunden zu begrenzen","pt":"O skill rate-limit-setup permite configurar um limite de taxa para evitar abusos e garantir a estabilidade do sistema. Ele utiliza uma tabela de rastreamento de uso no banco de dados.","ru":"Навык rate-limit-setup позволяет настроить лимит скорости, чтобы предотвратить злоупотребления и обеспечить стабильность системы. Он использует таблицу отслеживания использования в базе данных.","ar":"المهارة rate-limit-setup تسمح بضبط حد معدل الاستجابة لتجنب الإساءة وضمان استقرار النظام. وهي تستخدم جدول تتبع الاستخدام في قاعدة البيانات."},"seo":{"title":{"en":"rate-limit-setup: Database-Backed Rate Limiting Setup Gui...","zh":"AI工具率限设置指南","ja":"AIエージェントのレート制限セットアップガイド","ko":"AI 에이전트 레이트 제한 설정 가이드","es":"Configuración de límite de velocidad para Agentes de IA","fr":"Guide de configuration de la limitation de débit pour les...","de":"Rate Limit Setup für künstliche Intelligenz-Tools","pt":"Configuração de Limite de Taxa: Guia de Implantação","ru":"Настройка лимита скорости: Руководство по установке ИИ Аг...","ar":"إعداد حد معدل الاستجابة: دليل الإعداد للأدوات الذكية"},"description":{"en":"Discover how to set up rate limiting with database-backed implementation. Learn to limit premium image generation and more with this AI agent skill.","zh":"了解如何设置AI工具的率限，实现高效的API管理","ja":"AIエージェントのレート制限を設定する方法について学びます","ko":"AI 에이전트의 레이트 제한을 설정하는 방법을 알아보세요","es":"Aprende a configurar límites de velocidad para Agentes de IA con nuestra guía paso a paso","fr":"Découvrez comment configurer la limitation de débit pour les outils d''IA avec notre guide étape par étape","de":"Erfahren Sie, wie Sie die Rate Limitierung für künstliche Intelligenz-Tools mit unserer Schritt-für-Schritt-Anleitung konfigurieren","pt":"Aprenda a configurar o limite de taxa para evitar abusos e garantir a estabilidade do seu sistema com o skill rate-limit-setup","ru":"Узнайте, как настроить лимит скорости, чтобы предотвратить злоупотребления и обеспечить стабильность вашей системы с помощью ИИ Агентов","ar":"تعرف على كيفية ضبط حد معدل الاستجابة لتجنب الإساءة وضمان استقرار نظامك مع الأدوات الذكية"},"definition":{"en":"rate-limit-setup is a database-backed rate limiting implementation that tracks user activity and limits requests based on a SHA-256 hash of IP and User-Agent.","zh":"率限设置是指限制AI工具的使用频率，防止滥用","ja":"レート制限設定とは、AIエージェントの使用頻度を制限し、乱用を防ぐことです","ko":"레이트 제한 설정은 AI 에이전트의 사용 빈도를 제한하여 남용을 방지하는 것을 의미합니다","es":"El ajuste de límite de velocidad es un mecanismo que limita el número de solicitudes que un usuario puede realizar","fr":"La limitation de débit est un mécanisme qui limite le nombre de requêtes qu''un utilisateur peut effectuer","de":"Die Rate Limitierung ist ein Mechanismus, der die Anzahl der Anfragen begrenzt, die ein Benutzer stellen kann","pt":"O que é rate-limit-setup? É uma técnica de configuração de limite de taxa para evitar abusos e garantir a estabilidade do sistema.","ru":"Что такое rate-limit-setup? Это техника настройки лимита скорости, чтобы предотвратить злоупотребления и обеспечить стабильность системы.","ar":"ما هي مهارة rate-limit-setup؟ هي تقنية لضبط حد معدل الاستجابة لتجنب الإساءة وضمان استقرار النظام."},"features":{"en":["Implements rate limiting via the `usage_tracking` table","Limits 2 premium images per user per 24 hours","Uses SHA-256 hash of IP + User-Agent for anonymous identification","Automatically resets limits after 24 hours","Utilizes TypeScript for implementation, specifically in `app/api/generate-image/route.ts`"],"zh":["使用数据库进行跟踪","SHA-256哈希用户识别","每24小时限制2个高级图像","自动重置","TypeScript实现"],"ja":["データベースを使用したトラッキング","SHA-256ハッシュによるユーザー識別","24時間ごとに2つのプレミアムイメージを制限","自動リセット","TypeScript実装"],"ko":["데이터베이스를 사용한 추적","SHA-256 해시를 통한 사용자 식별","24시간마다 2개의 프리미엄 이미지 제한","자동 재설정","TypeScript 구현"],"es":["Límite de 2 imágenes premium por usuario cada 24 horas","Identificación mediante hash SHA-256 de IP y User-Agent","Reinicio automático después de 24 horas","Implementación con tabla de seguimiento de uso","Compatibilidad con NextRequest"],"fr":["Limite de 2 images premium par utilisateur toutes les 24 heures","Identification via un hash SHA-256 de l''IP et du User-Agent","Réinitialisation automatique après 24 heures","Implémentation avec une table de suivi d''utilisation","Compatibilité avec NextRequest"],"de":["Begrenzung auf 2 Premium-Bilder pro Benutzer alle 24 Stunden","Identifizierung mittels SHA-256-Hash von IP und User-Agent","Automatischer Reset nach 24 Stunden","Implementierung mit Nutzungsnachverfolgungstabelle","Kompatibilität mit NextRequest"],"pt":["Limite de 2 imagens premium por usuário por 24 horas","Identificação do usuário via hash SHA-256 de IP + User-Agent","Resete automático após 24 horas","Uso de tabela de rastreamento de uso no banco de dados"],"ru":["Лимит 2 премиум-изображений на пользователя в течение 24 часов","Идентификация пользователя по хэшу SHA-256 IP + User-Agent","Автоматический сброс после 24 часов","Использование таблицы отслеживания использования в базе данных"],"ar":["حد 2 صورة متميزة لكل مستخدم خلال 24 ساعة","تحديد الهوية للمستخدم عبر هاش SHA-256 IP + User-Agent","إعادة ضبط تلقائية بعد 24 ساعة","استخدام جدول تتبع الاستخدام في قاعدة البيانات"]},"keywords":{"en":["how to use rate-limit-setup","rate-limit-setup alternative","rate-limit-setup setup guide","what is rate-limit-setup","rate-limit-setup vs competitor","rate-limit-setup install","database-backed rate limiting","premium image generation limit","SHA-256 hash identification"],"zh":["AI工具率限设置","数据库跟踪","SHA-256哈希","TypeScript实现","API管理","レート制限","AIエージェント"],"ja":["AIエージェントのレート制限設定","データベーストラッキング","SHA-256ハッシュ","TypeScript実装","API管理","レート制限","AIエージェント"],"ko":["AI 에이전트 레이트 제한 설정","데이터베이스 추적","SHA-256 해시","TypeScript 구현","API 관리","레이트 제한","AI 에이전트"],"es":["ajuste de límite de velocidad","Agentes de IA","límite de velocidad para imágenes premium","seguridad de API","NextRequest","tabla de seguimiento de uso","hash SHA-256"],"fr":["limitation de débit","outils d''IA","limite de débit pour images premium","sécurité d''API","NextRequest","table de suivi d''utilisation","hash SHA-256"],"de":["Rate Limitierung","künstliche Intelligenz-Tools","Begrenzung von Premium-Bildern","API-Sicherheit","NextRequest","Nutzungsnachverfolgungstabelle","SHA-256-Hash"],"pt":["rate-limit-setup","configuração de limite de taxa","prevenção de abusos","estabilidade do sistema","banco de dados","tabela de rastreamento de uso","SHA-256","User-Agent"],"ru":["rate-limit-setup","настройка лимита скорости","предотвращение злоупотреблений","стабильность системы","база данных","таблица отслеживания использования","SHA-256","User-Agent","ИИ Агенты"],"ar":["rate-limit-setup","ضبط حد معدل الاستجابة","تجنب الإساءة","استقرار النظام","قاعدة البيانات","جدول تتبع الاستخدام","SHA-256","User-Agent","الأدوات الذكية"]}},"owner":"AppleLamps","repo":"grokify","repoPath":"AppleLamps/grokify","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.363Z","topics":[],"category":"community","skillMd":{"name":"rate-limit-setup","description":"Implement rate limiting for API endpoints. Use when user mentions rate limit, quota, usage tracking, throttle, or limit requests.","bodyPreview":"# Rate Limiting Implementation\n\nThis project uses database-backed rate limiting via the `usage_tracking` table.\n\n## Current Implementation\n\nLocated in `app/api/generate-image/route.ts`:\n- **Limit**: 2 premium images per user per 24 hours\n- **Identification**: SHA-256 hash of IP + User-Agent (anonymous)\n- **Reset**: Automatic after 24 hours\n\n## Instructions\n\n1. **Create user identifier** (anonymous hash):\n```typescript\nconst getUserIdentifier = async (req: NextRequest): Promise<string> => {\n  con","body":"# Rate Limiting Implementation\n\nThis project uses database-backed rate limiting via the `usage_tracking` table.\n\n## Current Implementation\n\nLocated in `app/api/generate-image/route.ts`:\n- **Limit**: 2 premium images per user per 24 hours\n- **Identification**: SHA-256 hash of IP + User-Agent (anonymous)\n- **Reset**: Automatic after 24 hours\n\n## Instructions\n\n1. **Create user identifier** (anonymous hash):\n```typescript\nconst getUserIdentifier = async (req: NextRequest): Promise<string> => {\n  const ip = req.headers.get(''x-forwarded-for'')?.split('','')[0]\n    || req.headers.get(''x-real-ip'')\n    || ''unknown'';\n  const userAgent = req.headers.get(''user-agent'') || ''unknown'';\n\n  const encoder = new TextEncoder();\n  const data = encoder.encode(ip + userAgent);\n  const hashBuffer = await crypto.subtle.digest(''SHA-256'', data);\n  const hashArray = Array.from(new Uint8Array(hashBuffer));\n  return hashArray.map((b) => b.toString(16).padStart(2, ''0'')).join('''');\n};\n```\n\n2. **Check and update usage**:\n```typescript\nimport { db, usageTracking } from ''@/db'';\nimport { eq } from ''drizzle-orm'';\n\nconst checkUsage = async (identifier: string, limit: number) => {\n  const existing = await db\n    .select()\n    .from(usageTracking)\n    .where(eq(usageTracking.userIdentifier, identifier))\n    .limit(1);\n\n  let usage = existing[0] || null;\n  const now = new Date();\n  const resetNeeded = !usage ||\n    now.getTime() - new Date(usage.lastResetAt!).getTime() > 24 * 60 * 60 * 1000;\n\n  if (!usage) {\n    const [inserted] = await db\n      .insert(usageTracking)\n      .values({ userIdentifier: identifier, premiumImagesCount: 0, lastResetAt: now })\n      .returning();\n    usage = inserted;\n  } else if (resetNeeded) {\n    const [updated] = await db\n      .update(usageTracking)\n      .set({ premiumImagesCount: 0, lastResetAt: now, updatedAt: now })\n      .where(eq(usageTracking.userIdentifier, identifier))\n      .returning();\n    usage = updated;\n  }\n\n  const withinLimit = (usage?.premiumImagesCount || 0) < limit;\n  return { withinLimit, usage };\n};\n```\n\n3. **Increment counter after successful action**:\n```typescript\nawait db\n  .update(usageTracking)\n  .set({\n    premiumImagesCount: (usage?.premiumImagesCount || 0) + 1,\n    updatedAt: new Date(),\n  })\n  .where(eq(usageTracking.userIdentifier, userIdentifier));\n```\n\n4. **Return appropriate response when limited**:\n```typescript\nif (!withinLimit) {\n  return NextResponse.json(\n    { error: ''Rate limit exceeded. Try again in 24 hours.'' },\n    { status: 429, headers: corsHeaders }\n  );\n}\n```\n\n## For New Rate-Limited Features\n\nIf tracking a different resource, add a new column to `usage_tracking` or create a new table:\n```typescript\n// In db/schema.ts\nfeatureCount: integer(''feature_count'').default(0),\n```\n\n## Examples\n\n- \"Limit roasts to 5 per day\" → Add `roastCount` column, apply pattern above\n- \"Add API request throttling\" → Create new tracking table for general requests\n\n## Guardrails\n\n- Never expose user identifiers in responses\n- Log usage counts, not full hashes\n- Use 429 status code for rate limit responses\n- Include reset time info in rate limit responses when possible\n- Test reset logic carefully (24-hour boundary)\n"},"lastSynced":"2026-03-08T02:04:16.393Z","agentAnalysis":{"suitability":{"en":"Perfect for Security Agents needing advanced rate limiting capabilities to prevent abuse and ensure fair usage.","zh":"适合需要高级速率限制功能的安全代理，以防止滥用和确保公平使用。","ja":"高度なレート制限機能が必要なセキュリティエージェントに適しています。不正使用を防ぎ、公平な使用を確保するために。","ko":"고급 레이트 제한 기능이 필요한 보안 에이전트에게 적합합니다. 남용을 방지하고 공정한 사용을 보장하기 위해","es":"Perfecto para agentes de seguridad que necesitan capacidades de limitación de velocidad avanzadas para prevenir el abuso y garantizar un uso justo.","fr":"Parfait pour les agents de sécurité nécessitant des capacités de limitation de débit avancées pour prévenir les abus et assurer une utilisation équitable.","de":"Perfekt für Sicherheitsagenten, die erweiterte Rate-Limiting-Funktionen benötigen, um Missbrauch zu verhindern und eine faire Nutzung zu gewährleisten.","pt":"Perfeito para Agentes de Segurança que necessitam de recursos avançados de limitação de taxa para prevenir abusos e garantir uso justo.","ru":"Идеально для агентов безопасности, которым необходимы продвинутые возможности ограничения скорости для предотвращения злоупотреблений и обеспечения справедливого использования.","ar":"مثالي لعميل الأمن الذين يحتاجون إلى إمكانيات متقدمة لتحديد معدل لمنع الإساءة وضمان استخدام عادل."},"recommendation":{"en":"Empowers agents to implement database-backed rate limiting via the `usage_tracking` table, utilizing SHA-256 hash of IP + User-Agent for anonymous identification and automatic reset after 24 hours, effectively preventing excessive premium image generation.","zh":"赋予代理实现数据库支持的速率限制，通过 `usage_tracking` 表，利用 IP + User-Agent 的 SHA-256 哈希进行匿名识别，并在 24 小时后自动重置，有效防止过度的高级图像生成。","ja":"エージェントに、`usage_tracking` テーブルを使用したデータベースバックエンドのレート制限を実装する力を与え、IP + User-Agent の SHA-256 ハッシュを使用した匿名識別と 24 時間後の自動リセットにより、過剰なプレミアムイメージ生成を効果的に防止します。","ko":"에이전트에게 `usage_tracking` 테이블을 사용한 데이터베이스 백엔드 레이트 제한을 구현할 수 있는 능력을 부여하여, IP + User-Agent의 SHA-256 해시를 사용한 익명 식별 및 24시간 후 자동 재설정으로 과도한 프리미엄 이미지 생성을 효과적으로 방지합니다.","es":"Permite a los agentes implementar una limitación de velocidad basada en bases de datos a través de la tabla `usage_tracking`, utilizando el hash SHA-256 de IP + User-Agent para la identificación anónima y el restablecimiento automático después de 24 horas, lo que evita efectivamente la generación excesiva de imágenes de alta calidad.","fr":"Permet aux agents de mettre en œuvre une limitation de débit basée sur une base de données via la table `usage_tracking`, en utilisant le hash SHA-256 de IP + User-Agent pour l''identification anonyme et la réinitialisation automatique après 24 heures, ce qui empêche efficacement la génération excessive d''images de haute qualité.","de":"Ermächtigt die Agenten, eine datenbankbasierte Rate-Limiting über die `usage_tracking`-Tabelle zu implementieren, unter Verwendung des SHA-256-Hash von IP + User-Agent für die anonyme Identifizierung und die automatische Zurücksetzung nach 24 Stunden, was die übermäßige Erzeugung von Premium-Bildern effektiv verhindert.","pt":"Habilita os agentes a implementar limitação de taxa com base em banco de dados via a tabela `usage_tracking`, utilizando o hash SHA-256 do IP + User-Agent para identificação anônima e reinicialização automática após 24 horas, impedindo efetivamente a geração excessiva de imagens premium.","ru":"Наделяет агентов возможностью реализовать ограничение скорости на основе базы данных через таблицу `usage_tracking`, используя хеш SHA-256 из IP + User-Agent для анонимной идентификации и автоматического сброса после 24 часов, эффективно предотвращая чрезмерную генерацию премиум-изображений.","ar":"يسمح للوكلاء بتنفيذ حد لسرعة القاعدة مع التتبع باستخدام جدول `usage_tracking` ، باستخدام SHA-256 هاش من IP + User-Agent للتعريف المجهول وإعادة الضبط التلقائي بعد 24 ساعة ، مما يمنع فعليًا توليد الصور المميزة الزائد."},"useCases":{"en":["Preventing abuse of premium image generation","Enforcing fair usage policies for users","Tracking and limiting API requests"],"zh":["防止高级图像生成的滥用","执行用户的公平使用策略","跟踪和限制 API 请求"],"ja":["プレミアムイメージ生成の不正使用を防止する","ユーザーの公平使用ポリシーを適用する","API リクエストを追跡して制限する"],"ko":["프리미엄 이미지 생성의 남용을 방지","사용자의 공정한 사용 정책을 적용","API 요청을 추적하고 제한"],"es":["Prevenir el abuso de la generación de imágenes de alta calidad","Hacer cumplir las políticas de uso justo para los usuarios","Seguimiento y limitación de solicitudes de API"],"fr":["Prévenir les abus de génération d''images de haute qualité","Faire respecter les politiques d''utilisation équitable pour les utilisateurs","Suivi et limitation des requêtes API"],"de":["Missbrauch der Erzeugung von Premium-Bildern verhindern","Einhalten der Richtlinien für faire Nutzung durch Benutzer","Nachverfolgung und Begrenzung von API-Anfragen"],"pt":["Prevenir abusos de geração de imagens premium","Fazer cumprir políticas de uso justo para os usuários","Rastrear e limitar solicitações de API"],"ru":["Предотвращение злоупотреблений генерацией премиум-изображений","Внедрение справедливых политик использования для пользователей","Отслеживание и ограничение запросов API"],"ar":["منع الإساءة لتوليد الصور المميزة","تنفيذ سياسات استخدام عادل للمستخدمين","تتبع وحدود الطلبات API"]},"limitations":{"en":["Requires database access for `usage_tracking` table","Limited to 2 premium images per user per 24 hours","Relies on SHA-256 hash for anonymous user identification"],"zh":["需要数据库访问 `usage_tracking` 表","每个用户每 24 小时限制 2 个高级图像","依赖 SHA-256 哈希进行匿名用户识别"],"ja":["`usage_tracking` テーブルへのデータベースアクセスが必要","ユーザーごとに 24 時間で 2 つのプレミアムイメージに制限","匿名ユーザー識別に SHA-256 ハッシュに依存"],"ko":["`usage_tracking` 테이블에 대한 데이터베이스 액세스가 필요","사용자당 24시간 동안 2개의 프리미엄 이미지를 제한","익명 사용자 식별에 SHA-256 해시에 의존"],"es":["Requiere acceso a la base de datos para la tabla `usage_tracking`","Limitado a 2 imágenes de alta calidad por usuario por 24 horas","Depende del hash SHA-256 para la identificación anónima de usuarios"],"fr":["Nécessite un accès à la base de données pour la table `usage_tracking`","Limité à 2 images de haute qualité par utilisateur par 24 heures","Dépend du hash SHA-256 pour l''identification anonyme des utilisateurs"],"de":["Erfordert Zugriff auf die Datenbank für die `usage_tracking`-Tabelle","Begrenzt auf 2 Premium-Bilder pro Benutzer pro 24 Stunden","Basiert auf dem SHA-256-Hash für die anonyme Benutzeridentifizierung"],"pt":["Requer acesso ao banco de dados para a tabela `usage_tracking`","Limitado a 2 imagens premium por usuário por 24 horas","Depende do hash SHA-256 para identificação anônima do usuário"],"ru":["Требует доступа к базе данных для таблицы `usage_tracking`","Ограничен до 2 премиум-изображений на пользователя в 24 часа","Полагается на хеш SHA-256 для анонимной идентификации пользователя"],"ar":["يتطلب الوصول إلى قاعدة البيانات لجدول `usage_tracking`","محدود بـ 2 صور مميزة لكل مستخدم كل 24 ساعة","يعتمد على SHA-256 هاش للتعريف المجهول للمستخدم"]},"version":4},"contentHash":"6eb9d679086bad0cbd3958611506de6448a889d84db57fcddd5653dedb81150a","qualityScore":57}');
