INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('baiyongping/cowork-platform/miniprogram-development', 'miniprogram-development', 'baiyongping', 'cowork-platform', 'community', 'miniprogram-development baiyongping cowork-platform community The miniprogram-development skill enables developers to build and deploy WeChat Mini Program pages and components. It supports integration with CloudBase capabilities and handles user identity and AI model calls. 微信小程序开发技能，用于开发和部署小程序页面和组件，集成CloudBase能力，如数据库、云函数和存储 WeChatミニプログラム開発スキル - 小程序ページとコンポーネントの開発とデプロイ、CloudBase機能の統合 미니프로그램 개발 스킬 - 미니프로그램 페이지와 컴포넌트 개발 및 배포، CloudBase 기능 통합 El desarrollo de miniprogramas para WeChat implica la creación de páginas y componentes personalizados, la integración de CloudBase y la autenticación de usuarios. Le développement de miniprogrammes pour WeChat consiste à créer des pages et des composants personnalisés, à intégrer CloudBase et à gérer l''authentification des utilisateurs. Die Entwicklung von Miniprogrammen für WeChat umfasst die Erstellung von benutzerdefinierten Seiten und Komponenten, die Integration von CloudBase und die Benutzerauthentifizierung. Desenvolva miniprogramas WeChat com recursos de CloudBase e autenticação. Utilize modelos de IA e obtenha dados de contagem de passos do WeChat. Разработайте мини-программы WeChat с функциями CloudBase и аутентификации. Используйте модели ИИ и получите данные счетчика шагов WeChat. طور برامج صغيرة للويتشات مع ميزات CloudBase والتحقق. استخدم نماذج الذكاء الاصطناعي واختر تقارير عدّ الخطوات من الويتشات. how to use miniprogram-development what is miniprogram-development miniprogram-development alternative miniprogram-development vs web-development miniprogram-development install miniprogram-development setup guide WeChat Mini Program development CloudBase integration mini program authentication 微信小程序开发 小程序页面开发 CloudBase集成 小程序部署 小程序认证 AI模型调用 微信步数数据 小程序开发技能 Develop WeChat mini program pages and components Integrate CloudBase capabilities, including database, cloud functions, and storage Deploy and preview mini program projects Handle mini program authentication and user identity Call AI models in mini programs Get WeChat step count data miniprogram-development is a skill for building WeChat Mini Program projects, integrating CloudBase capabilities, and handling authentication and AI model calls.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Ronasunil/rona-open-claw/merge-pr', 'community', 'Ronasunil', 'rona-open-claw', 'Ronasunil/rona-open-claw', 'merge-pr', 0, 0, 57, '2026-03-08T01:57:15.365Z', '2026-03-08T02:04:20.721Z', '5da3b96f58ed4ebb19ec690b498acde3e4f85f90f388483e9c3a29ed067efb0d', '{"id":"Ronasunil/rona-open-claw/merge-pr","name":"merge-pr","description":{"en":"The merge-pr skill enables developers to merge prepared PRs using deterministic squash merge, ensuring a clean and efficient workflow. It benefits developers and maintainers by providing a safe and controlled merge process.","zh":"merge-pr是一种使用确定性squash合并和gh pr merge --squash来管理代码的方法","ja":"merge-prは、決定性Squash Mergeとgh pr merge --squashを使用してコードを管理する方法です","ko":"merge-pr는 결정적 스쿼시 병합 및 gh pr merge --squash를 사용하여 코드를 관리하는 방법","es":"merge-pr es una habilidad que permite fusionar solicitudes de extracción de manera determinista utilizando gh y git. Permite a los desarrolladores fusionar PR de forma segura y eficiente.","fr":"merge-pr est une compétence qui permet de fusionner des demandes d''extraction de manière déterministe en utilisant gh et git. Elle permet aux développeurs de fusionner des PR de manière sécurisée et efficace.","de":"merge-pr ist eine Fähigkeit, die es ermöglicht, Pull-Requests deterministisch mit gh und git zu mergen. Sie ermöglicht es Entwicklern, PR auf sichere und effiziente Weise zu mergen.","pt":"O merge PR é uma ferramenta para mesclar PRs de forma segura e eficiente, utilizando gh pr merge --squash e evitando git push durante o merge.","ru":"Слияние PR - это инструмент для безопасного и эффективного слияния PR, используя gh pr merge --squash и избегая git push во время слияния.","ar":"合并 PR هو أداة لدمج الطلبات بالشكل الآمن والأكثر فعالية، باستخدام gh pr merge --squash وتجنب git push أثناء الmerge."},"seo":{"title":{"en":"merge-pr: Deterministic Squash Merge Setup Guide | AI Age...","zh":"merge-pr_SETUP GUIDE：确定性squash合并","ja":"merge-prセットアップガイド：決定性Squash Merge","ko":"merge-pr 설정 가이드: 결정적 스쿼시 병합","es":"Guía de configuración de merge-pr para desarrolladores","fr":"Guide de mise en place de merge-pr pour les développeurs","de":"Einrichtungsleitfaden für merge-pr für Entwickler","pt":"Guia de Configuração do Merge PR: Práticas Recomendadas p...","ru":"Настройка Слияния PR: Лучшие Практики для Разработчиков И...","ar":"دليل إعداد 合并 PR: أفضل الممارسات للمطورين والأدوات الذكية"},"description":{"en":"Explore merge-pr, the AI agent skill that streamlines PR merging via gh pr merge --squash. Learn how to set it up and optimize your workflow today!","zh":"了解merge-pr的工作原理，使用确定性squash合并和gh pr merge --squash来管理代码","ja":"merge-prの動作について学び、決定性Squash Mergeとgh pr merge --squashを使用してコードを管理する","ko":"merge-pr의 작동 원리를 이해하고 결정적 스쿼시 병합 및 gh pr merge --squash를 사용하여 코드를 관리","es":"Aprende a utilizar merge-pr para fusionar solicitudes de extracción de manera determinista con tecnologías como gh y git","fr":"Découvrez comment utiliser merge-pr pour fusionner des demandes d''extraction de manière déterministe avec des technologies comme gh et git","de":"Erfahren Sie, wie Sie merge-pr verwenden, um Pull-Requests deterministisch mit Technologien wie gh und git zu mergen","pt":"Aprenda a configurar o merge PR com segurança e eficiência, utilizando gh pr merge --squash e evitando git push durante o merge","ru":"Узнайте, как настроить слияние PR безопасно и эффективно, используя gh pr merge --squash и избегая git push во время слияния для ИИ Агентов","ar":"تعرف على كيفية إعداد 合并 PR بأمان وفعاليّة، باستخدام gh pr merge --squash وتجنب git push أثناء الmerge للأدوات الذكية"},"definition":{"en":"merge-pr is a skill that automates the merge of prepared PRs via deterministic squash merge, utilizing gh pr merge --squash and explicit co-author trailers.","zh":"merge-pr是一种代码合并工具，使用确定性squash合并和gh pr merge --squash","ja":"merge-prは、決定性Squash Mergeとgh pr merge --squashを使用するコード合併ツールです","ko":"merge-pr는 결정적 스쿼시 병합 및 gh pr merge --squash를 사용하는 코드 병합 도구","es":"merge-pr es una habilidad que realiza una fusión determinista de solicitudes de extracción utilizando tecnologías como gh y git","fr":"merge-pr est une compétence qui réalise une fusion déterministe de demandes d''extraction en utilisant des technologies comme gh et git","de":"merge-pr ist eine Fähigkeit, die eine deterministische Fusion von Pull-Requests mit Technologien wie gh und git durchführt","pt":"O que é merge PR? É uma ferramenta para mesclar PRs de forma determinística, utilizando squash merge e trailers de co-autoria.","ru":"Что такое слияние PR? Это инструмент для слияния PR по определенной схеме, используя squash merge и трейлеры соавторов для ИИ Агентов.","ar":"ما هو 合并 PR؟ هو أداة لدمج الطلبات بالشكل المحدد، باستخدام squash merge وتريلرز للتعاون"},"features":{"en":["Utilizes gh pr merge --squash for deterministic squash merge","Supports explicit co-author trailers for accurate attribution","Reads PR number or URL from .local/prep.env file if present","Asks for clarification when PR number or URL is ambiguous","Ensures safety by not running git push during merge"],"zh":["使用确定性squash合并","支持gh pr merge --squash","自动清理工作树","支持PR编号或URL输入","使用.local/prep.env文件","避免使用gh pr merge --auto"],"ja":["決定性Squash Mergeを使用","gh pr merge --squashをサポート","ワークツリーを自動的にクリーンアップ","PR番号またはURLの入力をサポート",".local/prep.envファイルを使用","gh pr merge --autoの使用を避ける"],"ko":["결정적 스쿼시 병합 사용","gh pr merge --squash 지원","작업 트리 자동 정리","PR 번호 또는 URL 입력 지원",".local/prep.env 파일 사용","gh pr merge --auto 사용 피하기"],"es":["Fusión determinista de solicitudes de extracción con gh pr merge --squash","Limpieza del árbol de trabajo después de una fusión exitosa","Compatibilidad con .local/prep.env para obtener el número de PR o la URL","Soporte para la opción --match-head-commit para una fusión más precisa","Evita el uso de gh pr merge --auto para aterrizajes de mantenedores","No ejecuta git push durante el proceso de fusión"],"fr":["Fusion déterministe de demandes d''extraction avec gh pr merge --squash","Nettoyage de l''arbre de travail après une fusion réussie","Compatibilité avec .local/prep.env pour obtenir le numéro de PR ou l''URL","Prise en charge de l''option --match-head-commit pour une fusion plus précise","Évite l''utilisation de gh pr merge --auto pour les atterrisages de mainteneurs","N''exécute pas git push pendant le processus de fusion"],"de":["Deterministische Fusion von Pull-Requests mit gh pr merge --squash","Bereinigung des Arbeitsverzeichnisses nach einer erfolgreichen Fusion","Kompatibilität mit .local/prep.env zur Abrufung der PR-Nummer oder URL","Unterstützung der Option --match-head-commit für eine präzisere Fusion","Vermeidung der Verwendung von gh pr merge --auto für Maintainer-Landungen","Führt kein git push während des Fusionierungsprozesses aus"],"pt":["Utiliza gh pr merge --squash para mesclar PRs","Evita git push durante o merge","Utiliza trailers de co-autoria para manter a autoria","Permite a configuração de PRs por meio de .local/prep.env","Pergunta por confirmação em caso de ambiguidade"],"ru":["Использует gh pr merge --squash для слияния PR","Избегает git push во время слияния","Использует трейлеры соавторов для поддержания авторства","Позволяет настраивать PR через .local/prep.env для ИИ Агентов","Запрашивает подтверждение в случае неоднозначности"],"ar":["يستخدم gh pr merge --squash لدمج الطلبات","يتجنب git push أثناء الmerge","يستخدم تريلرز للتعاون للحفاظ على حقوق التأليف","يسمح بإعداد الطلبات من خلال .local/prep.env للأدوات الذكية","يتطلب التأكيد في حالة الغموض"]},"keywords":{"en":["how to use merge-pr","merge-pr setup guide","gh pr merge --squash","deterministic squash merge","merge-pr vs git merge","merge-pr install","what is merge-pr","merge-pr alternative","merge-pr for developers"],"zh":["merge-pr","确定性squash合并","gh pr merge --squash","代码合并工具","AIエージェント","代码管理","git合并","PR管理"],"ja":["merge-pr","決定性Squash Merge","gh pr merge --squash","コード合併ツール","AIエージェント","コード管理","git合併","PR管理"],"ko":["merge-pr","결정적 스쿼시 병합","gh pr merge --squash","코드 병합 도구","AI 에이전트","코드 관리","git 병합","PR 관리"],"es":["merge-pr","fusión de solicitudes de extracción","gh pr merge","git","desarrollo de software","herramientas de desarrollo","integración continua","despliegue automatizado","gestión de versiones"],"fr":["merge-pr","fusion de demandes d''extraction","gh pr merge","git","développement de logiciels","outils de développement","intégration continue","déploiement automatisé","gestion de versions"],"de":["merge-pr","Fusion von Pull-Requests","gh pr merge","git","Software-Entwicklung","Entwicklungstools","kontinuierliche Integration","automatisierte Bereitstellung","Versionsverwaltung"],"pt":["merge PR","gh pr merge","squash merge","trailer de co-autoria","git push","desenvolvimento de software","ferramentas de desenvolvimento","práticas recomendadas para desenvolvedores"],"ru":["слияние PR","gh pr merge","squash merge","трейлеры соавторов","git push","разработка программного обеспечения","инструменты для разработчиков","лучшие практики для разработчиков ИИ Агентов"],"ar":["合并 PR","gh pr merge","squash merge","تريلرز للتعاون","git push","تطوير البرمجيات","أدوات تطوير","أفضل الممارسات للمطورين والأدوات الذكية"]}},"owner":"Ronasunil","repo":"rona-open-claw","repoPath":"Ronasunil/rona-open-claw","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.365Z","topics":[],"category":"community","skillMd":{"name":"merge-pr","description":"Merge a GitHub PR via squash after /prepare-pr. Use when asked to merge a ready PR. Do not push to main or modify code. Ensure the PR ends in MERGED state and clean up worktrees after success.","bodyPreview":"# Merge PR\n\n## Overview\n\nMerge a prepared PR via deterministic squash merge (`--match-head-commit` + explicit co-author trailer), then clean up the worktree after success.\n\n## Inputs\n\n- Ask for PR number or URL.\n- If missing, use `.local/prep.env` from the worktree if present.\n- If ambiguous, ask.\n\n## Safety\n\n- Use `gh pr merge --squash` as the only path to `main`.\n- Do not run `git push` at all during merge.\n- Do not use `gh pr merge --auto` for maintainer landings.\n- Do not run gateway stop co","body":"# Merge PR\n\n## Overview\n\nMerge a prepared PR via deterministic squash merge (`--match-head-commit` + explicit co-author trailer), then clean up the worktree after success.\n\n## Inputs\n\n- Ask for PR number or URL.\n- If missing, use `.local/prep.env` from the worktree if present.\n- If ambiguous, ask.\n\n## Safety\n\n- Use `gh pr merge --squash` as the only path to `main`.\n- Do not run `git push` at all during merge.\n- Do not use `gh pr merge --auto` for maintainer landings.\n- Do not run gateway stop commands. Do not kill processes. Do not touch port 18792.\n\n## Execution Rule\n\n- Execute the workflow. Do not stop after printing the TODO checklist.\n- If delegating, require the delegate to run commands and capture outputs.\n\n## Known Footguns\n\n- If you see \"fatal: not a git repository\", you are in the wrong directory. Move to the repo root and retry.\n- Read `.local/review.md`, `.local/prep.md`, and `.local/prep.env` in the worktree. Do not skip.\n- Always merge with `--match-head-commit \"$PREP_HEAD_SHA\"` to prevent racing stale or changed heads.\n- Clean up `.worktrees/pr-<PR>` only after confirmed `MERGED`.\n\n## Completion Criteria\n\n- Ensure `gh pr merge` succeeds.\n- Ensure PR state is `MERGED`, never `CLOSED`.\n- Record the merge SHA.\n- Leave a PR comment with merge SHA and prepared head SHA, and capture the comment URL.\n- Run cleanup only after merge success.\n\n## First: Create a TODO Checklist\n\nCreate a checklist of all merge steps, print it, then continue and execute the commands.\n\n## Setup: Use a Worktree\n\nUse an isolated worktree for all merge work.\n\n```sh\nrepo_root=$(git rev-parse --show-toplevel)\ncd \"$repo_root\"\ngh auth status\n\nWORKTREE_DIR=\".worktrees/pr-<PR>\"\ncd \"$WORKTREE_DIR\"\n```\n\nRun all commands inside the worktree directory.\n\n## Load Local Artifacts (Mandatory)\n\nExpect these files from earlier steps:\n\n- `.local/review.md` from `/review-pr`\n- `.local/prep.md` from `/prepare-pr`\n- `.local/prep.env` from `/prepare-pr`\n\n```sh\nls -la .local || true\n\nfor required in .local/review.md .local/prep.md .local/prep.env; do\n  if [ ! -f \"$required\" ]; then\n    echo \"Missing $required. Stop and run /review-pr then /prepare-pr.\"\n    exit 1\n  fi\ndone\n\nsed -n ''1,120p'' .local/review.md\nsed -n ''1,120p'' .local/prep.md\nsource .local/prep.env\n```\n\n## Steps\n\n1. Identify PR meta and verify prepared SHA still matches\n\n```sh\npr_meta_json=$(gh pr view <PR> --json number,title,state,isDraft,author,headRefName,headRefOid,baseRefName,headRepository,body)\nprintf ''%s\\n'' \"$pr_meta_json\" | jq ''{number,title,state,isDraft,author:.author.login,head:.headRefName,headSha:.headRefOid,base:.baseRefName,headRepo:.headRepository.nameWithOwner,body}''\npr_title=$(printf ''%s\\n'' \"$pr_meta_json\" | jq -r .title)\npr_number=$(printf ''%s\\n'' \"$pr_meta_json\" | jq -r .number)\npr_head_sha=$(printf ''%s\\n'' \"$pr_meta_json\" | jq -r .headRefOid)\ncontrib=$(printf ''%s\\n'' \"$pr_meta_json\" | jq -r .author.login)\nis_draft=$(printf ''%s\\n'' \"$pr_meta_json\" | jq -r .isDraft)\n\nif [ \"$is_draft\" = \"true\" ]; then\n  echo \"ERROR: PR is draft. Stop and run /prepare-pr after draft is cleared.\"\n  exit 1\nfi\n\nif [ \"$pr_head_sha\" != \"$PREP_HEAD_SHA\" ]; then\n  echo \"ERROR: PR head changed after /prepare-pr (expected $PREP_HEAD_SHA, got $pr_head_sha). Re-run /prepare-pr.\"\n  exit 1\nfi\n```\n\n2. Run sanity checks\n\nStop if any are true:\n\n- PR is a draft.\n- Required checks are failing.\n- Branch is behind main.\n\nIf checks are pending, wait for completion before merging. Do not use `--auto`.\nIf no required checks are configured, continue.\n\n```sh\ngh pr checks <PR> --required --watch --fail-fast || true\nchecks_json=$(gh pr checks <PR> --required --json name,bucket,state 2>/tmp/gh-checks.err || true)\nif [ -z \"$checks_json\" ]; then\n  checks_json=''[]''\nfi\nrequired_count=$(printf ''%s\\n'' \"$checks_json\" | jq ''length'')\nif [ \"$required_count\" -eq 0 ]; then\n  echo \"No required checks configured for this PR.\"\nfi\nprintf ''%s\\n'' \"$checks_json\" | jq -r ''.[] | \"\\(.bucket)\\t\\(.name)\\t\\(.state)\"''\n\nfailed_required=$(printf ''%s\\n'' \"$checks_json\" | jq ''[.[] | select(.bucket==\"fail\")] | length'')\npending_required=$(printf ''%s\\n'' \"$checks_json\" | jq ''[.[] | select(.bucket==\"pending\")] | length'')\nif [ \"$failed_required\" -gt 0 ]; then\n  echo \"Required checks are failing, run /prepare-pr.\"\n  exit 1\nfi\nif [ \"$pending_required\" -gt 0 ]; then\n  echo \"Required checks are still pending, retry /merge-pr when green.\"\n  exit 1\nfi\n\ngit fetch origin main\ngit fetch origin pull/<PR>/head:pr-<PR> --force\ngit merge-base --is-ancestor origin/main pr-<PR> || (echo \"PR branch is behind main, run /prepare-pr\" && exit 1)\n```\n\nIf anything is failing or behind, stop and say to run `/prepare-pr`.\n\n3. Merge PR with explicit attribution metadata\n\n```sh\nreviewer=$(gh api user --jq .login)\nreviewer_id=$(gh api user --jq .id)\ncoauthor_email=${COAUTHOR_EMAIL:-\"$contrib@users.noreply.github.com\"}\nif [ -z \"$coauthor_email\" ] || [ \"$coauthor_email\" = \"null\" ]; then\n  contrib_id=$(gh api users/$contrib --jq .id)\n  coauthor_email=\"${contrib_id}+${contrib}@users.noreply.github.com\"\nfi\n\ngh_email=$(gh api user --jq ''.email // \"\"'' || true)\ngit_email=$(git config user.email || true)\nmapfile -t reviewer_email_candidates < <(\n  printf ''%s\\n'' \\\n    \"$gh_email\" \\\n    \"$git_email\" \\\n    \"${reviewer_id}+${reviewer}@users.noreply.github.com\" \\\n    \"${reviewer}@users.noreply.github.com\" | awk ''NF && !seen[$0]++''\n)\n[ \"${#reviewer_email_candidates[@]}\" -gt 0 ] || { echo \"ERROR: could not resolve reviewer author email\"; exit 1; }\nreviewer_email=\"${reviewer_email_candidates[0]}\"\n\ncat > .local/merge-body.txt <<EOF\nMerged via /review-pr -> /prepare-pr -> /merge-pr.\n\nPrepared head SHA: $PREP_HEAD_SHA\nCo-authored-by: $contrib <$coauthor_email>\nCo-authored-by: $reviewer <$reviewer_email>\nReviewed-by: @$reviewer\nEOF\n\nrun_merge() {\n  local email=\"$1\"\n  local stderr_file\n  stderr_file=$(mktemp)\n  if gh pr merge <PR> \\\n    --squash \\\n    --delete-branch \\\n    --match-head-commit \"$PREP_HEAD_SHA\" \\\n    --author-email \"$email\" \\\n    --subject \"$pr_title (#$pr_number)\" \\\n    --body-file .local/merge-body.txt \\\n    2> >(tee \"$stderr_file\" >&2)\n  then\n    rm -f \"$stderr_file\"\n    return 0\n  fi\n  merge_err=$(cat \"$stderr_file\")\n  rm -f \"$stderr_file\"\n  return 1\n}\n\nmerge_err=\"\"\nselected_merge_author_email=\"$reviewer_email\"\nif ! run_merge \"$selected_merge_author_email\"; then\n  if printf ''%s\\n'' \"$merge_err\" | rg -qi ''author.?email|email.*associated|associated.*email|invalid.*email'' && [ \"${#reviewer_email_candidates[@]}\" -ge 2 ]; then\n    selected_merge_author_email=\"${reviewer_email_candidates[1]}\"\n    echo \"Retrying once with fallback author email: $selected_merge_author_email\"\n    run_merge \"$selected_merge_author_email\" || { echo \"ERROR: merge failed after fallback retry\"; exit 1; }\n  else\n    echo \"ERROR: merge failed\"\n    exit 1\n  fi\nfi\n```\n\nRetry is allowed exactly once when the error is clearly author-email validation.\n\n4. Verify PR state and capture merge SHA\n\n```sh\nstate=$(gh pr view <PR> --json state --jq .state)\nif [ \"$state\" != \"MERGED\" ]; then\n  echo \"Merge not finalized yet (state=$state), waiting up to 15 minutes...\"\n  for _ in $(seq 1 90); do\n    sleep 10\n    state=$(gh pr view <PR> --json state --jq .state)\n    if [ \"$state\" = \"MERGED\" ]; then\n      break\n    fi\n  done\nfi\n\nif [ \"$state\" != \"MERGED\" ]; then\n  echo \"ERROR: PR state is $state after waiting. Leave worktree and retry /merge-pr later.\"\n  exit 1\nfi\n\nmerge_sha=$(gh pr view <PR> --json mergeCommit --jq ''.mergeCommit.oid'')\nif [ -z \"$merge_sha\" ] || [ \"$merge_sha\" = \"null\" ]; then\n  echo \"ERROR: merge commit SHA missing.\"\n  exit 1\nfi\n\ncommit_body=$(gh api repos/:owner/:repo/commits/$merge_sha --jq .commit.message)\ncontrib=${contrib:-$(gh pr view <PR> --json author --jq .author.login)}\nreviewer=${reviewer:-$(gh api user --jq .login)}\nprintf ''%s\\n'' \"$commit_body\" | rg -q \"^Co-authored-by: $contrib <\" || { echo \"ERROR: missing PR author co-author trailer\"; exit 1; }\nprintf ''%s\\n'' \"$commit_body\" | rg -q \"^Co-authored-by: $reviewer <\" || { echo \"ERROR: missing reviewer co-author trailer\"; exit 1; }\n\necho \"merge_sha=$merge_sha\"\n```\n\n5. PR comment\n\nUse a multiline heredoc with interpolation enabled.\n\n```sh\nok=0\ncomment_output=\"\"\nfor _ in 1 2 3; do\n  if comment_output=$(gh pr comment <PR> -F - <<EOF\nMerged via squash.\n\n- Prepared head SHA: $PREP_HEAD_SHA\n- Merge commit: $merge_sha\n\nThanks @$contrib!\nEOF\n); then\n    ok=1\n    break\n  fi\n  sleep 2\ndone\n\n[ \"$ok\" -eq 1 ] || { echo \"ERROR: failed to post PR comment after retries\"; exit 1; }\ncomment_url=$(printf ''%s\\n'' \"$comment_output\" | rg -o ''https://github.com/[^ ]+/pull/[0-9]+#issuecomment-[0-9]+'' -m1 || true)\n[ -n \"$comment_url\" ] || comment_url=\"unresolved\"\necho \"comment_url=$comment_url\"\n```\n\n6. Clean up worktree only on success\n\nRun cleanup only if step 4 returned `MERGED`.\n\n```sh\ncd \"$repo_root\"\ngit worktree remove \".worktrees/pr-<PR>\" --force\ngit branch -D temp/pr-<PR> 2>/dev/null || true\ngit branch -D pr-<PR> 2>/dev/null || true\ngit branch -D pr-<PR>-prep 2>/dev/null || true\n```\n\n## Guardrails\n\n- Worktree only.\n- Do not close PRs.\n- End in MERGED state.\n- Clean up only after merge success.\n- Never push to main. Use `gh pr merge --squash` only.\n- Do not run `git push` at all in this command.\n"},"lastSynced":"2026-03-08T02:04:20.721Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub Integration Agents requiring automated merge PR workflows with deterministic squash merge capabilities.","zh":"适用于需要自动合并 PR 工作流的 GitHub 集成代理，具有确定性 squash 合并功能。","ja":"自動マージ PR ワークフローが必要な GitHub 統合エージェントに適しています。決定的な squash マージ機能を備えています。","ko":"자동 합치기 PR 워크플ロー가 필요한 GitHub 통합 에이전트에 적합합니다. 결정적 squash 합치기 기능을 제공합니다.","es":"Ideal para agentes de integración de GitHub que requieren flujos de trabajo de fusión de PR automatizados con capacidades de fusión de squash determinista.","fr":"Idéal pour les agents d''intégration de GitHub nécessitant des flux de travail de fusion de PR automatisés avec des capacités de fusion de squash déterministes.","de":"Ideal für GitHub-Integration-Agents, die automatisierte Merge-PR-Workflows mit deterministischen Squash-Merge-Funktionen erfordern.","pt":"Ideal para Agentes de Integração do GitHub que exigem fluxos de trabalho de mesclagem de PR automatizados com capacidades de mesclagem de esmagamento determinísticas.","ru":"Идеально подходит для агентов интеграции GitHub, требующих автоматизированных рабочих процессов слияния PR с возможностями детерминированного сжатия слияния.","ar":"مثالية لعميل التكامل GitHub الذي يتطلب سير عمل اندماج PR آلي مع قدرات اندماج الضغط المتحديد."},"recommendation":{"en":"Empowers agents to merge prepared PRs using `gh pr merge --squash`, ensuring a clean and controlled merge process with explicit co-author trailers, while preventing unintended `git push` operations and maintaining a safe workflow by avoiding `gh pr merge --auto` for maintainer landings.","zh":"赋予代理使用 `gh pr merge --squash` 合并准备好的 PR，确保清晰和受控的合并过程，具有明确的共同作者标签，同时防止意外的 `git push` 操作，通过避免 `gh pr merge --auto` 来维持安全的工作流程。","ja":"エージェントに `gh pr merge --squash` を使用して準備された PR をマージする機能を提供し、明示的な共同作者トレーラーを備えたクリーンで制御されたマージプロセスを保証し、意図しない `git push` 操作を防ぎ、`gh pr merge --auto` を回避することで安全なワークフローを維持します。","ko":"에이전트가 `gh pr merge --squash`를 사용하여 준비된 PR를 병합하도록 허용하여, 명시적인 공동 저자 트레일러를 갖춘 깨끗하고 제어된 병합 프로세스를 보장하고, 의도하지 않은 `git push` 동작을 방지하며, `gh pr merge --auto`를 회피하여 안전한 워크플로를 유지합니다.","es":"Habilita a los agentes a fusionar PR preparados mediante `gh pr merge --squash`, garantizando un proceso de fusión limpio y controlado con remolques de coautoría explícitos, al tiempo que evita operaciones de `git push` no deseadas y mantiene un flujo de trabajo seguro al evitar `gh pr merge --auto` para aterrizajes de mantenedores.","fr":"Permet aux agents de fusionner des PR préparés à l''aide de `gh pr merge --squash`, garantissant un processus de fusion propre et contrôlé avec des remorques de co-auteur explicites, tout en évitant les opérations de `git push` non intentionnelles et en maintenant un flux de travail sécurisé en évitant `gh pr merge --auto` pour les atterrissages de mainteneurs.","de":"Ermächtigt Agenten, vorbereitete PRs mithilfe von `gh pr merge --squash` zu mergen, wodurch ein sauberer und kontrollierter Merge-Prozess mit expliziten Co-Autoren-Trailern gewährleistet wird, während ungewollte `git push`-Operationen verhindert und ein sicherer Workflow durch Vermeidung von `gh pr merge --auto` für Maintainer-Landungen aufrechterhalten wird.","pt":"Habilita os agentes a mesclar PRs preparados usando `gh pr merge --squash`, garantindo um processo de mesclagem limpo e controlado com trailers de co-autoria explícitos, ao mesmo tempo em que evita operações de `git push` não intencionais e mantém um fluxo de trabalho seguro, evitando `gh pr merge --auto` para aterrissagens de mantenedor.","ru":"Наделяет агентов возможностью сливать подготовленные PR с помощью `gh pr merge --squash`, обеспечивая чистый и контролируемый процесс слияния с явными трейлерами соавторства, а также предотвращая незамеченные операции `git push` и поддерживая безопасный рабочий процесс, избегая `gh pr merge --auto` для посадок обслуживающих.","ar":"تمكّن الوكلاء من اندماج الطلبات الجاهزة باستخدام `gh pr merge --squash` ، مما يضمن عملية اندماج نظيفة ومحكمة مع مقاطع مؤلفين مشتركين صريحة ، وفي الوقت نفسه منع عمليات `git push` غير مقصودة والحفاظ على سير عمل آمن من خلال تجنب `gh pr merge --auto` لعمليات الهبوط للصيانة."},"useCases":{"en":["Automating PR merges with deterministic squash merge","Streamlining maintainer workflows by preventing auto-merge","Ensuring clean worktrees after successful PR merges"],"zh":["使用确定性 squash 合并自动合并 PR","通过防止自动合并来简化维护者工作流程","确保 PR 合并后工作树的清洁"],"ja":["決定的な squash マージを使用して PR を自動マージする","自動マージを防止してメンテナーのワークフローを簡素化する","PR マージ後にクリーンなワークツリーを確保する"],"ko":["결정적 squash 합치기를 사용하여 PR를 자동으로 합치기","자동 합치기를 방지하여 유지 관리자의 워크플로를 간소화하기","PR 합치기 후 깨끗한 워크트리를 보장하기"],"es":["Automatizar las fusiones de PR con fusión de squash determinista","Optimizar los flujos de trabajo de los mantenedores al evitar la fusión automática","Garantizar árboles de trabajo limpios después de fusiones de PR exitosas"],"fr":["Automatiser les fusions de PR avec une fusion de squash déterministe","Optimiser les flux de travail des mainteneurs en évitant la fusion automatique","Assurer des arbres de travail propres après des fusions de PR réussies"],"de":["Automatisierung von PR-Merges mit deterministischer Squash-Merge","Optimierung der Maintainer-Workflows durch Vermeidung von Auto-Merges","Sicherstellung sauberer Arbeitsbäume nach erfolgreichen PR-Merges"],"pt":["Automatizar a mesclagem de PRs com mesclagem de esmagamento determinístico","Otimizar os fluxos de trabalho dos mantenedores, evitando a mesclagem automática","Garantir árvores de trabalho limpas após a mesclagem de PRs bem-sucedida"],"ru":["Автоматизировать слияние PR с детерминированным сжатием слияния","Оптимизировать рабочие процессы обслуживающих, предотвращая автоматическое слияние","Обеспечить чистые рабочие деревья после успешного слияния PR"],"ar":["توفير آلي لاندماج الطلبات الجاهزة مع اندماج الضغط المتحديد","تبسيط سير عمل الصيانة من خلال منع الاندماج الآلي","ضمان شجرات العمل النظيفة بعد اندماج الطلبات الجاهزة بنجاح"]},"limitations":{"en":["Requires GitHub CLI and repository access","Limited to deterministic squash merge strategy","Does not support automatic push operations during merge"],"zh":["需要 GitHub CLI 和仓库访问权限","仅限于确定性 squash 合并策略","不支持合并过程中的自动推送操作"],"ja":["GitHub CLI とリポジトリへのアクセスが必要","決定的な squash マージ戦略のみに限定","マージプロセス中の自動プッシュ操作はサポートされません"],"ko":["GitHub CLI 및 저장소 액세스가 필요함","결정적 squash 합치기 전략만으로 제한됨","합치기 프로세스 중 자동 푸시 동작을 지원하지 않음"],"es":["Requiere GitHub CLI y acceso al repositorio","Limitado a la estrategia de fusión de squash determinista","No admite operaciones de push automáticas durante la fusión"],"fr":["Nécessite GitHub CLI et accès au référentiel","Limité à la stratégie de fusion de squash déterministe","Ne prend pas en charge les opérations de push automatiques pendant la fusion"],"de":["Erfordert GitHub-CLI und Repository-Zugriff","Begrenzt auf die deterministische Squash-Merge-Strategie","Unterstützt keine automatischen Push-Vorgänge während des Merges"],"pt":["Exige GitHub CLI e acesso ao repositório","Limitado à estratégia de mesclagem de esmagamento determinístico","Não suporta operações de push automáticas durante a mesclagem"],"ru":["Требует GitHub CLI и доступа к репозиторию","Ограничен стратегией детерминированного сжатия слияния","Не поддерживает автоматические операции push во время слияния"],"ar":["يتطلب واجهة سطر أوامر GitHub ووصول إلى المستودع","محدود بstrategy اندماج الضغط المتحديد","لا يدعم عمليات الدفع الآلي أثناء اندماج الطلبات"]},"version":4},"contentHash":"5da3b96f58ed4ebb19ec690b498acde3e4f85f90f388483e9c3a29ed067efb0d","qualityScore":57}');
