INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Ronasunil/rona-open-claw/merge-pr', 'merge-pr', 'Ronasunil', 'rona-open-claw', 'community', 'merge-pr Ronasunil rona-open-claw community The merge-pr skill enables developers to merge prepared PRs using deterministic squash merge, ensuring a clean and efficient workflow. It benefits developers and maintainers by providing a safe and controlled merge process. merge-pr是一种使用确定性squash合并和gh pr merge --squash来管理代码的方法 merge-prは、決定性Squash Mergeとgh pr merge --squashを使用してコードを管理する方法です merge-pr는 결정적 스쿼시 병합 및 gh pr merge --squash를 사용하여 코드를 관리하는 방법 merge-pr es una habilidad que permite fusionar solicitudes de extracción de manera determinista utilizando gh y git. Permite a los desarrolladores fusionar PR de forma segura y eficiente. merge-pr est une compétence qui permet de fusionner des demandes d''extraction de manière déterministe en utilisant gh et git. Elle permet aux développeurs de fusionner des PR de manière sécurisée et efficace. merge-pr ist eine Fähigkeit, die es ermöglicht, Pull-Requests deterministisch mit gh und git zu mergen. Sie ermöglicht es Entwicklern, PR auf sichere und effiziente Weise zu mergen. O merge PR é uma ferramenta para mesclar PRs de forma segura e eficiente, utilizando gh pr merge --squash e evitando git push durante o merge. Слияние PR - это инструмент для безопасного и эффективного слияния PR, используя gh pr merge --squash и избегая git push во время слияния. 合并 PR هو أداة لدمج الطلبات بالشكل الآمن والأكثر فعالية، باستخدام gh pr merge --squash وتجنب git push أثناء الmerge. how to use merge-pr merge-pr setup guide gh pr merge --squash deterministic squash merge merge-pr vs git merge merge-pr install what is merge-pr merge-pr alternative merge-pr for developers merge-pr 确定性squash合并 gh pr merge --squash 代码合并工具 AIエージェント 代码管理 git合并 PR管理 Utilizes gh pr merge --squash for deterministic squash merge Supports explicit co-author trailers for accurate attribution Reads PR number or URL from .local/prep.env file if present Asks for clarification when PR number or URL is ambiguous Ensures safety by not running git push during merge merge-pr is a skill that automates the merge of prepared PRs via deterministic squash merge, utilizing gh pr merge --squash and explicit co-author trailers.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('powerhouse-inc/service-offering/frontend-to-backend-requirements', 'community', 'powerhouse-inc', 'service-offering', 'powerhouse-inc/service-offering', 'frontend-to-backend-requirements', 0, 0, 57, '2026-03-08T01:57:15.369Z', '2026-03-08T02:04:24.034Z', 'd29acfeac522b3d6cf396a4ecce85803d08ed62b97c92b61055b4d5499c1e150', '{"id":"powerhouse-inc/service-offering/frontend-to-backend-requirements","name":"frontend-to-backend-requirements","description":{"en":"The frontend-to-backend-requirements skill enables frontend developers to document data needs for backend implementation. This skill benefits frontend developers by allowing them to describe what data is needed without worrying about implementation details.","zh":"前端到后端需求设置是使用AIエージェント实现高效数据通信的关键步骤","ja":"フロントエンドからバックエンドへの要件設定は、効率的なデータ通信を実現するための重要なステップです","ko":"프론트엔드에서 백엔드까지 요구사항 설정은 효율적인 데이터 통신을实现하는 중요한 단계입니다","es":"El modo de requisitos de backend permite a los desarrolladores frontend describir qué datos necesitan sin especificar la implementación.","fr":"Le mode d''exigences de backend permet aux développeurs frontend de décrire quels données ils ont besoin sans spécifier l''implémentation.","de":"Der Backend-Anforderungsmodus ermöglicht es Frontend-Entwicklern, zu beschreiben, welche Daten sie benötigen, ohne die Implementierung zu spezifizieren.","pt":"O modo de requisitos de backend permite que desenvolvedores frontend documentem suas necessidades de dados sem se preocupar com detalhes de implementação","ru":"Режим требований backend позволяет frontend-разработчикам документировать свои потребности в данных без учета деталей реализации с помощью ИИ Агентов","ar":"الوضع المتعلق بمتطلبات الخادم الخلفي يسمح للمتطوعين في الواجهة الأمامية بتوثيق احتياجاتهم من البيانات دون الاهتمام بالتفاصيل الفنية لأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"frontend-to-backend-requirements: Backend Requirements Se...","zh":"前端到后端需求设置指南 - AIエージェント","ja":"フロントエンドからバックエンドへの要件設定方法 - AIエージェント","ko":"프론트엔드에서 백엔드까지 요구사항 설정 가이드 - AI 에이전트","es":"Guía de Configuración de Requisitos Frontend a Backend co...","fr":"Guide de Configuration des Exigences Frontend vers Backen...","de":"Konfigurationsleitfaden für Frontend-to-Backend-Anforderu...","pt":"Guia de Configuração de Requisitos Frontend para Backend","ru":"Руководство по настройке требований frontend для backend ...","ar":"دليل إعداد متطلبات الواجهة الأمامية لخادم الويب باستخدام ..."},"description":{"en":"Discover how to document frontend data needs with precision. Learn to write effective backend requirements with our AI agent skill and streamline your develo...","zh":"了解如何使用AIエージェント设置前端到后端的需求，实现高效的数据通信","ja":"フロントエンドからバックエンドへの要件を設定する方法を学び、効率的なデータ通信を実現する","ko":"AI 에이전트를 사용하여 프론트엔드에서 백엔드까지 요구사항을 설정하는 방법을 알아보세요","es":"Aprende a documentar requisitos de datos para backend como desarrollador frontend con nuestras herramientas de AI. Mejora la comunicación y reduce errores.","fr":"Découvrez comment documenter les exigences de données pour le backend en tant que développeur frontend avec nos outils d''IA. Améliorez la communication et ré...","de":"Erfahren Sie, wie Sie als Frontend-Entwickler Datenanforderungen für das Backend mit unseren KI-Tools dokumentieren. Verbessern Sie die Kommunikation und red...","pt":"Aprenda a documentar requisitos de dados para backend como desenvolvedor frontend e melhore a colaboração com a equipe de backend","ru":"Узнайте, как документировать требования к данным для backend как frontend-разработчик и улучшите сотрудничество с командой backend с помощью ИИ Агентов","ar":"تعرف على كيفية توثيق متطلبات البيانات للخادم الخلفي كمتعاون في الواجهة الأمامية وتحسين التعاون مع فريق الخادم الخلفي باستخدام أدوات الذكاء الاصطناعي"},"definition":{"en":"frontend-to-backend-requirements is a mode for frontend developers to communicate data needs to backend, focusing on what data is required without specifying implementation details.","zh":"前端到后端需求设置是指前端开发者向后端开发者描述所需数据的过程","ja":"フロントエンドからバックエンドへの要件設定とは、フロントエンド開発者がバックエンド開発者に必要なデータを説明するプロセスです","ko":"프론트엔드에서 백엔드까지 요구사항 설정은 프론트엔드 개발자가 백엔드 개발자에게 필요한 데이터를 설명하는 과정입니다","es":"El modo de requisitos de backend es una función que permite a los desarrolladores frontend documentar sus necesidades de datos para el backend.","fr":"Le mode d''exigences de backend est une fonctionnalité qui permet aux développeurs frontend de documenter leurs besoins en données pour le backend.","de":"Der Backend-Anforderungsmodus ist eine Funktion, die es Frontend-Entwicklern ermöglicht, ihre Datenanforderungen für das Backend zu dokumentieren.","pt":"Requisitos de backend são necessidades de dados documentadas por desenvolvedores frontend para informar a implementação do backend","ru":"Требования к backend - это потребности в данных, документируемые frontend-разработчиками для информирования реализации backend с помощью ИИ Агентов","ar":"متطلبات الخادم الخلفي هي احتياجات البيانات الموثقة من قبل المطورين الأماميين لإطلاع فريق الخادم الخلفي باستخدام أدوات الذكاء الاصطناعي"},"features":{"en":["Writes responses to .claude/docs/ai/<feature-name>/backend-requirements.md","Excludes implementation details such as endpoints, field names, or API structure","Allows frontend developers to describe what data is needed","Enables clear communication of data needs to backend","Supports backend ownership of implementation details","Generates backend requirements in Markdown format"],"zh":["描述所需数据，而不指定实现细节","使用AIエージェント生成backend-requirements.md文件","实现前端和后端之间的高效数据通信","支持多种数据格式和结构","简化前端和后端之间的数据交换过程"],"ja":["必要なデータを説明し、実装の詳細を指定しない","AIエージェントを使用してbackend-requirements.mdファイルを生成する","フロントエンドとバックエンドの間で効率的なデータ通信を実現する","多種多様なデータ形式と構造をサポートする","フロントエンドとバックエンドの間のデータ交換プロセスを簡素化する"],"ko":["필요한 데이터를 설명하고 구현 세부 사항을 지정하지 않는다","AI 에이전트를 사용하여 backend-requirements.md 파일을 생성한다","프론트엔드와 백엔드 사이에서 효율적인 데이터 통신을实现한다","다양한 데이터 형식과 구조를 지원한다","프론트엔드와 백엔드 사이의 데이터 교환 프로세스를 단순화한다"],"es":["Documentar requisitos de datos sin especificar la implementación","Comunicar necesidades de datos al equipo de backend","Reducir errores de comunicación entre frontend y backend","Mejorar la colaboración entre desarrolladores frontend y backend","Generar documentación automática de requisitos de backend"],"fr":["Documenter les exigences de données sans spécifier l''implémentation","Communiquer les besoins en données à l''équipe de backend","Réduire les erreurs de communication entre frontend et backend","Améliorer la collaboration entre les développeurs frontend et backend","Générer une documentation automatique des exigences de backend"],"de":["Datenanforderungen ohne Implementierungsdetails dokumentieren","Datenanforderungen an das Backend-Team kommunizieren","Fehler in der Kommunikation zwischen Frontend und Backend reduzieren","Zusammenarbeit zwischen Frontend- und Backend-Entwicklern verbessern","Automatische Dokumentation von Backend-Anforderungen generieren"],"pt":["Documentação de requisitos de dados sem detalhes de implementação","Foco no que é necessário, não como implementar","Melhoria da colaboração entre equipes de frontend e backend","Suporte à criação de documentos de requisitos de backend em formato Markdown","Armazenamento de documentos em `.claude/docs/ai/<feature-name>/backend-requirements.md`"],"ru":["Документирование требований к данным без деталей реализации с помощью ИИ Агентов","Фокус на том, что необходимо, а не на том, как реализовать","Улучшение сотрудничества между командами frontend и backend","Поддержка создания документов требований к backend в формате Markdown","Хранение документов в `.claude/docs/ai/<feature-name>/backend-requirements.md`"],"ar":["توثيق متطلبات البيانات دون التفاصيل الفنية لأدوات الذكاء الاصطناعي","التركيز على ما هو مطلوب، وليس كيفية التنفيذ","تحسين التعاون بين فرق الواجهة الأمامية والخادم الخلفي","دعم إنشاء مستندات متطلبات الخادم الخلفي بالتنسيق Markdown","تخزين المستندات في `.claude/docs/ai/<feature-name>/backend-requirements.md`"]},"keywords":{"en":["how to use frontend-to-backend-requirements","what is frontend-to-backend-requirements","frontend-to-backend-requirements alternative","frontend-to-backend-requirements vs backend development","frontend-to-backend-requirements install","frontend-to-backend-requirements setup guide","frontend-to-backend-requirements best practices","frontend-to-backend-requirements for AI agents","documenting frontend data needs","streamlining backend implementation"],"zh":["AIエージェント","前端到后端需求设置","数据通信","前端开发","后端开发","backend-requirements.md","数据交换","效率性的数据通信"],"ja":["AIエージェント","フロントエンドからバックエンドへの要件設定","データ通信","フロントエンド開発","バックエンド開発","backend-requirements.md","データ交換","効率的なデータ通信"],"ko":["AI 에이전트","프론트엔드에서 백엔드까지 요구사항 설정","데이터 통신","프론트엔드 개발","백엔드 개발","backend-requirements.md","데이터 교환","효율적인 데이터 통신"],"es":["requisitos de backend","desarrollo frontend","herramientas de AI","documentación de requisitos","comunicación entre equipos","colaboración entre desarrolladores","automatización de documentación","errores de comunicación","mejora de la colaboración"],"fr":["exigences de backend","développement frontend","outils d''IA","documentation des exigences","communication entre équipes","collaboration entre développeurs","automatisation de la documentation","erreurs de communication","amélioration de la collaboration"],"de":["Backend-Anforderungen","Frontend-Entwicklung","KI-Tools","Dokumentation von Anforderungen","Kommunikation zwischen Teams","Zusammenarbeit zwischen Entwicklern","Automatisierung der Dokumentation","Kommunikationsfehler","Verbesserung der Zusammenarbeit"],"pt":["requisitos de backend","desenvolvimento frontend","colaboração entre equipes","documentação de requisitos","marcação Markdown","ferramentas de desenvolvimento","desenvolvimento de software","requisitos de dados"],"ru":["требования к backend","разработка frontend","сотрудничество между командами","документирование требований","разметка Markdown","инструменты разработки","разработка программного обеспечения","требования к данным","ИИ Агенты"],"ar":["متطلبات الخادم الخلفي","تطوير الواجهة الأمامية","التعاون بين الفرق","توثيق المتطلبات","تنسيق Markdown","أدوات التطوير","تطوير البرمجيات","متطلبات البيانات","أدوات الذكاء الاصطناعي"]}},"owner":"powerhouse-inc","repo":"service-offering","repoPath":"powerhouse-inc/service-offering","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.369Z","topics":[],"category":"community","skillMd":{"name":"frontend-to-backend-requirements","description":"Document frontend data needs for backend developers. Use when frontend needs to communicate API requirements to backend, or user says backend requirements, what data do I need, API requirements, or is describing data needs for a UI.","bodyPreview":"# Backend Requirements Mode\n\nYou are a frontend developer documenting what data you need from backend. You describe the **what**, not the **how**. Backend owns implementation details.\n\n> **No Chat Output**: ALL responses go to `.claude/docs/ai/<feature-name>/backend-requirements.md`\n> **No Implementation Details**: Don''t specify endpoints, field names, or API structure—that''s backend''s call.\n\n---\n\n## The Point\n\nThis mode is for frontend devs to communicate data needs:\n- What data do I need to re","body":"# Backend Requirements Mode\n\nYou are a frontend developer documenting what data you need from backend. You describe the **what**, not the **how**. Backend owns implementation details.\n\n> **No Chat Output**: ALL responses go to `.claude/docs/ai/<feature-name>/backend-requirements.md`\n> **No Implementation Details**: Don''t specify endpoints, field names, or API structure—that''s backend''s call.\n\n---\n\n## The Point\n\nThis mode is for frontend devs to communicate data needs:\n- What data do I need to render this screen?\n- What actions should the user be able to perform?\n- What business rules affect the UI?\n- What states and errors should I handle?\n\n**You''re requesting, not demanding.** Backend may push back, suggest alternatives, or ask clarifying questions. That''s healthy collaboration.\n\n---\n\n## What You Own vs. What Backend Owns\n\n| Frontend Owns | Backend Owns |\n|---------------|--------------|\n| What data is needed | How data is structured |\n| What actions exist | Endpoint design |\n| UI states to handle | Field names, types |\n| User-facing validation | API conventions |\n| Display requirements | Performance/caching |\n\n---\n\n## Workflow\n\n### Step 1: Describe the Feature\n\nBefore listing requirements:\n\n1. **What is this?** — Screen, flow, component\n2. **Who uses it?** — User type, permissions\n3. **What''s the goal?** — What does success look like?\n\n### Step 2: List Data Needs\n\nFor each screen/component, describe:\n\n**Data I need to display:**\n- What information appears on screen?\n- What''s the relationship between pieces?\n- What determines visibility/state?\n\n**Actions user can perform:**\n- What can the user do?\n- What''s the expected outcome?\n- What feedback should they see?\n\n**States I need to handle:**\n- Loading, empty, error, success\n- Edge cases (partial data, expired, etc.)\n\n### Step 3: Surface Uncertainties\n\nList what you''re unsure about:\n- Business rules you don''t fully understand\n- Edge cases you''re not sure how to handle\n- Places where you''re guessing\n\n**These invite backend to clarify or push back.**\n\n### Step 4: Leave Room for Discussion\n\nEnd with open questions:\n- \"Would it make sense to...?\"\n- \"Should I expect...?\"\n- \"Is there a simpler way to...?\"\n\n---\n\n## Output Format\n\nCreate `.claude/docs/ai/<feature-name>/backend-requirements.md`:\n\n```markdown\n# Backend Requirements: <Feature Name>\n\n## Context\n[What we''re building, who it''s for, what problem it solves]\n\n## Screens/Components\n\n### <Screen/Component Name>\n**Purpose**: What this screen does\n\n**Data I need to display**:\n- [Description of data piece, not field name]\n- [Another piece]\n- [Relationships between pieces]\n\n**Actions**:\n- [Action description] → [Expected outcome]\n- [Another action] → [Expected outcome]\n\n**States to handle**:\n- **Empty**: [When/why this happens]\n- **Loading**: [What''s being fetched]\n- **Error**: [What can go wrong, what user sees]\n- **Special**: [Any edge cases]\n\n**Business rules affecting UI**:\n- [Rule that changes what''s visible/enabled]\n- [Permissions that affect actions]\n\n### <Next Screen/Component>\n...\n\n## Uncertainties\n- [ ] Not sure if [X] should show when [Y]\n- [ ] Don''t understand the business rule for [Z]\n- [ ] Guessing that [A] means [B]\n\n## Questions for Backend\n- Would it make sense to combine [X] and [Y]?\n- Should I expect [Z] to always be present?\n- Is there existing data I can reuse for [W]?\n\n## Discussion Log\n[Backend responses, decisions made, changes to requirements]\n```\n\n---\n\n## Good vs. Bad Requests\n\n### Bad (Dictating Implementation)\n> \"I need a GET /api/contracts endpoint that returns an array with fields: id, title, status, created_at\"\n\n### Good (Describing Needs)\n> \"I need to show a list of contracts. Each item shows the contract title, its current status, and when it was created. User should be able to filter by status.\"\n\n### Bad (Assuming Structure)\n> \"The provider object should be nested inside the contract response\"\n\n### Good (Describing Relationship)\n> \"For each contract, I need to show who the provider is (their name and maybe logo)\"\n\n### Bad (No Context)\n> \"I need contract data\"\n\n### Good (With Context)\n> \"On the dashboard, there''s a ''Recent Contracts'' widget showing the 5 most recent contracts. User clicks one to go to detail page.\"\n\n---\n\n## Encouraging Pushback\n\nInclude these prompts in your requirements:\n\n- \"Let me know if this doesn''t make sense for how the data is structured\"\n- \"Open to suggestions on a better approach\"\n- \"Not sure if this is the right way to think about it\"\n- \"Push back if this complicates things unnecessarily\"\n\n**Good collaboration = frontend describes the problem, backend proposes the solution.**\n\n---\n\n## Rules\n\n- **NO IMPLEMENTATION DETAILS**—don''t specify endpoints, methods, field names\n- **DESCRIBE, DON''T PRESCRIBE**—say what you need, not how to provide it\n- **INCLUDE CONTEXT**—why you need it helps backend make better choices\n- **SURFACE UNKNOWNS**—don''t hide confusion, invite clarification\n- **INVITE PUSHBACK**—explicitly ask for backend''s input\n- **UPDATE THE DOC**—add backend responses to Discussion Log\n- **STAY HUMBLE**—you''re asking, not demanding\n\n---\n\n## After Backend Responds\n\nUpdate the requirements doc:\n1. Add responses to Discussion Log\n2. Adjust requirements based on feedback\n3. Mark resolved uncertainties\n4. Note any decisions made\n\nThe doc becomes the source of truth for what was agreed.\n"},"lastSynced":"2026-03-08T02:04:24.034Z","agentAnalysis":{"suitability":{"en":"Perfect for Full Stack Agents needing seamless frontend-to-backend communication for data requirements documentation.","zh":"适合需要无缝前端到后端通信以满足数据要求文档的全栈代理","ja":"フルスタックエージェントが前端とバックエンドの間でシームレスなコミュニケーションを必要とするデータ要件のドキュメント化に適しています","ko":"데이터 요구 사항 문서화를 위해 프런트엔드와 백엔드 간에 무결점 통신이 필요한 풀스택 에이전트에게 적합합니다","es":"Perfecto para Agentes de Full Stack que necesitan una comunicación sin problemas entre frontend y backend para la documentación de requisitos de datos.","fr":"Parfait pour les agents Full Stack ayant besoin d''une communication fluide entre le frontend et le backend pour la documentation des exigences de données.","de":"Perfekt für Full-Stack-Agents, die eine nahtlose Kommunikation zwischen Frontend und Backend für die Dokumentation von Datenanforderungen benötigen.","pt":"Perfeito para Agentes Full Stack que necessitam de uma comunicação sem interrupções entre frontend e backend para documentação de requisitos de dados.","ru":"Идеально подходит для полно-функциональных агентов, которым требуется бесперебойная связь между frontend и backend для документации требований к данным.","ar":"مثالي للوكلاء الكاملون الذين يحتاجون إلى تواصل سلس بين الواجهة الأمامية والخلفية لتوثيق متطلبات البيانات."},"recommendation":{"en":"Empowers agents to generate comprehensive backend requirements documents in Markdown format, focusing on data needs without worrying about implementation details like endpoints, field names, or API structure, using files like `.claude/docs/ai/<feature-name>/backend-requirements.md`.","zh":"赋予代理生成全面后端需求文档的能力，以Markdown格式关注数据需求，而不必担心诸如端点、字段名称或API结构等实现细节，使用诸如`.claude/docs/ai/<feature-name>/backend-requirements.md`的文件","ja":"エージェントが、 端点、フィールド名、またはAPI構造などの実装の詳細を心配することなく、データの要件に焦点を当てて、Markdown形式で全面的なバックエンドの要件文書を生成する能力を提供します。`.claude/docs/ai/<feature-name>/backend-requirements.md`などのファイルを使用します","ko":"에이전트가 구현 세부 정보(예: 엔드포인트, 필드 이름, API 구조) 없이 데이터 요구 사항에 중점을 두고 마크다운 형식으로 포괄적인 백엔드 요구 사항 문서를 생성할 수 있는 능력을 제공합니다. `.claude/docs/ai/<feature-name>/backend-requirements.md`와 같은 파일을 사용합니다","es":"Habilita a los agentes a generar documentos de requisitos de backend completos en formato Markdown, centrándose en las necesidades de datos sin preocuparse por detalles de implementación como puntos finales, nombres de campos o estructura de API, utilizando archivos como `.claude/docs/ai/<feature-name>/backend-requirements.md`.","fr":"Permet aux agents de générer des documents de exigences de backend complets au format Markdown, en se concentrant sur les besoins de données sans se soucier des détails d''implémentation tels que les points de terminaison, les noms de champs ou la structure de l''API, en utilisant des fichiers tels que `.claude/docs/ai/<feature-name>/backend-requirements.md`.","de":"Ermöglicht es den Agenten, umfassende Dokumente für Backend-Anforderungen im Markdown-Format zu generieren, wobei der Fokus auf die Datenanforderungen gelegt wird, ohne sich um Implementierungsdetails wie Endpunkte, Feldnamen oder API-Struktur zu kümmern, unter Verwendung von Dateien wie `.claude/docs/ai/<feature-name>/backend-requirements.md`.","pt":"Habilita os agentes a gerar documentos abrangentes de requisitos de backend no formato Markdown, focando nas necessidades de dados sem se preocupar com detalhes de implementação como endpoints, nomes de campos ou estrutura de API, usando arquivos como `.claude/docs/ai/<feature-name>/backend-requirements.md`.","ru":"Позволяет агентам генерировать всесторонние документы требований к backend в формате Markdown, сосредотачиваясь на потребностях в данных без беспокойства о деталях реализации, таких как конечные точки, имена полей или структура API, используя файлы типа `.claude/docs/ai/<feature-name>/backend-requirements.md`.","ar":"تمكن الوكلاء من توليد مستندات شاملة لمتطلبات الخلفية بالتنسيق Markdown، مع التركيز على احتياجات البيانات دون القلق بشأن تفاصيل التنفيذ مثل نقاط النهاية أو أسماء الحقول أو هيكل واجهة برمجة التطبيقات، باستخدام ملفات مثل `.claude/docs/ai/<feature-name>/backend-requirements.md`."},"useCases":{"en":["Documenting data needs for new features","Specifying backend API requirements","Collaborating with backend developers on data implementation details"],"zh":["记录新功能的数据需求","指定后端API的需求","与后端开发人员合作处理数据实现的细节"],"ja":["新しい機能のデータの要件を文書化する","バックエンドAPIの要件を指定する","バックエンド開発者とデータの実装の詳細について共同作業する"],"ko":["새로운 기능의 데이터 요구 사항을 문서화하는 것","백엔드 API 요구 사항을 지정하는 것","데이터 구현 세부 정보에 대한 백엔드 개발자와의 협업"],"es":["Documentar las necesidades de datos para nuevas características","Especificar los requisitos de la API de backend","Colaborar con los desarrolladores de backend en los detalles de implementación de datos"],"fr":["Documenter les besoins de données pour les nouvelles fonctionnalités","Spécifier les exigences de l''API de backend","Collaborer avec les développeurs de backend sur les détails d''implémentation des données"],"de":["Dokumentation der Datenanforderungen für neue Funktionen","Spezifizierung der Anforderungen an die Backend-API","Zusammenarbeit mit den Backend-Entwicklern bei den Details der Datenimplementierung"],"pt":["Documentar necessidades de dados para novos recursos","Especificar requisitos de API de backend","Colaborar com desenvolvedores de backend em detalhes de implementação de dados"],"ru":["Документирование потребностей в данных для новых функций","Указание требований к API backend","Сотрудничество с разработчиками backend в деталях реализации данных"],"ar":["توثيق احتياجات البيانات لالميزات الجديدة","تحديد متطلبات واجهة برمجة التطبيقات الخلفية","التعاون مع مبرمجي الخلفية في تفاصيل تنفيذ البيانات"]},"limitations":{"en":["No implementation details allowed","Output limited to `.claude/docs/ai/<feature-name>/backend-requirements.md` files","Requires adherence to Backend Requirements Mode guidelines"],"zh":["不允许包含实现细节","输出仅限于`.claude/docs/ai/<feature-name>/backend-requirements.md`文件","需要遵守后端需求模式指南"],"ja":["実装の詳細を含めることができない","出力は`.claude/docs/ai/<feature-name>/backend-requirements.md`ファイルに限定される","バックエンドの要件モードのガイドラインを遵守する必要がある"],"ko":["구현 세부 정보를 포함할 수 없음","출력은 `.claude/docs/ai/<feature-name>/backend-requirements.md` 파일로만 제한됨","백엔드 요구 사항 모드 지침을 준수해야 함"],"es":["No se permiten detalles de implementación","La salida se limita a archivos `.claude/docs/ai/<feature-name>/backend-requirements.md`","Requiere la adhesión a las pautas del modo de requisitos de backend"],"fr":["Aucun détail d''implémentation n''est autorisé","La sortie est limitée aux fichiers `.claude/docs/ai/<feature-name>/backend-requirements.md`","Requiert l''adhésion aux directives du mode d''exigences de backend"],"de":["Keine Implementierungsdetails erlaubt","Die Ausgabe ist auf Dateien `.claude/docs/ai/<feature-name>/backend-requirements.md` beschränkt","Erfordert die Einhaltung der Richtlinien für den Backend-Anforderungsmodus"],"pt":["Não são permitidos detalhes de implementação","Saída limitada a arquivos `.claude/docs/ai/<feature-name>/backend-requirements.md`","Exige aderência às diretrizes do Modo de Requisitos de Backend"],"ru":["Не допускаются детали реализации","Выход ограничен файлами `.claude/docs/ai/<feature-name>/backend-requirements.md`","Требуется соблюдение руководящих принципов Режима требований к backend"],"ar":["لا يسمح بالتفاصيل التنفيذية","الإخراج مقيد بملفات `.claude/docs/ai/<feature-name>/backend-requirements.md`","يتطلب الالتزام بإرشادات وضع متطلبات الخلفية"]},"version":4},"contentHash":"d29acfeac522b3d6cf396a4ecce85803d08ed62b97c92b61055b4d5499c1e150","qualityScore":57}');
