INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WILLOSCAR/research-units-pipeline-skills/opener-variator', 'opener-variator', 'WILLOSCAR', 'research-units-pipeline-skills', 'community', 'opener-variator WILLOSCAR research-units-pipeline-skills community The opener-variator skill rewrites the first paragraph of flagged H3 files, preserving argument moves and citations. It''s designed for developers working with semantic execution units and evidence-first methodology. Opener Variator是一种AIエージェント技能，用于优化H3文件的第一段落 Opener Variatorは、H3ファイルの最初の段落を最適化するAIエージェントスキルです Opener Variator는 H3 파일의 첫 번째段落를 최적화하는 AI 에이전트 스킬입니다 Opener Variator es una habilidad que reescribe el primer párrafo de documentos H3 para mejorar la claridad y coherencia Opener Variator est une compétence qui réécrit le premier paragraphe de documents H3 pour améliorer la clarté et la cohérence Opener Variator ist eine Fähigkeit, die den ersten Absatz von H3-Dokumenten umschreibt, um Klarheit und Kohärenz zu verbessern O Opener Variator é uma habilidade que pesquisa pipelines como unidades de execução semântica, declarando inputs, outputs e critérios de aceitação ИИ Агент Opener Variator исследует пайплайны как семантические единицы выполнения, объявляя входные и выходные данные, а также критерии принятия مفتاح البداية المتغير هو مهارة تبحث خطوط أنابيب البحث كوحدات تنفيذ семантиكية، وتعلن بيانات الدخول والخروج ومعايير القبول how to use opener-variator opener-variator setup guide H3 file optimization semantic execution units evidence-first methodology opener-variator alternative opener-variator install rewriting automation tells improving content structure Opener Variator AIエージェント H3文件优化 第一段落修复 结构优化 output/WRITER_SELFLOOP_TODO.md Style Smells Rewrites the first paragraph of flagged H3 files Preserves argument moves and citations Works with semantic execution units Utilizes evidence-first methodology Processes `output/WRITER_SELFLOOP_TODO.md` files References `secti` sections for context Opener-variator is a skill that rewrites H3 file introductions, fixing high-signal automation tells and maintaining content integrity.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('renocrypt/latex-arxiv-SKILL/arxiv-paper-writer', 'community', 'renocrypt', 'latex-arxiv-SKILL', 'renocrypt/latex-arxiv-SKILL', 'arxiv-paper-writer', 0, 0, 57, '2026-03-08T01:57:15.380Z', '2026-03-08T02:05:35.736Z', 'd38960dce83becae3a92cb6569e41d6512a353777a89e79d3de6972a262558e1', '{"id":"renocrypt/latex-arxiv-SKILL/arxiv-paper-writer","name":"arxiv-paper-writer","description":{"en":"The arxiv-paper-writer skill automates the LaTeX workflow for ML/AI review papers on arXiv, verifying BibTeX citations end-to-end. It benefits developers and researchers working with LaTeX and BibTeX.","zh":"arxiv-paper-writer技能提供了ML/AI审稿论文的LaTeX和BibTeX工作流程，支持IEEEtran模板和引用验证","ja":"arxiv-paper-writer AIエージェントは、ML/AIレビュー論文のLaTeXとBibTeXワークフローを提供し、IEEEtranテンプレートと引用検証をサポート","ko":"arxiv-paper-writer 스킬은 ML/AI 리뷰 논문의 LaTeX 및 BibTeX 워크플로우를 제공하며 IEEEtran 템플릿 및 참조 검증을 지원","es":"arxiv-paper-writer es una herramienta para crear documentos de revisión de ML/AI con LaTeX y BibTeX, que incluye la validación de citas y el flujo de trabajo de IEEEtran","fr":"arxiv-paper-writer est un outil pour créer des documents de revue de ML/AI avec LaTeX et BibTeX, qui inclut la validation des citations et le workflow IEEEtran","de":"arxiv-paper-writer ist ein Tool zur Erstellung von ML/AI-Überprüfungsberichten mit LaTeX und BibTeX, das die Zitierüberprüfung und den IEEEtran-Workflow umfasst","pt":"O arxiv-paper-writer é uma ferramenta de IA para criar documentos de revisão de ML/AI para arXiv com LaTeX e BibTeX","ru":"arxiv-paper-writer - это инструмент ИИ для создания документов по обзору ML/AI для arXiv с помощью LaTeX и BibTeX","ar":"arxiv-paper-writer هو أداة ذكاء اصطناعي لإنشاء مستندات مراجعة ML/AI ل arXiv باستخدام LaTeX و BibTeX"},"seo":{"title":{"en":"arxiv-paper-writer: LaTeX Workflow Automation for AI Agen...","zh":"arxiv-paper-writer LaTeX Setup Guide","ja":"arxiv-paper-writer AIエージェント LaTeX設定ガイド","ko":"arxiv-paper-writer LaTeX 설정 가이드","es":"Guía de configuración de arxiv-paper-writer para document...","fr":"Guide de mise en route de arxiv-paper-writer pour les doc...","de":"Einrichtungsleitfaden für arxiv-paper-writer zur Erstellu...","pt":"Guia de Configuração do arxiv-paper-writer para Ferrament...","ru":"Руководство по настройке arxiv-paper-writer для ИИ Агентов","ar":"دليل إعداد arxiv-paper-writer لأدوات الذكاء الاصطناعي"},"description":{"en":"Streamline your arXiv review paper workflow with arxiv-paper-writer. Discover how to automate LaTeX and BibTeX citations validation","zh":"使用arxiv-paper-writer技能，简化ML/AI审稿论文的LaTeX和BibTeX工作流程","ja":"arxiv-paper-writer AIエージェントを使用して、ML/AIレビュー論文のLaTeXとBibTeXワークフローを簡素化","ko":"arxiv-paper-writer 스킬을 사용하여 ML/AI 리뷰 논문의 LaTeX 및 BibTeX 워크플로우를 간소화","es":"Aprende a utilizar arxiv-paper-writer para crear documentos de revisión de ML/AI con LaTeX y BibTeX, incluyendo la validación de citas","fr":"Découvrez comment utiliser arxiv-paper-writer pour créer des documents de revue de ML/AI avec LaTeX et BibTeX, y compris la validation des citations","de":"Erfahren Sie, wie Sie arxiv-paper-writer verwenden, um ML/AI-Überprüfungsberichte mit LaTeX und BibTeX zu erstellen, einschließlich der Zitierüberprüfung","pt":"Aprenda a usar o arxiv-paper-writer para criar documentos de revisão de ML/AI para arXiv com LaTeX e BibTeX","ru":"Узнайте, как использовать arxiv-paper-writer для создания документов по обзору ML/AI для arXiv с помощью LaTeX и BibTeX","ar":"تعرف على كيفية استخدام arxiv-paper-writer لإنشاء مستندات مراجعة ML/AI ل arXiv باستخدام LaTeX و BibTeX"},"definition":{"en":"arxiv-paper-writer is a .codex skill that automates the LaTeX workflow for ML/AI review papers on arXiv, utilizing IEEEtran template and verifying BibTeX citations","zh":"arxiv-paper-writer是用于简化ML/AI审稿论文LaTeX和BibTeX工作流程的技能","ja":"arxiv-paper-writerは、ML/AIレビュー論文のLaTeXとBibTeXワークフローを簡素化するAIエージェント","ko":"arxiv-paper-writer는 ML/AI 리뷰 논문의 LaTeX 및 BibTeX 워크플로우를 간소화하는 스킬","es":"arxiv-paper-writer es una herramienta de inteligencia artificial que ayuda a crear documentos de revisión de ML/AI con LaTeX y BibTeX","fr":"arxiv-paper-writer est un outil d''intelligence artificielle qui aide à créer des documents de revue de ML/AI avec LaTeX et BibTeX","de":"arxiv-paper-writer ist ein KI-Tool, das bei der Erstellung von ML/AI-Überprüfungsberichten mit LaTeX und BibTeX hilft","pt":"O que é arxiv-paper-writer? Uma ferramenta de IA para criar documentos de revisão de ML/AI","ru":"Что такое arxiv-paper-writer? Инструмент ИИ для создания документов по обзору ML/AI","ar":"ما هو arxiv-paper-writer؟ أداة ذكاء اصطناعي لإنشاء مستندات مراجعة ML/AI"},"features":{"en":["Scaffolds LaTeX projects using IEEEtran template","Verifies BibTeX citations end-to-end for accuracy","Validates and repairs citations in existing LaTeX projects","Supports topic description and constraint inputs for customization","Automates citation validation for ML/AI review papers on arXiv"],"zh":["支持IEEEtran模板","LaTeX和BibTeX工作流程","引用验证和修复","支持现有项目的引用验证"],"ja":["IEEEtranテンプレートのサポート","LaTeXとBibTeXワークフロー","引用検証と修復","既存プロジェクトの引用検証のサポート"],"ko":["IEEEtran 템플릿 지원","LaTeX 및 BibTeX 워크플로우","참조 검증 및 修复","既存 프로젝트의 참조 검증 지원"],"es":["Scaffold de LaTeX para documentos de revisión de ML/AI","Verificación de citas con BibTeX","Flujo de trabajo de IEEEtran para documentos de revisión","Validación de citas y reparación de errores","Compatibilidad con proyectos LaTeX existentes"],"fr":["Squelette LaTeX pour les documents de revue de ML/AI","Vérification des citations avec BibTeX","Workflow IEEEtran pour les documents de revue","Validation des citations et réparation des erreurs","Compatibilité avec les projets LaTeX existants"],"de":["LaTeX-Skelett für ML/AI-Überprüfungsberichte","Zitierüberprüfung mit BibTeX","IEEEtran-Workflow für Überprüfungsberichte","Zitierüberprüfung und Fehlerbehebung","Kompatibilität mit bestehenden LaTeX-Projekten"],"pt":["Criação de documentos de revisão de ML/AI para arXiv com LaTeX","Verificação de citações BibTeX","Validação de citações em projetos LaTeX existentes","Suporte a template IEEEtran","Limites de página personalizáveis"],"ru":["Создание документов по обзору ML/AI для arXiv с помощью LaTeX","Проверка цитат BibTeX","Валидация цитат в существующих проектах LaTeX","Поддержка шаблона IEEEtran","Настраиваемые ограничения страниц"],"ar":["إنشاء مستندات مراجعة ML/AI ل arXiv باستخدام LaTeX","التحقق من الإشارات المرجعية BibTeX","التحقق من الإشارات المرجعية في مشاريع LaTeX الحالية","دعم قالب IEEEtran","حدود صفحة قابلة للتخصيص"]},"keywords":{"en":["how to use arxiv-paper-writer","arxiv-paper-writer setup guide","LaTeX workflow automation","BibTeX citation validation","arxiv-paper-writer alternative","arxiv-paper-writer vs LaTeX templates","ML/AI review paper workflow","IEEEtran template tutorial","arxiv-paper-writer install"],"zh":["arxiv-paper-writer","LaTeX","BibTeX","ML/AI审稿论文","IEEEtran模板","引用验证","AI工具","latex工作流程"],"ja":["arxiv-paper-writer","LaTeX","BibTeX","ML/AIレビュー論文","IEEEtranテンプレート","引用検証","AIエージェント","latexワークフロー"],"ko":["arxiv-paper-writer","LaTeX","BibTeX","ML/AI 리뷰 논문","IEEEtran 템플릿","참조 검증","AI 스킬","latex 워크플로우"],"es":["arxiv-paper-writer","herramientas de inteligencia artificial","documentos de revisión de ML/AI","LaTeX","BibTeX","IEEEtran","validación de citas","creación de documentos"],"fr":["arxiv-paper-writer","outils d''intelligence artificielle","documents de revue de ML/AI","LaTeX","BibTeX","IEEEtran","validation des citations","création de documents"],"de":["arxiv-paper-writer","KI-Tools","ML/AI-Überprüfungsberichte","LaTeX","BibTeX","IEEEtran","Zitierüberprüfung","Erstellung von Dokumenten"],"pt":["arxiv-paper-writer","ferramentas de IA","documentos de revisão de ML/AI","LaTeX","BibTeX","IEEEtran","criação de documentos","verificação de citações","validação de citações"],"ru":["arxiv-paper-writer","ИИ Агенты","документы по обзору ML/AI","LaTeX","BibTeX","IEEEtran","создание документов","проверка цитат","валидация цитат"],"ar":["arxiv-paper-writer","أدوات الذكاء الاصطناعي","مستندات مراجعة ML/AI","LaTeX","BibTeX","IEEEtran","إنشاء مستندات","التحقق من الإشارات المرجعية","التحقق من الإشارات المرجعية"]}},"owner":"renocrypt","repo":"latex-arxiv-SKILL","repoPath":"renocrypt/latex-arxiv-SKILL","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.380Z","topics":[],"category":"community","skillMd":{"name":"arxiv-paper-writer","description":">","bodyPreview":"# ML/AI Review Paper Workflow (IEEEtran template)\n\n## When to Use\n- ML/AI review papers for arXiv (main text ~6-10 pages; references excluded)\n- LaTeX + BibTeX workflow with verified citations\n- Citation validation/repair on existing LaTeX projects\n\n## When NOT to Use\n- Novel experimental research papers (this is a review workflow)\n- Non-academic documents\n\n## Inputs\n- Topic description (required)\n- Constraints: venue, page limit, author/affiliations (optional)\n- Existing project path for citati","body":"# ML/AI Review Paper Workflow (IEEEtran template)\n\n## When to Use\n- ML/AI review papers for arXiv (main text ~6-10 pages; references excluded)\n- LaTeX + BibTeX workflow with verified citations\n- Citation validation/repair on existing LaTeX projects\n\n## When NOT to Use\n- Novel experimental research papers (this is a review workflow)\n- Non-academic documents\n\n## Inputs\n- Topic description (required)\n- Constraints: venue, page limit, author/affiliations (optional)\n- Existing project path for citation validation (optional)\n\n## Outputs\n- `main.tex` (LaTeX source)\n- `ref.bib` (verified BibTeX entries)\n- `IEEEtran.cls`\n- `plan/<timestamp>-<slug>.md`, `issues/<timestamp>-<slug>.csv`\n- Figures/tables; `main.pdf`\n- `notes/literature-notes.md` (optional per-citation notes)\n- `notes/arxiv-registry.sqlite3` (arXiv metadata/BibTeX cache)\n\n**Conventions**: run `python3 scripts/...` from this skill folder (where `scripts/` lives); `<paper_dir>` is the paper/project root (contains `main.tex`, `ref.bib`, `plan/`, `issues/`, `notes/`). Paths like `plan/...` are under `<paper_dir>`. For arXiv discovery/metadata/BibTeX, use `scripts/arxiv_registry.py` (no ad-hoc curl/wget).\n\n---\n\n## Gated Workflow\n\n> Tip: Run `python3 scripts/<script>.py --help` before use.\n> Open reference files only when a step calls them out.\n\n### Non-Negotiable Rules\n1. **No prose in `main.tex`** until plan approved AND issues CSV exists.\n2. First deliverable: research snapshot + outline + clarification questions + draft plan.\n3. **Use plan + issues tracking for all new papers; do not opt out.**\n4. Issues CSV is the execution contract; update `Status` and `Verified_Citations` per issue, and add/split/insert issue rows when scope grows (do not do untracked work).\n5. **Template is fixed**: use IEEEtran two-column layout (`assets/template/IEEEtran.cls`).\n   Treat two-column width as a layout constraint (use two-column floats when needed).\n\n### Gate 0: Research Snapshot + Draft Plan\n1. Confirm constraints (venue, page limit, author block, date range).\n2. Translate the topic into search keywords and run a light discovery pass:\n   10-20 key papers (see `references/research-workflow.md`). After step 4 (once `<paper_dir>` exists), cache arXiv discovery with `arxiv_registry.py search`.\n3. Propose 2-4 candidate titles aligned to the topic.\n4. Scaffold the project folder and draft plan:\n   ```bash\n   python3 scripts/bootstrap_ieee_review_paper.py --stage kickoff --topic \"<topic>\"\n   ```\n   This copies LaTeX templates from `assets/template/`; plan/issues are generated from templates in `assets/`.\n   Initialize arXiv registry (once): `python3 scripts/arxiv_registry.py --project-dir <paper_dir> init`.\n5. Create a **framework skeleton** in `main.tex`\n   (section headings + 2-4 bullets per section + seed citations; **no prose**).\n6. Update the plan file to reflect the framework, proposed titles, and section/subsection plan.\n7. Compile early: `python3 scripts/compile_paper.py --project-dir <paper_dir>`\n   Fix any `Overfull \\hbox` warnings (see Layout Hygiene below).\n8. Return to user:\n    - Proposed outline (5-8 sections, 2-4 bullets each)\n    - Planned visualizations (5+) mapped to sections (see `references/visual-templates.md`)\n    - Clarification questions\n9. **STOP** until user approves.\n\n### Gate 1: Create Issues CSV (after approval)\n1. Check kickoff gate in plan: `- [x] User confirmed scope + outline in chat`.\n2. Create issues CSV (script refuses if gate unchecked):\n   ```bash\n   python3 scripts/bootstrap_ieee_review_paper.py --stage issues --topic \"<topic>\" --with-literature-notes\n   ```\n3. Validate:\n   ```bash\n   python3 scripts/validate_paper_issues.py <paper_dir>/issues/<timestamp>-<slug>.csv\n   ```\n4. If literature notes are enabled, keep short summaries and (optional) abstract snippets to avoid re-search.\n5. The plan may evolve; add/split/insert issues as needed, re‑validate after edits, and keep going until all issues (including inserted ones) are `DONE` or `SKIP` (when feasible, in the same run).\n\n### Phase 2: Per-Issue Writing Loop\nFor each writing issue in the CSV:\n- If an issue balloons (new figure, new subsection, new benchmark set, or a large QA fix), split/insert new issue row(s) (e.g., `W6a`, `Q5`) before proceeding; re-run `python3 scripts/validate_paper_issues.py <issues.csv>`; keep going until all issues are `DONE`/`SKIP`.\n1. **Research**: 8-12 section-specific papers.\n2. **Write**: Never 3 sentences without citations; varied paragraph rhythm\n   (see `references/writing-style.md`).\n   For section intent and structure, use `references/template-usage.md`.\n3. **Visualize**: Match content triggers (see `references/visual-templates.md`).\n   Prioritize single-column sizing; use double-column spans only when necessary (see Layout Hygiene).\n   Cite externally sourced figure content.\n4. **Verify**: Web search + open source page (and PDF if available) before adding to `ref.bib`.\n   For arXiv entries, append BibTeX via `python3 scripts/arxiv_registry.py --project-dir <paper_dir> export-bibtex <arxiv_id> --out-bib <paper_dir>/ref.bib`.\n5. **Update**: Mark issue `DONE` with `Verified_Citations` count.\n6. Compile after meaningful changes; fix `Overfull \\hbox` before marking `DONE`.\n\n### Phase 2.5: Rhythm Refinement\nAfter all writing issues are `DONE`, refine prose section-by-section using the `latex-rhythm-refiner` skill. This step varies sentence/paragraph lengths and removes filler phrases while preserving all citations.\n\n### Phase 3: QA Gate\n1. Run internal QA checklist (see `references/quality-report.md`).\n2. Compile; ensure no `Overfull \\hbox` warnings in `main.log`.\n3. Deliver `main.tex`, `ref.bib`, figures, and `main.pdf`.\n\n---\n\n## Existing Paper Workflow (No Re-Scaffold)\nIf a paper folder already exists, do NOT rerun scaffold:\n```bash\n# Create plan\npython3 scripts/create_paper_plan.py --topic \"<topic>\" --stage plan --output-dir <paper_dir>\n# STOP for approval, then check kickoff gate box\n# Create issues (use timestamp/slug from plan filename/frontmatter)\npython3 scripts/create_paper_plan.py --topic \"<topic>\" --stage issues --timestamp \"<TS>\" --slug \"<slug>\" --output-dir <paper_dir> --with-literature-notes\n```\n\n## Citation-Validation Variant\n1. Treat provided path as LaTeX project root.\n2. Follow `references/citation-workflow.md`.\n3. Use `references/bibtex-guide.md` for BibTeX rules if entries need repair.\n4. Deliver validation report and corrected `ref.bib` if requested.\n\n---\n\n## Success Criteria\n\n**Compilation**: `python3 scripts/compile_paper.py --project-dir <paper_dir>` (exit 0, no \"Citation undefined\" warnings). Use `--report-page-counts` for main-text page count.\n\n**Quality Metrics**:\n- 6-10 pages of main text (references excluded)\n- 60-80 total citations (8+ per section)\n- 100% citation verification rate\n- 70%+ citations from last 3 years\n- 5+ visualization types\n- All issues `DONE` or `SKIP`\n\n---\n\n## Safety & Guardrails\n- **Never fabricate** citations or results; add TODO and ask user if evidence missing.\n- **Verify every citation** via web search + source page (and PDF if available) before adding to `ref.bib`.\n- **Confirm before** large literature searches.\n- **Do not overwrite** user files without confirmation.\n- **Issues CSV** is the contract; mark `DONE` only when criteria met.\n- **No submission bundles** unless user requests.\n\n## Layout Hygiene\nFix `Overfull \\hbox` warnings before marking issues `DONE`:\n- Figures: start with `figure` + `\\columnwidth`; switch to `figure*` + `\\textwidth` if needed\n- Tables: prefer `p{...}` column widths / `\\tabcolsep` over `\\resizebox`\n- Equations: use `split`, `multline`, `aligned`, or `IEEEeqnarray` for line-breaking\n\n---\n\n## Issues CSV Schema\n| Phase | Issues |\n|-------|--------|\n| Research | Rx: discovery, scaffolding, framework, viz planning |\n| Writing | Wx: each section with target citations and visualization |\n| Refinement | RFx: apply `latex-rhythm-refiner` skill (after all Wx DONE) |\n| QA | Qx: citation verification, QA checklist, compilation, final review |\n\nStatus: `TODO` → `DOING` → `DONE`. Schema validated by `validate_paper_issues.py`.\n"},"lastSynced":"2026-03-08T02:05:35.736Z","agentAnalysis":{"suitability":{"en":"Perfect for Research Agents needing automated LaTeX workflows for ML/AI review papers on arXiv.","zh":"非常适合需要自动化LaTeX工作流的研究代理，以便于在arXiv上审阅机器学习/人工智能论文","ja":"Research Agentsが自動化されたLaTeXワークフローを必要とする場合に最適です。arXivでのML/AIレビュー論文用に","ko":"연구 에이전트가 자동화된 LaTeX 워크플로우를 필요로 하는 경우에 적합합니다. arXiv의 ML/AI 리뷰 논문용으로","es":"Perfecto para agentes de investigación que necesitan flujos de trabajo automatizados de LaTeX para artículos de revisión de ML/AI en arXiv.","fr":"Parfait pour les agents de recherche ayant besoin de flux de travail LaTeX automatisés pour les articles de revue ML/AI sur arXiv.","de":"Perfekt für Forschungsagenten, die automatisierte LaTeX-Workflows für ML/AI-Überprüfungsarbeiten auf arXiv benötigen.","pt":"Perfeito para Agentes de Pesquisa que necessitam de fluxos de trabalho LaTeX automatizados para artigos de revisão de ML/AI no arXiv.","ru":"Идеально для агентов-исследователей, которым необходимы автоматизированные рабочие процессы LaTeX для статей по обзору ML/AI в arXiv.","ar":"مثالي للوكلاء البحثيين الذين يحتاجون إلى سير عمل LaTeX آلي للورقات البحثية التي تحتاج إلى مراجعة ML/AI على arXiv."},"recommendation":{"en":"Empowers agents to automate the LaTeX workflow for ML/AI review papers, verifying BibTeX citations end-to-end, and providing a seamless IEEEtran template integration with citation validation and repair capabilities using LaTeX and BibTeX protocols.","zh":"赋予代理自动化LaTeX工作流的能力，用于ML/AI审阅论文，验证BibTeX引用，从头到尾，并提供无缝的IEEEtran模板集成，具有引用验证和修复能力，使用LaTeX和BibTeX协议","ja":"エージェントにLaTeXワークフローを自動化する能力を与え、ML/AIレビューペーパーのBibTeX引用をエンドツーエンドで検証し、LaTeXとBibTeXのプロトコルを使用して、シームレスなIEEEtranテンプレート統合を提供する","ko":"에이전트에게 LaTeX 워크플로우를 자동화하는 능력을 부여하여, ML/AI 리뷰 논문의 BibTeX 인용을 끝에서 끝까지 검증하고, LaTeX와 BibTeX 프로토콜을 사용하여 무ヒ즈의 IEEEtran 템플릿 통합을 제공함","es":"Habilita a los agentes a automatizar el flujo de trabajo de LaTeX para artículos de revisión de ML/AI, verificando las citas de BibTeX de extremo a extremo, y proporcionando una integración sin problemas del template IEEEtran con capacidades de validación y reparación de citas utilizando protocolos de LaTeX y BibTeX.","fr":"Permet aux agents d''automatiser le flux de travail LaTeX pour les articles de revue ML/AI, en vérifiant les citations BibTeX de bout en bout, et en fournissant une intégration sans problème du modèle IEEEtran avec des capacités de validation et de réparation de citations en utilisant les protocoles LaTeX et BibTeX.","de":"Ermächtigt die Agenten, den LaTeX-Workflow für ML/AI-Überprüfungsarbeiten zu automatisieren, indem sie BibTeX-Zitate von Ende zu Ende überprüfen und eine nahtlose Integration des IEEEtran-Templates mit Zitiervalidierungs- und Reparaturfunktionen unter Verwendung von LaTeX- und BibTeX-Protokollen bereitstellen.","pt":"Habilita os agentes a automatizar o fluxo de trabalho LaTeX para artigos de revisão de ML/AI, verificando citações BibTeX de ponta a ponta e fornecendo uma integração de modelo IEEEtran sem problemas com capacidades de validação e reparo de citações usando protocolos LaTeX e BibTeX.","ru":"Наделяет агентов возможностью автоматизировать рабочий процесс LaTeX для статей по обзору ML/AI, проверяя цитаты BibTeX от начала до конца и обеспечивая бесперебойную интеграцию шаблона IEEEtran с возможностями проверки и исправления цитат с использованием протоколов LaTeX и BibTeX.","ar":"تمكّن الوكلاء من توفير سير عمل LaTeX آلي للورقات البحثية التي تحتاج إلى مراجعة ML/AI، والتحقق من الإشارات المرجعية BibTeX من النهاية إلى النهاية، وتوفير تكامل سلس لنموذج IEEEtran مع إمكانيات التحقق والإصلاح للتقديمات باستخدام بروتوكولات LaTeX وBibTeX."},"useCases":{"en":["Automating ML/AI review paper submissions to arXiv with verified citations","Generating and validating BibTeX citations for existing LaTeX projects","Streamlining the LaTeX workflow for researchers and developers working with ML/AI review papers"],"zh":["使用经过验证的引用将ML/AI审阅论文提交到arXiv","为现有的LaTeX项目生成和验证BibTeX引用","简化研究人员和开发人员处理ML/AI审阅论文的LaTeX工作流"],"ja":["検証された引用を使用してML/AIレビューペーパーをarXivに提出する","既存のLaTeXプロジェクトのBibTeX引用を生成し検証する","ML/AIレビューペーパーのLaTeXワークフローを研究者や開発者が簡素化する"],"ko":["검증된 引用的를 사용하여 ML/AI 리뷰 논문을 arXiv에 제출하는 것","기존의 LaTeX 프로젝트 için BibTeX 引用的를 생성하고 검증하는 것","ML/AI 리뷰 논문에 대한 LaTeX 워크플로우를 연구자와 개발자가 간소화하는 것"],"es":["Automatizar las presentaciones de artículos de revisión de ML/AI en arXiv con citas verificadas","Generar y validar citas de BibTeX para proyectos de LaTeX existentes","Optimizar el flujo de trabajo de LaTeX para investigadores y desarrolladores que trabajan con artículos de revisión de ML/AI"],"fr":["Automatiser les soumissions d''articles de revue ML/AI sur arXiv avec des citations vérifiées","Générer et valider les citations BibTeX pour les projets LaTeX existants","Optimiser le flux de travail LaTeX pour les chercheurs et les développeurs travaillant sur les articles de revue ML/AI"],"de":["Automatisieren der Einreichungen von ML/AI-Überprüfungsarbeiten bei arXiv mit verifizierten Zitaten","Generieren und Validieren von BibTeX-Zitaten für bestehende LaTeX-Projekte","Optimieren des LaTeX-Workflows für Forscher und Entwickler, die mit ML/AI-Überprüfungsarbeiten arbeiten"],"pt":["Automatizar a submissão de artigos de revisão de ML/AI para o arXiv com citações verificadas","Gerar e validar citações BibTeX para projetos LaTeX existentes","Racionalizar o fluxo de trabalho LaTeX para pesquisadores e desenvolvedores que trabalham com artigos de revisão de ML/AI"],"ru":["Автоматизировать подачу статей по обзору ML/AI в arXiv с проверенными цитатами","Генерировать и проверять цитаты BibTeX для существующих проектов LaTeX","Оптимизировать рабочий процесс LaTeX для исследователей и разработчиков, работающих со статьями по обзору ML/AI"],"ar":["توفير آلي لتقديم الورقات البحثية التي تحتاج إلى مراجعة ML/AI إلى arXiv مع الإشارات المرجعية المحددة","توليد وتحقق من الإشارات المرجعية BibTeX لمشاريع LaTeX الحالية","تبسيط سير عمل LaTeX للباحثين والمطورين الذين يعملون مع الورقات البحثية التي تحتاج إلى مراجعة ML/AI"]},"limitations":{"en":["Limited to ML/AI review papers, excluding novel experimental research papers","Requires LaTeX and BibTeX workflow","Not suitable for non-academic documents"],"zh":["仅限于ML/AI审阅论文，不包括新颖的实验研究论文","需要LaTeX和BibTeX工作流","不适用于非学术文档"],"ja":["ML/AIレビューペーパーに限定され、新規の実験研究ペーパーは除く","LaTeXとBibTeXのワークフローが必要","非学術的な文書には適さない"],"ko":["ML/AI 리뷰 논문에만 국한되고, 새로울 실험 연구 논문은 제외","LaTeX와 BibTeX 워크플로우가 필요","비 학술적인 문서에는 적합하지 않음"],"es":["Limitado a artículos de revisión de ML/AI, excluyendo artículos de investigación experimental nuevos","Requiere un flujo de trabajo de LaTeX y BibTeX","No es adecuado para documentos no académicos"],"fr":["Limité aux articles de revue ML/AI, excluant les articles de recherche expérimentale nouveaux","Nécessite un flux de travail LaTeX et BibTeX","Non adapté aux documents non académiques"],"de":["Begrenzt auf ML/AI-Überprüfungsarbeiten, ausschließlich neuer experimenteller Forschungsarbeiten","Benötigt einen LaTeX- und BibTeX-Workflow","Nicht geeignet für nicht-akademische Dokumente"],"pt":["Limitado a artigos de revisão de ML/AI, excluindo artigos de pesquisa experimental novos","Exige fluxo de trabalho LaTeX e BibTeX","Não é adequado para documentos não acadêmicos"],"ru":["Ограничен статями по обзору ML/AI, исключая новые экспериментальные исследовательские статьи","Требует рабочего процесса LaTeX и BibTeX","Не подходит для неакадемических документов"],"ar":["محدود بالورقات البحثية التي تحتاج إلى مراجعة ML/AI، باستثناء الأوراق البحثية التجريبية الجديدة","يتطلب سير عمل LaTeX وBibTeX","غير مناسب للوثائق غير الأكاديمية"]},"version":4},"contentHash":"d38960dce83becae3a92cb6569e41d6512a353777a89e79d3de6972a262558e1","qualityScore":57}');
