INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('renocrypt/latex-arxiv-SKILL/arxiv-paper-writer', 'arxiv-paper-writer', 'renocrypt', 'latex-arxiv-SKILL', 'community', 'arxiv-paper-writer renocrypt latex-arxiv-SKILL community The arxiv-paper-writer skill automates the LaTeX workflow for ML/AI review papers on arXiv, verifying BibTeX citations end-to-end. It benefits developers and researchers working with LaTeX and BibTeX. arxiv-paper-writer技能提供了ML/AI审稿论文的LaTeX和BibTeX工作流程，支持IEEEtran模板和引用验证 arxiv-paper-writer AIエージェントは、ML/AIレビュー論文のLaTeXとBibTeXワークフローを提供し、IEEEtranテンプレートと引用検証をサポート arxiv-paper-writer 스킬은 ML/AI 리뷰 논문의 LaTeX 및 BibTeX 워크플로우를 제공하며 IEEEtran 템플릿 및 참조 검증을 지원 arxiv-paper-writer es una herramienta para crear documentos de revisión de ML/AI con LaTeX y BibTeX, que incluye la validación de citas y el flujo de trabajo de IEEEtran arxiv-paper-writer est un outil pour créer des documents de revue de ML/AI avec LaTeX et BibTeX, qui inclut la validation des citations et le workflow IEEEtran arxiv-paper-writer ist ein Tool zur Erstellung von ML/AI-Überprüfungsberichten mit LaTeX und BibTeX, das die Zitierüberprüfung und den IEEEtran-Workflow umfasst O arxiv-paper-writer é uma ferramenta de IA para criar documentos de revisão de ML/AI para arXiv com LaTeX e BibTeX arxiv-paper-writer - это инструмент ИИ для создания документов по обзору ML/AI для arXiv с помощью LaTeX и BibTeX arxiv-paper-writer هو أداة ذكاء اصطناعي لإنشاء مستندات مراجعة ML/AI ل arXiv باستخدام LaTeX و BibTeX how to use arxiv-paper-writer arxiv-paper-writer setup guide LaTeX workflow automation BibTeX citation validation arxiv-paper-writer alternative arxiv-paper-writer vs LaTeX templates ML/AI review paper workflow IEEEtran template tutorial arxiv-paper-writer install arxiv-paper-writer LaTeX BibTeX ML/AI审稿论文 IEEEtran模板 引用验证 AI工具 latex工作流程 Scaffolds LaTeX projects using IEEEtran template Verifies BibTeX citations end-to-end for accuracy Validates and repairs citations in existing LaTeX projects Supports topic description and constraint inputs for customization Automates citation validation for ML/AI review papers on arXiv arxiv-paper-writer is a .codex skill that automates the LaTeX workflow for ML/AI review papers on arXiv, utilizing IEEEtran template and verifying BibTeX citations');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('InterCooperative-Network/icn/icn-gateway-openapi-sync', 'community', 'InterCooperative-Network', 'icn', 'InterCooperative-Network/icn', 'icn-gateway-openapi-sync', 0, 0, 57, '2026-03-08T01:57:15.385Z', '2026-03-08T02:05:47.933Z', '76136cfe64e19b332101f151593bcbd492e61634b1c27e76d9c98e2c03abc473', '{"id":"InterCooperative-Network/icn/icn-gateway-openapi-sync","name":"icn-gateway-openapi-sync","description":{"en":"The icn-gateway-openapi-sync skill automates OpenAPI synchronization for the cooperative internet, benefiting developers by treating API drift as a blocking integration defect. It validates gateway behavior and regenerates OpenAPI specs from the source of truth.","zh":"ICN 网关 OpenAPI 同步是一种 substrate 守护进程，用于将治理转换为通用约束，内核强制执行这些约束","ja":"ICN ゲートウェイ OpenAPI 同期は、ガバナンスを汎用的な制約に変換し、カーネルがこれらの制約を強制実行する substrate 守護プロセスです","ko":"ICN 게이트웨이 OpenAPI 동기화는 가버넌스를 일반적인 제약조건으로 변환하고 커널이 이러한 제약조건을 강제하는 서브스트레이트 데몬입니다","es":"icn-gateway-openapi-sync es un daemon de substrato que trata el desplazamiento de la API como un defecto de integración bloqueante. Valida el comportamiento de la puerta de enlace y regenera la API de OpenAPI desde la fuente de verdad","fr":"icn-gateway-openapi-sync est un daemon de substrat qui traite le décalage de l''API comme un défaut d''intégration bloquant. Il valide le comportement de la passerelle et régénère l''API OpenAPI à partir de la source de vérité","de":"icn-gateway-openapi-sync ist ein Substrat-Daemon, der die API-Drift als ein blockierendes Integrationsdefekt behandelt. Er validiert das Verhalten der Gateways und regeneriert die OpenAPI von der Quelle der Wahrheit","pt":"O icn-gateway-openapi-sync é um daemon de substrato para internet cooperativa, tratando drift de API como defeito de integração","ru":"ИИ Агент icn-gateway-openapi-sync является субстратным демоном для кооперативного интернета, рассматривающим дрифт API как блокирующий дефект интеграции","ar":"وكيل icn-gateway-openapi-sync هو ديمون من طبقة متوافقة للإنترنت التعاوني ، يتعامل مع انزلاق واجهة برمجة التطبيقات على أنه عيب تكامل"},"seo":{"title":{"en":"icn-gateway-openapi-sync: OpenAPI Sync Setup Guide | AI A...","zh":"ICN 网关 OpenAPI 同步设置指南","ja":"ICN ゲートウェイ OpenAPI 同期ベストプラクティス","ko":"ICN 게이트웨이 OpenAPI 동기화 설정 가이드","es":"Configuración de icn-gateway-openapi-sync: Guía de sincro...","fr":"icn-gateway-openapi-sync : Guide de configuration pour la...","de":"icn-gateway-openapi-sync-Setup: Leitfaden für API-Synchro...","pt":"Guia de Configuração do icn-gateway-openapi-sync para Des...","ru":"ИИ Агенты: Руководство по настройке icn-gateway-openapi-sync","ar":"دليل ضبط icn-gateway-openapi-sync للبرمجة"},"description":{"en":"Automate API drift detection with icn-gateway-openapi-sync. Learn how to sync OpenAPI specs and ensure seamless integration. Get started now!","zh":"使用 ICN 网关 OpenAPI 同步技能，消除 API漂移，确保 gateway 端点合同的一致性","ja":"ICN ゲートウェイ OpenAPI 同期スキルを使用して、API ドリフトを解消し、ゲートウェイ エンドポイント契約の一貫性を確保します","ko":"ICN 게이트웨이 OpenAPI 동기화 스킬을 사용하여 API 드리프트를 제거하고 게이트웨이 엔드포인트 계약의 일관성을 보장합니다","es":"Aprende a configurar icn-gateway-openapi-sync para una integración de API sin problemas. Descubre cómo sincronizar la API y mantener la coherencia","fr":"Découvrez comment configurer icn-gateway-openapi-sync pour une intégration d''API sans faille. Apprenez à synchroniser l''API et à maintenir la cohérence","de":"Erfahren Sie, wie Sie icn-gateway-openapi-sync konfigurieren, um eine problemlose API-Integration zu ermöglichen. Lernen Sie, wie Sie die API synchronisieren...","pt":"Aprenda a configurar o icn-gateway-openapi-sync para tratamento de drift de API e integração de apps","ru":"Изучите, как настроить icn-gateway-openapi-sync для обработки дрифта API и интеграции приложений","ar":"تعلم كيفية ضبط icn-gateway-openapi-sync لمعالجة انزلاق واجهة برمجة التطبيقات وتكامل التطبيقات"},"definition":{"en":"icn-gateway-openapi-sync is a substrate daemon that enforces generic constraints translated from governance, ensuring seamless API integration.","zh":"ICN 网关 OpenAPI 同步是一种用于确保 API 一致性的 substrate 守护进程","ja":"ICN ゲートウェイ OpenAPI 同期は、API の一貫性を確保するための substrate 守護プロセスです","ko":"ICN 게이트웨이 OpenAPI 동기화는 API 일관성을 보장하는 서브스트레이트 데몬입니다","es":"icn-gateway-openapi-sync es un agente de AI que sincroniza la API de OpenAPI para garantizar la coherencia y la integridad de los datos","fr":"icn-gateway-openapi-sync est un agent IA qui synchronise l''API OpenAPI pour garantir la cohérence et l''intégrité des données","de":"icn-gateway-openapi-sync ist ein KI-Agent, der die OpenAPI-API synchronisiert, um die Konsistenz und Integrität der Daten zu gewährleisten","pt":"icn-gateway-openapi-sync é um daemon de substrato que trata drift de API como defeito","ru":"ИИ Агент icn-gateway-openapi-sync - субстратный демон для обработки дрифта API","ar":"وكيل icn-gateway-openapi-sync هو ديمون من طبقة متوافقة لمعالجة انزلاق واجهة برمجة التطبيقات"},"features":{"en":["Validates gateway behavior using `cargo test` command","Regenerates OpenAPI specs from source of truth using `icnctl`","Supports sled-storage feature for data persistence","Automates API drift detection for cooperative internet apps","Enforces endpoint contracts using auth/scopes/status codes","Triggers on changes to `icn/crates/icn-gateway/**` and shared API models"],"zh":["使用 Cargo 测试和构建来验证网关行为","从源代码中重新生成 OpenAPI","支持 sled-storage 功能","确保网关端点合同的一致性","消除 API 漂移","提高 API 一致性和可靠性"],"ja":["Cargo テストとビルドを使用してゲートウェイの動作を検証する","ソースコードから OpenAPI を再生成する","sled-storage 機能をサポートする","ゲートウェイ エンドポイント契約の一貫性を確保する","API ドリフトを解消する","API の一貫性と信頼性を高める"],"ko":["Cargo 테스트와 빌드를 사용하여 게이트웨이 동작을 검증하는","소스 코드에서 OpenAPI를 다시 생성하는","sled-storage 기능을 지원하는","게이트웨이 엔드포인트 계약의 일관성을 보장하는","API 드리프트를 제거하는","API 일관성과 신뢰성을 높이는"],"es":["Validación del comportamiento de la puerta de enlace","Regeneración de la API de OpenAPI desde la fuente de verdad","Uso de cargo para probar y generar la API","Compatibilidad con sled-storage","Integración con icnctl para la exposición de la API"],"fr":["Validation du comportement de la passerelle","Régénération de l''API OpenAPI à partir de la source de vérité","Utilisation de cargo pour tester et générer l''API","Compatibilité avec sled-storage","Intégration avec icnctl pour l''exposition de l''API"],"de":["Validierung des Verhaltens der Gateways","Regenerierung der OpenAPI von der Quelle der Wahrheit","Verwendung von cargo zum Testen und Generieren der API","Kompatibilität mit sled-storage","Integration mit icnctl für die Exposition der API"],"pt":["Validação de comportamento de gateway","Regeneração de OpenAPI a partir da fonte de verdade","Suporte a armazenamento sled","Integração com endpoints de gateway","Gerenciamento de escopos de autenticação","Tratamento de códigos de status"],"ru":["Валидация поведения шлюза","Регенерация OpenAPI из источника правды","Поддержка хранилища sled","Интеграция с конечными точками шлюза","Управление областями аутентификации","Обработка кодов состояния"],"ar":["التحقق من سلوك البوابة","إعادة إنشاء واجهة برمجة التطبيقات مفتوحة من مصدر الحقيقة","دعم تخزين sled","تكامل مع نقاط النهاية البوابة","إدارة نطاقات المصادقة","معالجة رموز الحالة"]},"keywords":{"en":["icn-gateway-openapi-sync setup guide","OpenAPI sync for cooperative internet","API drift detection tools","icn-gateway-openapi-sync vs traditional API integration","how to use icn-gateway-openapi-sync","icn-gateway-openapi-sync install","automating OpenAPI synchronization","cooperative internet development","icn-gateway-openapi-sync tutorial","OpenAPI spec generation"],"zh":["ICN 网关 OpenAPI 同步","AI 에이전트","substrate 守护进程","API 一致性","Cargo 测试","OpenAPI 生成","sled-storage","网关端点合同","API 漂移"],"ja":["ICN ゲートウェイ OpenAPI 同期","AI エージェント","substrate 守護プロセス","API 一貫性","Cargo テスト","OpenAPI 生成","sled-storage","ゲートウェイ エンドポイント契約","API ドリフト"],"ko":["ICN 게이트웨이 OpenAPI 동기화","AI 에이전트","서브스트레이트 데몬","API 일관성","Cargo 테스트","OpenAPI 생성","sled-storage","게이트웨이 엔드포인트 계약","API 드리프트"],"es":["icn-gateway-openapi-sync","sincronización de API","integración de API","validación de comportamiento","regeneración de API","cargo","sled-storage","icnctl","agentes de AI","herramientas de AI"],"fr":["icn-gateway-openapi-sync","synchronisation d''API","intégration d''API","validation de comportement","régénération d''API","cargo","sled-storage","icnctl","agents IA","outils IA"],"de":["icn-gateway-openapi-sync","API-Synchronisierung","API-Integration","Verhaltensvalidierung","API-Regenerierung","cargo","sled-storage","icnctl","KI-Agenten","KI-Tools"],"pt":["icn-gateway-openapi-sync","drift de API","integração de apps","substrato","internet cooperativa","validação de gateway","OpenAPI","armazenamento sled"],"ru":["ИИ Агенты","icn-gateway-openapi-sync","дрифт API","интеграция приложений","субстрат","кооперативный интернет","валидация шлюза","OpenAPI","хранилище sled"],"ar":["وكلاء الذكاء الاصطناعي","icn-gateway-openapi-sync","انزلاق واجهة برمجة التطبيقات","تكامل التطبيقات","طبقة متوافقة","الإنترنت التعاوني","التحقق من البوابة","واجهة برمجة التطبيقات مفتوحة","تخزين sled"]}},"owner":"InterCooperative-Network","repo":"icn","repoPath":"InterCooperative-Network/icn","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.385Z","topics":[],"category":"community","skillMd":{"name":"icn-gateway-openapi-sync","description":"Keep ICN gateway API behavior, exported OpenAPI spec, and generated TypeScript SDK types in sync. Use when modifying icn-gateway routes, request/response models, auth behavior, or any API shape that can cause OpenAPI/SDK drift.","bodyPreview":"# ICN Gateway OpenAPI Sync\n\nTreat API drift as a blocking integration defect.\n\n## Trigger Conditions\n\nUse this skill when changes touch:\n- `icn/crates/icn-gateway/**`\n- shared API models consumed by gateway endpoints\n- auth/scopes/status codes that affect endpoint contracts\n\n## Workflow\n\n1. Validate gateway behavior.\n```bash\ncd icn\ncargo test -p icn-gateway --features sled-storage\n```\n\n2. Regenerate OpenAPI from source of truth.\n```bash\ncd icn\ncargo build -p icnctl\n./target/debug/icnctl api expo","body":"# ICN Gateway OpenAPI Sync\n\nTreat API drift as a blocking integration defect.\n\n## Trigger Conditions\n\nUse this skill when changes touch:\n- `icn/crates/icn-gateway/**`\n- shared API models consumed by gateway endpoints\n- auth/scopes/status codes that affect endpoint contracts\n\n## Workflow\n\n1. Validate gateway behavior.\n```bash\ncd icn\ncargo test -p icn-gateway --features sled-storage\n```\n\n2. Regenerate OpenAPI from source of truth.\n```bash\ncd icn\ncargo build -p icnctl\n./target/debug/icnctl api export-openapi -o ../docs/api/openapi.generated.yaml\n```\n\n3. Regenerate TypeScript types.\n```bash\ncd sdk/typescript\nnpm ci\nnpm run generate-types\nnpm run check-types\nnpm run build\nnpm test\nnpm run lint\n```\n\n4. Confirm drift status.\n```bash\ngit status --short docs/api/openapi.generated.yaml sdk/typescript\n```\n- If generated artifacts changed, include them in the same PR.\n- If artifacts did not change, state that explicitly.\n\n5. Validate docs alignment.\n- Update docs for changed semantics or response behavior.\n- Ensure auth gating semantics match implementation.\n\n## Guardrails\n\n- Do not hand-edit generated OpenAPI/types.\n- Do not hide API changes by skipping regeneration.\n- Keep error/status semantics explicit and documented.\n\n## Output Contract\n\nReturn:\n1. whether gateway API surface changed,\n2. generated files changed or unchanged,\n3. commands run with pass/fail outcome,\n4. follow-up docs/spec tasks if any.\n"},"lastSynced":"2026-03-08T02:05:47.933Z","agentAnalysis":{"suitability":{"en":"Perfect for API Management Agents needing automated OpenAPI synchronization and validation for cooperative internet development.","zh":"非常适合需要自动化OpenAPI同步和验证的API管理代理，以进行合作互联网开发。","ja":"API Management Agentsが自動化されたOpenAPI同期と検証を必要とする場合に最適です。協力的なインターネット開発のために。","ko":"자동화된 OpenAPI 동기화 및 검증이 필요한 API 관리 에이전트에게 적합합니다. 협력적인 인터넷 개발을 위해.","es":"Perfecto para agentes de gestión de API que necesitan una sincronización y validación automatizadas de OpenAPI para el desarrollo de internet cooperativo.","fr":"Parfait pour les agents de gestion d''API nécessitant une synchronisation et une validation automatisées d''OpenAPI pour le développement d''internet coopératif.","de":"Perfekt für API-Management-Agents, die eine automatisierte OpenAPI-Synchronisierung und -Validierung für die kooperative Internetentwicklung benötigen.","pt":"Perfeito para Agentes de Gerenciamento de API que necessitam de sincronização automática OpenAPI e validação para desenvolvimento de internet cooperativo.","ru":"Идеально подходит для агентов управления API, которым требуется автоматическая синхронизация и валидация OpenAPI для кооперативного развития интернета.","ar":"مثالي للوكلاء إدارة واجهة برمجة التطبيقات الذين يحتاجون إلى تنسيقautomated واجهة برمجة التطبيقات مفتوحة و التحقق من صحتها للتنمية الشبكية التعاونية."},"recommendation":{"en":"Empowers agents to treat API drift as a blocking integration defect by validating gateway behavior and regenerating OpenAPI specs from the source of truth, utilizing Cargo and OpenAPI protocols.","zh":"赋予代理以将API漂移视为阻塞集成缺陷的能力，通过验证网关行为并从真实源头再生成OpenAPI规范，利用Cargo和OpenAPI协议。","ja":"APIドリフトをブロッキング統合欠陥として扱うエージェントを可能にします。ゲートウェイの動作を検証し、真実の源からOpenAPI仕様を再生成します。CargoとOpenAPIプロトコルを利用しています。","ko":"API 드리프트를 차단 통합 결함으로 처리하는 에이전트를 가능하게 합니다. 게이트웨이 동작을 검증하고 진실의 원천에서 OpenAPI 사양을 다시 생성하여 Cargo와 OpenAPI 프로토콜을 활용합니다.","es":"Habilita a los agentes a tratar el desajuste de API como un defecto de integración de bloqueo, validando el comportamiento de la puerta de enlace y regenerando las especificaciones de OpenAPI desde la fuente de verdad, utilizando los protocolos Cargo y OpenAPI.","fr":"Permet aux agents de traiter le décalage d''API comme un défaut d''intégration de blocage, en validant le comportement de la passerelle et en régénérant les spécifications OpenAPI à partir de la source de vérité, en utilisant les protocoles Cargo et OpenAPI.","de":"Ermächtigt die Agenten, API-Drift als blockierendes Integrationsdefekt zu behandeln, indem sie das Gateway-Verhalten validieren und die OpenAPI-Spezifikationen aus der Quelle der Wahrheit neu generieren, wobei die Protokolle Cargo und OpenAPI verwendet werden.","pt":"Habilita os agentes a tratar a deriva da API como um defeito de integração de bloqueio, validando o comportamento do gateway e regenerando especificações OpenAPI da fonte de verdade, utilizando protocolos Cargo e OpenAPI.","ru":"Наделяет агентов возможностью рассматривать дрейф API как блокирующий дефект интеграции, проверяя поведение шлюза и регенерируя спецификации OpenAPI из источника правды, используя протоколы Cargo и OpenAPI.","ar":"يتمكّن الوكلاء من معاملة انحراف واجهة برمجة التطبيقات كعيب تكامل مسدّد، من خلال التحقق من سلوك البوابة وإعادة توليد مواصفات واجهة برمجة التطبيقات المفتوحة من مصدر الصواب، باستخدام بروتوكولات Cargo و واجهة برمجة التطبيقات المفتوحة."},"useCases":{"en":["Automating OpenAPI synchronization for cooperative internet gateways","Validating gateway behavior against expected API contracts","Regenerating OpenAPI specifications from source of truth after code changes"],"zh":["为合作互联网网关自动化OpenAPI同步","验证网关行为是否符合预期的API契约","在代码更改后从真实源头再生成OpenAPI规范"],"ja":["協力的なインターネットゲートウェイのOpenAPI同期を自動化する","ゲートウェイの動作を期待されるAPI契約と比較して検証する","コードの変更後、真実の源からOpenAPI仕様を再生成する"],"ko":["협력적인 인터넷 게이트웨이의 OpenAPI 동기화를 자동화하는 것","게이트웨이 동작을 기대되는 API 계약과 비교하여 검증하는 것","코드 변경 후 진실의 원천에서 OpenAPI 사양을 다시 생성하는 것"],"es":["Automatización de la sincronización de OpenAPI para puertas de enlace de internet cooperativo","Validación del comportamiento de la puerta de enlace frente a contratos de API esperados","Regeneración de especificaciones de OpenAPI a partir de la fuente de verdad después de cambios de código"],"fr":["Automatisation de la synchronisation d''OpenAPI pour les passerelles d''internet coopératif","Validation du comportement de la passerelle par rapport aux contrats d''API attendus","Régénération des spécifications OpenAPI à partir de la source de vérité après des changements de code"],"de":["Automatisierung der OpenAPI-Synchronisierung für kooperative Internet-Gateways","Validierung des Gateway-Verhaltens gegenüber erwarteten API-Verträgen","Neugenerierung von OpenAPI-Spezifikationen aus der Quelle der Wahrheit nach Codeänderungen"],"pt":["Automatizar a sincronização OpenAPI para gateways de internet cooperativa","Validar o comportamento do gateway contra contratos de API esperados","Regenerar especificações OpenAPI a partir da fonte de verdade após alterações de código"],"ru":["Автоматизировать синхронизацию OpenAPI для кооперативных интернет-шлюзов","Проверять поведение шлюза против ожидаемых контрактов API","Регенерировать спецификации OpenAPI из источника правды после изменений кода"],"ar":["تأتمتة تنسيق واجهة برمجة التطبيقات المفتوحة لبوابات الشبكة التعاونية","التحقق من سلوك البوابة مقابل عقود واجهة برمجة التطبيقات المتوقعة","إعادة توليد مواصفات واجهة برمجة التطبيقات المفتوحة من مصدر الصواب بعد تغييرات الشفرة"]},"limitations":{"en":["Requires Cargo and Rust environment for execution","Limited to icn-gateway and shared API models","Needs access to icn/crates/icn-gateway and auth/scopes/status codes"],"zh":["需要Cargo和Rust环境来执行","仅限于icn-gateway和共享API模型","需要访问icn/crates/icn-gateway和auth/scopes/status代码"],"ja":["実行にはCargoとRustの環境が必要","icn-gatewayと共有APIモデルに限定される","icn/crates/icn-gatewayとauth/scopes/statusコードへのアクセスが必要"],"ko":["실행을 위해 Cargo와 Rust 환경이 필요합니다.","icn-gateway와 공유 API 모델에만 제한됩니다.","icn/crates/icn-gateway와 auth/scopes/status 코드에 대한 액세스가 필요합니다."],"es":["Requiere un entorno de Cargo y Rust para la ejecución","Limitado a icn-gateway y modelos de API compartidos","Necesita acceso a icn/crates/icn-gateway y auth/scopes/status codes"],"fr":["Nécessite un environnement Cargo et Rust pour l''exécution","Limité à icn-gateway et modèles d''API partagés","Nécessite un accès à icn/crates/icn-gateway et auth/scopes/status codes"],"de":["Benötigt eine Cargo- und Rust-Umgebung für die Ausführung","Begrenzt auf icn-gateway und gemeinsame API-Modelle","Benötigt Zugriff auf icn/crates/icn-gateway und auth/scopes/Statuscodes"],"pt":["Exige ambiente Cargo e Rust para execução","Limitado a icn-gateway e modelos de API compartilhados","Necessita acesso a icn/crates/icn-gateway e auth/scopes/status codes"],"ru":["Требует среды Cargo и Rust для выполнения","Ограничен до icn-gateway и общих моделей API","Требует доступа к icn/crates/icn-gateway и auth/scopes/status codes"],"ar":["يتطلب بيئة Cargo و Rust للتنفيذ","محدود ل icn-gateway و نماذج واجهة برمجة التطبيقات المشتركة","يحتاج إلى الوصول إلى icn/crates/icn-gateway و auth/scopes/status codes"]},"version":4},"contentHash":"76136cfe64e19b332101f151593bcbd492e61634b1c27e76d9c98e2c03abc473","qualityScore":57}');
