INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('InterCooperative-Network/icn/icn-gateway-openapi-sync', 'icn-gateway-openapi-sync', 'InterCooperative-Network', 'icn', 'community', 'icn-gateway-openapi-sync InterCooperative-Network icn community The icn-gateway-openapi-sync skill automates OpenAPI synchronization for the cooperative internet, benefiting developers by treating API drift as a blocking integration defect. It validates gateway behavior and regenerates OpenAPI specs from the source of truth. ICN 网关 OpenAPI 同步是一种 substrate 守护进程，用于将治理转换为通用约束，内核强制执行这些约束 ICN ゲートウェイ OpenAPI 同期は、ガバナンスを汎用的な制約に変換し、カーネルがこれらの制約を強制実行する substrate 守護プロセスです ICN 게이트웨이 OpenAPI 동기화는 가버넌스를 일반적인 제약조건으로 변환하고 커널이 이러한 제약조건을 강제하는 서브스트레이트 데몬입니다 icn-gateway-openapi-sync es un daemon de substrato que trata el desplazamiento de la API como un defecto de integración bloqueante. Valida el comportamiento de la puerta de enlace y regenera la API de OpenAPI desde la fuente de verdad icn-gateway-openapi-sync est un daemon de substrat qui traite le décalage de l''API comme un défaut d''intégration bloquant. Il valide le comportement de la passerelle et régénère l''API OpenAPI à partir de la source de vérité icn-gateway-openapi-sync ist ein Substrat-Daemon, der die API-Drift als ein blockierendes Integrationsdefekt behandelt. Er validiert das Verhalten der Gateways und regeneriert die OpenAPI von der Quelle der Wahrheit O icn-gateway-openapi-sync é um daemon de substrato para internet cooperativa, tratando drift de API como defeito de integração ИИ Агент icn-gateway-openapi-sync является субстратным демоном для кооперативного интернета, рассматривающим дрифт API как блокирующий дефект интеграции وكيل icn-gateway-openapi-sync هو ديمون من طبقة متوافقة للإنترنت التعاوني ، يتعامل مع انزلاق واجهة برمجة التطبيقات على أنه عيب تكامل icn-gateway-openapi-sync setup guide OpenAPI sync for cooperative internet API drift detection tools icn-gateway-openapi-sync vs traditional API integration how to use icn-gateway-openapi-sync icn-gateway-openapi-sync install automating OpenAPI synchronization cooperative internet development icn-gateway-openapi-sync tutorial OpenAPI spec generation ICN 网关 OpenAPI 同步 AI 에이전트 substrate 守护进程 API 一致性 Cargo 测试 OpenAPI 生成 sled-storage 网关端点合同 API 漂移 Validates gateway behavior using `cargo test` command Regenerates OpenAPI specs from source of truth using `icnctl` Supports sled-storage feature for data persistence Automates API drift detection for cooperative internet apps Enforces endpoint contracts using auth/scopes/status codes Triggers on changes to `icn/crates/icn-gateway/**` and shared API models icn-gateway-openapi-sync is a substrate daemon that enforces generic constraints translated from governance, ensuring seamless API integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('yellinzero/aico/aico-backend-task-breakdown', 'community', 'yellinzero', 'aico', 'yellinzero/aico', 'aico-backend-task-breakdown', 0, 0, 57, '2026-03-08T01:57:15.397Z', '2026-03-08T02:06:24.918Z', '1b05c916a71fdb86ca40c35955273cb174e54d0f237185a51e8512737a580877', '{"id":"yellinzero/aico/aico-backend-task-breakdown","name":"aico-backend-task-breakdown","description":{"en":"The aico-backend-task-breakdown skill enables AI teams to build and manage task breakdowns in seconds. It benefits developers by providing a structured approach to task management.","zh":"aico-backend-task-breakdown技能提供快速任务分解和AI团队构建的解决方案。通过关键规则和最佳实践，立即开始工作","ja":"aico-backend-task-breakdownスキルは、迅速なタスク分解とAIチームの構築を提供します。重要なルールとベストプラクティスを通じて、すぐに作業を開始します","ko":"aico-backend-task-breakdown 스킬은 빠른 태스크 분해와 AI 팀 구축을 제공합니다. 중요한 규칙과 모범 사례를 통해 즉시 작업을 시작합니다","es":"aico-backend-task-breakdown es una habilidad que permite a los desarrolladores crear un desglose de tareas para su equipo de Agentes de IA en segundos","fr":"aico-backend-task-breakdown est une compétence qui permet aux développeurs de créer une décomposition de tâches pour leurs Outils d''IA en quelques secondes","de":"aico-backend-task-breakdown ist eine Fähigkeit, die es Entwicklern ermöglicht, eine Aufgabenzerlegung für ihre KI-Agenten in Sekundenschnelle zu erstellen","pt":"O aico-backend-task-breakdown é uma habilidade que permite criar equipes de IA em segundos, começando a trabalhar imediatamente com tarefas de backend","ru":"ИИ Агенты aico-backend-task-breakdown - это навык, который позволяет создавать команды ИИ за секунды, начиная работать сразу с задачами бэкэнда","ar":"أدوات الذكاء الاصطناعي aico-backend-task-breakdown هي مهارة تمكن من إنشاء فرق الذكاء الاصطناعي في ثوان، والبدء في العمل على الفور مع مهام الباك إند"},"seo":{"title":{"en":"aico-backend-task-breakdown: Task Management Setup Guide ...","zh":"AI工具任务分解设置指南 - aico-backend-task-breakdown","ja":"AIエージェントタスクブレークダウン設定ガイド - aico-backend-task-breakdown","ko":"AI 에이전트 태스크 분해 설정 가이드 - aico-backend-task-breakdown","es":"Guía de configuración de aico-backend-task-breakdown para...","fr":"Guide de démarrage rapide pour aico-backend-task-breakdow...","de":"Setup-Leitfaden für aico-backend-task-breakdown KI-Agenten","pt":"Guia de Configuração do aico-backend-task-breakdown para ...","ru":"Настройка aico-backend-task-breakdown для команд ИИ Агентов","ar":"دليل إعداد aico-backend-task-breakdown لأدوات الذكاء الاص..."},"description":{"en":"Streamline AI team task breakdowns with aico-backend-task-breakdown. Learn how to create and manage tasks efficiently and get started today!","zh":"使用aico-backend-task-breakdown技能，快速构建AI团队，立即开始工作。了解任务分解的关键规则和最佳实践","ja":"aico-backend-task-breakdownスキルを使用して、AIチームを瞬時に構築し、すぐに作業を開始します。タスク分解の重要なルールとベストプラクティスを学びます","ko":"aico-backend-task-breakdown 스킬을 사용하여 AI 팀을 즉시 구축하고 즉시 작업을 시작합니다. 태스크 분해의 중요한 규칙과 모범 사례를 배우세요","es":"Aprende a configurar aico-backend-task-breakdown para tu equipo de Agentes de IA y comienza a trabajar de inmediato","fr":"Découvrez comment configurer aico-backend-task-breakdown pour vos Outils d''IA et commencez à travailler rapidement","de":"Erfahren Sie, wie Sie aico-backend-task-breakdown für Ihre KI-Agenten einrichten und sofort loslegen können","pt":"Aprenda a configurar o aico-backend-task-breakdown para equipes de IA de forma eficiente, seguindo as regras críticas para tarefas de backend","ru":"Узнайте, как настроить aico-backend-task-breakdown для команд ИИ Агентов, соблюдая критические правила для задач бэкэнда","ar":"تعلم كيفية إعداد aico-backend-task-breakdown لأدوات الذكاء الاصطناعي بفعالية، باتباع القواعد الحرجة لأعمال الباك إند"},"definition":{"en":"aico-backend-task-breakdown is a skill that facilitates task breakdown management for AI teams, using Markdown files and a specific naming pattern.","zh":"aico-backend-task-breakdown是AI工具的一种技能，用于快速构建AI团队和任务分解","ja":"aico-backend-task-breakdownは、AIエージェントの迅速な構築とタスク分解に使用されるスキルの一種です","ko":"aico-backend-task-breakdown는 AI 에이전트의 빠른 구축과 태스크 분해에 사용되는 스킬의 한 종류입니다","es":"aico-backend-task-breakdown es una habilidad de desglose de tareas para Agentes de IA que permite a los desarrolladores crear y gestionar tareas de manera eficiente","fr":"aico-backend-task-breakdown est une compétence de décomposition de tâches pour Outils d''IA qui permet aux développeurs de créer et de gérer des tâches de manière efficace","de":"aico-backend-task-breakdown ist eine Fähigkeit zur Aufgabenzerlegung für KI-Agenten, die es Entwicklern ermöglicht, Aufgaben effizient zu erstellen und zu verwalten","pt":"O aico-backend-task-breakdown é uma habilidade de IA que automatiza a criação de tarefas de backend para equipes de desenvolvimento","ru":"ИИ Агенты aico-backend-task-breakdown - это навык, который автоматизирует создание задач бэкэнда для команд разработки","ar":"أدوات الذكاء الاصطناعي aico-backend-task-breakdown هي مهارة تتيح автомatisation إنشاء مهام الباك إند لفرق التطوير"},"features":{"en":["Creates new task breakdown files in Markdown format","Checks for existing task files in the docs/reference/backend/tasks directory","Follows a specific file naming pattern: story-{story-name}.md","Allows for updating existing tasks or adding new ones","Enforces critical rules for task breakdown management, such as never re-breaking down existing tasks"],"zh":["CHECK EXISTING TASK FILE FIRST","FILE NAMING Pattern: story-{story-name}.md","NEVER re-break down existing tasks","创建新任务分解文件","更新现有任务","按照关键规则工作"],"ja":["CHECK EXISTING TASK FILE FIRST","FILE NAMING Pattern: story-{story-name}.md","NEVER re-break down existing tasks","新しいタスク分解ファイルを作成","既存のタスクを更新","重要なルールに従って作業"],"ko":["CHECK EXISTING TASK FILE FIRST","FILE NAMING Pattern: story-{story-name}.md","NEVER re-break down existing tasks","새로운 태스크 분해 파일을 생성","기존 태스크를 업데이트","중요한 규칙을 따라 작업"],"es":["Creación de desglose de tareas en segundos","Comprobación automática de archivos de tareas existentes","Patrón de nombramiento de archivos: story-{story-name}.md","Actualización de tareas existentes o creación de nuevas","Integración con herramientas de desarrollo de backend"],"fr":["Création d''une décomposition de tâches en quelques secondes","Vérification automatique des fichiers de tâches existants","Modèle de nommage de fichiers : story-{story-name}.md","Mise à jour de tâches existantes ou création de nouvelles","Intégration avec des outils de développement de backend"],"de":["Erstellung einer Aufgabenzerlegung in Sekundenschnelle","Automatische Überprüfung von existierenden Aufgabendateien","Dateinamensmuster: story-{story-name}.md","Aktualisierung von bestehenden Aufgaben oder Erstellung neuer","Integration mit Backend-Entwicklungstools"],"pt":["Criação de tarefas de backend em segundos","Verificação automática de arquivos de tarefas existentes","Padrão de nomenclatura de arquivos: story-{story-name}.md","Compatibilidade com equipes de desenvolvimento ágeis","Suporte à criação de novas tarefas e atualização de tarefas existentes"],"ru":["Создание задач бэкэнда за секунды","Автоматическая проверка существующих файлов задач","Паттерн названия файлов: story-{story-name}.md","Совместимость с командами разработки, использующими гибкие методологии","Поддержка создания новых задач и обновления существующих задач"],"ar":["إنشاء مهام الباك إند في ثوان","التحقق التلقائي من ملفات المهام الموجودة","نمط تسمية الملفات: story-{story-name}.md","التوافق مع فرق التطوير التي تستخدم منهجيات سريعة","دعم إنشاء مهام جديدة وتحديث المهام الموجودة"]},"keywords":{"en":["how to use aico-backend-task-breakdown","aico-backend-task-breakdown setup guide","aico-backend-task-breakdown vs other task management tools","aico-backend-task-breakdown install","what is aico-backend-task-breakdown","aico-backend-task-breakdown alternative","task breakdown management for AI teams","Markdown file management","aico-backend-task-breakdown best practices"],"zh":["AI工具","任务分解","aico-backend-task-breakdown","AI团队构建","快速任务分解","关键规则","最佳实践","story-{story-name}.md","CHECK EXISTING TASK FILE FIRST"],"ja":["AIエージェント","タスクブレークダウン","aico-backend-task-breakdown","AIチーム構築","迅速なタスク分解","重要なルール","ベストプラクティス","story-{story-name}.md","CHECK EXISTING TASK FILE FIRST"],"ko":["AI 에이전트","태스크 분해","aico-backend-task-breakdown","AI 팀 구축","빠른 태스크 분해","중요한 규칙","모범 사례","story-{story-name}.md","CHECK EXISTING TASK FILE FIRST"],"es":["aico-backend-task-breakdown","Agentes de IA","desglose de tareas","creación de tareas","gestión de tareas","herramientas de desarrollo de backend","integración con backend","desarrollo de software"],"fr":["aico-backend-task-breakdown","Outils d''IA","décomposition de tâches","création de tâches","gestion de tâches","outils de développement de backend","intégration avec backend","développement de logiciels"],"de":["aico-backend-task-breakdown","KI-Agenten","Aufgabenzerlegung","Erstellung von Aufgaben","Verwaltung von Aufgaben","Backend-Entwicklungstools","Integration mit Backend","Softwareentwicklung"],"pt":["aico-backend-task-breakdown","equipes de IA","tarefas de backend","criação de tarefas","verificação de arquivos","padrão de nomenclatura","desenvolvimento ágil","criação de equipes de IA"],"ru":["ИИ Агенты","aico-backend-task-breakdown","команды ИИ","задачи бэкэнда","создание задач","проверка файлов","паттерн названия файлов","гибкие методологии","создание команд ИИ"],"ar":["أدوات الذكاء الاصطناعي","aico-backend-task-breakdown","فرق الذكاء الاصطناعي","مهام الباك إند","إنشاء مهام","التحقق من الملفات","نمط تسمية الملفات","منهجيات سريعة","إنشاء فرق الذكاء الاصطناعي"]}},"owner":"yellinzero","repo":"aico","repoPath":"yellinzero/aico","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.397Z","topics":[],"category":"community","skillMd":{"name":"aico-backend-task-breakdown","description":"|","bodyPreview":"# Task Breakdown\n\n## ⚠️ CRITICAL RULES - READ FIRST\n\n**BEFORE doing anything, you MUST:**\n\n1. **CHECK EXISTING TASK FILE FIRST**:\n   - ALWAYS check if `story-{story-name}.md` already exists in `docs/reference/backend/tasks/`\n   - If exists: READ it and continue from current progress (add new tasks or update existing ones)\n   - If not exists: Create new task breakdown file\n   - **NEVER re-break down existing tasks**\n\n2. **FILE NAMING**:\n   - Pattern: `story-{story-name}.md` (single file per story","body":"# Task Breakdown\n\n## ⚠️ CRITICAL RULES - READ FIRST\n\n**BEFORE doing anything, you MUST:**\n\n1. **CHECK EXISTING TASK FILE FIRST**:\n   - ALWAYS check if `story-{story-name}.md` already exists in `docs/reference/backend/tasks/`\n   - If exists: READ it and continue from current progress (add new tasks or update existing ones)\n   - If not exists: Create new task breakdown file\n   - **NEVER re-break down existing tasks**\n\n2. **FILE NAMING**:\n   - Pattern: `story-{story-name}.md` (single file per story)\n   - Example: `story-user-profile.md`\n   - All tasks for this story go into this ONE file\n   - Tasks are separated by `---` dividers\n\n3. **MULTIPLE TASKS IN ONE FILE**:\n   - One file contains ALL tasks for the story\n   - Each task = independently testable section\n   - Clear scope and acceptance criteria per task\n   - Tasks numbered sequentially (Task 1, Task 2, etc.)\n\n4. **ALWAYS SAVE TO CORRECT PATH**:\n   - Path: `docs/reference/backend/tasks/story-{story-name}.md`\n   - NO exceptions, NO other locations\n\n5. **READ CONTEXT FIRST**:\n   - Read story from `docs/reference/pm/stories/`\n   - Read constraints from `docs/reference/backend/constraints.md`\n\n## Language Configuration\n\nBefore generating any content, check `aico.json` in project root for `language` field to determine the output language. If not set, default to English.\n\n## Process\n\n1. **Read story/PRD**: Load from `docs/reference/pm/stories/` or `docs/reference/pm/versions/`\n2. **Read constraints**: Load technical constraints\n3. **Identify components**: What backend layers are needed\n4. **Identify interactions**: What APIs and data flows are needed\n5. **Break into tasks**: Independently testable, single responsibility, by architecture layer\n6. **Order by dependencies**: Types → DB → Repository → Service → API → Tests\n7. **Generate single file**: Create `story-{story-name}.md` with all tasks in sections\n8. **Update Story file**: Add \"Related Tasks\" section to story file with link to task file\n9. **Summary**: Show created file and next steps\n\n## Task File Format\n\nSee [Task File Template](references/task-file-template.md) for complete structure.\n\n**Key points:**\n\n- Single file contains all tasks for the story\n- Tasks numbered sequentially (Task 1, Task 2, etc.)\n- Each task has: Description, Context, Acceptance Criteria, Scope, Implementation Steps\n- Progress section at the end tracks completion\n- Both story-based and standalone use the same format (only filename differs)\n- Backend tasks ordered by architecture layers: Types → DB → Repository → Service → API → Tests\n\n## Updating Story File\n\nAfter generating the task file, **ALWAYS** update the story file to add the \"Related Tasks\" section:\n\n```markdown\n## Related Tasks\n\n### Backend Tasks\n\nTask breakdown: [docs/reference/backend/tasks/story-user-profile.md](../backend/tasks/story-user-profile.md)\n\n**Progress**: 0/6 tasks completed\n\n- [ ] Task 1: Define Types\n- [ ] Task 2: Database Schema\n- [ ] Task 3: Repository Layer\n- [ ] Task 4: Service Layer\n- [ ] Task 5: API Endpoints\n- [ ] Task 6: Add Tests\n```\n\n**Key points:**\n\n- Add this section at the end of the story file (before any existing notes)\n- Include link to the task file\n- Use `- [ ]` checkboxes for each task (will be checked when task completes)\n- List tasks in execution order (Types → DB → Repository → Service → API → Tests)\n- Keep the section organized by frontend/backend if both exist\n- Include progress counter (X/Y tasks completed)\n\n## Output Example\n\nAfter breaking down \"user-profile\" story:\n\n```\nCreated task file for story ''user-profile'':\n\n✓ docs/reference/backend/tasks/story-user-profile.md\n\nTask breakdown includes:\n- Task 1: Define Types (setup)\n- Task 2: Database Schema (feature)\n- Task 3: Repository Layer (feature)\n- Task 4: Service Layer (feature)\n- Task 5: API Endpoints (feature)\n- Task 6: Add Tests (testing)\n\nTotal: 6 tasks\n\nNext steps:\n1. Review task breakdown in story-user-profile.md\n2. Use /backend.plan to add detailed steps to specific tasks\n3. Use /backend.implement to start executing tasks\n```\n\n## Key Rules\n\n- ALWAYS create a single file containing all tasks for the story\n- MUST use `story-{story-name}.md` naming (NOT multiple files)\n- ALWAYS include test tasks at the end\n- MUST note dependencies between tasks (in each task''s metadata)\n- Keep tasks focused - not too big, not too small\n- Each task section is self-contained with clear acceptance criteria\n- Separate tasks with `---` dividers\n- Include Story Progress section at the end of file\n\n## Common Mistakes\n\n- ❌ Tasks too large (full feature) → ✅ Break into layers\n- ❌ Tasks too small (add one field) → ✅ Group related work\n- ❌ Skip dependencies → ✅ Note which tasks depend on others\n- ❌ Forget testing → ✅ Always include test tasks\n- ❌ Create multiple files → ✅ Use single file with multiple task sections\n"},"lastSynced":"2026-03-08T02:06:24.918Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Project Management Agents needing structured task breakdown capabilities.","zh":"非常适合需要结构化任务分解能力的AI项目管理代理。","ja":"タスク分解能力が必要なAIプロジェクト管理エージェントに最適です。","ko":"구조화된 태스크 분할 기능이 필요한 AI 프로젝트 관리 에이전트에 적합합니다.","es":"Perfecto para agentes de gestión de proyectos de IA que necesitan capacidades de desglose de tareas estructuradas.","fr":"Parfait pour les agents de gestion de projet d''IA nécessitant des capacités de décomposition de tâches structurées.","de":"Perfekt für AI-Projektmanagement-Agenten, die strukturierte Aufgabenzerlegungsfunktionen benötigen.","pt":"Perfeito para Agentes de Gerenciamento de Projetos de IA que precisam de capacidades de quebra de tarefas estruturadas.","ru":"Идеально подходит для агентов управления проектами ИИ, которым необходимы возможности структурированного разбиения задач.","ar":"مثالي لعميل إدارة مشاريع الذكاء الاصطناعي الذي يحتاج إلى قدرات تحليل مهام منظم"},"recommendation":{"en":"Empowers agents to manage tasks efficiently using Markdown files, providing a structured approach to task management with critical rules such as checking existing task files and adhering to specific file naming patterns like `story-{story-name}.md`.","zh":"通过Markdown文件使代理能够高效地管理任务，提供结构化的任务管理方法，包括检查现有任务文件和遵循特定的文件命名模式，如`story-{story-name}.md`等关键规则。","ja":"Markdownファイルを使用して、エージェントがタスクを効率的に管理できるようにし、タスク管理に構造化されたアプローチを提供します。例えば、既存のタスクファイルを確認し、`story-{story-name}.md`のような特定のファイル命名パターンに従うなどの重要なルールです。","ko":"Markdown 파일을 사용하여 에이전트가 태스크를 효율적으로 관리할 수 있도록 하며, 태스크 관리에 구조화된 접근 방식을 제공합니다. 예를 들어, 기존의 태스크 파일을 확인하고 `story-{story-name}.md`와 같은 특정 파일命명 패턴을 따르는 등 중요 규칙입니다.","es":"Habilita a los agentes a gestionar tareas de manera eficiente utilizando archivos Markdown, proporcionando un enfoque estructurado para la gestión de tareas con reglas críticas como la comprobación de archivos de tareas existentes y el cumplimiento de patrones de nombre de archivo específicos como `story-{story-name}.md`.","fr":"Permet aux agents de gérer les tâches de manière efficace en utilisant des fichiers Markdown, fournissant une approche structurée de la gestion des tâches avec des règles critiques telles que la vérification des fichiers de tâches existants et le respect de modèles de nom de fichier spécifiques comme `story-{story-name}.md`.","de":"Ermächtigt Agenten, Aufgaben effizient mit Markdown-Dateien zu verwalten, wodurch ein strukturierter Ansatz für die Aufgabenverwaltung mit kritischen Regeln wie der Überprüfung vorhandener Aufgabendateien und der Einhaltung spezifischer Dateinamensmuster wie `story-{story-name}.md` ermöglicht wird.","pt":"Habilita os agentes a gerenciar tarefas de forma eficiente usando arquivos Markdown, fornecendo uma abordagem estruturada para o gerenciamento de tarefas com regras críticas, como verificar arquivos de tarefas existentes e aderir a padrões de nomenclatura de arquivos específicos, como `story-{story-name}.md`.","ru":"Наделяет агентов возможностью эффективно управлять задачами с помощью файлов Markdown, обеспечивая структурированный подход к управлению задачами с критическими правилами, такими как проверка существующих файлов задач и соблюдение определенных шаблонов именования файлов, таких как `story-{story-name}.md`.","ar":"تمكّن الوكيل من إدارة المهام بفعالية باستخدام ملفات Markdown، وتوفير نهج منظم لإدارة المهام بالقواعد الحيوية مثل التحقق من ملفات المهام الحالية والامتثال لأنماط اسم الملف الخاص مثل `story-{story-name}.md`."},"useCases":{"en":["Automating task breakdown creation for new stories","Updating existing task breakdowns in `docs/reference/backend/tasks/`","Ensuring consistency in task management through strict file naming conventions"],"zh":["自动创建新故事的任务分解","更新`docs/reference/backend/tasks/`中的现有任务分解","通过严格的文件命名约定确保任务管理的一致性"],"ja":["新しいストーリーのタスク分解を作成を自動化する","`docs/reference/backend/tasks/`内の既存のタスク分解を更新する","ファイル命名規約を厳格に適用してタスク管理の一貫性を確保する"],"ko":["새로운 스토리의 태스크 분할을 자동으로 생성하는 것","`docs/reference/backend/tasks/`에 있는 기존의 태스크 분할을 업데이트하는 것","파일命명 규칙을 엄격히 적용하여 태스크 관리의 일관성을 보장하는 것"],"es":["Automatización de la creación de desglose de tareas para nuevas historias","Actualización de desgloses de tareas existentes en `docs/reference/backend/tasks/`","Garantía de la consistencia en la gestión de tareas a través de convenciones de nombres de archivo estrictas"],"fr":["Automatisation de la création de décomposition de tâches pour de nouvelles histoires","Mise à jour des décompositions de tâches existantes dans `docs/reference/backend/tasks/`","Assurance de la cohérence dans la gestion des tâches grâce à des conventions de nom de fichier strictes"],"de":["Automatisierung der Erstellung von Aufgabenzerlegungen für neue Geschichten","Aktualisierung von bestehenden Aufgabenzerlegungen in `docs/reference/backend/tasks/`","Sicherstellung der Konsistenz bei der Aufgabenverwaltung durch strenge Dateinamenskonventionen"],"pt":["Automatizar a criação de quebra de tarefas para novas histórias","Atualizar quebras de tarefas existentes em `docs/reference/backend/tasks/`","Garantir a consistência no gerenciamento de tarefas por meio de convenções rigorosas de nomenclatura de arquivos"],"ru":["Автоматизировать создание разбиения задач для новых историй","Обновлять существующие разбиения задач в `docs/reference/backend/tasks/`","Обеспечивать согласованность в управлении задачами посредством строгих конвенций именования файлов"],"ar":["توفير автомاتيزي للتحليل الأولي للمهام للقصص الجديدة","تحديث تحليل المهام الحالية في `docs/reference/backend/tasks/`","ضمان الاتساق في إدارة المهام من خلال اتفاقيات صارمة لتسمية الملفات"]},"limitations":{"en":["Requires access to the `docs/reference/backend/tasks/` directory","Must adhere to the `story-{story-name}.md` file naming pattern","Assumes existing knowledge of Markdown file formatting"],"zh":["需要访问`docs/reference/backend/tasks/`目录","必须遵循`story-{story-name}.md`文件命名模式","假设已经具备Markdown文件格式的知识"],"ja":["`docs/reference/backend/tasks/`ディレクトリへのアクセスが必要","`story-{story-name}.md`ファイル命名パターンに従う必要がある","既にMarkdownファイル形式の知識を持っていることが前提"],"ko":["`docs/reference/backend/tasks/` 디렉토리에 접근할 수 있어야 함","`story-{story-name}.md` 파일 이름 패턴을 따라야 함","이미 Markdown 파일 형식의 지식을 가지고 있는 것으로 가정"],"es":["Requiere acceso al directorio `docs/reference/backend/tasks/`","Debe cumplir con el patrón de nombre de archivo `story-{story-name}.md`","Supone conocimientos previos de formato de archivos Markdown"],"fr":["Nécessite un accès au répertoire `docs/reference/backend/tasks/`","Doit respecter le modèle de nom de fichier `story-{story-name}.md`","Suppose des connaissances préalables sur le formatage des fichiers Markdown"],"de":["Benötigt Zugriff auf das Verzeichnis `docs/reference/backend/tasks/`","Muss dem Dateinamensmuster `story-{story-name}.md` entsprechen","Geht von vorhandenem Wissen über die Formatierung von Markdown-Dateien aus"],"pt":["Requer acesso ao diretório `docs/reference/backend/tasks/`","Deve aderir ao padrão de nomenclatura de arquivos `story-{story-name}.md`","Pressupõe conhecimento prévio de formatação de arquivos Markdown"],"ru":["Требует доступа к каталогу `docs/reference/backend/tasks/`","Должно придерживаться шаблона именования файлов `story-{story-name}.md`","Предполагает наличие предварительных знаний форматирования файлов Markdown"],"ar":["يتطلب الوصول إلى الدليل `docs/reference/backend/tasks/`","يجب الالتزام بنمط تسمية الملفات `story-{story-name}.md`","يفترض وجود معرفة مسبقة بتنسيق ملفات Markdown"]},"version":4},"contentHash":"1b05c916a71fdb86ca40c35955273cb174e54d0f237185a51e8512737a580877","qualityScore":57}');
