INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cinience/alicloud-skills/alicloud-ai-audio-tts', 'alicloud-ai-audio-tts', 'cinience', 'alicloud-skills', 'community', 'alicloud-ai-audio-tts cinience alicloud-skills community The alicloud-ai-audio-tts skill enables developers to generate text-to-speech audio using Alibaba Cloud''s AI capabilities. It benefits developers working with Python and audio processing. 阿里云AI音频TTS是一种基于深度学习的音频合成技术，能够生成高质量的音频文件 Alibaba Cloud AIエージェントの音声合成は、深度学習を基盤とした音声生成技術です 알리바바 클라우드 AI 오디오 TTS는 딥러닝 기반의 오디오 합성 기술로 높은 품질의 오디오 파일을 생성합니다 alicloud-ai-audio-tts es un skill de Alibaba Cloud que permite desarrollar soluciones de audio avanzadas con Python y CLI alicloud-ai-audio-tts est une compétence d''Alibaba Cloud qui permet de développer des solutions audio avancées avec Python et CLI alicloud-ai-audio-tts ist ein Skill von Alibaba Cloud, der die Entwicklung von fortschrittlichen Audio-Lösungen mit Python und CLI ermöglicht O alicloud-ai-audio-tts é uma ferramenta de síntese de áudio que utiliza Python e CLI para gerar áudio sintetizado de alta qualidade. alicloud-ai-audio-tts - это инструмент синтеза аудио, который использует Python и CLI для генерации синтезированного аудио высокого качества. أداة أليكلود-إيه آي-أوديو-تي تي إس هي أداة合成 الصوت التي تستخدم بايثون و CLI لإنشاء صوت م 合ن высок الجودة. how to use alicloud-ai-audio-tts alicloud-ai-audio-tts setup guide python text to speech library alibaba cloud ai services tts script compilation py_compile tutorial alicloud-ai-audio-tts alternative text to speech audio generation python audio processing 阿里云AI音频TTS AI音频合成 Python音频生成 CLI音频操作 深度学习音频合成 高质量音频文件 音频格式支持 Compiles TTS scripts using py_compile Validates script compilation with output file generation Generates text-to-speech audio files using Alibaba Cloud''s AI services Saves audio links, sample audio files, and request payloads to output directory Utilizes bash commands for script execution and validation Supports Python-based development for custom TTS applications alicloud-ai-audio-tts is a Python-based skill for generating text-to-speech audio using Alibaba Cloud''s AI services, utilizing scripts and validation via py_compile.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SalesforceCommerceCloud/b2c-developer-tooling/b2c-sandbox', 'community', 'SalesforceCommerceCloud', 'b2c-developer-tooling', 'SalesforceCommerceCloud/b2c-developer-tooling', 'b2c-sandbox', 0, 0, 57, '2026-03-08T01:57:15.404Z', '2026-03-08T02:06:51.800Z', 'a98a12436a404202e43a0780b72a849e42b6d47aebf7f6a8c3b0557a2a1e8a1b', '{"id":"SalesforceCommerceCloud/b2c-developer-tooling/b2c-sandbox","name":"b2c-sandbox","description":{"en":"The b2c-sandbox skill manages Salesforce B2C Commerce On-demand sandboxes using the b2c CLI plugin, benefiting developers and administrators who need to create, delete, or list sandboxes.","zh":"B2C Sandbox 是一种 Salesforce Commerce AIエージェント，用于管理 On-demand sandboxes (ODS) 和 Tooling SDK。使用 B2C CLI 创建和删除沙盒。","ja":"B2C Sandbox は、Salesforce Commerce の On-demand sandboxes (ODS) と Tooling SDK を管理する AIエージェントです。B2C CLI を使用してサンドボックスを作成および削除します。","ko":"B2C Sandbox는 On-demand sandboxes (ODS) 및 Tooling SDK를 관리하는 Salesforce Commerce 인공지능 에이전트입니다. B2C CLI를 사용하여 샌드박스를 생성 및 삭제합니다.","es":"El skill b2c-sandbox permite la gestión de sandboxes de Salesforce B2C Commerce On-demand utilizando el plugin CLI b2c","fr":"Le skill b2c-sandbox permet la gestion des sandboxes de Salesforce B2C Commerce On-demand à l''aide du plugin CLI b2c","de":"Das b2c-sandbox-Skill ermöglicht die Verwaltung von Sandboxes von Salesforce B2C Commerce On-demand mithilfe des b2c-CLI-Plugins","pt":"O b2c-sandbox é uma habilidade que permite criar e gerenciar sandboxes On-demand do Salesforce B2C Commerce usando o plugin b2c CLI.","ru":"ИИ Агент b2c-sandbox позволяет создавать и управлять песочницами Salesforce B2C Commerce с помощью плагина b2c CLI.","ar":"وظيفة ب2c-sandbox تتيح إنشاء وإدارة بيئات التطوير المخصصة لشركة Salesforce B2C Commerce باستخدام إضافة ب2c CLI."},"seo":{"title":{"en":"b2c-sandbox: Salesforce B2C Commerce On-de