platform for efficient web application development with AI-native capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('blackpwnguin/Personal-AI/Observability', 'community', 'blackpwnguin', 'Personal-AI', 'blackpwnguin/Personal-AI', 'Observability', 0, 0, 57, '2026-03-08T01:57:15.413Z', '2026-03-08T02:07:09.129Z', '4c0f788c22cecff199e32220ed276d10edba8b48a3c68e518b997522a271422f', '{"id":"blackpwnguin/Personal-AI/Observability","name":"Observability","description":{"en":"Observability provides real-time monitoring of PAI multi-agent activity with WebSocket streaming, benefiting developers and operators who need to track agent performance. It offers a dashboard UI and server API for easy access.","zh":"Observability提供了实时监控PAI多代理活动的功能，包括WebSocket实时流媒体和Dashboard UI。","ja":"Observabilityは、AIエージェントのリアルタイムモニタリングを実現する機能で、WebSocketストリーミングとDashboard UIを提供します。","ko":"Observability는 PAI 다중 에이전트 활동을 실시간으로 모니터링하는 기능으로, WebSocket 스트리밍과 Dashboard UI를 제공합니다.","es":"La observabilidad permite el monitoreo en tiempo real de la actividad de los agentes de IA con WebSocket","fr":"L''observabilité permet la surveillance en temps réel de l''activité des agents d''IA avec WebSocket","de":"Die Observability ermöglicht die Echtzeitüberwachung der Aktivität von KI-Agents mit WebSocket","pt":"A observabilidade permite o monitoramento em tempo real de atividades de agentes de IA com WebSocket streaming. Configure o dashboard e o servidor para começar a monitorar.","ru":"Инструменты наблюдаемости позволяют мониторить hoạtность ИИ Агентов в режиме реального времени с WebSocket streaming. Настройте панель управления и сервер, чтобы начать мониторинг.","ar":"مراقبة الوكلاء الذكية تسمح بمراقبة الأنشطة في الوقت الفعلي مع WebSocket streaming. أعد إعداد لوحة التحكم والخادم لبدء المراقبة."},"seo":{"title":{"en":"Observability: Real-time Monitoring Setup Guide | AI Agen...","zh":"Observability Setup Guide - 实时监控PAI多代理活动","ja":"Observability ベストプラクティス - AIエージェントのリアルタイムモニタリング","ko":"Observability 설정 가이드 - WebSocket 스트리밍을 통한 PAI 다중 에이전트 활동 ...","es":"Guía de Configuración de Observabilidad para Agentes de IA","fr":"Guide de Configuration de l''Observabilité pour les Agents...","de":"Einrichtungsleitfaden für Observability in KI-Agents","pt":"Guia de Configuração de Observabilidade para Agentes de IA","ru":"Настройка инструментов наблюдаемости для ИИ Агентов","ar":"دليل إعداد مراقبة الوكلاء الذكية"},"description":{"en":"Unlock real-time insights into PAI multi-agent activity with Observability''s WebSocket streaming. Get started now and discover how to monitor your AI agents ...","zh":"了解如何设置Observability来监控PAI多代理活动，包括WebSocket实时流媒体和Dashboard UI","ja":"AIエージェントのリアルタイムモニタリングを実現するObservabilityの設定方法について学びます","ko":"PAI 다중 에이전트 활동을 실시간으로 모니터링하는 Observability 설정 방법 및 WebSocket 스트리밍 기능에 대해 알아보세요","es":"Aprende a configurar la observabilidad para agentes de IA con WebSocket y API de servidor","fr":"Découvrez comment configurer l''observabilité pour les agents d''IA avec WebSocket et API de serveur","de":"Erfahren Sie, wie Sie die Observability für KI-Agents mit WebSocket und Server-API einrichten","pt":"Aprenda a configurar a observabilidade para monitorar atividades de agentes de IA em tempo real com WebSocket streaming","ru":"Узнайте, как настроить инструменты наблюдаемости для мониторинга hoạtности ИИ Агентов в режиме реального времени с WebSocket streaming","ar":"تعرف على كيفية إعداد مراقبة الوكلاء الذكية لمراقبة الأنشطة في الوقت الفعلي مع WebSocket streaming"},"definition":{"en":"Observability is a skill that enables real-time monitoring of PAI multi-agent activity, providing insights into agent performance and behavior through WebSocket streaming.","zh":"Observability是指实时监控和分析PAI多代理活动的能力","ja":"Observabilityは、AIエージェントの動作をリアルタイムに監視し、分析する能力です","ko":"Observability는 PAI 다중 에이전트 활동을 실시간으로 모니터링하고 분석하는 능력을 말합니다","es":"La observabilidad es la capacidad de monitorear la actividad de los agentes de IA en tiempo real","fr":"L''observabilité est la capacité de surveiller l''activité des agents d''IA en temps réel","de":"Die Observability ist die Fähigkeit, die Aktivität von KI-Agents in Echtzeit zu überwachen","pt":"Observabilidade é a capacidade de monitorar atividades de agentes de IA em tempo real","ru":"Наблюдаемость - это способность мониторить hoạtность ИИ Агентов в режиме реального времени","ar":"مراقبة الوكلاء الذكية هي القدرة على مراقبة الأنشطة في الوقت الفعلي"},"features":{"en":["Real-time monitoring of PAI multi-agent activity with WebSocket streaming","Dashboard UI accessible at http://localhost:5172","Server API available at http://localhost:5172 for programmatic access","Manage.sh script for easy startup, shutdown, and restart of the server and dashboard","Status checking capability to monitor the skill''s health and performance"],"zh":["WebSocket实时流媒体","Dashboard UI","支持PAI多代理活动监控","提供实时数据分析","支持CLI命令行操作"],"ja":["WebSocketストリーミング","Dashboard UI","AIエージェントのリアルタイムモニタリング","リアルタイムデータ分析","CLIコマンドライン操作対応"],"ko":["WebSocket 스트리밍","Dashboard UI","PAI 다중 에이전트 활동 실시간 모니터링","실시간 데이터 분석","CLI 명령어 지원"],"es":["Monitoreo en tiempo real de la actividad de los agentes de IA","Transmisión de WebSocket para una actualización en tiempo real","API de servidor para una integración flexible","Interfaz de usuario de dashboard para una visualización sencilla","Compatibilidad con CLI para una configuración fácil","Soporte para la gestión de estado de los agentes"],"fr":["Surveillance en temps réel de l''activité des agents d''IA","Transmission WebSocket pour une mise à jour en temps réel","API de serveur pour une intégration flexible","Interface utilisateur de tableau de bord pour une visualisation simple","Compatibilité avec CLI pour une configuration facile","Prise en charge de la gestion d''état des agents"],"de":["Echtzeitüberwachung der Aktivität von KI-Agents","WebSocket-Streaming für eine Echtzeitaktualisierung","Server-API für eine flexible Integration","Benutzeroberfläche des Dashboards für eine einfache Visualisierung","Kompatibilität mit CLI für eine einfache Konfiguration","Unterstützung für die Zustandsverwaltung der Agents"],"pt":["Monitoramento em tempo real de atividades de agentes de IA","WebSocket streaming para atualizações em tempo real","Painel de controle de usuário para visualização de dados","API do servidor para integração com outras ferramentas","Comandos CLI para gerenciamento do servidor e do painel","Suporte a restart e status do servidor"],"ru":["Мониторинг hoạtности ИИ Агентов в режиме реального времени","WebSocket streaming для обновлений в режиме реального времени","Панель управления пользователем для визуализации данных","API сервера для интеграции с другими инструментами","Команды CLI для управления сервером и панелью","Поддержка перезапуска и статуса сервера"],"ar":["مراقبة الأنشطة في الوقت الفعلي لمراقبة الوكلاء الذكية","WebSocket streaming لتحديثات في الوقت الفعلي","لوحة تحكم للمستخدم لتصور البيانات","API للخادم لتكامل مع أدوات أخرى","أوامر CLI لإدارة الخادم ولوحة التحكم","دعم إعادة التشغيل وحالة الخادم"]},"keywords":{"en":["how to use Observability","what is Observability","Observability alternative","Observability vs New Relic","Observability install","Observability setup guide","real-time monitoring tools","PAI multi-agent monitoring","WebSocket streaming for AI agents"],"zh":["Observability","PAI多代理活动监控","WebSocket实时流媒体","Dashboard UI","CLI命令行操作","实时数据分析"],"ja":["Observability","AIエージェント","WebSocketストリーミング","Dashboard UI","CLIコマンドライン操作","リアルタイムデータ分析"],"ko":["Observability","PAI 다중 에이전트 활동","WebSocket 스트리밍","Dashboard UI","CLI 명령어","실시간 데이터 분석"],"es":["observabilidad agentes de IA","monitoreo en tiempo real","WebSocket","API de servidor","CLI","gestión de estado","configuración de observabilidad","guias de configuración","herramientas de IA"],"fr":["observabilité agents d''IA","surveillance en temps réel","WebSocket","API de serveur","CLI","gestion d''état","configuration de l''observabilité","guides de configuration","outils d''IA"],"de":["Observability KI-Agents","Echtzeitüberwachung","WebSocket","Server-API","CLI","Zustandsverwaltung","Konfiguration der Observability","Konfigurationsleitfäden","KI-Tools"],"pt":["observabilidade de agentes de IA","monitoramento em tempo real","WebSocket streaming","painel de controle de usuário","API do servidor","comandos CLI","gerenciamento de servidor","integração com ferramentas","desenvolvimento de software","tecnologias de IA"],"ru":["наблюдаемость ИИ Агентов","мониторинг в режиме реального времени","WebSocket streaming","панель управления пользователем","API сервера","команды CLI","управление сервером","интеграция с инструментами","разработка программного обеспечения","технологии ИИ"],"ar":["مراقبة الوكلاء الذكية","مراقبة في الوقت الفعلي","WebSocket streaming","لوحة تحكم للمستخدم","API للخادم","أوامر CLI","إدارة الخادم","تكامل مع أدوات","تطوير البرمجيات","تكنولوجيا الذكاء الاصطناعي"]}},"owner":"blackpwnguin","repo":"Personal-AI","repoPath":"blackpwnguin/Personal-AI","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.413Z","topics":[],"category":"community","skillMd":{"name":"Observability","description":"Real-time monitoring dashboard for PAI multi-agent activity. USE WHEN user says start observability, stop dashboard, restart observability, monitor agents, show agent activity, or needs to debug multi-agent workflows.","bodyPreview":"# Agent Observability Dashboard\n\nReal-time monitoring of PAI multi-agent activity with WebSocket streaming.\n\n## Quick Start\n\n```bash\n# Start server and dashboard\n~/.claude/skills/observability/manage.sh start\n\n# Stop everything\n~/.claude/skills/observability/manage.sh stop\n\n# Restart both\n~/.claude/skills/observability/manage.sh restart\n\n# Check status\n~/.claude/skills/observability/manage.sh status\n```\n\n## Access Points\n\n- **Dashboard UI**: http://localhost:5172\n- **Server API**: http://localho","body":"# Agent Observability Dashboard\n\nReal-time monitoring of PAI multi-agent activity with WebSocket streaming.\n\n## Quick Start\n\n```bash\n# Start server and dashboard\n~/.claude/skills/observability/manage.sh start\n\n# Stop everything\n~/.claude/skills/observability/manage.sh stop\n\n# Restart both\n~/.claude/skills/observability/manage.sh restart\n\n# Check status\n~/.claude/skills/observability/manage.sh status\n```\n\n## Access Points\n\n- **Dashboard UI**: http://localhost:5172\n- **Server API**: http://localhost:4000\n- **WebSocket Stream**: ws://localhost:4000/stream\n\n## What It Monitors\n\n### Real-Time Tracking\n- Agent session starts/ends\n- Tool calls across all agents\n- Hook event execution\n- Session timelines and traces\n- WebSocket live updates\n\n### Data Sources\n- **Primary**: `~/.claude/history/raw-outputs/YYYY-MM/YYYY-MM-DD_all-events.jsonl`\n- **Format**: JSONL with structured event data\n- **Hooks**: Events logged automatically by PAI hook system\n\n## Architecture\n\n**Stack:**\n- Server: Bun + Express + TypeScript\n- Client: Vite + Vue + TypeScript\n- Storage: In-memory streaming (no database)\n- Protocol: WebSocket for real-time updates\n\n**Key Features:**\n- Watch filesystem with automatic reload\n- Tail-follow for today''s event file\n- Cache events in-memory\n- Broadcast WebSocket to all clients\n- No persistence (fresh start each launch)\n\n## When to Activate This Skill\n\n- \"Start observability\"\n- \"Stop the dashboard\"\n- \"Restart observability\"\n- \"Monitor agents\"\n- \"Show agent activity\"\n- \"Observability status\"\n- \"Debug agent workflow\"\n\n## Examples\n\n**Example 1: Start monitoring agents**\n```\nUser: \"start observability\"\n→ Launches server on port 4000\n→ Starts dashboard on port 5172\n→ Opens browser to live agent activity view\n```\n\n**Example 2: Debug a stuck workflow**\n```\nUser: \"something''s weird with my agents, show me what''s happening\"\n→ Opens observability dashboard\n→ Shows real-time tool calls across all agents\n→ Reveals which agent is blocked or looping\n```\n\n**Example 3: Check dashboard status**\n```\nUser: \"is observability running?\"\n→ Runs manage.sh status\n→ Reports server and client running state\n→ Shows access URLs if active\n```\n\n## Development\n\n### Server\n```bash\ncd ~/.claude/skills/observability/apps/server\nbun install\nbun run dev\n```\n\n### Client\n```bash\ncd ~/.claude/skills/observability/apps/client\nbun install\nbun run dev\n```\n\n## Troubleshooting\n\n### Dashboard not loading\n- Check server is running: `curl http://localhost:4000/health`\n- Check client is running: `curl http://localhost:5172`\n- Restart: `./manage.sh restart`\n\n### No events showing\n- Verify events file exists: `~/.claude/history/raw-outputs/YYYY-MM/YYYY-MM-DD_all-events.jsonl`\n- Check hooks are configured in `~/.claude/settings.json`\n- Try triggering an event (use any tool or agent)\n\n### Port conflicts\n- Server uses: 4000\n- Client uses: 5172\n- Check nothing else is using these ports\n\n## Files\n\n```\n~/.claude/skills/observability/\n├── SKILL.md                          # This file\n├── manage.sh                         # Control script\n├── apps/\n│   ├── server/                       # Backend (Bun + Express)\n│   │   ├── src/index.ts\n│   │   └── package.json\n│   └── client/                       # Frontend (Vite + Vue)\n│       ├── src/\n│       ├── package.json\n│       └── vite.config.ts\n└── scripts/                          # Utility scripts\n```\n\n## Key Principles\n\n1. **Real-time** - Events stream as they happen\n2. **Ephemeral** - No persistence, in-memory only\n3. **Simple** - No database, no configuration\n4. **Transparent** - Full visibility into agent activity\n5. **Unobtrusive** - Doesn''t interfere with PAI operation\n\n## Hook Integration\n\nFor the observability dashboard to receive events, configure your PAI hooks to log to:\n`~/.claude/history/raw-outputs/YYYY-MM/YYYY-MM-DD_all-events.jsonl`\n\nThe `capture-all-events.ts` hook in `~/.claude/hooks/` handles this automatically.\n"},"lastSynced":"2026-03-08T02:07:09.129Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing real-time monitoring and performance tracking with WebSocket streaming.","zh":"非常适合需要实时监控和性能跟踪的AI代理，支持WebSocket流媒体。","ja":"リアルタイムの監視とパフォーマンス追跡が必要なAIエージェントに最適です。WebSocketストリーミングをサポートしています。","ko":"실시간 모니터링 및 성능 추적이 필요한 AI 에이전트에게 적합합니다. WebSocket 스트리밍을 지원합니다.","es":"Perfecto para agentes de IA que necesitan un monitoreo y seguimiento de rendimiento en tiempo real con streaming de WebSocket.","fr":"Parfait pour les agents IA nécessitant un suivi et un monitoring des performances en temps réel avec un streaming WebSocket.","de":"Perfekt für KI-Agents, die ein Echtzeit-Monitoring und Leistungsverfolgung mit WebSocket-Streaming benötigen.","pt":"Perfeito para Agentes de IA que necessitam de monitoramento em tempo real e rastreamento de desempenho com transmissão WebSocket.","ru":"Идеально для ИИ-агентов, которым требуется мониторинг и отслеживание производительности в режиме реального времени с помощью потоковой передачи WebSocket.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى مراقبة الوقت الفعلي وتتبع الأداء باستخدام بث WebSocket."},"recommendation":{"en":"Empowers agents to track performance in real-time using WebSocket streaming, providing a dashboard UI and server API for easy access and monitoring of PAI multi-agent activity.","zh":"赋予代理实时跟踪性能的能力，使用WebSocket流媒体提供仪表盘UI和服务器API，实现PAI多代理活动的轻松访问和监控。","ja":"エージェントにリアルタイムでパフォーマンスを追跡する能力を提供します。WebSocketストリーミングを使用してダッシュボードUIとサーバーAPIを提供し、PAIマルチエージェントアクティビティの簡単なアクセスと監視を実現します。","ko":"에이전트가 실시간으로 성능을 추적할 수 있는 능력을 제공합니다. WebSocket 스트리밍을 사용하여 대시보드 UI와 서버 API를 제공하여 PAI 멀티 에이전트 활동의 쉬운 접근 및 모니터링을 구현합니다.","es":"Habilita a los agentes a realizar un seguimiento del rendimiento en tiempo real utilizando streaming de WebSocket, proporcionando una interfaz de usuario de dashboard y una API de servidor para un acceso y monitoreo fáciles de la actividad de multiagentes PAI.","fr":"Permet aux agents de suivre les performances en temps réel en utilisant le streaming WebSocket, en fournissant une interface utilisateur de tableau de bord et une API de serveur pour un accès et un suivi faciles de l''activité multi-agents PAI.","de":"Ermöglicht es Agents, die Leistung in Echtzeit mit WebSocket-Streaming zu verfolgen, indem ein Dashboard-Benutzeroberfläche und eine Server-API für einen einfachen Zugriff und Überwachung der PAI-Multiagenten-Aktivität bereitgestellt wird.","pt":"Habilita os agentes a rastrear o desempenho em tempo real usando transmissão WebSocket, fornecendo uma interface de usuário de painel e API de servidor para acesso e monitoramento fácil da atividade de multi-agente PAI.","ru":"Наделяет агентов возможностью отслеживать производительность в реальном времени с помощью потоковой передачи WebSocket, предоставляя панель управления и серверный API для легкого доступа и мониторинга активности PAI multi-agent.","ar":"يمنح الوكلاء القدرة على تتبع الأداء في الوقت الفعلي باستخدام بث WebSocket، وتوفر واجهة مستخدم لوحة وتطبيق برمجي للخادم للوصول السهل ومراقبة نشاط وكيل PAI متعددة."},"useCases":{"en":["Monitoring agent performance in real-time","Debugging PAI multi-agent interactions","Analyzing agent activity with WebSocket streaming"],"zh":["实时监控代理性能","调试PAI多代理交互","使用WebSocket流媒体分析代理活动"],"ja":["エージェントのパフォーマンスをリアルタイムで監視する","PAIマルチエージェントの相互作用をデバッグする","WebSocketストリーミングを使用してエージェントアクティビティを分析する"],"ko":["실시간으로 에이전트 성능 모니터링","PAI 멀티 에이전트 상호 작용 디버깅","WebSocket 스트리밍을 사용하여 에이전트 활동 분석"],"es":["Monitoreo del rendimiento del agente en tiempo real","Depuración de interacciones de multiagentes PAI","Análisis de la actividad del agente con streaming de WebSocket"],"fr":["Suivi des performances de l''agent en temps réel","Débogage des interactions multi-agents PAI","Analyse de l''activité de l''agent avec un streaming WebSocket"],"de":["Überwachung der Leistung des Agents in Echtzeit","Fehlerbehebung bei PAI-Multiagenten-Interaktionen","Analyse der Agentenaktivität mit WebSocket-Streaming"],"pt":["Monitoramento do desempenho do agente em tempo real","Depuração de interações de multi-agente PAI","Análise da atividade do agente com transmissão WebSocket"],"ru":["Мониторинг производительности агента в реальном времени","Отладка взаимодействий PAI multi-agent","Анализ активности агента с помощью потоковой передачи WebSocket"],"ar":["مراقبة أداء الوكيل في الوقت الفعلي","تصحيح أخطاء التفاعلات متعددة الوكلاء PAI","تحليل نشاط الوكيل باستخدام بث WebSocket"]},"limitations":{"en":["Requires local server setup","Limited to PAI multi-agent activity monitoring"],"zh":["需要本地服务器设置","仅限PAI多代理活动监控"],"ja":["ローカルサーバーの設定が必要","PAIマルチエージェントアクティビティの監視に限定"],"ko":["로컬 서버 설정이 필요","PAI 멀티 에이전트 활동 모니터링에만 제한"],"es":["Requiere una configuración de servidor local","Limitado al monitoreo de la actividad de multiagentes PAI"],"fr":["Nécessite une configuration de serveur local","Limité au suivi de l''activité multi-agents PAI"],"de":["Erfordert eine lokale Server-Einrichtung","Begrenzt auf die Überwachung der PAI-Multiagenten-Aktivität"],"pt":["Requer configuração de servidor local","Limitado ao monitoramento de atividade de multi-agente PAI"],"ru":["Требуется настройка локального сервера","Ограничен мониторингом активности PAI multi-agent"],"ar":["يتطلب إعداد خادم محلي","محدود بمراقبة نشاط وكيل PAI متعددة"]},"version":4},"contentHash":"4c0f788c22cecff199e32220ed276d10edba8b48a3c68e518b997522a271422f","qualityScore":57}');
