INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('blackpwnguin/Personal-AI/Observability', 'Observability', 'blackpwnguin', 'Personal-AI', 'community', 'Observability blackpwnguin Personal-AI community Observability provides real-time monitoring of PAI multi-agent activity with WebSocket streaming, benefiting developers and operators who need to track agent performance. It offers a dashboard UI and server API for easy access. Observability提供了实时监控PAI多代理活动的功能，包括WebSocket实时流媒体和Dashboard UI。 Observabilityは、AIエージェントのリアルタイムモニタリングを実現する機能で、WebSocketストリーミングとDashboard UIを提供します。 Observability는 PAI 다중 에이전트 활동을 실시간으로 모니터링하는 기능으로, WebSocket 스트리밍과 Dashboard UI를 제공합니다. La observabilidad permite el monitoreo en tiempo real de la actividad de los agentes de IA con WebSocket L''observabilité permet la surveillance en temps réel de l''activité des agents d''IA avec WebSocket Die Observability ermöglicht die Echtzeitüberwachung der Aktivität von KI-Agents mit WebSocket A observabilidade permite o monitoramento em tempo real de atividades de agentes de IA com WebSocket streaming. Configure o dashboard e o servidor para começar a monitorar. Инструменты наблюдаемости позволяют мониторить hoạtность ИИ Агентов в режиме реального времени с WebSocket streaming. Настройте панель управления и сервер, чтобы начать мониторинг. مراقبة الوكلاء الذكية تسمح بمراقبة الأنشطة في الوقت الفعلي مع WebSocket streaming. أعد إعداد لوحة التحكم والخادم لبدء المراقبة. how to use Observability what is Observability Observability alternative Observability vs New Relic Observability install Observability setup guide real-time monitoring tools PAI multi-agent monitoring WebSocket streaming for AI agents Observability PAI多代理活动监控 WebSocket实时流媒体 Dashboard UI CLI命令行操作 实时数据分析 Real-time monitoring of PAI multi-agent activity with WebSocket streaming Dashboard UI accessible at http://localhost:5172 Server API available at http://localhost:5172 for programmatic access Manage.sh script for easy startup, shutdown, and restart of the server and dashboard Status checking capability to monitor the skill''s health and performance Observability is a skill that enables real-time monitoring of PAI multi-agent activity, providing insights into agent performance and behavior through WebSocket streaming.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Danik911/thesis_project/debugging-docker', 'community', 'Danik911', 'thesis_project', 'Danik911/thesis_project', 'debugging-docker', 0, 0, 57, '2026-03-08T01:57:15.414Z', '2026-03-08T02:07:09.383Z', '82f286487a334cec6fe83577e009becd6e66ed92598577b5a0e28c2b57cc5708', '{"id":"Danik911/thesis_project/debugging-docker","name":"debugging-docker","description":{"en":"The debugging-docker skill provides systematic troubleshooting workflows for Docker build failures, runtime errors, and performance optimization, benefiting developers in multi-platform environments","zh":"Docker 调试技能提供系统化的故障排除工作流，用于解决构建失败、运行时错误和性能优化问题","ja":"Docker デバッグスキルは、ビルドの失敗、ランタイム エラー、パフォーマンスの最適化を解決するための体系的なトラブルシューティング ワークフローを提供します","ko":"도커 디버깅 스킬은 빌드 실패, 런타임 오류 및 성능 최적화를 해결하기 위한 체계적인 문제 해결 워크플로를 제공합니다","es":"Depuración de operaciones de Docker para desarrolladores, incluyendo solución de errores de compilación y ejecución en entornos multiplataforma","fr":"Débogage des opérations Docker pour les développeurs, y compris la résolution des erreurs de build et d''exécution dans des environnements multiplateformes","de":"Debugging von Docker-Operationen für Entwickler, einschließlich der Lösung von Build- und Laufzeitfehlern in multiplattformigen Umgebungen","pt":"O skill de depuração de Docker fornece fluxos de trabalho sistemáticos para solução de problemas de build, erros de runtime e otimização de desempenho em ambientes multiplataforma","ru":"Навык отладки Docker предоставляет системные рабочие процессы для решения проблем с построением, ошибками runtime и оптимизацией производительности в многофункциональных средах","ar":"مهارة تصحيح أخطاء دوكر توفر عمليات عمل منهجية لحل مشاكل البناء وأخطاء وقت التشغيل وضبط الأداء في بيئات متعددة المنصات"},"seo":{"title":{"en":"debugging-docker: Troubleshooting Guide for AI Agents","zh":"Docker 调试设置指南：解决构建失败和运行时错误","ja":"Docker デバッグベストプラクティス：AIエージェントによるトラブルシューティング","ko":"도커 디버깅 설정 가이드: 빌드 실패 및 런타임 오류 해결","es":"Guía de Depuración de Docker: Mejores Prácticas para Desa...","fr":"Débogage Docker: Guide de Configuration pour les Développ...","de":"Docker-Debugging: Einrichtungsleitfaden für Entwickler","pt":"Guia de Depuração de Docker: Melhores Práticas para Desen...","ru":"Руководство по отладке Docker: ИИ Агенты для решения проблем","ar":"دليل تصحيح أخطاء دوكر: أدوات ذكاء اصطناعي للتعامل مع الأخطاء"},"description":{"en":"Master systematic troubleshooting for Docker build failures & runtime errors. Learn how to debug Docker operations for multi-platform environments","zh":"使用 Docker 调试技能解决构建失败、运行时错误和性能优化问题，适用于多平台环境和 GAMP-5 验证","ja":"Docker デバッグスキルを使用して、ビルドの失敗、ランタイム エラー、パフォーマンスの最適化を解決します。マルチ プラットフォーム環境と GAMP-5 認定に対応","ko":"도커 디버깅 스킬을 사용하여 빌드 실패, 런타임 오류 및 성능 최적화를 해결합니다. 멀티 플랫폼 환경 및 GAMP-5 인증에 적합","es":"Aprende a depurar operaciones de Docker con nuestra guía de mejores prácticas para desarrolladores, incluyendo solución de errores de compilación y ejecución","fr":"Découvrez comment déboguer les opérations Docker avec notre guide de configuration pour les développeurs, y compris la résolution des erreurs de build et d''e...","de":"Erfahren Sie, wie Sie Docker-Operationen mit unserem Einrichtungsleitfaden für Entwickler debuggen, einschließlich der Lösung von Build- und Laufzeitfehlern","pt":"Aprenda a depurar operações do Docker com nosso guia completo, incluindo solução de problemas de build, erros de runtime e otimização de desempenho","ru":"Узнайте, как отладить операции Docker с помощью нашего полного руководства, включая решение проблем с построением, ошибками runtime и оптимизацией производит...","ar":"تعلم كيفية تصحيح أخطاء عمليات دوكر باستخدام دليلنا الشامل، بما في ذلك حل مشاكل البناء وأخطاء وقت التشغيل وضبط الأداء"},"definition":{"en":"debugging-docker is a systematic approach to troubleshooting Docker operations, including build failures, runtime errors, and performance optimization","zh":"Docker 调试技能是用于解决 Docker 构建失败、运行时错误和性能优化问题的系统化故障排除工作流","ja":"Docker デバッグスキルとは、Docker のビルドの失敗、ランタイム エラー、パフォーマンスの最適化を解決するための体系的なトラブルシューティング ワークフローです","ko":"도커 디버깅 스킬은 도커 빌드 실패, 런타임 오류 및 성능 최적화를 해결하기 위한 체계적인 문제 해결 워크플로입니다","es":"Depuración de Docker es el proceso de identificar y solucionar errores en operaciones de Docker, como errores de compilación y ejecución","fr":"Le débogage Docker est le processus d''identification et de résolution des erreurs dans les opérations Docker, comme les erreurs de build et d''exécution","de":"Docker-Debugging ist der Prozess der Identifizierung und Lösung von Fehlern in Docker-Operationen, wie Build- und Laufzeitfehlern","pt":"Depuração de Docker é o processo de identificação e solução de problemas em operações do Docker, incluindo build, runtime e desempenho","ru":"Отладка Docker - это процесс выявления и решения проблем в операциях Docker, включая построение, runtime и производительность","ar":"تصحيح أخطاء دوكر هو عملية تحديد ومعالجة المشاكل في عمليات دوكر، بما في ذلك البناء ووقت التشغيل والأداء"},"features":{"en":["Troubleshoots Docker build failures, including package installation errors and COPY failures","Resolves runtime errors, such as container crashes and exit codes","Optimizes performance for multi-platform environments, including ARM64, AMD64, and WSL2","Supports GAMP-5 validation for pharmaceutical compliance contexts","Identifies and resolves layer caching issues and DNS resolution problems"],"zh":["解决 Docker 构建失败问题，例如包安装错误和层缓存问题","解决 Docker 运行时错误问题，例如容器崩溃和 DNS 解析问题","支持多平台环境，包括 ARM64、AMD64 和 WSL2","支持 GAMP-5 验证和药品合规性","提供性能优化功能，提高 Docker 容器的性能"],"ja":["Docker ビルドの失敗問題を解決します。パッケージのインストール エラーとレイヤー キャッシュの問題など","Docker ランタイム エラー問題を解決します。コンテナーのクラッシュと DNS 解決の問題など","マルチ プラットフォーム環境をサポートします。ARM64、AMD64、WSL2 など","GAMP-5 認定と薬品のコンプライアンスをサポートします","パフォーマンスの最適化機能を提供します。Docker コンテナーのパフォーマンスを向上させる"],"ko":["도커 빌드 실패 문제를 해결합니다. 패키지 설치 오류 및 레이어 캐싱 문제 등","도커 런타임 오류 문제를 해결합니다. 컨테이너 충돌 및 DNS 解析 문제 등","멀티 플랫폼 환경을 지원합니다. ARM64, AMD64, WSL2 등","GAMP-5 인증 및 제약물품 컴플라이언스를 지원합니다","성능 최적화 기능을 제공합니다. 도커 컨테이너의 성능을 향상시킵니다"],"es":["Solución de errores de compilación de Docker","Depuración de errores de ejecución en contenedores","Optimización del rendimiento en entornos multiplataforma","Compatibilidad con ARM64, AMD64 y WSL2","Validación GAMP-5 para contextos de cumplimiento farmacéutico"],"fr":["Résolution des erreurs de build de Docker","Débogage des erreurs d''exécution dans les conteneurs","Optimisation des performances dans des environnements multiplateformes","Compatibilité avec ARM64, AMD64 et WSL2","Validation GAMP-5 pour les contextes de conformité pharmaceutique"],"de":["Lösung von Build-Fehlern in Docker","Debugging von Laufzeitfehlern in Containern","Leistungsoptimierung in multiplattformigen Umgebungen","Kompatibilität mit ARM64, AMD64 und WSL2","GAMP-5-Validierung für pharmazeutische Compliance-Kontexte"],"pt":["Solução de problemas de build, incluindo erros de instalação de pacotes e falhas de COPY","Análise de erros de runtime, incluindo crashes de contêiner e códigos de saída","Otimização de desempenho em ambientes multiplataforma, incluindo ARM64, AMD64 e WSL2","Suporte a contextos de conformidade farmacêutica, incluindo validação GAMP-5"],"ru":["Решение проблем с построением, включая ошибки установки пакетов и сбой COPY","Анализ ошибок runtime, включая крахи контейнеров и коды выхода","Оптимизация производительности в многофункциональных средах, включая ARM64, AMD64 и WSL2","Поддержка контекстов фармацевтической соответствия, включая валидацию GAMP-5"],"ar":["حل مشاكل البناء، بما في ذلك أخطاء تثبيت الحزم وفشل COPY","تحليل أخطاء وقت التشغيل، بما في ذلك تحطم الحاويات وأكواد الخروج","ضبط الأداء في بيئات متعددة المنصات، بما في ذلك ARM64 وAMD64 وWSL2","دعم سياقات مطابقة دوائية، بما في ذلك التحقق من صحة GAMP-5"]},"keywords":{"en":["how to debug Docker","debugging-docker tutorial","Docker troubleshooting guide","debugging-docker vs traditional debugging","debugging-docker install","debugging-docker setup for multi-platform environments","GAMP-5 validation for Docker","Docker performance optimization techniques"],"zh":["Docker 调试","Docker 构建失败","Docker 运行时错误","Docker 性能优化","GAMP-5 验证","药品合规性","多平台环境","ARM64","AMD64","WSL2"],"ja":["Docker デバッグ","Docker ビルドの失敗","Docker ランタイム エラー","Docker パフォーマンスの最適化","GAMP-5 認定","薬品のコンプライアンス","マルチ プラットフォーム環境","ARM64","AMD64","WSL2"],"ko":["도커 디버깅","도커 빌드 실패","도커 런타임 오류","도커 성능 최적화","GAMP-5 인증","제약물품 컴플라이언스","멀티 플랫폼 환경","ARM64","AMD64","WSL2"],"es":["depuración de docker","errores de compilación de docker","errores de ejecución de docker","optimización de rendimiento de docker","docker para desarrolladores","herramientas de depuración de docker","mejores prácticas de docker"],"fr":["débogage docker","erreurs de build de docker","erreurs d''exécution de docker","optimisation des performances de docker","docker pour les développeurs","outils de débogage de docker","meilleures pratiques de docker"],"de":["docker-debugging","docker-build-fehler","docker-laufzeitfehler","docker-leistungsoptimierung","docker für entwickler","docker-debugging-tools","docker-best-practices"],"pt":["depuração de docker","solução de problemas de build","erros de runtime","otimização de desempenho","ambientes multiplataforma","conformidade farmacêutica","GAMP-5","desenvolvimento de software","contêineres"],"ru":["отладка docker","решение проблем с построением","ошибки runtime","оптимизация производительности","многофункциональные среды","фармацевтическая соответствия","GAMP-5","разработка программного обеспечения","контейнеры"],"ar":["تصحيح أخطاء دوكر","حل مشاكل البناء","أخطاء وقت التشغيل","ضبط الأداء","بيئات متعددة المنصات","مطابقة دوائية","GAMP-5","تطوير البرمجيات","الحاويات"]}},"owner":"Danik911","repo":"thesis_project","repoPath":"Danik911/thesis_project","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.414Z","topics":[],"category":"community","skillMd":{"name":"debugging-docker","description":"Debugs Docker build failures, container runtime errors, platform architecture issues (ARM64/AMD64/WSL2), AWS ECR/ECS pull failures, and optimizes Docker workflows. Use when encountering Docker build errors, container crashes, ECR authentication issues, ECS deployment problems, performance issues, networking failures, volume permission errors, or when working with multi-platform Docker images.","bodyPreview":"# Debugging Docker Operations\n\n## Overview\n\nSystematic troubleshooting workflows for Docker build failures, runtime errors, AWS container services, platform-specific issues, and performance optimization. Designed for multi-platform environments (ARM64/AMD64/WSL2) with pharmaceutical compliance contexts requiring GAMP-5 validation.\n\n## When to Use\n\n- **Build Failures**: Package installation errors, COPY failures, layer caching issues\n- **Runtime Errors**: Container crashes, exit codes, DNS resolu","body":"# Debugging Docker Operations\n\n## Overview\n\nSystematic troubleshooting workflows for Docker build failures, runtime errors, AWS container services, platform-specific issues, and performance optimization. Designed for multi-platform environments (ARM64/AMD64/WSL2) with pharmaceutical compliance contexts requiring GAMP-5 validation.\n\n## When to Use\n\n- **Build Failures**: Package installation errors, COPY failures, layer caching issues\n- **Runtime Errors**: Container crashes, exit codes, DNS resolution, port conflicts\n- **AWS Container Services**: ECR authentication, ECS pull failures, rate limiting\n- **Platform Issues**: ARM64 vs AMD64 emulation, WSL2 integration, cross-platform builds\n- **Performance Problems**: Slow builds, large images, QEMU emulation overhead\n- **Volumes/Networking**: Permission errors, mount failures, port binding\n\n---\n\n## Available Tools\n\n### Standard Tools\n| Tool | Purpose |\n|------|---------|\n| Bash | Execute Docker commands, view logs |\n| Read | Examine Dockerfiles, compose files |\n| Grep | Search for patterns in logs |\n| Glob | Find Docker-related files |\n\n### AWS MCP Tools\n| Tool | Purpose |\n|------|---------|\n| `mcp__aws-api-mcp__call_aws` | Execute AWS CLI for ECR/ECS operations |\n| `mcp__aws-knowledge-mcp__aws___search_documentation` | Search AWS docs for container guidance |\n| `mcp__aws-ccapi-mcp__list_resources` | List ECS tasks, ECR repositories |\n\n---\n\n## Core Workflow\n\n### Phase 1: Symptom Diagnosis\n\n**Objective**: Identify problem category and gather diagnostic information\n\n1. **Identify Problem Type**\n   ```bash\n   # For build failures\n   docker build 2>&1 | tee build.log\n\n   # For runtime errors\n   docker logs <container-name>\n   docker inspect <container-name>\n\n   # For AWS issues\n   aws ecr describe-repositories\n   aws ecs describe-tasks --cluster <cluster> --tasks <task-arn>\n   ```\n\n2. **Categorize the Issue**\n   - Build Failure (exit during `docker build`)\n   - Runtime Error (container exits or crashes)\n   - AWS ECR/ECS Issue (authentication, pull failures)\n   - Platform/Architecture Issue (ARM64/AMD64 mismatch)\n   - Performance Problem (slow or inefficient)\n   - Networking/Volume Issue\n\n3. **Collect Context**\n   ```bash\n   docker version && docker info | head -30\n   uname -m  # Platform: x86_64 or aarch64\n   ```\n\n**Quality Gate**: Problem type identified, initial logs collected\n\n---\n\n### Phase 2: Root Cause Analysis\n\n#### Build Failures\n\n**Common Patterns:**\n```bash\n# Check build log for specific failures\ngrep -E \"ERROR|failed|error:\" build.log\n\n# Common patterns:\n# \"COPY failed\" → File not in build context\n# \"returned a non-zero code\" → Command failed\n# \"no matching manifest\" → Platform mismatch\n```\n\n**Key Checks:**\n- Build context: `ls -la <path-to-file>`\n- .dockerignore: `cat .dockerignore`\n- Layer caching: `docker build --no-cache`\n\nSee `reference/common-errors.md` for complete error matrix.\n\n#### Runtime Errors\n\n**Exit Code Quick Reference:**\n\n| Code | Meaning | Common Cause |\n|------|---------|--------------|\n| 0 | Normal exit | Application completed |\n| 1 | Application error | Check application logs |\n| 126 | Cannot execute | Permission issue |\n| 127 | Command not found | Wrong CMD/ENTRYPOINT |\n| 137 | OOM killed | Memory limit exceeded |\n| 139 | Segfault | Application crash |\n| 143 | SIGTERM | Graceful shutdown |\n\n**Diagnosis:**\n```bash\ndocker inspect <container> | jq ''.[0].State''\ndocker logs --tail 100 <container>\n```\n\n#### AWS ECR/ECS Issues\n\n**ECR Authentication:**\n```\nError: \"no basic auth credentials\"\n```\n- **Cause**: ECR login token expired (12-hour validity)\n- **Fix**:\n  ```bash\n  aws ecr get-login-password --region eu-west-2 | \\\n    docker login --username AWS --password-stdin \\\n    <account-id>.dkr.ecr.eu-west-2.amazonaws.com\n  ```\n\n**ECS Pull Failures:**\n```\nError: \"CannotPullContainerError\"\n```\n- **Checklist**:\n  1. Task execution role has ECR permissions\n  2. VPC has NAT Gateway (for private subnets)\n  3. Image tag exists in ECR\n\n**Using AWS MCP:**\n```\n# Check ECR images\nmcp__aws-api-mcp__call_aws: aws ecr describe-images --repository-name <repo>\n\n# Check ECS task failures\nmcp__aws-api-mcp__call_aws: aws ecs describe-tasks --cluster <cluster> --tasks <task-arn>\n```\n\nSee `reference/aws-ecr-ecs.md` for complete AWS troubleshooting guide.\n\n#### Platform/Architecture Issues\n\n**Slow Build Detection:**\n```bash\n# Check if emulation is active (ARM64 host building AMD64)\ndocker run --rm --platform=linux/amd64 alpine uname -m\n# If output shows x86_64 on ARM64 host → emulation active (slow)\n```\n\n**Solutions:**\n1. Use native platform for development\n2. Build target platform only for deployment\n3. Use multi-stage with `${BUILDPLATFORM}`\n\nSee `reference/platform-guide.md` for complete platform guidance.\n\n**Quality Gate**: Root cause identified, specific error patterns documented\n\n---\n\n### Phase 3: Solution & Validation\n\n#### Build Failure Fixes\n\n```dockerfile\n# Fix missing file in context\n# Verify path exists: ls -la <path>\nCOPY main.py /app/\n\n# Fix package installation with retry\nRUN pip install --no-cache-dir -r requirements.txt || \\\n    (pip install --upgrade pip && pip install --no-cache-dir -r requirements.txt)\n\n# Fix platform issues\n# docker build --platform=linux/amd64 -t image:prod .\n```\n\n#### Runtime Error Fixes\n\n```bash\n# Fix permission issues\ndocker run --user $(id -u):$(id -g) image:tag\n\n# Fix OOM (Exit 137)\ndocker run -m 2g --memory-swap 2g image:tag\n\n# Fix port conflicts\ndocker run -p 8081:8080 image:tag  # Change host port\n```\n\n#### AWS Fixes\n\n```bash\n# Refresh ECR credentials\naws ecr get-login-password --region eu-west-2 | docker login --username AWS --password-stdin <account>.dkr.ecr.eu-west-2.amazonaws.com\n\n# Fix Docker Hub rate limiting - use ECR Public\n# FROM public.ecr.aws/docker/library/python:3.12-slim\n```\n\n#### Validation\n\n```bash\n# Rebuild with verbose output\ndocker build --progress=plain -f Dockerfile -t image:test .\n\n# Test container startup\ndocker run --rm image:test\n\n# Verify functionality\ndocker run -it image:test /bin/sh -c \"command-to-test\"\n```\n\n**Quality Gate**: Fix applied, container builds and runs without errors\n\n---\n\n## Quick Reference Table\n\n| Problem | Quick Check | Common Fix |\n|---------|-------------|------------|\n| ECR \"no basic auth\" | Token age (12hr) | `aws ecr get-login-password \\| docker login` |\n| ECS CannotPull | Task role, NAT | Check IAM + VPC config |\n| Docker Hub rate limit | Error message | Use ECR Public or authenticate |\n| Build fails at COPY | `ls -la <file>` | Fix path or add to build context |\n| Package install fails | Check network | Update pip, verify package name |\n| Exit 137 (OOM) | `docker inspect` OOMKilled | Increase memory limit (-m flag) |\n| Exit 127 | Command not found | Fix CMD/ENTRYPOINT path |\n| Slow ARM64 build | `--platform` flag | Use native ARM64 for dev |\n| WSL2 vmmem bloat | Task Manager | `.wslconfig` memory limits |\n| Volume mount not working | Check compose mounts | `docker-compose down && up -d` |\n| Port already in use | `docker ps` | Change host port or stop conflict |\n| Permission denied | Check USER in Dockerfile | Add USER directive, fix volume perms |\n\n---\n\n## Best Practices\n\n### Build Optimization\n- **Layer ordering**: Dependencies before code (cache efficiency)\n- **Multi-stage builds**: Separate build and runtime environments\n- **Use .dockerignore**: Exclude `node_modules`, `.git`, `__pycache__`\n\n### Security\n```dockerfile\n# Non-root user\nRUN adduser -D appuser\nUSER appuser\n\n# Never COPY secrets - use --secret flag\n```\n\n### Platform Handling\n```bash\n# Development (native platform - fast)\ndocker build -t image:dev .\n\n# Production (target platform)\ndocker build --platform=linux/amd64 -t image:prod .\n\n# Multi-platform with cache\ndocker buildx build \\\n  --platform linux/amd64,linux/arm64 \\\n  --cache-from type=registry,ref=<repo>:cache \\\n  --cache-to type=registry,ref=<repo>:cache \\\n  -t image:multi --push .\n```\n\n### WSL2 Performance\n- Store projects in WSL2 filesystem (`~/`), NOT Windows mount (`/mnt/c/`)\n- Configure `.wslconfig` with memory limits\n- Use `wsl --shutdown` to reclaim memory\n\nSee `reference/wsl2-optimization.md` for complete WSL2 guide.\n\n---\n\n## Common Pitfalls\n\n### Don''t: Use relative paths without verification\n```dockerfile\n# WRONG - may fail if context is incorrect\nCOPY ../app/file.py /app/\n\n# RIGHT - relative to build context root\nCOPY app/file.py /app/\n```\n\n### Do: Use explicit platform for production\n```bash\n# WRONG - platform inferred (may differ from prod)\ndocker build -t api:latest .\n\n# RIGHT - explicit platform\ndocker build --platform=linux/amd64 -t api:latest .\n```\n\n### Do: Verify volume mounts work\n```bash\n# Check if container sees host files\ndocker exec <container> ls -la /app/\n\n# Recreate containers after mount changes\ndocker-compose down && docker-compose up -d\n```\n\n---\n\n## Quality Checklist\n\n- [ ] Problem type identified (build/runtime/AWS/platform/network/volume)\n- [ ] Diagnostic logs collected and analyzed\n- [ ] Root cause determined with specific error patterns\n- [ ] Solution applied with appropriate fix\n- [ ] Build succeeds without errors\n- [ ] Container starts and runs successfully\n- [ ] Functionality validated\n- [ ] Platform architecture verified (matches deployment target)\n- [ ] Security checked (non-root user, no exposed secrets)\n\n---\n\n## Detailed References\n\n- **Docker Commands**: `reference/docker-commands.md`\n- **Common Error Matrix**: `reference/common-errors.md` (20+ error patterns)\n- **AWS ECR/ECS Guide**: `reference/aws-ecr-ecs.md`\n- **Platform Guide**: `reference/platform-guide.md` (ARM64/AMD64/WSL2, buildx caching)\n- **WSL2 Optimization**: `reference/wsl2-optimization.md`\n- **Build Optimization**: `reference/build-optimization.md`\n- **Security Hardening**: `reference/security-hardening.md`\n\n## Diagnostic Scripts\n\n- **Build Failure Analysis**: `scripts/analyze-build-failure.sh <log-file>`\n- **Container Inspection**: `scripts/inspect-container.sh <container-name>`\n- **Platform Check**: `scripts/check-platform.sh`\n\n---\n\n**Remember**: Docker issues are systematic and diagnosable. Follow the three-phase workflow (Symptom → Root Cause → Solution), use AWS MCP tools for ECR/ECS issues, and reference the detailed guides for complex scenarios. Always validate fixes before considering the issue resolved.\n"},"lastSynced":"2026-03-08T02:07:09.383Z","agentAnalysis":{"suitability":{"en":"Perfect for DevOps Agents needing systematic Docker troubleshooting workflows for build failures and runtime errors in multi-platform environments","zh":"非常适合需要系统性的Docker故障排除工作流程来解决构建失败和运行时错误的DevOps代理，特别是在多平台环境中","ja":"DevOpsエージェントがマルチプラットフォーム環境でビルドの失敗やランタイムエラーを解決するための体系的なDockerトラブルシューティングワークフローに最適","ko":"다중 플랫폼 환경에서 빌드 실패 및 런타임 오류를 시스템적으로 해결해야 하는 DevOps 에이전트에 적합","es":"Perfecto para agentes de DevOps que necesitan flujos de trabajo de depuración de Docker sistemáticos para fallos de compilación y errores de tiempo de ejecución en entornos multiplataforma","fr":"Parfait pour les agents DevOps ayant besoin de flux de travail de dépannage Docker systématiques pour les échecs de build et les erreurs d''exécution dans des environnements multi-plateformes","de":"Perfekt für DevOps-Agents, die systematische Docker-Fehlerbehebungs-Workflows für Build-Fehler und Laufzeitfehler in Multi-Plattform-Umgebungen benötigen","pt":"Perfeito para agentes DevOps que precisam de fluxos de trabalho de solução de problemas do Docker sistemáticos para falhas de build e erros de tempo de execução em ambientes multiplataforma","ru":"Идеально подходит для агентов DevOps, которым необходимы системные рабочие процессы устранения неполадок Docker для сбойных сборок и ошибок во время выполнения в много платформенных средах","ar":"مثالي للوكلاء DevOps الذين يحتاجون إلى تدفقات عمل منهجية لتصحيح أخطاء Docker لفشل البناء وأخطاء وقت التشغيل في بيئات متعددة المنصات"},"recommendation":{"en":"Empowers agents to diagnose and resolve Docker build failures, runtime errors, and performance optimization issues using systematic troubleshooting workflows, including package installation errors, COPY failures, and layer caching issues, with support for AWS container services and GAMP-5 validation","zh":"赋予代理诊断和解决Docker构建失败、运行时错误和性能优化问题的能力，使用系统性的故障排除工作流程，包括包安装错误、COPY失败和层缓存问题，并支持AWS容器服务和GAMP-5验证","ja":"Dockerのビルドの失敗やランタイムエラー、パフォーマンス最適化の問題を、体系的なトラブルシューティングワークフローを使用して診断し解決するエージェントの能力を提供します。パッケージのインストールエラー、COPYの失敗、レイヤーキャッシュの問題などを含み、AWSコンテナサービスやGAMP-5の検証もサポート","ko":"에이전트가 시스템적인 트러블슈팅 워크플로를 사용하여 도커 빌드 실패, 런타임 오류 및 성능 최적화 문제를 진단하고 해결할 수 있도록 합니다. 패키지 설치 오류, COPY 실패 및 계층 캐싱 문제를 포함하며 AWS 컨테이너 서비스 및 GAMP-5 검증을 지원합니다.","es":"Habilita a los agentes a diagnosticar y resolver errores de compilación de Docker, errores de tiempo de ejecución y problemas de optimización del rendimiento utilizando flujos de trabajo de depuración sistemáticos, incluidos errores de instalación de paquetes, errores de copia y problemas de caché de capas, con soporte para servicios de contenedores de AWS y validación de GAMP-5","fr":"Permet aux agents de diagnostiquer et de résoudre les échecs de build Docker, les erreurs d''exécution et les problèmes d''optimisation des performances en utilisant des flux de travail de dépannage systématiques, notamment les erreurs d''installation de packages, les échecs de copie et les problèmes de mise en cache de couches, avec un support pour les services de conteneurs AWS et la validation GAMP-5","de":"Ermächtigt Agents, Docker-Build-Fehler, Laufzeitfehler und Leistungsoptimierungsprobleme mithilfe systematischer Fehlerbehebungs-Workflows zu diagnostizieren und zu lösen, einschließlich Paketinstallationsfehlern, COPY-Fehlern und Layer-Caching-Problemen, mit Unterstützung für AWS-Containerdienste und GAMP-5-Validierung","pt":"Habilita os agentes a diagnosticar e resolver falhas de build do Docker, erros de tempo de execução e problemas de otimização de desempenho usando fluxos de trabalho de solução de problemas sistemáticos, incluindo erros de instalação de pacotes, falhas de Cópia e problemas de cache de camada, com suporte a serviços de contêiner do AWS e validação GAMP-5","ru":"Наделяет агентов возможностью диагностировать и решать проблемы сборки Docker, ошибки во время выполнения и вопросы оптимизации производительности с помощью системных рабочих процессов устранения неполадок, включая ошибки установки пакетов, сбой копирования и проблемы кэширования слоев, с поддержкой сервисов контейнеров AWS и проверкой GAMP-5","ar":"يمنح الوكلاء القدرة على تشخيص ومعالجة مشاكل بناء Docker والأخطاء أثناء التنفيذ ومشاكل تحسين الأداء باستخدام تدفقات عمل منهجية لتصحيح الأخطاء، بما في ذلك أخطاء تثبيت الحزم وفشل النسخ ومشاكل ذاكرة التخزين المؤقت للطبقات، مع دعم خدمات حاويات AWS و التحقق من GAMP-5"},"useCases":{"en":["Debugging Docker build failures due to package installation errors or COPY failures","Resolving runtime errors such as container crashes or DNS resolution issues","Optimizing Docker performance in multi-platform environments, including ARM64, AMD64, and WSL2"],"zh":["由于包安装错误或COPY失败导致的Docker构建失败的调试","解决运行时错误，如容器崩溃或DNS解析问题","在多平台环境中（包括ARM64、AMD64和WSL2）优化Docker性能"],"ja":["パッケージのインストールエラーまたはCOPYの失敗により発生するDockerのビルドの失敗のデバッグ","コンテナーのクラッシュやDNSの解決などのランタイムエラーの解決","ARM64、AMD64、WSL2を含むマルチプラットフォーム環境でDockerのパフォーマンスを最適化"],"ko":["패키지 설치 오류 또는 COPY 실패로 인해 발생하는 도커 빌드 실패의 디버깅","컨테이너 충돌 또는 DNS 해석과 같은 런타임 오류의 해결","ARM64, AMD64 및 WSL2를 포함한 다중 플랫폼 환경에서 도커 성능을 최적화"],"es":["Depuración de errores de compilación de Docker debido a errores de instalación de paquetes o errores de copia","Resolución de errores de tiempo de ejecución como fallos de contenedores o problemas de resolución de DNS","Optimización del rendimiento de Docker en entornos multiplataforma, incluidos ARM64, AMD64 y WSL2"],"fr":["Débogage des échecs de build Docker en raison d''erreurs d''installation de packages ou d''échecs de copie","Résolution des erreurs d''exécution telles que les échecs de conteneur ou les problèmes de résolution DNS","Optimisation des performances de Docker dans des environnements multi-plateformes, notamment ARM64, AMD64 et WSL2"],"de":["Fehlerbehebung bei Docker-Build-Fehlern aufgrund von Paketinstallationsfehlern oder COPY-Fehlern","Behebung von Laufzeitfehlern wie Containerrückschlägen oder DNS-Auflösungsproblemen","Optimierung der Docker-Leistung in Multi-Plattform-Umgebungen, einschließlich ARM64, AMD64 und WSL2"],"pt":["Depuração de falhas de build do Docker devido a erros de instalação de pacotes ou falhas de Cópia","Resolução de erros de tempo de execução, como falhas de contêiner ou problemas de resolução de DNS","Otimização do desempenho do Docker em ambientes multiplataforma, incluindo ARM64, AMD64 e WSL2"],"ru":["Отладка сбойных сборок Docker из-за ошибок установки пакетов или сбоев копирования","Решение ошибок во время выполнения, таких как сбои контейнеров или проблемы с разрешением DNS","Оптимизация производительности Docker в много платформенных средах, включая ARM64, AMD64 и WSL2"],"ar":["تصحيح أخطاء بناء Docker بسبب أخطاء تثبيت الحزم أو فشل النسخ","معالجة أخطاء وقت التنفيذ، مثل فشل الحاويات أو مشاكل حل DNS","تحسين أداء Docker في بيئات متعددة المنصات، بما في ذلك ARM64 وAMD64 وWSL2"]},"limitations":{"en":["Requires Docker installation and configuration","Limited to Docker-specific troubleshooting, not applicable to other containerization platforms"],"zh":["需要Docker的安装和配置","仅限于Docker特有的故障排除，不适用于其他容器化平台"],"ja":["Dockerのインストールと設定が必要","Docker固有のトラブルシューティングに限定され、他のコンテナ化プラットフォームには適用されない"],"ko":["도커 설치 및 구성이 필요","도커 고유의 트러블슈팅에만 국한되며 다른 컨테이너화 플랫폼에는 적용되지 않음"],"es":["Requiere instalación y configuración de Docker","Limitado a la depuración específica de Docker, no aplicable a otras plataformas de contenerización"],"fr":["Nécessite l''installation et la configuration de Docker","Limité au dépannage spécifique de Docker, non applicable à d''autres plateformes de conteneurisation"],"de":["Benötigt Docker-Installation und -Konfiguration","Begrenzt auf spezifische Docker-Fehlerbehebung, nicht anwendbar auf andere Containerisierungsplattformen"],"pt":["Requer instalação e configuração do Docker","Limitado à solução de problemas específica do Docker, não se aplica a outras plataformas de contêiner"],"ru":["Требует установки и настройки Docker","Ограничен только устранением неполадок Docker, не применимо к другим платформам контейнеризации"],"ar":["يتطلب تثبيت وتهيئة Docker","محدود بتصحيح أخطاء Docker فقط، لا ينطبق على منصات حاويات أخرى"]},"version":4},"contentHash":"82f286487a334cec6fe83577e009becd6e66ed92598577b5a0e28c2b57cc5708","qualityScore":57}');
