INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Danik911/thesis_project/debugging-docker', 'debugging-docker', 'Danik911', 'thesis_project', 'community', 'debugging-docker Danik911 thesis_project community The debugging-docker skill provides systematic troubleshooting workflows for Docker build failures, runtime errors, and performance optimization, benefiting developers in multi-platform environments Docker 调试技能提供系统化的故障排除工作流，用于解决构建失败、运行时错误和性能优化问题 Docker デバッグスキルは、ビルドの失敗、ランタイム エラー、パフォーマンスの最適化を解決するための体系的なトラブルシューティング ワークフローを提供します 도커 디버깅 스킬은 빌드 실패, 런타임 오류 및 성능 최적화를 해결하기 위한 체계적인 문제 해결 워크플로를 제공합니다 Depuración de operaciones de Docker para desarrolladores, incluyendo solución de errores de compilación y ejecución en entornos multiplataforma Débogage des opérations Docker pour les développeurs, y compris la résolution des erreurs de build et d''exécution dans des environnements multiplateformes Debugging von Docker-Operationen für Entwickler, einschließlich der Lösung von Build- und Laufzeitfehlern in multiplattformigen Umgebungen O skill de depuração de Docker fornece fluxos de trabalho sistemáticos para solução de problemas de build, erros de runtime e otimização de desempenho em ambientes multiplataforma Навык отладки Docker предоставляет системные рабочие процессы для решения проблем с построением, ошибками runtime и оптимизацией производительности в многофункциональных средах مهارة تصحيح أخطاء دوكر توفر عمليات عمل منهجية لحل مشاكل البناء وأخطاء وقت التشغيل وضبط الأداء في بيئات متعددة المنصات how to debug Docker debugging-docker tutorial Docker troubleshooting guide debugging-docker vs traditional debugging debugging-docker install debugging-docker setup for multi-platform environments GAMP-5 validation for Docker Docker performance optimization techniques Docker 调试 Docker 构建失败 Docker 运行时错误 Docker 性能优化 GAMP-5 验证 药品合规性 多平台环境 ARM64 AMD64 WSL2 Troubleshoots Docker build failures, including package installation errors and COPY failures Resolves runtime errors, such as container crashes and exit codes Optimizes performance for multi-platform environments, including ARM64, AMD64, and WSL2 Supports GAMP-5 validation for pharmaceutical compliance contexts Identifies and resolves layer caching issues and DNS resolution problems debugging-docker is a systematic approach to troubleshooting Docker operations, including build failures, runtime errors, and performance optimization');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ihmorol/data-collection-web/app-builder', 'community', 'ihmorol', 'data-collection-web', 'ihmorol/data-collection-web', 'app-builder', 0, 0, 57, '2026-03-08T01:57:15.435Z', '2026-03-08T02:07:38.234Z', '0169334a5adab93cfb503fab2c66aa377c2a7177e49c3b0c0094365eb3bb5baa', '{"id":"ihmorol/data-collection-web/app-builder","name":"app-builder","description":{"en":"The app-builder skill analyzes user requests, determines the optimal tech stack, plans the project structure, and coordinates agents for efficient application building. This skill benefits developers and project managers by streamlining the application development process.","zh":"应用构建器是一种应用程序构建编排工具，分析用户请求，确定技术栈，规划结构和协调代理","ja":"アプリケーションビルダーは、アプリケーションをビルドするためのオーケストレーションツールです。ユーザーのリクエストを分析し、テクノロジー・スタックを決定します","ko":"애플리케이션 빌더는 애플리케이션을 빌드하는 오케스트레이션 도구입니다. 사용자의 요청을 분석하고 기술 스택을 결정하며 구조를 계획하고 에이전트를 조정합니다","es":"App Builder es una herramienta de orquestación que analiza solicitudes de usuarios, determina la pila tecnológica y coordina agentes. Utiliza tecnologías como Python y React","fr":"App Builder est un outil d''orchestration qui analyse les demandes des utilisateurs, détermine la pile technologique et coordonne les agents. Il utilise des technologies comme Python et React","de":"App Builder ist ein Orchestrierungstool, das Benutzeranfragen analysiert, die Technologie-Stack bestimmt und Agenten koordiniert. Es verwendet Technologien wie Python und React","pt":"O App Builder é uma ferramenta de orquestração de aplicativos que analisa solicitações de usuários e determina a pilha de tecnologia. Ele coordena agentes e planeja a estrutura do aplicativo","ru":"App Builder - это инструмент для создания приложений ИИ Агенты, который анализирует запросы пользователей и определяет технологическую стек. Он координирует агентов и планирует структуру приложения","ar":"