INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ihmorol/data-collection-web/app-builder', 'app-builder', 'ihmorol', 'data-collection-web', 'community', 'app-builder ihmorol data-collection-web community The app-builder skill analyzes user requests, determines the optimal tech stack, plans the project structure, and coordinates agents for efficient application building. This skill benefits developers and project managers by streamlining the application development process. 应用构建器是一种应用程序构建编排工具，分析用户请求，确定技术栈，规划结构和协调代理 アプリケーションビルダーは、アプリケーションをビルドするためのオーケストレーションツールです。ユーザーのリクエストを分析し、テクノロジー・スタックを決定します 애플리케이션 빌더는 애플리케이션을 빌드하는 오케스트레이션 도구입니다. 사용자의 요청을 분석하고 기술 스택을 결정하며 구조를 계획하고 에이전트를 조정합니다 App Builder es una herramienta de orquestación que analiza solicitudes de usuarios, determina la pila tecnológica y coordina agentes. Utiliza tecnologías como Python y React App Builder est un outil d''orchestration qui analyse les demandes des utilisateurs, détermine la pile technologique et coordonne les agents. Il utilise des technologies comme Python et React App Builder ist ein Orchestrierungstool, das Benutzeranfragen analysiert, die Technologie-Stack bestimmt und Agenten koordiniert. Es verwendet Technologien wie Python und React O App Builder é uma ferramenta de orquestração de aplicativos que analisa solicitações de usuários e determina a pilha de tecnologia. Ele coordena agentes e planeja a estrutura do aplicativo App Builder - это инструмент для создания приложений ИИ Агенты, который анализирует запросы пользователей и определяет технологическую стек. Он координирует агентов и планирует структуру приложения بناء التطبيقات هو أداة لorchestration التطبيقات التي تحليل طلبات المستخدمين وتحدد مجموعة التكنولوجيا. أنها تتنسيق الوكلاء وتخطط هيكل التطبيق how to use app-builder app-builder alternative app-builder setup guide what is app-builder app-builder vs other orchestrators app-builder install app-builder for AI agents application building orchestrator tech stack determination project type detection 应用构建器 AI应用构建 技术栈 项目检测 tech-stack.md 应用程序构建 AI驱动的应用程序构建 应用构建工具 Analyzes user requests to determine the optimal tech stack Plans project structure based on the detected project type Coordinates agents for efficient application building Utilizes a keyword matrix for project type detection as described in project-detection.md References the 2025 default stack and alternatives from tech-stack.md for tech stack determination app-builder is an application building orchestrator that analyzes user requests, determines the tech stack, plans the structure, and coordinates agents for efficient project execution.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('get-convex/convex-evals/analyze-eval', 'community', 'get-convex', 'convex-evals', 'get-convex/convex-evals', 'analyze-eval', 0, 0, 57, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:45.084Z', '7eb24519ebc06816147beb0de1413fda1c68663a66f53c3dc90260ef396dfac0', '{"id":"get-convex/convex-evals/analyze-eval","name":"analyze-eval","description":{"en":"The analyze-eval skill helps developers diagnose eval failures by extracting eval IDs from URLs. It supports Convex document IDs and visualizer URL patterns.","zh":"analyze-eval 技能用于排除 Convex 评估故障，通过提取 URL 中的评估 ID 来诊断问题","ja":"analyze-eval スキルは、Convex Eval の故障を診断するために使用され、URL から評価 ID を抽出して問題を解決します","ko":"analyze-eval 스킬은 Convex 평가 오류를 분석하고 URL에서 평가 ID를 추출하여 문제를 해결하는 데 사용됩니다","es":"Analyze-eval es una herramienta para evaluar experimentos y diagnosticar errores. Extrae el ID de evaluación de la URL y analiza los resultados","fr":"Analyze-eval est un outil pour évaluer les expériences et diagnostiquer les erreurs. Il extrait l''ID d''évaluation de l''URL et analyse les résultats","de":"Analyze-eval ist ein Tool zur Auswertung von Experimenten und Fehlerdiagnose. Es extrahiert die Bewertungs-ID aus der URL und analysiert die Ergebnisse","pt":"O Analyze-Eval é uma ferramenta de análise de URLs que ajuda a identificar erros em experimentos de Convex","ru":"Analyze-Eval - это инструмент анализа URL, который помогает выявить ошибки в экспериментах Convex","ar":"Analyze-Eval هو أداة تحليل URL تساعد في تحديد الأخطاء في تجارب Convex"},"seo":{"title":{"en":"analyze-eval: Eval Failure Analysis Setup Guide | AI Agen...","zh":"analyze-eval 设置指南：Convex 评估故障排除","ja":"analyze-eval セットアップガイド：ConvexEval の故障診断","ko":"analyze-eval 설정 가이드: Convex 평가 오류 분석","es":"Guía de configuración de analyze-eval para evaluar experi...","fr":"Guide de configuration d''analyze-eval pour évaluer les ex...","de":"Einrichtungsleitfaden für analyze-eval zur Auswertung von...","pt":"Guia de Configuração do Analyze-Eval: Ferramentas de Anál...","ru":"Настройка Analyze-Eval: Лучшие практики для ИИ Агентов","ar":"دليل إعداد Analyze-Eval: أدوات تحليل إجابة العميل"},"description":{"en":"Troubleshoot eval failures with analyze-eval. Learn how to extract eval IDs from URLs and diagnose issues. Get started with our setup guide today!","zh":"了解如何使用 analyze-eval 技能排除 Convex 评估故障，并从 URL 中提取评估 ID","ja":"Convex Eval の故障を診断するために、analyze-eval スキルの使用方法を学びます。また、URL から評価 ID を抽出する方法についても説明しています","ko":"analyze-eval 스킬을 사용하여 Convex 평가 오류를 분석하고 URL에서 평가 ID를 추출하는 방법에 대해 알아보세요","es":"Aprende a utilizar analyze-eval para evaluar experimentos y diagnosticar errores con nuestra guía paso a paso","fr":"Découvrez comment utiliser analyze-eval pour évaluer les expériences et diagnostiquer les erreurs avec notre guide étape par étape","de":"Erfahren Sie, wie Sie analyze-eval verwenden, um Experimente auszuwerten und Fehler zu diagnostizieren, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o Analyze-Eval para análise de URLs e identificação de erros em experimentos de Convex","ru":"Узнайте, как настроить Analyze-Eval для анализа URL и выявления ошибок в экспериментах Convex","ar":"تعلم كيفية إعداد Analyze-Eval لتحليل URLs وتحديد الأخطاء في تجارب Convex"},"definition":{"en":"analyze-eval is a skill that analyzes eval failures by extracting eval IDs from URLs, supporting Convex document IDs and visualizer URL patterns.","zh":"analyze-eval 是一种 Convex 评估故障排除技能，用于提取 URL 中的评估 ID","ja":"analyze-eval は Convex Eval の故障診断スキルで、URL から評価 ID を抽出するために使用されます","ko":"analyze-eval은 Convex 평가 오류를 분석하고 URL에서 평가 ID를 추출하는 스킬입니다","es":"Analyze-eval es una herramienta de evaluación de experimentos que ayuda a diagnosticar errores","fr":"Analyze-eval est un outil d''évaluation d''expériences qui aide à diagnostiquer les erreurs","de":"Analyze-eval ist ein Auswertungstool für Experimente, das bei der Fehlerdiagnose hilft","pt":"O que é Analyze-Eval? Uma ferramenta de análise de URLs para identificar erros em experimentos de Convex","ru":"Что такое Analyze-Eval? Инструмент анализа URL для выявления ошибок в экспериментах Convex","ar":"ما هو Analyze-Eval؟ أداة تحليل URL لتحديد الأخطاء في تجارب Convex"},"features":{"en":["Extracts eval IDs from visualizer URLs using the pattern /experiment/$experimentId/run/$runId/$category/$evalId","Supports Convex document IDs for runs, such as jn7922j1w29pdxm76bj9ps0enx80mg9e","Analyzes eval failures based on specific eval IDs","Handles URLs like https://convex-evals.netlify.app/experiment/.../run/$runId/$category/$evalId","Diagnoses issues with evals using the extracted eval ID"],"zh":["从 URL 中提取评估 ID","支持 Convex 文档 ID","Convex 评估故障排除","使用 Visualizer URL 模式","支持多种运行 ID 和评估 ID 格式"],"ja":["URL から評価 ID を抽出","Convex ドキュメント ID をサポート","Convex Eval の故障診断","Visualizer URL パターンを使用","複数の実行 ID および評価 ID フォーマットをサポート"],"ko":["URL에서 평가 ID 추출","Convex 문서 ID 지원","Convex 평가 오류 분석","Visualizer URL 패턴 사용","다양한 실행 ID 및 평가 ID 형식 지원"],"es":["Extracción del ID de evaluación de la URL","Análisis de resultados de experimentos","Diagnóstico de errores en la evaluación","Compatibilidad con URLs de Convex","Análisis de categorías y IDs de ejecución"],"fr":["Extraction de l''ID d''évaluation de l''URL","Analyse des résultats d''expériences","Diagnostic des erreurs d''évaluation","Compatibilité avec les URLs de Convex","Analyse de catégories et d''IDs d''exécution"],"de":["Extraktion der Bewertungs-ID aus der URL","Analyse der Ergebnisse von Experimenten","Fehlerdiagnose bei der Auswertung","Kompatibilität mit Convex-URLs","Analyse von Kategorien und Ausführungs-IDs"],"pt":["Extração do ID de avaliação a partir da URL","Análise de URLs de experimentos de Convex","Identificação de erros em runs de experimentos","Suporte a URLs de formato `/experiment/$experimentId/run/$runId/$category/$evalId`","Integração com a plataforma Convex"],"ru":["Извлечение ID оценки из URL","Анализ URL экспериментов Convex","Выявление ошибок в запусках экспериментов","Поддержка URL формата `/experiment/$experimentId/run/$runId/$category/$evalId`","Интеграция с платформой Convex"],"ar":["استخراج معرف التقييم من URL","تحليل URLs لتجارب Convex","تحديد الأخطاء في تشغيل التجارب","دعم URLs بتنسيق `/experiment/$experimentId/run/$runId/$category/$evalId`","التكامل مع منصة Convex"]},"keywords":{"en":["how to use analyze-eval","analyze-eval setup guide","convex document id","visualizer url pattern","eval failure analysis","analyze-eval vs convex","analyze-eval install","what is analyze-eval","analyze-eval alternative"],"zh":["Convex 评估故障排除","analyze-eval 技能","Convex 文档 ID","Visualizer URL 模式","评估 ID 提取","AI エージェント","Convex Eval 故障诊断"],"ja":["Convex Eval の故障診断","analyze-eval スキル","Convex ドキュメント ID","Visualizer URL パターン","評価 ID 抽出","AI エージェント","Convex Eval 故障解決"],"ko":["Convex 평가 오류 분석","analyze-eval 스킬","Convex 문서 ID","Visualizer URL 패턴","평가 ID 추출","AI 에이전트","Convex 평가 오류 해결"],"es":["analyze-eval","evaluación de experimentos","diagnóstico de errores","herramientas de evaluación","Convex","URL de evaluación","ID de evaluación","experimentos de IA","Herramientas de IA para desarrolladores"],"fr":["analyze-eval","évaluation d''expériences","diagnostic d''erreurs","outils d''évaluation","Convex","URL d''évaluation","ID d''évaluation","expériences d''IA","Outils d''IA pour développeurs"],"de":["analyze-eval","Auswertung von Experimenten","Fehlerdiagnose","Auswertungstools","Convex","URL der Auswertung","Bewertungs-ID","Experimente mit künstlicher Intelligenz","KI-Tools für Entwickler"],"pt":["Analyze-Eval","Ferramentas de análise de AI","Análise de URLs","Experimentos de Convex","Identificação de erros","Configuração do Analyze-Eval","Guia de uso do Analyze-Eval","Análise de dados de Convex"],"ru":["Analyze-Eval","ИИ Агенты","Анализ URL","Эксперименты Convex","Выявление ошибок","Настройка Analyze-Eval","Руководство по использованию Analyze-Eval","Анализ данных Convex"],"ar":["Analyze-Eval","أدوات تحليل إجابة العميل","تحليل URLs","تجارب Convex","تحديد الأخطاء","إعداد Analyze-Eval","دليل استخدام Analyze-Eval","تحليل بيانات Convex"]}},"owner":"get-convex","repo":"convex-evals","repoPath":"get-convex/convex-evals","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.441Z","topics":[],"category":"community","skillMd":{"name":"analyze-eval","description":"Investigate a single failing eval from the convex-evals system. Use when the user shares a visualizer URL pointing to a specific eval, asks about a specific failing eval, or references a specific eval ID.","bodyPreview":"# Analyze Eval\n\n## When to use\n\n- User shares a URL like `https://convex-evals.netlify.app/experiment/.../run/$runId/$category/$evalId`\n- User asks \"why did this eval fail?\" or \"what went wrong with this eval?\"\n- User references a specific eval ID\n\n## Step 1: Extract the eval ID from the URL\n\nThe visualizer URL pattern is:\n\n```\n/experiment/$experimentId/run/$runId/$category/$evalId?tab=steps\n```\n\n- `$runId` — the Convex document ID for the run (e.g. `jn7922j1w29pdxm76bj9ps0enx80mg9e`)\n- `$evalId","body":"# Analyze Eval\n\n## When to use\n\n- User shares a URL like `https://convex-evals.netlify.app/experiment/.../run/$runId/$category/$evalId`\n- User asks \"why did this eval fail?\" or \"what went wrong with this eval?\"\n- User references a specific eval ID\n\n## Step 1: Extract the eval ID from the URL\n\nThe visualizer URL pattern is:\n\n```\n/experiment/$experimentId/run/$runId/$category/$evalId?tab=steps\n```\n\n- `$runId` — the Convex document ID for the run (e.g. `jn7922j1w29pdxm76bj9ps0enx80mg9e`)\n- `$evalId` — the Convex document ID for the specific eval (e.g. `jh73jvjz2n00gfeve1dt5h963s80mbc6`)\n\nYou need the **evalId** to query.\n\n## Step 2: Query the debug action\n\nRun the internal action from the `evalScores/` directory. Always use `--prod` to query the production database (where CI writes results):\n\n```bash\nnpx convex run --prod debug:getEvalDebugInfo ''{\"evalId\": \"<evalId>\"}''\n```\n\nThis returns a JSON object with:\n\n| Field | Contents |\n|-------|----------|\n| `eval` | Name, category, evalPath, status (pass/fail + failure reason), task text |\n| `run` | Model name, provider, experiment name, run status |\n| `steps` | Array of step results: filesystem, install, deploy, tsc, eslint, tests — each with pass/fail/skipped and failure reason |\n| `outputFiles` | Map of file path -> file content from the model''s generated output (unzipped) |\n| `evalSourceFiles` | Map of file path -> file content from the eval source (answer dir, grader, TASK.txt, etc.) |\n\n## Step 3: Analyze the failure\n\nWith the data returned, compare:\n\n1. **Which step failed?** — Check `steps` for the first entry with `status.kind === \"failed\"`. The `failureReason` field has the error message.\n2. **What did the model generate?** — Look at `outputFiles` for the model''s code.\n3. **What was expected?** — Look at `evalSourceFiles` for the answer directory and grader test files.\n4. **What was the task?** — Check `eval.task` for the TASK.txt content.\n\nCommon failure patterns:\n- **eslint fail** — Check the failure reason for the specific lint rule violated. Compare the model output against the answer to spot the lint issue.\n- **tsc fail** — TypeScript compilation error. Check the failure reason for the specific type error.\n- **convex dev fail** — Schema or function definition issues that prevent Convex from deploying.\n- **tests fail** — The grader tests didn''t pass. Compare `outputFiles` against `evalSourceFiles` (look for files like `grader.test.ts` or `answer/`) to understand what the tests expected.\n\n## Step 4: Classify and report findings\n\nClassify the failure as one of:\n- **MODEL_FAULT**: The model genuinely got it wrong\n- **OVERLY_STRICT**: The eval/lint/test requirements are unreasonable for what was asked\n- **AMBIGUOUS_TASK**: The task description is unclear and the model''s interpretation was reasonable\n- **KNOWN_GAP**: A known limitation of this eval that affects all models (e.g. the Convex API returns fields the model can''t predict without being told)\n\nSummarize:\n1. The eval name, model, and experiment\n2. Which step failed and the exact error\n3. The classification and reasoning\n4. The relevant code from the model output that caused the failure\n5. What the correct code should look like (from the answer/eval source)\n6. Whether any action is recommended (config change, task clarification, etc.)\n"},"lastSynced":"2026-03-08T02:07:45.084Z","agentAnalysis":{"suitability":{"en":"Perfect for Debugging Agents needing advanced eval failure diagnosis capabilities.","zh":"适合需要高级评估失败诊断功能的调试代理。","ja":"高度な評価失敗診断機能を必要とするデバッグエージェントに最適です。","ko":"고급 평가 실패 진단 기능이 필요한 디버깅 에이전트에 적합합니다.","es":"Perfecto para agentes de depuración que necesitan capacidades de diagnóstico de fallos de evaluación avanzadas.","fr":"Parfait pour les agents de débogage nécessitant des capacités de diagnostic de défaillance d''évaluation avancées.","de":"Perfekt für Debugging-Agents, die erweiterte Fehldiagnosefunktionen für Bewertungen benötigen.","pt":"Perfeito para Agentes de Depuração que necessitam de capacidades avançadas de diagnóstico de falha de avaliação.","ru":"Идеально для агентов отладки, которым необходимы расширенные возможности диагностики неудач оценки.","ar":"مثالي لعميل Debugging الذي يحتاج إلى قدرات تشخيص فشل التقييم المتقدمة."},"recommendation":{"en":"Empowers agents to extract eval IDs from URLs, supporting Convex document IDs and visualizer URL patterns, and diagnose eval failures using experiment and run IDs.","zh":"赋予代理从URL中提取评估ID的能力，支持Convex文档ID和可视化器URL模式，并使用实验和运行ID诊断评估失败。","ja":"エージェントにURLから評価IDを抽出する機能を付与し、ConvexドキュメントIDとビジュアライザURLパターンをサポートし、実験名と実行IDを使用して評価失敗を診断します。","ko":"에이전트가 URL에서 평가 ID를 추출할 수 있도록 하며 Convex 문서 ID와 시각화기 URL 패턴을 지원하며 실험 및 실행 ID를 사용하여 평가 실패를 진단합니다.","es":"Habilita a los agentes a extraer IDs de evaluación de URLs, que admiten IDs de documentos Convex y patrones de URL de visualizador, y a diagnosticar fallos de evaluación utilizando IDs de experimentos y ejecuciones.","fr":"Permet aux agents d''extraire les IDs d''évaluation à partir d''URL, en prenant en charge les IDs de documents Convex et les modèles d''URL de visualiseur, et de diagnostiquer les défaillances d''évaluation à l''aide d''IDs d''expériences et d''exécutions.","de":"Ermöglicht es Agenten, Bewertungs-IDs aus URLs zu extrahieren, die Convex-Dokument-IDs und Visualizer-URL-Muster unterstützen, und Bewertungsfehler mithilfe von Experiment- und Lauf-IDs zu diagnostizieren.","pt":"Habilita os agentes a extrair IDs de avaliação de URLs, dando suporte a IDs de documentos Convex e padrões de URL de visualizador, e diagnosticar falhas de avaliação usando IDs de experimento e execução.","ru":"Наделяет агентов возможностью извлекать идентификаторы оценки из URL-адресов, поддерживая идентификаторы документов Convex и шаблоны URL-адресов визуализатора, и диагностировать неудачи оценки с помощью идентификаторов эксперимента и запуска.","ar":"يمكن العميل من استخراج معرفات التقييم من عناوين URL، ودعم معرفات وثائق Convex وأنماط عنوان URL للعرض، وتشخيص فشل التقييم باستخدام معرفات التجربة والتشغيل."},"useCases":{"en":["Debugging eval failures with specific IDs","Extracting eval IDs from visualizer URLs","Diagnosing experiment run issues"],"zh":["使用特定ID调试评估失败","从可视化器URL中提取评估ID","诊断实验运行问题"],"ja":["特定のIDを使用した評価失敗のデバッグ","ビジュアライザURLから評価IDを抽出","実験名の問題の診断"],"ko":["특정 ID를 사용한 평가 실패 디버깅","시각화기 URL에서 평가 ID 추출","실험 실행 문제 진단"],"es":["Depuración de fallos de evaluación con IDs específicos","Extracción de IDs de evaluación de URLs de visualizador","Diagnóstico de problemas de ejecución de experimentos"],"fr":["Débogage des défaillances d''évaluation avec des IDs spécifiques","Extraction des IDs d''évaluation à partir d''URL de visualiseur","Diagnostique des problèmes d''exécution d''expériences"],"de":["Fehldiagnose von Bewertungsfehlern mit spezifischen IDs","Extraktion von Bewertungs-IDs aus Visualizer-URLs","Diagnose von Experimentlaufproblemen"],"pt":["Depuração de falhas de avaliação com IDs específicos","Extração de IDs de avaliação de URLs de visualizador","Diagnóstico de problemas de execução de experimento"],"ru":["Отладка неудач оценки с конкретными идентификаторами","Извлечение идентификаторов оценки из URL-адресов визуализатора","Диагностика проблем запуска эксперимента"],"ar":["تصحيح أخطاء فشل التقييم مع معرّفات محددة","استخراج معرّفات التقييم من عناوين URL للعرض","تشخيص مشاكل تشغيل التجربة"]},"limitations":{"en":["Requires Convex document ID and visualizer URL pattern support","Limited to specific URL formats"],"zh":["需要Convex文档ID和可视化器URL模式支持","仅限特定URL格式"],"ja":["ConvexドキュメントIDとビジュアライザURLパターンのサポートが必要","特定のURL形式に限定"],"ko":["Convex 문서 ID 및 시각화기 URL 패턴 지원 필요","특정 URL 형식에만 제한"],"es":["Requiere compatibilidad con IDs de documentos Convex y patrones de URL de visualizador","Limitado a formatos de URL específicos"],"fr":["Nécessite une prise en charge des IDs de documents Convex et des modèles d''URL de visualiseur","Limité à des formats d''URL spécifiques"],"de":["Benötigt Unterstützung für Convex-Dokument-IDs und Visualizer-URL-Muster","Begrenzt auf bestimmte URL-Formate"],"pt":["Exige suporte a ID de documento Convex e padrão de URL de visualizador","Limitado a formatos de URL específicos"],"ru":["Требует поддержки идентификатора документа Convex и шаблона URL-адреса визуализатора","Ограничен конкретными форматами URL-адресов"],"ar":["يتطلب دعمًا لمعرف وثيقة Convex ونمط عنوان URL للعرض","محدود بالتنسيقات المحددة لعنوان URL"]},"version":4},"contentHash":"7eb24519ebc06816147beb0de1413fda1c68663a66f53c3dc90260ef396dfac0","qualityScore":57}');
