INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('get-convex/convex-evals/analyze-eval', 'analyze-eval', 'get-convex', 'convex-evals', 'community', 'analyze-eval get-convex convex-evals community The analyze-eval skill helps developers diagnose eval failures by extracting eval IDs from URLs. It supports Convex document IDs and visualizer URL patterns. analyze-eval 技能用于排除 Convex 评估故障，通过提取 URL 中的评估 ID 来诊断问题 analyze-eval スキルは、Convex Eval の故障を診断するために使用され、URL から評価 ID を抽出して問題を解決します analyze-eval 스킬은 Convex 평가 오류를 분석하고 URL에서 평가 ID를 추출하여 문제를 해결하는 데 사용됩니다 Analyze-eval es una herramienta para evaluar experimentos y diagnosticar errores. Extrae el ID de evaluación de la URL y analiza los resultados Analyze-eval est un outil pour évaluer les expériences et diagnostiquer les erreurs. Il extrait l''ID d''évaluation de l''URL et analyse les résultats Analyze-eval ist ein Tool zur Auswertung von Experimenten und Fehlerdiagnose. Es extrahiert die Bewertungs-ID aus der URL und analysiert die Ergebnisse O Analyze-Eval é uma ferramenta de análise de URLs que ajuda a identificar erros em experimentos de Convex Analyze-Eval - это инструмент анализа URL, который помогает выявить ошибки в экспериментах Convex Analyze-Eval هو أداة تحليل URL تساعد في تحديد الأخطاء في تجارب Convex how to use analyze-eval analyze-eval setup guide convex document id visualizer url pattern eval failure analysis analyze-eval vs convex analyze-eval install what is analyze-eval analyze-eval alternative Convex 评估故障排除 analyze-eval 技能 Convex 文档 ID Visualizer URL 模式 评估 ID 提取 AI エージェント Convex Eval 故障诊断 Extracts eval IDs from visualizer URLs using the pattern /experiment/$experimentId/run/$runId/$category/$evalId Supports Convex document IDs for runs, such as jn7922j1w29pdxm76bj9ps0enx80mg9e Analyzes eval failures based on specific eval IDs Handles URLs like https://convex-evals.netlify.app/experiment/.../run/$runId/$category/$evalId Diagnoses issues with evals using the extracted eval ID analyze-eval is a skill that analyzes eval failures by extracting eval IDs from URLs, supporting Convex document IDs and visualizer URL patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('fxstein/ai-todo/branch-cleanup', 'community', 'fxstein', 'ai-todo', 'fxstein/ai-todo', 'branch-cleanup', 0, 0, 57, '2026-03-08T01:57:15.443Z', '2026-03-08T02:08:46.512Z', '7be9f4d7a88cebc33d766eb25e02b1693351e182240c29e32959779358cb1cdc', '{"id":"fxstein/ai-todo/branch-cleanup","name":"branch-cleanup","description":{"en":"branch-cleanup is an AI-native task management solution for coding agents, providing persistent, version-controlled TODO tracking. It automates branch cleanup for AI agents like OpenClaw, Cursor, Claude, and Copilot.","zh":"Branch Cleanup 是一个自动化 Git 分支管理的工具，支持 AI 代理，如 OpenClaw、Cursor、Claude 和 Copilot","ja":"Branch Cleanup は、AIエージェントとの連携で自動化 Git ブランチ管理を実現するツールです","ko":"Branch Cleanup은 자동화 Git 브랜치 관리를 지원하는 도구입니다. OpenClaw, Cursor, Claude 및 Copilot과 같은 AI 에이전트와 함께 사용할 수 있습니다","es":"Branch-cleanup es una tarea de gestión de código que sincroniza la rama principal con el origen y elimina ramas locales fusionadas","fr":"Branch-cleanup est une tâche de gestion de code qui synchronise la branche principale avec l''origine et supprime les branches locales fusionnées","de":"Branch-cleanup ist eine Code-Verwaltungsaufgabe, die den Hauptzweig mit dem Ursprung synchronisiert und lokale Zweige bereinigt","pt":"O branch cleanup é uma solução de gestão de código que trabalha naturalmente com ferramentas de IA. Ele fornece acompanhamento de TODO persistente e versionado","ru":"Очистка веток - это решение для управления кодом, которое работает естественно с ИИ Агентами. Оно предоставляет постоянное и версионное отслеживание TODO","ar":"تنظيف الفروع هو حل لإدارة الشفرة التي تعمل بطريقة طبيعية مع أدوات الدعم الذكاء الاصطناعي. يوفر تتبعًا دائمًا ونسخة من TODO"},"seo":{"title":{"en":"branch-cleanup: Automated Branch Management for AI Agents...","zh":"Branch Cleanup 设置指南 - 自动化 Git 分支管理","ja":"Branch Cleanup 導入ガイド - AIエージェントとの自動化 Git ブランチ管理","ko":"Branch Cleanup 설정 가이드 - 자동화 Git 브랜치 관리","es":"Guía de configuración de branch-cleanup para agentes de IA","fr":"Guide de configuration de branch-cleanup pour les agents ...","de":"Einrichtungsleitfaden für branch-cleanup bei KI-Agents","pt":"Guia de Configuração do Branch Cleanup para Ferramentas d...","ru":"Настройка очистки веток для ИИ Агентов","ar":"دليل إعداد تنظيف الفروع لآلات الدعم الذكاء الاصطناعي"},"description":{"en":"Discover how branch-cleanup simplifies TODO tracking and branch management for AI agents like OpenClaw and Copilot. Learn how to sync and clean up branches w...","zh":"学习如何使用 Branch Cleanup 实现自动化 Git 分支管理，包括同步主分支和清理合并的分支","ja":"AIエージェントとの連携で自動化 Git ブランチ管理を実現する Branch Cleanup の使い方を学ぶ","ko":"Branch Cleanup을 사용하여 자동화 Git 브랜치 관리를 구현하는 방법을 배우세요","es":"Automatice la limpieza de ramas con branch-cleanup, compatible con OpenClaw, Cursor, Claude y Copilot","fr":"Automatisez le nettoyage des branches avec branch-cleanup, compatible avec OpenClaw, Cursor, Claude et Copilot","de":"Automatisieren Sie die Bereinigung von Zweigen mit branch-cleanup, kompatibel mit OpenClaw, Cursor, Claude und Copilot","pt":"Aprenda a configurar o branch cleanup para ferramentas de IA como OpenClaw, Cursor, Claude e Copilot. Melhore a gestão de código com nossa solução de acompan...","ru":"Узнайте, как настроить очистку веток для ИИ Агентов, таких как OpenClaw, Cursor, Claude и Copilot. Улучшите управление кодом с нашей системой отслеживания TODO","ar":"تعلم كيفية تعيين تنظيف الفروع للأدوات الذكية مثل OpenClaw و Cursor و Claude و Copilot. تحسين إدارة الشفرة باستخدام نظامنا لتتبع TODO"},"definition":{"en":"branch-cleanup is an automated workflow that syncs main with origin and cleans up local branches that have merged PRs, utilizing git commands like git fetch and git checkout.","zh":"Branch Cleanup 是一个自动化 Git 分支管理的工具，用于同步主分支和清理合并的分支","ja":"Branch Cleanup は、自動化 Git ブランチ管理を行うツールで、主ブランチの同期とマージされたブランチのクリーンアップを行う","ko":"Branch Cleanup은 자동화 Git 브랜치 관리를 수행하는 도구로, 메인 브랜치의 동기화와 병합된 브랜치의 정리를 수행합니다","es":"Branch-cleanup es una herramienta de gestión de código que automatiza la limpieza de ramas","fr":"Branch-cleanup est un outil de gestion de code qui automatise le nettoyage des branches","de":"Branch-cleanup ist ein Code-Verwaltungstool, das die Bereinigung von Zweigen automatisiert","pt":"O que é branch cleanup? É uma solução de gestão de código que automatiza a limpeza de branches locais que têm PRs mescladas","ru":"Что такое очистка веток? Это решение для управления кодом, которое автоматизирует очистку локальных веток, имеющих слитые PR","ar":"ما هو تنظيف الفروع؟ هو حل لإدارة الشفرة الذي يutomatiza تنظيف الفروع المحلية التي تم مزجها"},"features":{"en":["Automates branch cleanup using git commands like git fetch origin and git branch --show-current","Syncs main branch with origin using git checkout main and git pull origin main --ff-only","Performs pre-flight checks, including verifying the current branch and updating remote refs","Supports AI agents like OpenClaw, Cursor, Claude, and Copilot for seamless integration","Provides version-controlled TODO tracking for persistent task management","Utilizes git pull with --ff-only flag to ensure fast-forward updates"],"zh":["自动同步主分支","清理合并的分支","支持 AI 代理，如 OpenClaw、Cursor、Claude 和 Copilot","使用 Git 命令行工具进行分支管理","支持本地分支和远程分支的管理"],"ja":["主ブランチの自動同期","マージされたブランチのクリーンアップ","AIエージェントとの連携、例：OpenClaw、Cursor、Claude、Copilot","Git コマンドラインツールを使用したブランチ管理","ローカルブランチとリモートブランチの管理をサポート"],"ko":["자동 메인 브랜치 동기화","병합된 브랜치의 정리","AI 에이전트와의 연동, 예: OpenClaw, Cursor, Claude, Copilot","Git 명령줄 도구를 사용한 브랜치 관리","로컬 브랜치와 리모트 브랜치의 관리를 지원"],"es":["Sincronización de la rama principal con el origen","Eliminación de ramas locales fusionadas","Compatibilidad con OpenClaw, Cursor, Claude y Copilot","Verificación de la rama actual antes de la limpieza","Soporte para Git y comandos de línea de comandos"],"fr":["Synchronisation de la branche principale avec l''origine","Suppression des branches locales fusionnées","Compatibilité avec OpenClaw, Cursor, Claude et Copilot","Vérification de la branche actuelle avant le nettoyage","Prise en charge de Git et des commandes de línea de comandos"],"de":["Synchronisation des Hauptzweigs mit dem Ursprung","Bereinigung von lokalen Zweigen, die fusioniert wurden","Kompatibilität mit OpenClaw, Cursor, Claude und Copilot","Überprüfung der aktuellen Zweig vor der Bereinigung","Unterstützung für Git und Befehlszeilen"],"pt":["Acompanhamento de TODO persistente e versionado","Integração com ferramentas de IA como OpenClaw, Cursor, Claude e Copilot","Automatização da limpeza de branches locais com PRs mescladas","Suporte a git fetch e git pull","Verificação da branch atual e solicitação de confirmação para alterar para a branch main"],"ru":["Постоянное и версионное отслеживание TODO","Интеграция с ИИ Агентами, такими как OpenClaw, Cursor, Claude и Copilot","Автоматизация очистки локальных веток с слитыми PR","Поддержка git fetch и git pull","Проверка текущей ветки и запрос подтверждения на переключение на ветку main"],"ar":["تتبع دائم ونسخة من TODO","التكامل مع أدوات الدعم الذكاء الاصطناعي مثل OpenClaw و Cursor و Claude و Copilot","التحكم الآلي في تنظيف الفروع المحلية التي تم مزجها","دعم git fetch و git pull","التحقق من الفرع الحالي وطلب التأكيد لتحويل إلى الفرع الرئيسي"]},"keywords":{"en":["how to use branch-cleanup","branch-cleanup alternative","branch-cleanup setup guide","what is branch-cleanup","branch-cleanup vs gitflow","branch-cleanup install for OpenClaw","automated branch management for AI agents","git branch cleanup best practices","branch-cleanup for Copilot and Cursor"],"zh":["Branch Cleanup","Git 分支管理","AI 代理","自动化 Git","OpenClaw","Cursor","Claude","Copilot","Git 命令行工具"],"ja":["Branch Cleanup","Git ブランチ管理","AIエージェント","自動化 Git","OpenClaw","Cursor","Claude","Copilot","Git コマンドラインツール"],"ko":["Branch Cleanup","Git 브랜치 관리","AI 에이전트","자동화 Git","OpenClaw","Cursor","Claude","Copilot","Git 명령줄 도구"],"es":["branch-cleanup","agentes de IA","gestión de código","sincronización de ramas","eliminación de ramas","OpenClaw","Cursor","Claude","Copilot","Git"],"fr":["branch-cleanup","agents d''IA","gestion de code","synchronisation de branches","suppression de branches","OpenClaw","Cursor","Claude","Copilot","Git"],"de":["branch-cleanup","KI-Agents","Code-Verwaltung","Synchronisation von Zweigen","Bereinigung von Zweigen","OpenClaw","Cursor","Claude","Copilot","Git"],"pt":["branch cleanup","ferramentas de IA","gestão de código","acompanhamento de TODO","OpenClaw","Cursor","Claude","Copilot","git fetch","git pull"],"ru":["очистка веток","ИИ Агенты","управление кодом","отслеживание TODO","OpenClaw","Cursor","Claude","Copilot","git fetch","git pull"],"ar":["تنظيف الفروع","أدوات الدعم الذكاء الاصطناعي","إدارة الشفرة","تتبع TODO","OpenClaw","Cursor","Claude","Copilot","git fetch","git pull"]}},"owner":"fxstein","repo":"ai-todo","repoPath":"fxstein/ai-todo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.443Z","topics":[],"category":"community","skillMd":{"name":"branch-cleanup","description":"Clean up local branches after PR merges. Syncs main with origin, identifies branches with merged PRs, and proposes safe deletion. Use when the user asks to clean up branches, delete merged branches, sync branches, or mentions branch cleanup.","bodyPreview":"# Branch Cleanup\n\nAutomated workflow to sync main with origin and clean up local branches that have merged PRs.\n\n## Quick Start\n\nWhen user asks to \"clean up branches\" or \"delete merged branches\":\n\n1. **Pre-flight checks:**\n   - `git fetch origin` (update remote refs)\n   - `git branch --show-current` (verify current branch)\n   - If not on main: **Ask user:** \"Should I switch to main? (Current: {branch})\"\n\n2. **Sync main:**\n   - `git checkout main`\n   - `git pull origin main --ff-only`\n   - **If c","body":"# Branch Cleanup\n\nAutomated workflow to sync main with origin and clean up local branches that have merged PRs.\n\n## Quick Start\n\nWhen user asks to \"clean up branches\" or \"delete merged branches\":\n\n1. **Pre-flight checks:**\n   - `git fetch origin` (update remote refs)\n   - `git branch --show-current` (verify current branch)\n   - If not on main: **Ask user:** \"Should I switch to main? (Current: {branch})\"\n\n2. **Sync main:**\n   - `git checkout main`\n   - `git pull origin main --ff-only`\n   - **If conflicts:** ⚠️ Stop and report \"Main has conflicts. Resolve manually.\"\n\n3. **List local branches:**\n   - `git branch --format=''%(refname:short)''`\n   - Filter out: `main`, `master`, `develop`, `staging`, `production`, `archive*`\n   - **If no branches:** Report \"No local branches to clean up\" and STOP.\n\n4. **Check PR status for each branch:**\n   - Get PR for branch: `gh pr list --head {branch} --state merged --json number,title,url`\n   - **If merged PR found:** Add to cleanup list\n   - **If no PR or not merged:** Skip\n\n5. **Present cleanup list:**\n   - Show table with: branch name, PR number, PR title, PR URL\n   - **Ask user:** \"Delete these {count} branches? (y/n)\"\n   - **If user declines:** STOP.\n\n6. **Delete branches:**\n   - For each approved branch:\n     - `git branch -d {branch}` (safe delete)\n     - **If fails with unmerged warning:** Show warning and skip\n     - **If succeeds:** Report \"✅ Deleted {branch}\"\n   - **Final summary:** \"Deleted {count} branches, skipped {count} unmerged branches\"\n\n## Workflow Details\n\n### Step 1: Pre-flight Checks\n\n```bash\n# Fetch latest remote refs\ngit fetch origin\n\n# Check current branch\nCURRENT_BRANCH=$(git branch --show-current)\n```\n\n**If not on main:**\n- Show: \"Currently on `{CURRENT_BRANCH}`. Switch to main?\"\n- Wait for user confirmation\n\n**Safety:**\n- Never switch branches with uncommitted changes\n- Check: `git status --porcelain` (must be empty)\n\n### Step 2: Sync Main\n\n```bash\n# Switch to main\ngit checkout main\n\n# Fast-forward merge only (no conflicts)\ngit pull origin main --ff-only\n```\n\n**If fast-forward fails:**\n- ⚠️ Stop with error: \"Main branch has diverged from origin. Manual resolution required.\"\n- Do NOT attempt merge or rebase\n\n### Step 3: Identify Merged Branches\n\nFor each local branch:\n\n```bash\n# Get merged PR for branch\ngh pr list --head {branch} --state merged --json number,title,url --limit 1\n```\n\n**Branch categories:**\n\n| Status | Action |\n|--------|--------|\n| Merged PR found | Add to cleanup list |\n| Open PR found | Skip (not merged) |\n| No PR found | Skip (might be local work) |\n| Protected branch | Skip (main, master, etc.) |\n\n**Protected branches:**\n- `main`, `master`, `develop`, `staging`, `production`\n- Any branch starting with `archive` (e.g., `archive-2024`, `archive/old`)\n- Any branch matching `origin/*`\n\n### Step 4: Present Cleanup List\n\nFormat as markdown table:\n\n```markdown\n## Branches with merged PRs\n\n| Branch | PR | Title |\n|--------|-----|-------|\n| fxstein/AIT-12-feature | [#45](url) | Feature implementation |\n| oliver/ait-8-bugfix | [#38](url) | Fix login bug |\n\nTotal: 2 branches\n```\n\n**User prompt:**\n\"Delete these branches? They have merged PRs and are safe to remove. (y/n)\"\n\n### Step 5: Safe Deletion\n\n```bash\n# Safe delete (only if fully merged)\ngit branch -d {branch}\n```\n\n**If `git branch -d` fails:**\n- Shows: \"The branch ''{branch}'' is not fully merged.\"\n- **Action:** Skip and report to user\n- **Reason:** Prevents data loss\n\n**Force delete (`-D`) is NEVER used automatically.**\n\n## Edge Cases\n\n### No Merged Branches\n\nIf no branches qualify for cleanup:\n```\n✅ All local branches are up to date.\nNo merged branches found for cleanup.\n```\n\n### Partially Merged Branches\n\nIf branch has commits not in main but PR is merged:\n- `git branch -d` will fail (expected)\n- Report: \"⚠️ Skipped {branch}: has unmerged commits (possible rebase)\"\n- User can manually verify with: `git log main..{branch}`\n\n### Archive Branches\n\nBranches starting with `archive` are preserved:\n- ❌ Skip: `archive-2024`, `archive/backup`, `archive-old-features`\n- **Reason:** Archive branches contain historical work that should be manually managed\n\n### Remote Tracking Branches\n\nOnly delete **local** branches, never remote refs:\n- ✅ Delete: `fxstein/AIT-12-feature`\n- ❌ Skip: `origin/fxstein/AIT-12-feature`\n\nUse `git push origin --delete {branch}` only if user explicitly requests remote deletion.\n\n## Error Handling\n\n**If ANY error occurs:**\n1. STOP IMMEDIATELY\n2. Report the specific error\n3. Show current state: branch name, operation attempted\n4. WAIT for user input\n\n**Common errors:**\n\n| Error | Cause | Action |\n|-------|-------|--------|\n| \"Not on main\" | Current branch not main | Ask to switch |\n| \"Fast-forward failed\" | Main diverged from origin | Stop, manual resolution |\n| \"gh command not found\" | GitHub CLI not installed | Stop, ask user to install |\n| \"Branch not fully merged\" | Branch has unmerged commits | Skip branch |\n\n## Safety Guarantees\n\n- ✅ Never force-delete (`-D`) branches\n- ✅ Never delete without user confirmation\n- ✅ Never modify remote branches\n- ✅ Never switch branches with uncommitted changes\n- ✅ Always use `--ff-only` for main sync\n\n## Output Format\n\n### Success\n\n```\n🔄 Syncing main with origin...\n✅ Main is up to date\n\n📋 Found 3 branches with merged PRs:\n- fxstein/AIT-12-feature (PR #45)\n- oliver/ait-8-bugfix (PR #38)\n- fxstein/AIT-10-docs (PR #42)\n\n🗑️  Deleting branches...\n✅ Deleted fxstein/AIT-12-feature\n✅ Deleted oliver/ait-8-bugfix\n✅ Deleted fxstein/AIT-10-docs\n\n✨ Cleanup complete: 3 branches deleted\n```\n\n### With Skipped Branches\n\n```\n🗑️  Deleting branches...\n✅ Deleted fxstein/AIT-12-feature\n⚠️  Skipped fxstein/AIT-15-wip: not fully merged\n✅ Deleted oliver/ait-8-bugfix\n\n✨ Cleanup complete: 2 deleted, 1 skipped\n```\n\n## Additional Features\n\n### Dry Run Mode\n\nIf user asks for \"preview\" or \"dry run\":\n- Execute steps 1-4 only\n- Show cleanup list\n- STOP before deletion\n\n### Delete Remote Branches\n\nIf user explicitly asks to \"delete remote branches too\":\n- After local deletion succeeds\n- For each deleted branch:\n  ```bash\n  git push origin --delete {branch}\n  ```\n- Report: \"✅ Deleted {branch} (local + remote)\"\n\n## Requirements\n\n- **Git:** Version 2.0+\n- **GitHub CLI (gh):** Required for PR status checks\n- **Repository:** Must be a git repository with GitHub remote\n\n## Forbidden Actions\n\n- ❌ Never use `git branch -D` (force delete)\n- ❌ Never delete branches without user confirmation\n- ❌ Never modify `main`, `master`, or protected branches\n- ❌ Never attempt merge/rebase to resolve conflicts\n"},"lastSynced":"2026-03-08T02:08:46.512Z","agentAnalysis":{"suitability":{"en":"Perfect for Coding Agents like OpenClaw, Cursor, and Claude needing automated branch management and cleanup capabilities.","zh":"适合像 OpenClaw、Cursor 和 Claude 这样的编码代理，需要自动化分支管理和清理功能。","ja":"OpenClaw、Cursor、Claude などのコーディングエージェントに適しており、自動化されたブランチ管理とクリーンアップ機能が必要です。","ko":"OpenClaw, Cursor, Claude 같은 코딩 에이전트에 적합하며 자동화된 브랜치 관리 및 정리 기능이 필요합니다.","es":"Perfecto para Agentes de Codificación como OpenClaw, Cursor y Claude que necesitan capacidades de administración y limpieza de ramas automatizadas.","fr":"Parfait pour les Agents de Codage comme OpenClaw, Cursor et Claude nécessitant une gestion et un nettoyage de branches automatisés.","de":"Perfekt für Coding-Agenten wie OpenClaw, Cursor und Claude, die eine automatisierte Verwaltung und Bereinigung von Zweigen benötigen.","pt":"Perfeito para Agentes de Codificação como OpenClaw, Cursor e Claude que precisam de capacidades de gerenciamento e limpeza de branch automatizadas.","ru":"Идеально подходит для агентов кодирования, таких как OpenClaw, Cursor и Claude, которым требуются автоматические возможности управления и очистки веток.","ar":" مثالي للوكلاء البرمجيين مثل OpenClaw و Cursor و Claude الذين يحتاجون إلى возможности إدارة الفرع والتنظيف التلقائي."},"recommendation":{"en":"Empowers agents to automate Git workflow synchronization, utilizing git fetch, git checkout, and git pull to maintain a clean and up-to-date repository, ensuring seamless collaboration and version control.","zh":"赋予代理人自动化 Git 工作流同步的能力，利用 git fetch、git checkout 和 git pull 来维护一个干净和最新的仓库，确保无缝的协作和版本控制。","ja":"エージェントに Git ワークフローの同期を自動化する機能を付与し、git fetch、git checkout、git pull を使用してクリーンで最新のリポジトリを維持し、無邪気なコラボレーションとバージョン管理を確保します。","ko":"에이전트에게 Git 워크플로우 동기화를 자동화하는 기능을 부여하며, git fetch, git checkout, git pull을 사용하여 깨끗하고 최신의 저장소를 유지하고, 무결점의 협업 및 버전 관리를 보장합니다.","es":"Habilita a los agentes a automatizar la sincronización del flujo de trabajo de Git, utilizando git fetch, git checkout y git pull para mantener un repositorio limpio y actualizado, asegurando una colaboración y control de versiones sin problemas.","fr":"Permet aux agents d''automatiser la synchronisation du workflow Git, en utilisant git fetch, git checkout et git pull pour maintenir un référentiel propre et à jour, garantissant une collaboration et un contrôle de version sans problème.","de":"Ermöglicht es Agenten, die Synchronisation des Git-Workflows zu automatisieren, indem sie git fetch, git checkout und git pull verwenden, um ein sauberes und aktuelles Repository zu erhalten, und somit eine nahtlose Zusammenarbeit und Versionskontrolle sicherzustellen.","pt":"Habilita os agentes a automatizar a sincronização do fluxo de trabalho do Git, utilizando git fetch, git checkout e git pull para manter um repositório limpo e atualizado, garantindo uma colaboração e controle de versão sem interrupções.","ru":"Позволяет агентам автоматизировать синхронизацию рабочего процесса Git, используя git fetch, git checkout и git pull для поддержания чистого и актуального репозитория, обеспечивая бесперебойное сотрудничество и контроль версий.","ar":"يُمكن الوكلاء من تلقين автоматيزيّاً متوافقّة تدفق العمل Git، من خلال استخدام git fetch و git checkout و git pull من أجل الحفاظ على مستودع نظيف و محدث، و ضمان تعاون و سيطرة إصدارات بدون انقطاع."},"useCases":{"en":["Automating branch cleanup for merged PRs","Syncing main branch with origin","Streamlining local branch management"],"zh":["自动化合并 PR 的分支清理","同步主分支与原点","简化本地分支管理"],"ja":["マージされた PR のブランチのクリーンアップを自動化する","メインブランチをオリジンと同期する","ローカルブランチ管理を簡素化する"],"ko":["병합된 PR의 브랜치 정리를 자동화하는 것","메인 브랜치를 원본과 동기화하는 것","로컬 브랜치 관리를 간소화하는 것"],"es":["Automatizar la limpieza de ramas para PR fusionadas","Sincronizar la rama principal con el origen","Optimizar la administración de ramas locales"],"fr":["Automatiser le nettoyage de branches pour les PR fusionnées","Synchroniser la branche principale avec l''origine","Optimiser la gestion des branches locales"],"de":["Automatisierung der Bereinigung von Zweigen für zusammengeführte PR","Synchronisierung des Hauptzweigs mit dem Ursprung","Optimierung der lokalen Zweigverwaltung"],"pt":["Automatizar a limpeza de branch para PRs mesclados","Sincronizar a branch principal com a origem","Otimizar o gerenciamento de branch local"],"ru":["Автоматизировать очистку веток для объединенных PR","Синхронизировать основную ветку с исходной","Оптимизировать локальное управление ветками"],"ar":["تلقين автоматيزيّاً تنظيف الفرع للمراسلات المدمجة","متوافقّة الفرع الرئيسي مع المنشأ","تحسين إدارة الفرع المحلي"]},"limitations":{"en":["Requires Git installation and configuration","Limited to repositories with merge PRs"],"zh":["需要 Git 安装和配置","仅限于具有合并 PR 的仓库"],"ja":["Git のインストールと設定が必要","マージされた PR を持つリポジトリに限定される"],"ko":["Git 설치 및 구성이 필요","병합된 PR를 가진 저장소에만 제한"],"es":["Requiere la instalación y configuración de Git","Limitado a repositorios con PR de fusión"],"fr":["Nécessite l''installation et la configuration de Git","Limité aux référentiels avec des PR de fusion"],"de":["Benötigt die Installation und Konfiguration von Git","Begrenzt auf Repositorys mit Merge-PR"],"pt":["Requer instalação e configuração do Git","Limitado a repositórios com PRs mesclados"],"ru":["Требует установки и конфигурации Git","Ограничен репозиториями с объединенными PR"],"ar":["يتطلب تثبيت وضبط Git","محدود بالمستودعات ذات المراسلات المدمجة"]},"version":4},"contentHash":"7be9f4d7a88cebc33d766eb25e02b1693351e182240c29e32959779358cb1cdc","qualityScore":57}');
