INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('fxstein/ai-todo/branch-cleanup', 'branch-cleanup', 'fxstein', 'ai-todo', 'community', 'branch-cleanup fxstein ai-todo community branch-cleanup is an AI-native task management solution for coding agents, providing persistent, version-controlled TODO tracking. It automates branch cleanup for AI agents like OpenClaw, Cursor, Claude, and Copilot. Branch Cleanup 是一个自动化 Git 分支管理的工具，支持 AI 代理，如 OpenClaw、Cursor、Claude 和 Copilot Branch Cleanup は、AIエージェントとの連携で自動化 Git ブランチ管理を実現するツールです Branch Cleanup은 자동화 Git 브랜치 관리를 지원하는 도구입니다. OpenClaw, Cursor, Claude 및 Copilot과 같은 AI 에이전트와 함께 사용할 수 있습니다 Branch-cleanup es una tarea de gestión de código que sincroniza la rama principal con el origen y elimina ramas locales fusionadas Branch-cleanup est une tâche de gestion de code qui synchronise la branche principale avec l''origine et supprime les branches locales fusionnées Branch-cleanup ist eine Code-Verwaltungsaufgabe, die den Hauptzweig mit dem Ursprung synchronisiert und lokale Zweige bereinigt O branch cleanup é uma solução de gestão de código que trabalha naturalmente com ferramentas de IA. Ele fornece acompanhamento de TODO persistente e versionado Очистка веток - это решение для управления кодом, которое работает естественно с ИИ Агентами. Оно предоставляет постоянное и версионное отслеживание TODO تنظيف الفروع هو حل لإدارة الشفرة التي تعمل بطريقة طبيعية مع أدوات الدعم الذكاء الاصطناعي. يوفر تتبعًا دائمًا ونسخة من TODO how to use branch-cleanup branch-cleanup alternative branch-cleanup setup guide what is branch-cleanup branch-cleanup vs gitflow branch-cleanup install for OpenClaw automated branch management for AI agents git branch cleanup best practices branch-cleanup for Copilot and Cursor Branch Cleanup Git 分支管理 AI 代理 自动化 Git OpenClaw Cursor Claude Copilot Git 命令行工具 Automates branch cleanup using git commands like git fetch origin and git branch --show-current Syncs main branch with origin using git checkout main and git pull origin main --ff-only Performs pre-flight checks, including verifying the current branch and updating remote refs Supports AI agents like OpenClaw, Cursor, Claude, and Copilot for seamless integration Provides version-controlled TODO tracking for persistent task management Utilizes git pull with --ff-only flag to ensure fast-forward updates branch-cleanup is an automated workflow that syncs main with origin and cleans up local branches that have merged PRs, utilizing git commands like git fetch and git checkout.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('obra/superpowers-chrome/browsing', 'community', 'obra', 'superpowers-chrome', 'obra/superpowers-chrome', 'browsing', 0, 0, 57, '2026-03-08T01:57:15.445Z', '2026-03-08T02:08:53.786Z', '16cfcc0358ac2e0a5af69b6afda0a501e48b59cbba35a55d298ac4b427e0dc70', '{"id":"obra/superpowers-chrome/browsing","name":"browsing","description":{"en":"The browsing skill enables developers to control Chrome via DevTools Protocol using the `use_browser` MCP tool, ideal for managing authenticated sessions and multiple tabs. This skill benefits developers who need to automate browsing sessions.","zh":"浏览技能允许您使用DevTools Protocol控制Chrome浏览器，实现零依赖的浏览器控制","ja":"ブラウジングスキルは、DevTools Protocolを使用してChromeブラウザを制御し、ゼロ依存のブラウザ制御を実現します","ko":"브라우징 스킬은 DevTools Protocol을 사용하여 Chrome 브라우저를 제어하며, 제로 의존성 브라우저 제어를 구현합니다","es":"La habilidad de navegación utiliza el protocolo DevTools para controlar Chrome de forma directa, permitiendo una interfaz unificada y el arranque automático de Chrome","fr":"La compétence de navigation utilise le protocole DevTools pour contrôler Chrome de manière directe, permettant une interface unifiée et le démarrage automatique de Chrome","de":"Die Navigation-Fähigkeit nutzt das DevTools-Protokoll, um Chrome direkt zu steuern, ermöglicht eine einheitliche Schnittstelle und den automatischen Start von Chrome","pt":"O plugin Claude Code permite o controle direto do Chrome via DevTools Protocol, sem dependências. Utilize a habilidade de navegação para controle de sessões autenticadas e gerenciamento de múltiplas abas.","ru":"Плагин Claude Code позволяет直接 управлять Chrome через DevTools Protocol, без зависимостей. Используйте навык просмотра для контроля аутентифицированных сеансов и управления несколькими вкладками.","ar":"إضافة Claude Code تسمح بالسيطرة المباشرة على Chrome من خلال بروتوكول DevTools، بدون依赖ات. استخدم مهارة المتصفح للسيطرة على الجلسات المصرح بها وإدارة علامات التبويب المتعددة."},"seo":{"title":{"en":"Browsing: Chrome DevTools Protocol Control Setup Guide | ...","zh":"浏览技能设置指南 - 使用Chrome DevTools Protocol控制浏览器","ja":"ブラウジングスキルセットアップガイド - ChromeをDevTools Protocolで制御","ko":"브라우징 스킬 설정 가이드 - Chrome DevTools Protocol을 사용한 브라우저 제어","es":"Guía de configuración de navegación con Chrome Direct","fr":"Guide de démarrage de la navigation avec Chrome Direct","de":"Einrichtungsleitfaden für die Navigation mit Chrome Direct","pt":"Guia de Configuração do Navegador com Claude Code","ru":"ИИ Агенты: Настройка Плагина Claude Code для Браузера","ar":"دليل تثبيت متصفح الويب باستخدام Claude Code"},"description":{"en":"Discover how to control Chrome via DevTools Protocol with the browsing skill. Learn how to automate browsing sessions and manage multiple tabs with ease.","zh":"使用Claude Code插件和DevTools Protocol实现零依赖的Chrome浏览器控制，适用于控制authenticated sessions和多个标签页","ja":"Claude CodeプラグインとDevTools Protocolを使用して、ゼロ依存のChromeブラウザ制御を実現します。認証セッションと複数のタブを制御するのに適しています","ko":"Claude Code 플러그인과 DevTools Protocol을 사용하여 Chrome 브라우저를 제어합니다. 인증된 세션과 여러 탭을 제어하는 데 적합합니다","es":"Controla Chrome de forma directa con el protocolo DevTools y la herramienta use_browser MCP, ideal para sesiones autenticadas y gestión de pestañas","fr":"Contrôlez Chrome de manière directe avec le protocole DevTools et l''outil use_browser MCP, idéal pour les sessions authentifiées et la gestion des onglets","de":"Steuerung von Chrome über das DevTools-Protokoll und das Tool use_browser MCP, ideal für authentifizierte Sitzungen und die Verwaltung von Tabs","pt":"Controle o Chrome via DevTools Protocol com o plugin Claude Code. Saiba como utilizar a habilidade de navegação para controle de sessões autenticadas e geren...","ru":"Используйте плагин Claude Code для управления Chrome через DevTools Protocol. Узнайте, как использовать навык просмотра для контроля аутентифицированных сеан...","ar":"استخدم إضافة Claude Code للسيطرة على Chrome من خلال بروتوكول DevTools. تعرف على كيفية استخدام مهارة المتصفح للسيطرة على الجلسات المصرح بها وإدارة علامات التب..."},"definition":{"en":"Browsing is a Claude Code plugin that allows for direct Chrome browser control via DevTools Protocol, providing a unified interface with auto-starting Chrome.","zh":"浏览技能是一种使用DevTools Protocol控制Chrome浏览器的技术","ja":"ブラウジングスキルは、DevTools Protocolを使用してChromeブラウザを制御する技術です","ko":"브라우징 스킬은 DevTools Protocol을 사용하여 Chrome 브라우저를 제어하는 기술입니다","es":"La navegación es una habilidad que permite controlar Chrome mediante el protocolo DevTools","fr":"La navigation est une compétence qui permet de contrôler Chrome via le protocole DevTools","de":"Die Navigation ist eine Fähigkeit, die es ermöglicht, Chrome über das DevTools-Protokoll zu steuern","pt":"O que é navegação? É a habilidade de controlar o Chrome via DevTools Protocol, utilizando o plugin Claude Code.","ru":"Что такое просмотр? Это навык управления Chrome через DevTools Protocol, используя плагин Claude Code.","ar":"ما هي المتصفح؟ هي القدرة على التحكم في Chrome من خلال بروتوكول DevTools، باستخدام إضافة Claude Code."},"features":{"en":["Control Chrome via DevTools Protocol using the `use_browser` MCP tool","Auto-starting Chrome for a unified browsing experience","Manage multiple tabs in a running browser instance","Ideal for controlling authenticated sessions","Alternative to Playwright MCP for specific use cases","Zero dependencies for seamless integration"],"zh":["使用DevTools Protocol控制Chrome浏览器","零依赖的浏览器控制","支持控制authenticated sessions","支持管理多个标签页","自动启动Chrome浏览器","统一的接口"],"ja":["DevTools Protocolを使用してChromeブラウザを制御","ゼロ依存のブラウザ制御","認証セッションの制御をサポート","複数のタブの管理をサポート","Chromeブラウザの自動起動","統一されたインターフェース"],"ko":["DevTools Protocol을 사용하여 Chrome 브라우저를 제어","제로 의존성 브라우저 제어","인증된 세션의 제어를 지원","여러 탭의 관리를 지원","Chrome 브라우저의 자동 시작","統一された 인터페이스"],"es":["Control de Chrome mediante el protocolo DevTools","Interfaz unificada con arranque automático de Chrome","Gestión de sesiones autenticadas","Gestión de múltiples pestañas en una navegador en ejecución","Alternativa a Playwright MCP para ciertos casos de uso"],"fr":["Contrôle de Chrome via le protocole DevTools","Interface unifiée avec démarrage automatique de Chrome","Gestion de sessions authentifiées","Gestion de plusieurs onglets dans un navigateur en cours d''exécution","Alternative à Playwright MCP pour certains cas d''utilisation"],"de":["Steuerung von Chrome über das DevTools-Protokoll","Einheitliche Schnittstelle mit automatischem Start von Chrome","Verwaltung von authentifizierten Sitzungen","Verwaltung von mehreren Tabs in einem laufenden Browser","Alternative zu Playwright MCP für bestimmte Anwendungsfälle"],"pt":["Controle do Chrome via DevTools Protocol","Gerenciamento de múltiplas abas","Controle de sessões autenticadas","Utilização do plugin Claude Code","Sem dependências","Interface unificada com inicialização automática do Chrome"],"ru":["Управление Chrome через DevTools Protocol","Управление несколькими вкладками","Контроль аутентифицированных сеансов","Использование плагина Claude Code","Без зависимостей","Единый интерфейс с автоматическим запуском Chrome"],"ar":["السيطرة على Chrome من خلال بروتوكول DevTools","إدارة علامات التبويب المتعددة","السيطرة على الجلسات المصرح بها","استخدام إضافة Claude Code","بدون依赖ات","واجهة موحدة مع تشغيل تلقائي للكروم"]},"keywords":{"en":["how to use browsing skill","browsing alternative to playwright","what is browsing in chrome","browsing setup guide","chrome devtools protocol tutorial","browsing vs playwright mcp","browsing install guide","automating chrome browsing sessions"],"zh":["浏览技能","Chrome DevTools Protocol","零依赖浏览器控制","authenticated sessions","多个标签页","自动启动Chrome","AIエージェント","浏览器自动化"],"ja":["ブラウジングスキル","Chrome DevTools Protocol","ゼロ依存ブラウザ制御","認証セッション","複数のタブ","Chrome自動起動","AIエージェント","ブラウザ自動化"],"ko":["브라우징 스킬","Chrome DevTools Protocol","제로 의존성 브라우저 제어","인증된 세션","여러 탭","Chrome 자동 시작","AI 에이전트","브라우저 자동화"],"es":["navegación con Chrome Direct","control de Chrome con DevTools","use_browser MCP","sesiones autenticadas","gestión de pestañas","alternativa a Playwright MCP","desarrollo de aplicaciones web","herramientas de desarrollo"],"fr":["navigation avec Chrome Direct","contrôle de Chrome avec DevTools","use_browser MCP","sessions authentifiées","gestion des onglets","alternative à Playwright MCP","développement d''applications web","outils de développement"],"de":["Navigation mit Chrome Direct","Steuerung von Chrome mit DevTools","use_browser MCP","authentifizierte Sitzungen","Verwaltung von Tabs","Alternative zu Playwright MCP","Webanwendungsentwicklung","Entwicklungstools"],"pt":["navegação com Claude Code","controle do Chrome","DevTools Protocol","gerenciamento de abas","sessões autenticadas","plugin Claude Code","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["просмотр с Claude Code","управление Chrome","DevTools Protocol","управление вкладками","аутентифицированные сеансы","плагин Claude Code","веб-разработка","инструменты разработки"],"ar":["متصفح مع Claude Code","السيطرة على الكروم","بروتوكول DevTools","إدارة علامات التبويب","الجلسات المصرح بها","إضافة Claude Code","تطوير الويب","أدوات التطوير"]}},"owner":"obra","repo":"superpowers-chrome","repoPath":"obra/superpowers-chrome","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.445Z","topics":[],"category":"community","skillMd":{"name":"browsing","description":"Use when you need direct browser control - teaches Chrome DevTools Protocol for controlling existing browser sessions, multi-tab management, form automation, and content extraction via use_browser MCP tool","bodyPreview":"# Browsing with Chrome Direct\n\n## Overview\n\nControl Chrome via DevTools Protocol using the `use_browser` MCP tool. Single unified interface with auto-starting Chrome.\n\n**Announce:** \"I''m using the browsing skill to control Chrome.\"\n\n## When to Use\n\n**Use this when:**\n- Controlling authenticated sessions\n- Managing multiple tabs in running browser\n- Playwright MCP unavailable or excessive\n\n**Use Playwright MCP when:**\n- Need fresh browser instances\n- Generating screenshots/PDFs\n- Prefer higher-le","body":"# Browsing with Chrome Direct\n\n## Overview\n\nControl Chrome via DevTools Protocol using the `use_browser` MCP tool. Single unified interface with auto-starting Chrome.\n\n**Announce:** \"I''m using the browsing skill to control Chrome.\"\n\n## When to Use\n\n**Use this when:**\n- Controlling authenticated sessions\n- Managing multiple tabs in running browser\n- Playwright MCP unavailable or excessive\n\n**Use Playwright MCP when:**\n- Need fresh browser instances\n- Generating screenshots/PDFs\n- Prefer higher-level abstractions\n\n## Auto-Capture\n\nEvery DOM action (navigate, click, type, select, eval, keyboard_press) automatically saves:\n- `{prefix}.png` — viewport screenshot\n- `{prefix}.md` — page content as structured markdown\n- `{prefix}.html` — full rendered DOM\n- `{prefix}-console.txt` — browser console messages\n\nFiles are saved to the session directory with sequential prefixes (001-navigate, 002-click, etc.). You must check these before using extract or screenshot actions.\n\n## The use_browser Tool\n\nSingle MCP tool with action-based interface. Chrome auto-starts on first use.\n\n**Parameters:**\n- `action` (required): Operation to perform\n- `tab_index` (optional): Tab to operate on (default: 0)\n- `selector` (optional): CSS selector for element operations\n- `payload` (optional): Action-specific data\n- `timeout` (optional): Timeout in ms for await operations (default: 5000)\n\n## Actions Reference\n\n### Navigation\n- **navigate**: Navigate to URL\n  - `payload`: URL string\n  - Example: `{action: \"navigate\", payload: \"https://example.com\"}`\n\n- **await_element**: Wait for element to appear\n  - `selector`: CSS selector\n  - `timeout`: Max wait time in ms\n  - Example: `{action: \"await_element\", selector: \".loaded\", timeout: 10000}`\n\n- **await_text**: Wait for text to appear\n  - `payload`: Text to wait for\n  - Example: `{action: \"await_text\", payload: \"Welcome\"}`\n\n### Interaction\n- **click**: Click element\n  - `selector`: CSS selector\n  - Example: `{action: \"click\", selector: \"button.submit\"}`\n\n- **type**: Type text into input (append `\\n` to submit)\n  - `selector`: CSS selector\n  - `payload`: Text to type\n  - Example: `{action: \"type\", selector: \"#email\", payload: \"user@example.com\\n\"}`\n\n- **select**: Select dropdown option\n  - `selector`: CSS selector\n  - `payload`: Option value(s)\n  - Example: `{action: \"select\", selector: \"select[name=state]\", payload: \"CA\"}`\n\n### Extraction\n- **extract**: Get page content\n  - `payload`: Format (''markdown''|''text''|''html'')\n  - `selector`: Optional - limit to element\n  - Example: `{action: \"extract\", payload: \"markdown\"}`\n  - Example: `{action: \"extract\", payload: \"text\", selector: \"h1\"}`\n\n- **attr**: Get element attribute\n  - `selector`: CSS selector\n  - `payload`: Attribute name\n  - Example: `{action: \"attr\", selector: \"a.download\", payload: \"href\"}`\n\n- **eval**: Execute JavaScript\n  - `payload`: JavaScript code\n  - Example: `{action: \"eval\", payload: \"document.title\"}`\n\n### Export\n- **screenshot**: Capture screenshot of a specific element\n  - `payload`: Filename\n  - `selector`: Optional - screenshot specific element\n  - Viewport screenshots are auto-captured after every DOM action. Use this only when you need a specific element.\n  - Example: `{action: \"screenshot\", payload: \"/tmp/chart.png\", selector: \".chart\"}`\n\n### Tab Management\n- **list_tabs**: List all open tabs\n  - Example: `{action: \"list_tabs\"}`\n\n- **new_tab**: Create new tab\n  - Example: `{action: \"new_tab\"}`\n\n- **close_tab**: Close tab\n  - `tab_index`: Tab to close\n  - Example: `{action: \"close_tab\", tab_index: 2}`\n\n### Browser Mode Control\n- **show_browser**: Make browser window visible (headed mode)\n  - Example: `{action: \"show_browser\"}`\n  - ⚠️ **WARNING**: Restarts Chrome, reloads pages via GET, loses POST state\n\n- **hide_browser**: Switch to headless mode (invisible browser)\n  - Example: `{action: \"hide_browser\"}`\n  - ⚠️ **WARNING**: Restarts Chrome, reloads pages via GET, loses POST state\n\n- **browser_mode**: Check current browser mode, port, and profile\n  - Example: `{action: \"browser_mode\"}`\n  - Returns: `{\"headless\": true|false, \"mode\": \"headless\"|\"headed\", \"running\": true|false, \"port\": 9222, \"profile\": \"name\", \"profileDir\": \"/path\"}`\n\n### Profile Management\n- **set_profile**: Change Chrome profile (must kill Chrome first)\n  - Example: `{action: \"set_profile\", \"payload\": \"browser-user\"}`\n  - ⚠️ **WARNING**: Chrome must be stopped first\n\n- **get_profile**: Get current profile name and directory\n  - Example: `{action: \"get_profile\"}`\n  - Returns: `{\"profile\": \"name\", \"profileDir\": \"/path\"}`\n\n**Default behavior**: Chrome starts in **headless mode** with **\"superpowers-chrome\" profile** on a **dynamically allocated port** (range 9222-12111). Override with `CHROME_WS_PORT` env var or MCP `--port=N` flag.\n\n**Critical caveats when toggling modes**:\n1. **Chrome must restart** - Cannot switch headless/headed mode on running Chrome\n2. **Pages reload via GET** - All open tabs are reopened with GET requests\n3. **POST state is lost** - Form submissions, POST results, and POST-based navigation will be lost\n4. **Session state is lost** - Any client-side state (JavaScript variables, etc.) is cleared\n5. **Cookies/auth may persist** - Uses same user data directory, so logged-in sessions may survive\n\n**When to use headed mode**:\n- Debugging visual rendering issues\n- Demonstrating browser behavior to user\n- Testing features that only work with visible browser\n- Debugging issues that don''t reproduce in headless mode\n\n**When to stay in headless mode** (default):\n- All other cases - faster, cleaner, less intrusive\n- Screenshots work perfectly in headless mode\n- Most automation works identically in both modes\n\n**Profile management**:\nProfiles store persistent browser data (cookies, localStorage, extensions, auth sessions).\n\n**Profile locations**:\n- macOS: `~/Library/Caches/superpowers/browser-profiles/{name}/`\n- Linux: `~/.cache/superpowers/browser-profiles/{name}/`\n- Windows: `%LOCALAPPDATA%/superpowers/browser-profiles/{name}/`\n\n**When to use separate profiles**:\n- **Default profile (\"superpowers-chrome\")**: General automation, shared sessions\n- **Agent-specific profiles**: Isolate different agents'' browser state\n  - Example: browser-user agent uses \"browser-user\" profile\n- **Task-specific profiles**: Testing with different user contexts\n  - Example: \"test-logged-in\" vs \"test-logged-out\"\n\n**Profile data persists across**:\n- Chrome restarts\n- Mode toggles (headless ↔ headed)\n- System reboots (data is in cache directory)\n\n**To use a different profile**:\n1. Kill Chrome if running: `await chromeLib.killChrome()`\n2. Set profile: `{action: \"set_profile\", \"payload\": \"my-profile\"}`\n3. Start Chrome: Next navigate/action will use new profile\n\n## Quick Start Pattern\n\n```\nNavigate and extract:\n{action: \"navigate\", payload: \"https://example.com\"}\n{action: \"await_element\", selector: \"h1\"}\n{action: \"extract\", payload: \"text\", selector: \"h1\"}\n```\n\n## Common Patterns\n\n### Fill and Submit Form\n```\n{action: \"navigate\", payload: \"https://example.com/login\"}\n{action: \"await_element\", selector: \"input[name=email]\"}\n{action: \"type\", selector: \"input[name=email]\", payload: \"user@example.com\"}\n{action: \"type\", selector: \"input[name=password]\", payload: \"pass123\\n\"}\n{action: \"await_text\", payload: \"Welcome\"}\n```\n\nThe `\\n` at the end of the password submits the form.\n\n### Multi-Tab Workflow\n```\n{action: \"list_tabs\"}\n{action: \"click\", tab_index: 2, selector: \"a.email\"}\n{action: \"await_element\", tab_index: 2, selector: \".content\"}\n{action: \"extract\", tab_index: 2, payload: \"text\", selector: \".amount\"}\n```\n\n### Dynamic Content\n```\n{action: \"navigate\", payload: \"https://example.com\"}\n{action: \"type\", selector: \"input[name=q]\", payload: \"query\"}\n{action: \"click\", selector: \"button.search\"}\n{action: \"await_element\", selector: \".results\"}\n{action: \"extract\", payload: \"text\", selector: \".result-title\"}\n```\n\n### Get Link Attribute\n```\n{action: \"navigate\", payload: \"https://example.com\"}\n{action: \"await_element\", selector: \"a.download\"}\n{action: \"attr\", selector: \"a.download\", payload: \"href\"}\n```\n\n### Execute JavaScript\n```\n{action: \"eval\", payload: \"document.querySelectorAll(''a'').length\"}\n{action: \"eval\", payload: \"Array.from(document.querySelectorAll(''a'')).map(a => a.href)\"}\n```\n\n### Resize Viewport (Responsive Testing)\nUse `eval` to resize the browser window for testing responsive layouts:\n```\n{action: \"eval\", payload: \"window.resizeTo(375, 812); ''Resized to mobile''\"}\n{action: \"eval\", payload: \"window.resizeTo(768, 1024); ''Resized to tablet''\"}\n{action: \"eval\", payload: \"window.resizeTo(1920, 1080); ''Resized to desktop''\"}\n```\n\n**Note**: This resizes the window, not device emulation. It won''t change:\n- Device pixel ratio (retina displays)\n- Touch events\n- User-Agent string\n\nFor most responsive testing, window resize is sufficient.\n\n### Clear Cookies\nUse `eval` to clear cookies accessible to JavaScript:\n```\n{action: \"eval\", payload: \"document.cookie.split('';'').forEach(c => { document.cookie = c.trim().split(''='')[0] + ''=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=/''; }); ''Cookies cleared''\"}\n```\n\n**Note**: This clears cookies accessible to JavaScript. It won''t clear:\n- httpOnly cookies (server-side only)\n- Cookies from other domains\n\nFor most logout/reset scenarios, this is sufficient.\n\n### Scroll Page\n```\n{action: \"eval\", payload: \"window.scrollTo(0, document.body.scrollHeight); ''Scrolled to bottom''\"}\n{action: \"eval\", payload: \"window.scrollTo(0, 0); ''Scrolled to top''\"}\n{action: \"eval\", payload: \"document.querySelector(''.target'').scrollIntoView(); ''Scrolled to element''\"}\n```\n\n## Tips\n\n**Always wait before interaction:**\nDon''t click or fill immediately after navigate - pages need time to load.\n\n```\n// BAD - might fail if page slow\n{action: \"navigate\", payload: \"https://example.com\"}\n{action: \"click\", selector: \"button\"}  // May fail!\n\n// GOOD - wait first\n{action: \"navigate\", payload: \"https://example.com\"}\n{action: \"await_element\", selector: \"button\"}\n{action: \"click\", selector: \"button\"}\n```\n\n**Use specific selectors:**\nAvoid generic selectors that match multiple elements.\n\n```\n// BAD - matches first button\n{action: \"click\", selector: \"button\"}\n\n// GOOD - specific\n{action: \"click\", selector: \"button[type=submit]\"}\n{action: \"click\", selector: \"#login-button\"}\n```\n\n**Submit forms with \\n:**\nAppend newline to text to submit forms automatically.\n\n```\n{action: \"type\", selector: \"#search\", payload: \"query\\n\"}\n```\n\n**Check content first:**\nExtract page content to verify selectors before building workflow.\n\n```\n{action: \"extract\", payload: \"html\"}\n```\n\n## Troubleshooting\n\n**Element not found:**\n- Use `await_element` before interaction\n- Verify selector with `extract` action using ''html'' format\n\n**Timeout errors:**\n- Increase timeout: `{timeout: 30000}` for slow pages\n- Wait for specific element instead of text\n\n**Tab index out of range:**\n- Use `list_tabs` to get current indices\n- Tab indices change when tabs close\n\n**eval returns `[object Object]`:**\n- Use `JSON.stringify()` for complex objects: `{action: \"eval\", payload: \"JSON.stringify({name: ''test''})\"}`\n- For async functions: `{action: \"eval\", payload: \"JSON.stringify(await yourAsyncFunction())\"}`\n\n## Test Automation (Advanced)\n\n<details>\n<summary>Click to expand test automation guidance</summary>\n\nWhen building test automation, you have two approaches:\n\n### Approach 1: use_browser MCP (Simple Tests)\nBest for: Single-step tests, direct Claude control during conversation\n\n```json\n{\"action\": \"navigate\", \"payload\": \"https://app.com\"}\n{\"action\": \"click\", \"selector\": \"#test-button\"}\n{\"action\": \"eval\", \"payload\": \"JSON.stringify({passed: document.querySelector(''.success'') !== null})\"}\n```\n\n### Approach 2: chrome-ws CLI (Complex Tests)\nBest for: Multi-step test suites, standalone automation scripts\n\n**Key insight**: `chrome-ws` is the reference implementation showing proper Chrome DevTools Protocol usage. When `use_browser` doesn''t work as expected, examine how `chrome-ws` handles the same operation.\n\n```bash\n# Example: Automated form testing\n./chrome-ws navigate 0 \"https://app.com/form\"\n./chrome-ws fill 0 \"#email\" \"test@example.com\"\n./chrome-ws click 0 \"button[type=submit]\"\n./chrome-ws wait-text 0 \"Success\"\n```\n\n### When use_browser Fails\n1. **Check chrome-ws source code** - It shows the correct CDP pattern\n2. **Use chrome-ws to verify** - Test the same operation via CLI\n3. **Adapt the pattern** - Apply the working CDP approach to use_browser\n\n### Common Test Automation Patterns\n- **Form validation**: Fill forms, check error states\n- **UI state testing**: Click elements, verify DOM changes\n- **Performance testing**: Measure load times, capture metrics\n- **Screenshot comparison**: Capture before/after states\n\n</details>\n\n## Advanced Usage\n\nFor command-line usage outside Claude Code, see [COMMANDLINE-USAGE.md](COMMANDLINE-USAGE.md).\n\nFor detailed examples, see [EXAMPLES.md](EXAMPLES.md).\n\n## Protocol Reference\n\nFull CDP documentation: https://chromedevtools.github.io/devtools-protocol/\n"},"lastSynced":"2026-03-08T02:08:53.786Z","agentAnalysis":{"suitability":{"en":"Ideal for Automation Agents requiring seamless Chrome control via DevTools Protocol for managing authenticated sessions and multiple tabs.","zh":"适用于需要通过DevTools Protocol实现无缝Chrome控制的自动化代理，用于管理已认证会话和多个标签页。","ja":"DevTools Protocolを介してシームレスなChrome制御を必要とする自動化エージェントに適しています。認証セッションと複数のタブを管理するために使用されます。","ko":"DevTools Protocol을 통해 무결점 Chrome 제어를 요구하는 자동화 에이전트에 적합합니다. 인증 세션 및 여러 탭을 관리하는 데 사용됩니다.","es":"Ideal para Agentes de Automatización que requieren un control perfecto de Chrome a través del Protocolo de DevTools para gestionar sesiones autenticadas y múltiples pestañas.","fr":"Idéal pour les agents d''automatisation nécessitant un contrôle transparent de Chrome via le Protocole DevTools pour gérer les sessions authentifiées et les onglets multiples.","de":"Ideal für Automatisierungsagenten, die eine nahtlose Chrome-Steuerung über das DevTools-Protokoll für die Verwaltung authentifizierter Sitzungen und mehrerer Registerkarten erfordern.","pt":"Ideal para Agentes de Automação que exigem controle perfeito do Chrome via DevTools Protocol para gerenciar sessões autenticadas e várias guias.","ru":"Идеально подходит для агентов автоматизации, требующих бесшовного управления Chrome через протокол DevTools для управления аутентифицированными сессиями и несколькими вкладками.","ar":"مثالية لعمليات وكيل الأتمتة التي تتطلب التحكم السلس في Chrome من خلال بروتوكول DevTools لإدارة الجلسات المصرح بها وعدة علامات تبويب."},"recommendation":{"en":"Empowers agents to control Chrome using the `use_browser` MCP tool, enabling automated browsing sessions with a unified interface and auto-starting Chrome, perfect for tasks involving authenticated sessions and multi-tab management using DevTools Protocol.","zh":"赋予代理使用`use_browser` MCP工具控制Chrome的能力，使得自动化浏览会话能够通过统一接口进行，并自动启动Chrome，非常适合涉及认证会话和多标签管理的任务，使用DevTools Protocol。","ja":"`use_browser` MCPツールを使用してChromeを制御するエージェントを可能にします。自動化されたブラウジングセッションを統一されたインターフェイスで実行し、Chromeを自動で起動します。認証セッションやマルチタブ管理をDevTools Protocolで行うタスクに最適です。","ko":"`use_browser` MCP 도구를 사용하여 Chrome를 제어하는 에이전트를 가능하게 합니다. 자동화된 브라우징 세션을 통일된 인터페이스로 실행하고 Chrome를 자동으로 시작합니다. DevTools Protocol을 사용하는 인증 세션 및 멀티 탭 관리 작업에 적합합니다.","es":"Habilita a los agentes a controlar Chrome utilizando la herramienta `use_browser` MCP, lo que permite sesiones de navegación automatizadas con una interfaz unificada y el arranque automático de Chrome, perfecto para tareas que involucran sesiones autenticadas y gestión de múltiples pestañas utilizando el Protocolo DevTools.","fr":"Permet aux agents de contrôler Chrome en utilisant l''outil `use_browser` MCP, permettant ainsi des sessions de navigation automatisées avec une interface unifiée et le démarrage automatique de Chrome, parfait pour les tâches impliquant des sessions authentifiées et la gestion de plusieurs onglets à l''aide du Protocole DevTools.","de":"Ermächtigt die Agenten, Chrome mithilfe des `use_browser`-MCP-Tools zu steuern, wodurch automatisierte Browsersitzungen mit einer einheitlichen Oberfläche und dem automatischen Start von Chrome ermöglicht werden, ideal für Aufgaben, die authentifizierte Sitzungen und die Verwaltung mehrerer Registerkarten unter Verwendung des DevTools-Protokolls beinhalten.","pt":"Habilita os agentes a controlar o Chrome usando a ferramenta `use_browser` MCP, permitindo sessões de navegação automatizadas com uma interface unificada e inicialização automática do Chrome, perfeita para tarefas que envolvem sessões autenticadas e gerenciamento de várias guias usando o DevTools Protocol.","ru":"Наделяет агентов возможностью управлять Chrome с помощью инструмента `use_browser` MCP, что позволяет автоматизировать сеансы просмотра с унифицированным интерфейсом и автоматическим запуском Chrome, идеально подходит для задач, связанных с аутентифицированными сессиями и управлением несколькими вкладками с помощью DevTools Protocol.","ar":"تمكين الوكيل من التحكم في Chrome باستخدام أداة `use_browser` MCP، مما يسمح بالجلسات التصفح الآلي مع واجهة موحدة وبدء تشغيل تلقائي لبرنامج Chrome، مثالية للمهام التي تتضمن الجلسات المصرح بها وإدارة علامات التبويب المتعددة باستخدام بروتوكول DevTools."},"useCases":{"en":["Automating authenticated browsing sessions","Managing multiple tabs in a running browser instance","Controlling Chrome for data scraping and extraction"],"zh":["自动化认证浏览会话","管理运行中的浏览器实例中的多个标签页","使用DevTools Protocol进行数据抓取和提取的Chrome控制"],"ja":["認証付きブラウジングセッションの自動化","実行中のブラウザインスタンス内の複数のタブを管理する","DevTools Protocolを使用したデータスクラピングおよび抽出のためのChrome制御"],"ko":["인증된 브라우징 세션 자동화","실행 중인 브라우저 인스턴스 내의 여러 탭 관리","DevTools Protocol을 사용한 데이터 스크레이핑 및 추출을 위한 Chrome 제어"],"es":["Automatizar sesiones de navegación autenticadas","Gestionar múltiples pestañas en una instancia de navegador en ejecución","Controlar Chrome para la extracción y extracción de datos"],"fr":["Automatiser les sessions de navigation authentifiées","Gérer plusieurs onglets dans une instance de navigateur en cours d''exécution","Contrôler Chrome pour le scraping et l''extraction de données"],"de":["Automatisierte authentifizierte Browsersitzungen","Verwalten von mehreren Registerkarten in einer laufenden Browser-Instanz","Steuerung von Chrome für Daten-Scraping und -Extraktion"],"pt":["Automatizar sessões de navegação autenticadas","Gerenciar várias guias em uma instância de navegador em execução","Controlar o Chrome para raspagem e extração de dados"],"ru":["Автоматизировать аутентифицированные сеансы просмотра","Управлять несколькими вкладками в запущенной инстанции браузера","Управлять Chrome для сбора и извлечения данных"],"ar":["أتمتة جلسات التصفح المصرح بها","إدارة علامات التبويب المتعددة في مثيل متصفح قيد التشغيل","التحكم في Chrome لاستخراج البيانات واستخراجها"]},"limitations":{"en":["Requires `use_browser` MCP tool","Chrome only","Playwright MCP unavailable or excessive"],"zh":["需要`use_browser` MCP工具","仅支持Chrome","Playwright MCP不可用或过度"],"ja":["`use_browser` MCPツールを必要とする","Chromeのみをサポート","Playwright MCPは使用できないか過剰"],"ko":["`use_browser` MCP 도구가 필요","Chrome만 지원","Playwright MCP는 사용할 수 없거나 과도"],"es":["Requiere la herramienta `use_browser` MCP","Solo Chrome","Playwright MCP no disponible o excesivo"],"fr":["Nécessite l''outil `use_browser` MCP","Chrome uniquement","Playwright MCP indisponible ou excessif"],"de":["Benötigt das `use_browser`-MCP-Tool","Nur Chrome","Playwright-MCP nicht verfügbar oder übermäßig"],"pt":["Exige a ferramenta `use_browser` MCP","Somente Chrome","Playwright MCP indisponível ou excessivo"],"ru":["Требует инструмента `use_browser` MCP","Только Chrome","Playwright MCP недоступен или излишен"],"ar":["يتطلب أداة `use_browser` MCP","برنامج Chrome فقط","Playwright MCP غير متوفر أو زائد"]},"version":4},"contentHash":"16cfcc0358ac2e0a5af69b6afda0a501e48b59cbba35a55d298ac4b427e0dc70","qualityScore":57}');
