INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sathidpong01/magga/tailwind-design-system', 'tailwind-design-system', 'sathidpong01', 'magga', 'community', 'tailwind-design-system sathidpong01 magga community This AI agent skill enables developers to build production-ready design systems using Tailwind CSS v4. It focuses on CSS-first configuration, design tokens, component variants, and accessible responsive patterns for frontend teams creating component libraries. Tailwind 设计系统是一个用于构建生产就绪的设计系统的工具，支持 CSS-first 配置、设计令牌和组件变体 Tailwind Design System は、生産可能なデザイン システムを構築するためのツールで、CSS-first 構成、デザイン トークン、コンポーネント バリアントをサポートします Tailwind 디자인 시스템은 생산 준비가 된 디자인 시스템을 구축하기 위한 도구로 CSS-first 구성, 디자인 토큰 및 컴포넌트 변형을 지원합니다 El sistema de diseño Tailwind permite a los desarrolladores crear bibliotecas de componentes con Tailwind v4 y implementar tokens de diseño y temas con configuración CSS-first Le système de design Tailwind permet aux développeurs de créer des bibliothèques de composants avec Tailwind v4 et de mettre en œuvre des jetons de design et des thèmes avec une configuration CSS-first Das Tailwind-Designsystem ermöglicht es Entwicklern, Komponentenbibliotheken mit Tailwind v4 zu erstellen und Design-Tokens und Themen mit einer CSS-ersten Konfiguration zu implementieren O Tailwind Design System é uma ferramenta para criar sistemas de design personalizados com Tailwind CSS v4. Система Дизайна Tailwind - это инструмент для создания производственных систем дизайна с Tailwind CSS v4. نظام التصميم Tailwind هو أداة لإنشاء أنظمة تصميم مخصصة مع Tailwind CSS v4. tailwind-design-system setup guide what is tailwind-design-system tailwind css v4 design tokens tailwind-design-system vs storybook how to use tailwind-design-system tailwind css component library tailwind-design-system install css-first configuration tailwind Tailwind 设计系统 Tailwind CSS v4 CSS-first 配置 设计令牌 组件变体 响应式模式 无障碍支持 AIエージェント Builds component libraries with Tailwind CSS v4 Implements CSS-first configuration for design tokens Creates component variants for reusable UI Builds responsive patterns for modern layouts Ensures accessibility compliance in generated components tailwind-design-system is an AI agent skill for building design systems with Tailwind CSS v4. It provides capabilities for CSS-first configuration, managing design tokens, creating component variants, and implementing responsive and accessible UI patterns for component libraries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jdiegosierra/contributor-report/find-skills', 'community', 'jdiegosierra', 'contributor-report', 'jdiegosierra/contributor-report', 'find-skills', 0, 0, 57, '2026-03-08T01:57:15.456Z', '2026-03-08T02:09:06.786Z', '2ecead454dcf067ec2ae332fa22d843bdc4f7fcf599ee61d29f1da6c39842813', '{"id":"jdiegosierra/contributor-report/find-skills","name":"find-skills","description":{"en":"The find-skills AI agent skill enables developers to discover and install capabilities from the open agent skills ecosystem. It directly addresses user queries asking ''how do I do X'' or ''is there a skill for X'' to extend agent functionality.","zh":"Find Skills帮助您发现和安装技能，使用GitHub Action评估贡献者质量","ja":"Find Skillsは、スキルを発見してインストールし、GitHub Actionを使用してコントリビューターの品質を評価する","ko":"Find Skills는 스킬을 검색하여 설치하고 GitHub Action을 사용하여 기여자의 품질을 평가합니다","es":"find-skills es una acción de GitHub que evalúa la calidad de los contribuyentes utilizando métricas objetivas para combatir el spam generado por IA y el código de baja calidad","fr":"find-skills est une action GitHub qui évalue la qualité des contributeurs en utilisant des métriques objectives pour combattre le spam généré par l''IA et le code de mauvaise qualité","de":"find-skills ist eine GitHub-Aktion, die die Qualität der Mitwirkenden mit objektiven Metriken bewertet, um Spam generiert von KI und schlechten Code zu bekämpfen","pt":"O Find-Skills é uma ação do GitHub que ajuda a avaliar a qualidade dos contribuidores usando métricas objetivas, combatendo assim o spam e o código de baixa qualidade","ru":"Find-Skills - действие GitHub, которое помогает оценить качество вкладчиков с помощью объективных метрик, борясь со спамом и плохим кодом ИИ Агентов","ar":"Find-Skills هو إجراء GitHub يساعد في تقييم جودة المساهمين باستخدام معايير موضوعية، مما يساعد في مكافحة البريد العشوائي ورمز المنخفضة الجودة"},"