INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jdiegosierra/contributor-report/find-skills', 'find-skills', 'jdiegosierra', 'contributor-report', 'community', 'find-skills jdiegosierra contributor-report community The find-skills AI agent skill enables developers to discover and install capabilities from the open agent skills ecosystem. It directly addresses user queries asking ''how do I do X'' or ''is there a skill for X'' to extend agent functionality. Find Skills帮助您发现和安装技能，使用GitHub Action评估贡献者质量 Find Skillsは、スキルを発見してインストールし、GitHub Actionを使用してコントリビューターの品質を評価する Find Skills는 스킬을 검색하여 설치하고 GitHub Action을 사용하여 기여자의 품질을 평가합니다 find-skills es una acción de GitHub que evalúa la calidad de los contribuyentes utilizando métricas objetivas para combatir el spam generado por IA y el código de baja calidad find-skills est une action GitHub qui évalue la qualité des contributeurs en utilisant des métriques objectives pour combattre le spam généré par l''IA et le code de mauvaise qualité find-skills ist eine GitHub-Aktion, die die Qualität der Mitwirkenden mit objektiven Metriken bewertet, um Spam generiert von KI und schlechten Code zu bekämpfen O Find-Skills é uma ação do GitHub que ajuda a avaliar a qualidade dos contribuidores usando métricas objetivas, combatendo assim o spam e o código de baixa qualidade Find-Skills - действие GitHub, которое помогает оценить качество вкладчиков с помощью объективных метрик, борясь со спамом и плохим кодом ИИ Агентов Find-Skills هو إجراء GitHub يساعد في تقييم جودة المساهمين باستخدام معايير موضوعية، مما يساعد في مكافحة البريد العشوائي ورمز المنخفضة الجودة how to use find-skills what is find-skills find-skills install guide find-skills vs skill discovery find-skills setup AI agent skill discovery extend AI agent capabilities open agent skills ecosystem Find Skills AIエージェント GitHub Action 代码质量 技能发现 贡献者质量评估 代码搜索 工具搜索 Discovers existing skills for common tasks from the open agent ecosystem Installs skills based on user queries like ''how do I do X'' Responds to direct search commands like ''find a skill for X'' Extends agent capabilities by adding specialized functionalities Searches for tools, templates, and workflows within the skills ecosystem find-skills is an AI agent skill that helps users discover and install other skills from the open agent skills ecosystem. It is used when a user asks about performing a common task or expresses interest in extending their agent''s capabilities.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Columbia-Cloudworks-LLC/EquipQR/google-maps', 'community', 'Columbia-Cloudworks-LLC', 'EquipQR', 'Columbia-Cloudworks-LLC/EquipQR', 'google-maps', 0, 0, 57, '2026-03-08T01:57:15.483Z', '2026-03-08T02:10:00.449Z', '3372c251d462d8968482786480325ed73b12d987861fd40b624f5fff468dff64', '{"id":"Columbia-Cloudworks-LLC/EquipQR/google-maps","name":"google-maps","description":{"en":"The google-maps skill enables developers to manage fleet service equipment history using secure QR codes, leveraging Google Maps for visualization, address picking, and geocoding. This skill benefits developers and fleet managers.","zh":"EquipQR使用Google Maps实现Fleet Map、Places Autocomplete和Geocoding功能，提供安全的设备历史记录管理","ja":"EquipQRはGoogle Mapsを使用してFleet Map、Places Autocomplete、Geocoding機能を実現し、安全な機器履歴管理を提供","ko":"EquipQR는 Google Maps를 사용하여 Fleet Map, Places Autocomplete, Geocoding 기능을 구현하여 안전한 장비 기록 관리를 제공","es":"La integración de Google Maps en EquipQR permite la visualización de flotas, autocompletar direcciones y geocodificar ubicaciones de manera segura","fr":"L''intégration de Google Maps dans EquipQR permet la visualisation des flottes, l''autocomplétion des adresses et la géocodification des emplacements de manière sécurisée","de":"Die Integration von Google Maps in EquipQR ermöglicht die Visualisierung von Flotten, das Autocompleten von Adressen und das Geocodieren von Standorten auf sichere Weise","pt":"O Google Maps é integrado ao EquipQR para fornecer visualização de mapas de frota, preenchimento automático de endereços e geocodificação","ru":"Google Maps интегрирован с EquipQR для предоставления визуализации карт флотилии, автозаполнения адресов и геокодирования для ИИ Агентов","ar":"تم دمج خرائط جوجل مع EquipQR لتوفير تصور خرائط الأسطول وتكملة العناوين автомاتически والتعرف على الموقع"},"seo":{"title":{"en":"google-maps: Integration Setup Guide | AI Agent Skill","zh":"Google Maps集成指南 - EquipQR","ja":"Google Maps統合ガイド - EquipQR","ko":"Google Maps 통합 설정 가이드 - EquipQR","es":"Guía de configuración de Google Maps para EquipQR","fr":"Guide d''intégration de Google Maps pour EquipQR","de":"Konfigurationsleitfaden für Google Maps in EquipQR","pt":"Guia de Configuração do Google Maps para Desenvolvedores","ru":"Настройка Google Maps: Руководство для разработчиков ИИ А...","ar":"إعداد خرائط جوجل: دليل للمطورين"},"description":{"en":"Unlock the full potential of EquipQR with Google Maps integration - learn how to set up Fleet Map, Places Autocomplete, and Geocoding features","zh":"使用Google Maps的Fleet Map、Places Autocomplete和Geocoding功能，管理您的车队服务设备历史记录","ja":"Google MapsのFleet Map、Places Autocomplete、Geocoding機能を使用して、車隊サービス機器の履歴を管理","ko":"Google Maps의 Fleet Map, Places Autocomplete, Geocoding 기능을 사용하여 차량 서비스 장비 기록을 관리","es":"Aprende a integrar Google Maps en EquipQR para visualizar flotas, autocompletar direcciones y geocodificar ubicaciones","fr":"Découvrez comment intégrer Google Maps dans EquipQR pour visualiser les flottes, autocompléter les adresses et géocoder les emplacements","de":"Erfahren Sie, wie Sie Google Maps in EquipQR integrieren, um Flotten zu visualisieren, Adressen zu autocompleten und Standorte zu geocodieren","pt":"Aprenda a integrar o Google Maps em sua aplicação com EquipQR, utilizando recursos como Fleet Map, Places Autocomplete e Geocoding","ru":"Узнайте, как интегрировать Google Maps в ваше приложение с помощью EquipQR, используя функции, такие как Fleet Map, Places Autocomplete и Geocoding для ИИ Аг...","ar":"تعرف على كيفية دمج خرائط جوجل في تطبيقك باستخدام EquipQR، وتعلم استخدام ميزات مثل Fleet Map و Places Autocomplete و Geocoding"},"definition":{"en":"google-maps is a skill that integrates Google Maps features, including Fleet Map, Places Autocomplete, and Geocoding, to enhance EquipQR functionality","zh":"Google Maps集成是 EquipQR 中的一项功能，使用Google Maps API实现车队服务设备历史记录管理","ja":"Google Maps統合は、EquipQRの中の1機能で、Google Maps APIを使用して車隊サービス機器の履歴を管理","ko":"Google Maps 통합은 EquipQR의 기능 중 하나로 Google Maps API를 사용하여 차량 서비스 장비 기록을 관리","es":"Google Maps es una herramienta de mapas en línea que se integra en EquipQR para ofrecer funcionalidades de visualización y geocodificación","fr":"Google Maps est un outil de cartographie en ligne qui s''intègre dans EquipQR pour offrir des fonctionnalités de visualisation et de géocodification","de":"Google Maps ist ein Online-Kartentool, das in EquipQR integriert ist, um Visualisierungs- und Geocodierungsfunktionen zu bieten","pt":"O Google Maps é uma tecnologia de mapeamento que fornece recursos de visualização de mapas, geocodificação e autocomplete de endereços","ru":"Google Maps - это технология картографирования, которая предоставляет функции визуализации карт, геокодирования и автозаполнения адресов для ИИ Агентов","ar":"خرائط جوجل هي تقنية خريطة توفر ميزات مثل عرض الخرائط والتعرف على الموقع وتكملة العناوين"},"features":{"en":["Fleet Map visualization using Google Maps","Places Autocomplete for address picking","Geocoding for location-based data","Frontend hooks/components for seamless integration","Server-side Supabase Edge Functions for secure data processing","Use of GOOGLE_MAPS_BROWSER_KEY for secure authentication"],"zh":["Fleet Map可视化","Places Autocomplete地址选择","Geocoding地理编码","使用Supabase Edge Functions实现服务器端集成","使用React Hooks和组件实现前端集成","支持安全的设备历史记录管理"],"ja":["Fleet Mapの可視化","Places Autocompleteによる住所の選択","Geocodingによる地理コード化","Supabase Edge Functionsを使用したサーバーサイド統合","React Hooksとコンポーネントを使用したフロントエンド統合","安全な機器履歴管理のサポート"],"ko":["Fleet Map 시각화","Places Autocomplete 주소 선택","Geocoding 지리 코드화","Supabase Edge Functions를 사용한 서버측 통합","React Hooks와 컴포넌트를 사용한 프론트엔드 통합","안전한 장비 기록 관리 지원"],"es":["Visualización de flotas en un mapa","Autocompletar direcciones con Places Autocomplete","Geocodificación de ubicaciones con la API de Google Maps","Integración con Supabase Edge Functions","Uso de claves de API de Google Maps para autenticación","Compatibilidad con navegadores y dispositivos móviles"],"fr":["Visualisation des flottes sur une carte","Autocomplétion des adresses avec Places Autocomplete","Géocodification des emplacements avec l''API Google Maps","Intégration avec Supabase Edge Functions","Utilisation de clés d''API Google Maps pour l''authentification","Compatibilité avec les navigateurs et les appareils mobiles"],"de":["Visualisierung von Flotten auf einer Karte","Autocompleten von Adressen mit Places Autocomplete","Geocodierung von Standorten mit der Google Maps-API","Integration mit Supabase Edge Functions","Verwendung von Google Maps-API-Schlüsseln für die Authentifizierung","Kompatibilität mit Browsern und Mobilgeräten"],"pt":["Integração com Fleet Map para visualização de mapas de frota","Uso de Places Autocomplete para preenchimento automático de endereços","Geocodificação para conversão de endereços em coordenadas geográficas","Utilização de Supabase Edge Functions para processamento de dados","Integração com frontend hooks/components para melhor experiência do usuário","Uso de GOOGLE_MAPS_BROWSER_KEY para autenticação segura"],"ru":["Интеграция с Fleet Map для визуализации карт флотилии","Использование Places Autocomplete для автозаполнения адресов","Геокодирование для преобразования адресов в географические координаты","Применение Supabase Edge Functions для обработки данных","Интеграция с frontend hooks/components для лучшего опыта пользователя","Использование GOOGLE_MAPS_BROWSER_KEY для безопасной аутентификации"],"ar":["التكامل مع Fleet Map لعرض خرائط الأسطول","استخدام Places Autocomplete لتكملة العناوين","التعرف على الموقع لتحويل العناوين إلى إحداثيات جغرافية","استخدام Supabase Edge Functions لمعالجة البيانات","التكامل مع مكونات واجهة المستخدم الأمامية لتحسين تجربة المستخدم","استخدام GOOGLE_MAPS_BROWSER_KEY للتحقق من الهوية بشكل آمن"]},"keywords":{"en":["how to use google-maps in EquipQR","google-maps alternative for fleet management","google-maps vs Mapbox for geocoding","google-maps install guide for AI agents","google-maps setup guide for EquipQR","what is google-maps integration in EquipQR"],"zh":["Google Maps集成","EquipQR","Fleet Map","Places Autocomplete","Geocoding","Supabase Edge Functions","React Hooks","设备历史记录管理","车队服务设备管理","AIエージェント"],"ja":["Google Maps統合","EquipQR","Fleet Map","Places Autocomplete","Geocoding","Supabase Edge Functions","React Hooks","機器履歴管理","車隊サービス機器管理","AIエージェント"],"ko":["Google Maps 통합","EquipQR","Fleet Map","Places Autocomplete","Geocoding","Supabase Edge Functions","React Hooks","장비 기록 관리","차량 서비스 장비 관리","AI 에이전트"],"es":["Google Maps API","Integración de Google Maps","Visualización de flotas","Autocompletar direcciones","Geocodificación de ubicaciones","Supabase Edge Functions","Desarrollo de aplicaciones móviles","Herramientas de mapas en línea","API de geocodificación"],"fr":["API Google Maps","Intégration de Google Maps","Visualisation des flottes","Autocomplétion des adresses","Géocodification des emplacements","Supabase Edge Functions","Développement d''applications mobiles","Outils de cartographie en ligne","API de géocodification"],"de":["Google Maps-API","Integration von Google Maps","Visualisierung von Flotten","Autocompleten von Adressen","Geocodierung von Standorten","Supabase Edge Functions","Entwicklung von Mobilanwendungen","Online-Kartentools","Geocodierungs-API"],"pt":["google maps para desenvolvedores","integração google maps","fleet map","places autocomplete","geocodificação","supabase edge functions","frontend hooks/components","google maps api","desenvolvimento de aplicativos"],"ru":["google maps для разработчиков","интеграция google maps","fleet map","places autocomplete","геокодирование","supabase edge functions","frontend hooks/components","google maps api","разработка приложений","ИИ Агенты"],"ar":["خرائط جوجل للمطورين","دمج خرائط جوجل","fleet map","places autocomplete","التعرف على الموقع","supabase edge functions","مكونات واجهة المستخدم الأمامية","google maps api","تطوير التطبيقات","أدوات الذكاء الاصطناعي"]}},"owner":"Columbia-Cloudworks-LLC","repo":"EquipQR","repoPath":"Columbia-Cloudworks-LLC/EquipQR","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.483Z","topics":[],"category":"community","skillMd":{"name":"google-maps","description":"Expert guide for developing, debugging, and extending Google Maps integration in EquipQR. Use when working with maps, geocoding, places autocomplete, location features, fleet map, Google Maps API keys, or address components. Also use when the user mentions google maps, geocode, fleet map, places autocomplete, map marker, address picker, or location.","bodyPreview":"# Google Maps Integration — EquipQR\n\n## Architecture Overview\n\nEquipQR uses Google Maps for three main features: **Fleet Map** visualization, **Places Autocomplete** address picking, and **Geocoding**. The integration spans frontend hooks/components and server-side Supabase Edge Functions.\n\n```\nBrowser                                    Supabase Edge Functions\n───────                                    ──────────────────────\nuseGoogleMapsKey ──→ public-google-maps-key ──→ GOOGLE_MAPS_BROWSER_KEY","body":"# Google Maps Integration — EquipQR\n\n## Architecture Overview\n\nEquipQR uses Google Maps for three main features: **Fleet Map** visualization, **Places Autocomplete** address picking, and **Geocoding**. The integration spans frontend hooks/components and server-side Supabase Edge Functions.\n\n```\nBrowser                                    Supabase Edge Functions\n───────                                    ──────────────────────\nuseGoogleMapsKey ──→ public-google-maps-key ──→ GOOGLE_MAPS_BROWSER_KEY\nuseGoogleMapsLoader ──→ Google Maps JS API (loads <script> with browser key)\nGooglePlacesAutocomplete ──→ PlaceAutocompleteElement (web component)\n                         └─→ places-autocomplete edge fn (fallback) ──→ GOOGLE_MAPS_SERVER_KEY\nMapView (GoogleMap) ──→ @react-google-maps/api\nClickableAddress ──→ maps.google.com deep link\ngeocode-location edge fn ──→ GOOGLE_MAPS_SERVER_KEY + geocoded_locations cache\n```\n\n## API Keys\n\nTwo separate keys with different restrictions:\n\n| Key | Env Var | Where Set | Used By |\n|-----|---------|-----------|---------|\n| **Browser key** | `GOOGLE_MAPS_BROWSER_KEY` | Supabase Edge Function secrets | `public-google-maps-key` → served to browser |\n| **Server key** | `GOOGLE_MAPS_SERVER_KEY` | Supabase Edge Function secrets | `geocode-location`, `places-autocomplete` |\n\n**Local development**: Set both in `supabase/functions/.env` (NOT the root `.env`).\n\n**Production**: Set in Supabase Dashboard → Project → Settings → Edge Functions → Secrets.\n\n**Important**: These are NOT Vercel env vars. Redeploying on Vercel does not affect these secrets.\n\n### Legacy key names (still supported with fallback)\n\n| Legacy Name | New Canonical Name |\n|---|---|\n| `VITE_GOOGLE_MAPS_BROWSER_KEY` | `GOOGLE_MAPS_BROWSER_KEY` |\n| `GOOGLE_MAPS_API_KEY` | `GOOGLE_MAPS_SERVER_KEY` |\n| `VITE_GOOGLE_MAPS_API_KEY` | `GOOGLE_MAPS_SERVER_KEY` |\n\nAll edge functions prefer the new name and fall back to legacy names.\n\n## Frontend Components & Hooks\n\n### `useGoogleMapsKey` (`src/hooks/useGoogleMapsKey.ts`)\n\nFetches the browser API key from the `public-google-maps-key` edge function. Returns `{ googleMapsKey, isLoading, error, retry }`.\n\n### `useGoogleMapsLoader` (`src/hooks/useGoogleMapsLoader.ts`)\n\n**Singleton** Google Maps JS API loader. Ensures the `<script>` tag is loaded exactly once across all components. Returns `{ isLoaded, loadError, googleMapsKey, isKeyLoading, keyError, retry }`.\n\n**Always use this hook** — never load the Maps JS API manually.\n\n### `GooglePlacesAutocomplete` (`src/components/ui/GooglePlacesAutocomplete.tsx`)\n\nAddress picker with three-tier fallback strategy:\n1. **Web component** — `PlaceAutocompleteElement` (Google''s native widget)\n2. **Edge function** — `places-autocomplete` edge function proxy (if web component fails, e.g. Places API New not enabled)\n3. **Plain text** — simple text input fallback\n\nProps: `{ value, onPlaceSelect, onClear, placeholder, disabled, className, isLoaded }`.\n\nReturns `PlaceLocationData`: `{ formatted_address, street, city, state, country, lat, lng }`.\n\n### `MapView` (`src/features/fleet-map/components/MapView.tsx`)\n\nFleet map component using `@react-google-maps/api` (`GoogleMap`, `MarkerF`, `InfoWindowF`). Renders colored markers by location source (team, equipment, scan, geocoded) and star markers for team HQ locations.\n\n### `ClickableAddress` (`src/components/ui/ClickableAddress.tsx`)\n\nRenders an address as a link that opens Google Maps.\n\n## Edge Functions\n\n### `public-google-maps-key`\n\n- **Purpose**: Serve the browser API key to authenticated users\n- **Auth**: JWT required (`verify_jwt = true`)\n- **Key**: `GOOGLE_MAPS_BROWSER_KEY`\n- **Pattern**: User-scoped client with `requireUser`\n\n### `geocode-location`\n\n- **Purpose**: Geocode addresses with caching in `geocoded_locations` table\n- **Auth**: JWT + org membership verification\n- **Key**: `GOOGLE_MAPS_SERVER_KEY`\n- **Rate limit**: 30 cache misses per org per minute\n- **Cache**: `geocoded_locations` table (upsert on `organization_id, normalized_text`)\n- **Input normalization**: lowercase, trim, collapse whitespace\n\n### `places-autocomplete`\n\n- **Purpose**: Proxy Google Places Autocomplete and Details APIs\n- **Auth**: JWT required\n- **Key**: `GOOGLE_MAPS_SERVER_KEY`\n- **Actions**: `autocomplete` (predictions) and `details` (structured address)\n- **Validation**: Zod discriminated union schema\n\n## Common Tasks\n\n### Adding a new map feature\n\n1. Use `useGoogleMapsLoader` to get `isLoaded` state\n2. Only render Google Maps components when `isLoaded === true`\n3. Handle `loadError` and `keyError` gracefully with error boundaries\n\n```tsx\nimport { useGoogleMapsLoader } from ''@/hooks/useGoogleMapsLoader'';\n\nfunction MyMapFeature() {\n  const { isLoaded, loadError, retry } = useGoogleMapsLoader();\n  \n  if (loadError) return <ErrorState onRetry={retry} />;\n  if (!isLoaded) return <Skeleton />;\n  \n  return <GoogleMap /* ... */ />;\n}\n```\n\n### Using the address picker\n\n```tsx\nimport GooglePlacesAutocomplete, { PlaceLocationData } from ''@/components/ui/GooglePlacesAutocomplete'';\nimport { useGoogleMapsLoader } from ''@/hooks/useGoogleMapsLoader'';\n\nfunction AddressField() {\n  const { isLoaded } = useGoogleMapsLoader();\n  \n  const handlePlaceSelect = (data: PlaceLocationData) => {\n    // data.formatted_address, data.street, data.city, \n    // data.state, data.country, data.lat, data.lng\n  };\n\n  return (\n    <GooglePlacesAutocomplete\n      isLoaded={isLoaded}\n      onPlaceSelect={handlePlaceSelect}\n      placeholder=\"Enter address...\"\n    />\n  );\n}\n```\n\n### Geocoding an address server-side\n\nCall the `geocode-location` edge function:\n\n```ts\nconst { data, error } = await supabase.functions.invoke(''geocode-location'', {\n  body: { organizationId: orgId, input: addressString }\n});\n// data: { lat, lng, formatted_address } or { lat: null, lng: null }\n```\n\n### Adding a new Edge Function that uses Google Maps\n\n1. Use the `edge-function-creator` skill to scaffold the function\n2. Read the server key: `Deno.env.get(\"GOOGLE_MAPS_SERVER_KEY\")`\n3. Always fall back to legacy names: `|| Deno.env.get(\"GOOGLE_MAPS_API_KEY\")`\n4. Never expose the server key in responses — only return processed data\n\n## Debugging\n\n### \"Map Configuration Error\" toast\n\nThe browser key fetch failed. Check:\n1. `GOOGLE_MAPS_BROWSER_KEY` is set in Supabase Edge Function secrets\n2. The `public-google-maps-key` function is deployed\n3. The user is authenticated (JWT required)\n\n### Places autocomplete not showing results\n\n1. Check if web component mode failed (console: `AutocompletePlaces blocked`)\n2. The component auto-falls-back to edge function mode\n3. Verify `GOOGLE_MAPS_SERVER_KEY` is set in Supabase secrets\n4. Check the `places-autocomplete` edge function logs\n\n### Geocoding returns `{ lat: null, lng: null }`\n\n1. Address may be unresolvable — check raw address string\n2. Rate limit may be exceeded (30/min/org) — check for 429 responses\n3. Verify `GOOGLE_MAPS_SERVER_KEY` is valid and has Geocoding API enabled\n\n### Fleet map markers not appearing\n\n1. Confirm `isLoaded` is true before rendering `<GoogleMap>`\n2. Check that equipment has valid `lat`/`lng` coordinates\n3. Verify the location source in `EquipmentLocation.source` field\n\n## Google Cloud Console requirements\n\nThe project requires these APIs enabled:\n\n| API | Used By |\n|-----|---------|\n| Maps JavaScript API | Fleet map, web component autocomplete |\n| Places API | Web component autocomplete |\n| Places API (Legacy) | `places-autocomplete` edge function |\n| Geocoding API | `geocode-location` edge function |\n\nBrowser key restrictions should allow the app''s domain(s). Server key should have no referrer restrictions (IP restrictions recommended).\n\n## Key files\n\n| File | Purpose |\n|------|---------|\n| `src/hooks/useGoogleMapsKey.ts` | Fetch browser API key from edge function |\n| `src/hooks/useGoogleMapsLoader.ts` | Singleton Maps JS API loader |\n| `src/components/ui/GooglePlacesAutocomplete.tsx` | Address picker component |\n| `src/components/ui/ClickableAddress.tsx` | Address → Google Maps link |\n| `src/features/fleet-map/components/MapView.tsx` | Fleet map with markers |\n| `src/features/fleet-map/pages/FleetMap.tsx` | Fleet map page |\n| `src/features/fleet-map/components/FleetMapErrorBoundary.tsx` | Map error boundary |\n| `src/utils/effectiveLocation.ts` | Location resolution + Maps URL builder |\n| `src/services/placesAutocompleteService.ts` | Edge function client for places |\n| `supabase/functions/public-google-maps-key/index.ts` | Browser key edge function |\n| `supabase/functions/geocode-location/index.ts` | Geocoding edge function |\n| `supabase/functions/places-autocomplete/index.ts` | Places proxy edge function |\n"},"lastSynced":"2026-03-08T02:10:00.449Z","agentAnalysis":{"suitability":{"en":"Perfect for Location-Based Agents needing advanced geocoding and mapping capabilities with Google Maps","zh":"适合需要高级地理编码和映射功能的基于位置的代理，使用Google Maps","ja":"Google Mapsを使用して高度な地理コード化およびマッピング機能を必要とするロケーションベースのエージェントに最適","ko":"Google Maps를 사용하여 고급 지리 코딩 및 매핑 기능이 필요한 위치 기반 에이전트에 적합","es":"Perfecto para Agentes Basados en Ubicación que necesitan capacidades de geocodificación y mapeo avanzadas con Google Maps","fr":"Idéal pour les agents basés sur l''emplacement nécessitant des fonctionnalités de géocodage et de cartographie avancées avec Google Maps","de":"Perfekt für Standort-basierte Agenten, die erweiterte Geocoding- und Kartierungs-Funktionen mit Google Maps benötigen","pt":"Perfeito para Agentes Baseados em Localização que precisam de capacidades de geocodificação e mapeamento avançadas com Google Maps","ru":"Идеально для агентов, основанных на местоположении, которым требуются передовые возможности геокодирования и картографии с Google Maps","ar":"مثالي للوكلاء القائمين على الموقع الذين يحتاجون إلى 기능 متقدمة لترميز الموقع والخريطة مع Google Maps"},"recommendation":{"en":"Empowers agents to leverage Google Maps for fleet visualization, utilizing Places Autocomplete for address picking and Geocoding for precise location data, all through secure QR code management and Supabase Edge Functions","zh":"使代理能够利用Google Maps进行车队可视化，使用Places Autocomplete进行地址选择和Geocoding进行精确位置数据，所有这些都通过安全的QR代码管理和Supabase Edge Functions","ja":"エージェントがGoogle Mapsを使用して車隊の可視化を行い、Places Autocompleteを使用して住所を選択し、Geocodingを使用して正確な位置データを取得することができ、すべてが安全なQRコード管理とSupabase Edge Functionsを通じて実現される","ko":"에이전트가 Google Maps를 사용하여車队의 시각화를 수행하고, Places Autocomplete를 사용하여 주소를 선택하며, Geocoding를 사용하여 정확한 위치 데이터를 얻을 수 있으며, 모두가 안전한 QR 코드 관리 및 Supabase Edge Functions를 통해 구현","es":"Permite a los agentes aprovechar Google Maps para la visualización de flotas, utilizando Places Autocomplete para la selección de direcciones y Geocoding para datos de ubicación precisos, todo a través de una gestión de códigos QR segura y Supabase Edge Functions","fr":"Permet aux agents d''utiliser Google Maps pour la visualisation de flottes, en utilisant Places Autocomplete pour la sélection d''adresses et Geocoding pour des données de localisation précises, le tout via une gestion de codes QR sécurisée et Supabase Edge Functions","de":"Ermöglicht es Agenten, Google Maps für die Visualisierung von Flotten zu nutzen, Places Autocomplete zur Adressauswahl und Geocoding für präzise Standortdaten zu verwenden, all dies über eine sichere QR-Code-Verwaltung und Supabase Edge Functions","pt":"Habilita os agentes a utilizar o Google Maps para visualização de frota, utilizando Places Autocomplete para escolha de endereços e Geocoding para dados de localização precisos, tudo por meio de gerenciamento de códigos QR seguros e Supabase Edge Functions","ru":"Наделяет агентов возможностью использовать Google Maps для визуализации флота, используя Places Autocomplete для выбора адресов и Geocoding для точных данных о местоположении, все это через безопасное управление QR-кодами и Supabase Edge Functions","ar":"يمنح الوكلاء القدرة على استخدام Google Maps لتصور الأسطول، باستخدام Places Autocomplete لاختيار العناوين وترميز الموقع لبيانات الموقع الدقيقة، كل ذلك من خلال إدارة رمز QR آمنة و Supabase Edge Functions"},"useCases":{"en":["Visualizing fleet equipment history on a map","Automating address picking with Places Autocomplete","Geocoding locations for precise coordinates"],"zh":["在地图上可视化车队设备历史记录","使用Places Autocomplete自动选择地址","使用Geocoding获取精确坐标"],"ja":["マップ上に車隊設備の履歴を可視化する","Places Autocompleteを使用して住所を自動で選択する","Geocodingを使用して正確な座標を取得する"],"ko":["맵에 車队 장비 기록을 시각화","Places Autocomplete를 사용하여 주소를 자동으로 선택","Geocoding를 사용하여 精确한 좌표를 얻는"],"es":["Visualizar el historial de equipo de flota en un mapa","Automatizar la selección de direcciones con Places Autocomplete","Geocodificar ubicaciones para coordenadas precisas"],"fr":["Visualiser l''historique de l''équipement de flotte sur une carte","Automatiser la sélection d''adresses avec Places Autocomplete","Géocoder des emplacements pour des coordonnées précises"],"de":["Visualisieren des Equipments-Historie einer Flotte auf einer Karte","Automatisieren der Adressauswahl mit Places Autocomplete","Geocodieren von Standorten für präzise Koordinaten"],"pt":["Visualizar o histórico de equipamentos da frota no mapa","Automatizar a escolha de endereços com Places Autocomplete","Geocodificar locais para coordenadas precisas"],"ru":["Визуализировать историю оборудования флота на карте","Автоматизировать выбор адресов с помощью Places Autocomplete","Геокодировать местоположения для точных координат"],"ar":["تصور تاريخ معدات الأسطول على الخريطة","تأتمة اختيار العناوين مع Places Autocomplete","ترميز الموقع للمواقع للحصول على إحداثيات دقيقة"]},"limitations":{"en":["Requires Google Maps API key","Dependent on Supabase Edge Functions for server-side operations","Limited to Google Maps services for geocoding and mapping"],"zh":["需要Google Maps API密钥","依赖Supabase Edge Functions进行服务器端操作","仅限于Google Maps服务进行地理编码和映射"],"ja":["Google Maps APIキーが必要","Supabase Edge Functionsに依存してサーバーサイド操作を行う","地理コード化およびマッピングにはGoogle Mapsサービスのみを使用"],"ko":["Google Maps API 키가 필요","Supabase Edge Functions에 의존하여 서버 측 작업을 수행","지리 코딩 및 매핑에는 Google Maps 서비스만 사용"],"es":["Requiere una clave de API de Google Maps","Dependiente de Supabase Edge Functions para operaciones en el servidor","Limitado a los servicios de Google Maps para geocodificación y mapeo"],"fr":["Nécessite une clé d''API Google Maps","Dépendant de Supabase Edge Functions pour les opérations serveur","Limité aux services Google Maps pour le géocodage et la cartographie"],"de":["Benötigt einen Google Maps API-Schlüssel","Abhängig von Supabase Edge Functions für Server-Operationen","Begrenzt auf Google Maps-Dienste für Geocoding und Kartierung"],"pt":["Exige uma chave de API do Google Maps","Depende de Supabase Edge Functions para operações no lado do servidor","Limitado aos serviços do Google Maps para geocodificação e mapeamento"],"ru":["Требует ключа API Google Maps","Зависит от Supabase Edge Functions для операций на стороне сервера","Ограничен услугами Google Maps для геокодирования и картографии"],"ar":["يتطلب مفتاح API من Google Maps","يعتمد على Supabase Edge Functions للعمليات على جانب الخادم","محدود بخدمات Google Maps لترميز الموقع والخريطة"]},"version":4},"contentHash":"3372c251d462d8968482786480325ed73b12d987861fd40b624f5fff468dff64","qualityScore":57}');
