INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Columbia-Cloudworks-LLC/EquipQR/google-maps', 'google-maps', 'Columbia-Cloudworks-LLC', 'EquipQR', 'community', 'google-maps Columbia-Cloudworks-LLC EquipQR community The google-maps skill enables developers to manage fleet service equipment history using secure QR codes, leveraging Google Maps for visualization, address picking, and geocoding. This skill benefits developers and fleet managers. EquipQR使用Google Maps实现Fleet Map、Places Autocomplete和Geocoding功能，提供安全的设备历史记录管理 EquipQRはGoogle Mapsを使用してFleet Map、Places Autocomplete、Geocoding機能を実現し、安全な機器履歴管理を提供 EquipQR는 Google Maps를 사용하여 Fleet Map, Places Autocomplete, Geocoding 기능을 구현하여 안전한 장비 기록 관리를 제공 La integración de Google Maps en EquipQR permite la visualización de flotas, autocompletar direcciones y geocodificar ubicaciones de manera segura L''intégration de Google Maps dans EquipQR permet la visualisation des flottes, l''autocomplétion des adresses et la géocodification des emplacements de manière sécurisée Die Integration von Google Maps in EquipQR ermöglicht die Visualisierung von Flotten, das Autocompleten von Adressen und das Geocodieren von Standorten auf sichere Weise O Google Maps é integrado ao EquipQR para fornecer visualização de mapas de frota, preenchimento automático de endereços e geocodificação Google Maps интегрирован с EquipQR для предоставления визуализации карт флотилии, автозаполнения адресов и геокодирования для ИИ Агентов تم دمج خرائط جوجل مع EquipQR لتوفير تصور خرائط الأسطول وتكملة العناوين автомاتически والتعرف على الموقع how to use google-maps in EquipQR google-maps alternative for fleet management google-maps vs Mapbox for geocoding google-maps install guide for AI agents google-maps setup guide for EquipQR what is google-maps integration in EquipQR Google Maps集成 EquipQR Fleet Map Places Autocomplete Geocoding Supabase Edge Functions React Hooks 设备历史记录管理 车队服务设备管理 AIエージェント Fleet Map visualization using Google Maps Places Autocomplete for address picking Geocoding for location-based data Frontend hooks/components for seamless integration Server-side Supabase Edge Functions for secure data processing Use of GOOGLE_MAPS_BROWSER_KEY for secure authentication google-maps is a skill that integrates Google Maps features, including Fleet Map, Places Autocomplete, and Geocoding, to enhance EquipQR functionality');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('armanisadeghi/real-singles/ux-architect', 'community', 'armanisadeghi', 'real-singles', 'armanisadeghi/real-singles', 'ux-architect', 0, 0, 57, '2026-03-08T01:57:15.484Z', '2026-03-08T02:10:00.834Z', '65aba62cf1063337a4027c4427fafdf69622909149f1ebaddc54b53c621df5ef', '{"id":"armanisadeghi/real-singles/ux-architect","name":"ux-architect","description":{"en":"The ux-architect skill analyzes existing systems, understands user flows, and creates solid plans before implementation, benefiting developers and platform experts. It determines what to build and why, handling feature planning and infrastructure plans.","zh":"ux-architect负责分析现有系统、理解用户流程并创建实施计划，利用AIエージェント技术优化用户体验","ja":"ux-architectは既存のシステムを分析し、ユーザーフローを理解し、実装計画を立てることで、AIエージェント技術を活用してユーザーエクスペリエンスを最適化します","ko":"ux-architect는 기존 시스템을 분석하고 사용자 흐름을 이해하여 구현 계획을 수립하고, AI 에이전트 기술을 활용하여 사용자 경험을 최적화합니다","es":"El UX Architect analiza sistemas existentes y crea planes sólidos antes de la implementación, determinando qué y por qué construir","fr":"L''UX Architect analyse les systèmes existants et crée des plans solides avant la mise en œuvre, déterminant ce qui et pourquoi construire","de":"Der UX Architect analysiert bestehende Systeme und erstellt solide Pläne vor der Implementierung, um zu bestimmen, was und warum gebaut wird","pt":"O UX Architect é responsável por planejar recursos e melhorar a jornada do usuário. Ele cria planos sólidos antes da implementação.","ru":"ИИ Агенты в UX Architect помогают планировать функции и улучшать пользовательский опыт. Они создают прочные планы до реализации.","ar":"معماري تجربة المستخدم يخطط الميزات ويتحسين رحلة المستخدم. يقوم بإنشاء خطط قوية قبل التنفيذ."},"seo":{"title":{"en":"ux-architect: Planning Guide for AI Agents | AI Agent Skill","zh":"ux-architect Setup Guide - AIエージェント用户体验架构师","ja":"ux-architect ベストプラクティス - AIエージェントによるユーザーエクスペリエンス設計","ko":"ux-architect 구축 가이드 - AI 에이전트를 이용한 사용자 경험 설계","es":"Guía de configuración de UX Architect: Planificación de f...","fr":"Guide de mise en place de l''UX Architect: Conception de p...","de":"Einrichtungsleitfaden für UX Architect: Planung von Benut...","pt":"Guia de Configuração de UX Architect: Planejamento de Rec...","ru":"ИИ Агенты: Руководство по Настройке UX Architect","ar":"دليل إعداد معماري تجربة المستخدم: تخطيط الميزات"},"description":{"en":"Unlock efficient feature planning with ux-architect. Learn how to analyze user flows, create solid plans, and determine what to build before implementation. ...","zh":"了解ux-architect的功能和应用，包括用户流分析、平台规划和基础设施设计，利用AIエージェント优化用户体验","ja":"ux-architectの機能と応用について学びます。ユーザーフロー分析、プラットフォーム計画、インフラ設計など、AIエージェントを活用してユーザーエクスペリエンスを最適化します","ko":"ux-architect의 기능과 적용에 대해 알아보세요. 사용자 흐름 분석, 플랫폼 계획, 인프라 설계 등 AI 에이전트를 활용하여 사용자 경험을 최적화합니다","es":"Aprende a utilizar el skill de UX Architect para planificar características y flujos de usuario antes de la implementación","fr":"Découvrez comment utiliser le skill d''UX Architect pour planifier des fonctionnalités et des parcours utilisateur avant la mise en œuvre","de":"Erfahren Sie, wie Sie das Skill von UX Architect nutzen, um Funktionen und Benutzerflüsse vor der Implementierung zu planen","pt":"Aprenda a planejar recursos com o UX Architect. Descubra como criar planos sólidos antes da implementação e melhorar a jornada do usuário.","ru":"Изучите возможности ИИ Агентов в UX Architect. Планируйте функции и улучшайте пользовательский опыт.","ar":"تعرف على كيفية تخطيط الميزات مع معماري تجربة المستخدم. قم بتحسين رحلة المستخدم وتطوير التخطيط قبل التنفيذ."},"definition":{"en":"ux-architect is a skill that analyzes existing systems, understands user flows, and creates plans for feature development and implementation across multiple platforms.","zh":"ux-architect是一种AIエージェント，负责用户体验架构设计，包括用户流分析和平台规划","ja":"ux-architectは、ユーザーエクスペリエンス設計を担当するAIエージェントであり、ユーザーフロー分析やプラットフォーム計画などを担当します","ko":"ux-architect는 사용자 경험 설계를 담당하는 AI 에이전트로, 사용자 흐름 분석 및 플랫폼 계획 등을 수행합니다","es":"Un UX Architect es un experto que analiza sistemas y crea planes para mejorar la experiencia del usuario","fr":"Un UX Architect est un expert qui analyse les systèmes et crée des plans pour améliorer l''expérience utilisateur","de":"Ein UX Architect ist ein Experte, der Systeme analysiert und Pläne erstellt, um die Benutzererfahrung zu verbessern","pt":"UX Architect é um especialista que planeja e projeta a experiência do usuário em sistemas e plataformas.","ru":"ИИ Агенты в UX Architect - это специалисты, которые планируют и проектируют пользовательский опыт в системах и платформах.","ar":"معماري تجربة المستخدم هو خبير يخطط ويسرد تجربة المستخدم في الأنظمة والمنصات."},"features":{"en":["Analyzes existing systems to identify areas for improvement","Understands user flows to create solid plans for feature development","Determines what to build and why, handling feature planning","Creates infrastructure plans that span multiple platforms, including iOS, Android, and Web","Evaluates user journeys to identify what''s missing, redundant, or needs improvement","Handles planning for new feature or feature areas"],"zh":["用户流分析","平台规划","基础设施设计","多平台支持","用户体验优化"],"ja":["ユーザーフロー分析","プラットフォーム計画","インフラ設計","複数プラットフォーム対応","ユーザーエクスペリエンス最適化"],"ko":["사용자 흐름 분석","플랫폼 계획","인프라 설계","다중 플랫폼 지원","사용자 경험 최적화"],"es":["Análisis de sistemas existentes","Creación de planes sólidos para características y flujos de usuario","Determinación de qué y por qué construir","Planificación de infraestructuras que abarcan múltiples plataformas","Identificación de aspectos mejorables en la experiencia del usuario"],"fr":["Analyse de systèmes existants","Création de plans solides pour des fonctionnalités et des parcours utilisateur","Détermination de ce qui et pourquoi construire","Planification d''infrastructures qui couvrent plusieurs plateformes","Identification d''aspects améliorables dans l''expérience utilisateur"],"de":["Analyse bestehender Systeme","Erstellung solider Pläne für Funktionen und Benutzerflüsse","Bestimmung von was und warum gebaut wird","Planung von Infrastrukturen, die mehrere Plattformen umfassen","Identifizierung von verbesserbaren Aspekten in der Benutzererfahrung"],"pt":["Análise de sistemas existentes","Criação de planos de recursos","Melhoria da jornada do usuário","Identificação de melhorias e redundâncias","Criação de infraestrutura para múltiplas plataformas"],"ru":["Анализ существующих систем","Создание планов функций","Улучшение пользовательского опыта","Определение улучшений и избыточностей","Создание инфраструктуры для нескольких платформ"],"ar":["تحليل الأنظمة الحالية","إنشاء خطط للميزات","تحسين تجربة المستخدم","تحديد التحسينات والزائدة","إنشاء البنية التحتية لمнож منصات"]},"keywords":{"en":["how to use ux-architect","what is ux-architect","ux-architect alternative","ux-architect vs competitors","ux-architect install","ux-architect setup guide","ux-architect for AI agents","ux-architect for feature planning","ux-architect for platform experts"],"zh":["ux-architect","AIエージェント","用户体验设计","用户流分析","平台规划","基础设施设计","多平台支持"],"ja":["ux-architect","AIエージェント","ユーザーエクスペリエンス設計","ユーザーフロー分析","プラットフォーム計画","インフラ設計","複数プラットフォーム対応"],"ko":["ux-architect","AI 에이전트","사용자 경험 설계","사용자 흐름 분석","플랫폼 계획","인프라 설계","다중 플랫폼 지원"],"es":["UX Architect","planificación de características","flujos de usuario","análisis de sistemas","infraestructuras de múltiples plataformas","mejora de la experiencia del usuario","herramientas de UX","AI Agents para UX"],"fr":["UX Architect","planification de fonctionnalités","parcours utilisateur","analyse de systèmes","infrastructures de plusieurs plateformes","amélioration de l''expérience utilisateur","outils de UX","Agents IA pour UX"],"de":["UX Architect","Funktionenplanung","Benutzerflüsse","Systemanalyse","Infrastrukturen für mehrere Plattformen","Verbesserung der Benutzererfahrung","UX-Tools","KI-Agents für UX"],"pt":["ux architect","planejamento de recursos","melhoria da jornada do usuário","análise de sistemas","criação de planos","infraestrutura para múltiplas plataformas","desenvolvimento de software","experiência do usuário"],"ru":["ИИ Агенты","ux architect","планирование функций","улучшение пользовательского опыта","анализ систем","создание планов","инфраструктура для нескольких платформ","разработка программного обеспечения","пользовательский опыт"],"ar":["معماري تجربة المستخدم","تخطيط الميزات","تحسين رحلة المستخدم","تحليل الأنظمة","إنشاء خطط","بنية تحتية لمнож منصات","تطوير البرمجيات","تجربة المستخدم"]}},"owner":"armanisadeghi","repo":"real-singles","repoPath":"armanisadeghi/real-singles","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.484Z","topics":[],"category":"community","skillMd":{"name":"ux-architect","description":"Analyzes user flows, determines feature requirements, and creates UI/UX infrastructure plans. Use when planning new features, evaluating user journeys, identifying feature gaps, or when the user mentions user flow, UX planning, feature analysis, UI architecture, or needs to understand what features to add, remove, or modify. Outputs actionable plans for platform experts to implement.","bodyPreview":"# UX Architect\n\n**Your job:** Analyze existing systems, understand user flows, and create solid plans BEFORE implementation. You determine WHAT to build and WHY. Platform experts (iOS, Android, Web) handle HOW.\n\n---\n\n## When to Use This Skill\n\n- Planning a new feature or feature area\n- Evaluating if a user journey makes sense\n- Identifying what''s missing, redundant, or needs improvement\n- Creating infrastructure plans that span multiple platforms\n- User says: \"plan\", \"flow\", \"what features\", \"us","body":"# UX Architect\n\n**Your job:** Analyze existing systems, understand user flows, and create solid plans BEFORE implementation. You determine WHAT to build and WHY. Platform experts (iOS, Android, Web) handle HOW.\n\n---\n\n## When to Use This Skill\n\n- Planning a new feature or feature area\n- Evaluating if a user journey makes sense\n- Identifying what''s missing, redundant, or needs improvement\n- Creating infrastructure plans that span multiple platforms\n- User says: \"plan\", \"flow\", \"what features\", \"user journey\", \"UX analysis\"\n\n---\n\n## Core Principles\n\n### 1. User-Centric Analysis\n\nEvery decision answers: **\"What does the user need to accomplish, and what''s the shortest path to get there?\"**\n\n### 2. Data-Driven Discovery\n\nDon''t guess. Analyze:\n- What APIs already exist\n- What the database supports\n- What UI is currently built\n- What the data inventory shows as gaps\n\n### 3. Platform-Agnostic Planning\n\nYour plans describe WHAT happens, not HOW each platform implements it. Implementation details are for platform-specific skills.\n\n### 4. Actionable Output\n\nPlans must be specific enough that a developer can execute without asking clarifying questions.\n\n---\n\n## Analysis Workflow\n\n### Phase 1: Understand the Goal\n\nBefore analyzing anything, clarify:\n\n```markdown\n## Goal Definition\n\n**What the user wants:** [User''s request in their words]\n**Core user problem:** [What pain point or need does this address?]\n**Success criteria:** [How will we know this works?]\n**Scope boundaries:** [What''s explicitly NOT included?]\n```\n\n### Phase 2: System Discovery\n\n**Analyze in this order:**\n\n#### 2.1 Data Inventory Check\n\nStart with `docs/data_inventory.md` — the source of truth for what exists.\n\n```markdown\n## Relevant Data Fields\n\n| Field | DB | API | Web | Mobile | Status |\n|-------|----|----|-----|--------|--------|\n| [field] | ✓/✗ | R/W | E/D | E/D | FULL/PARTIAL |\n\n**Gaps identified:**\n- [List fields that exist in DB but not UI]\n- [List fields that exist in API but not exposed]\n```\n\n#### 2.2 API Capabilities\n\nCheck `web/src/app/api/` for existing endpoints.\n\n```markdown\n## Available API Endpoints\n\n| Operation | Endpoint | Exists? | Notes |\n|-----------|----------|---------|-------|\n| [verb] [resource] | [path] | ✓/✗ | [what it does or what''s missing] |\n\n**API gaps:**\n- [Operations needed but not available]\n- [Endpoints that need enhancement]\n```\n\n#### 2.3 Current UI Audit\n\nCheck existing pages in `web/src/app/(app)/` and `mobile/app/`.\n\n```markdown\n## Current UI State\n\n### Web Pages\n| Page | Path | What it does | Issues |\n|------|------|-------------|--------|\n| [name] | [path] | [purpose] | [problems or gaps] |\n\n### Mobile Screens\n| Screen | Path | What it does | Issues |\n|--------|------|-------------|--------|\n| [name] | [path] | [purpose] | [problems or gaps] |\n```\n\n#### 2.4 Business Logic Check\n\nReview `docs/business_logic.md` for rules that affect the feature.\n\n---\n\n### Phase 3: User Flow Mapping\n\nMap the complete user journey for this feature.\n\n```markdown\n## User Flow: [Feature Name]\n\n### Entry Points\n- [How users discover/access this feature]\n\n### Primary Flow\n1. User is on [starting point]\n2. User [action] → System [response]\n3. User sees [result/screen]\n4. User [next action] → ...\n5. Success state: [what indicates completion]\n\n### Alternate Flows\n- If [condition]: [what happens]\n- If [error]: [how we handle it]\n\n### Exit Points\n- [Where users go after completing the flow]\n- [How users cancel/abandon]\n\n### Flow Diagram\n[entry] → [step 1] → [step 2] → [decision point]\n                                  ↓ yes        ↓ no\n                              [path A]     [path B]\n                                  ↓            ↓\n                              [success]    [retry/exit]\n```\n\n---\n\n### Phase 4: Gap Analysis\n\nIdentify what''s missing, redundant, or broken.\n\n```markdown\n## Gap Analysis\n\n### Features to ADD\n| Feature | Why Needed | User Benefit | Complexity |\n|---------|------------|--------------|------------|\n| [feature] | [reason] | [user value] | Low/Med/High |\n\n### Features to MODIFY\n| Current State | Problem | Proposed Change |\n|---------------|---------|-----------------|\n| [what exists] | [issue] | [improvement] |\n\n### Features to REMOVE\n| Feature | Why Remove | Migration Path |\n|---------|------------|----------------|\n| [feature] | [reason] | [how to handle existing users] |\n\n### Technical Debt\n| Issue | Impact | Priority |\n|-------|--------|----------|\n| [problem] | [effect on users/system] | P1/P2/P3 |\n```\n\n---\n\n### Phase 5: Infrastructure Requirements\n\nDefine what needs to exist for this feature to work.\n\n```markdown\n## Infrastructure Requirements\n\n### Database Changes\n| Table | Change | Migration |\n|-------|--------|-----------|\n| [table] | [add/modify column] | [migration description] |\n\n### New API Endpoints\n| Method | Path | Purpose | Request | Response |\n|--------|------|---------|---------|----------|\n| [verb] | [path] | [what it does] | [body] | [shape] |\n\n### API Modifications\n| Endpoint | Current | Needed Change |\n|----------|---------|---------------|\n| [path] | [behavior] | [new behavior] |\n\n### Shared Constants\n| Constant | Values | Used By |\n|----------|--------|---------|\n| [name] | [options] | [components] |\n\nRemember: Constants must be synced between:\n- `mobile/constants/options.ts`\n- `web/src/types/index.ts`\n```\n\n---\n\n### Phase 6: Action Plan\n\nCreate the implementation roadmap.\n\n```markdown\n## Implementation Plan\n\n### Phase A: Foundation (Backend)\n1. [ ] Database migration: [description]\n2. [ ] API endpoint: [description]\n3. [ ] Business logic: [description]\n\n### Phase B: Web Implementation\n1. [ ] Page/component: [description]\n2. [ ] Integration: [description]\n\n### Phase C: Mobile Implementation\n1. [ ] iOS screen: [description]\n2. [ ] Android screen: [description]\n\n### Phase D: Verification\n1. [ ] Feature parity check\n2. [ ] User flow testing\n3. [ ] Edge case handling\n\n### Dependencies\n- [Phase B depends on Phase A completion]\n- [Component X requires API Y]\n\n### Risks\n| Risk | Mitigation |\n|------|------------|\n| [potential issue] | [how to prevent/handle] |\n```\n\n---\n\n## Analysis Templates\n\n### Quick Feature Audit\n\nUse when evaluating a single feature:\n\n```markdown\n## Feature Audit: [Name]\n\n**Current state:** [Working/Broken/Partial/Missing]\n\n**User flow:**\n[entry] → [step 1] → [step 2] → [outcome]\n\n**Problems:**\n1. [Issue and impact]\n\n**Recommendations:**\n1. [Specific action]\n\n**Effort:** Low/Medium/High\n**Priority:** P1/P2/P3\n```\n\n### User Journey Map\n\nUse for multi-screen flows:\n\n```markdown\n## Journey: [User Goal]\n\n| Step | Screen | User Action | System Response | Pain Points |\n|------|--------|-------------|-----------------|-------------|\n| 1 | [screen] | [action] | [response] | [friction] |\n| 2 | ... | ... | ... | ... |\n\n**Opportunities:**\n- [Where we can reduce friction]\n- [Where we can add delight]\n```\n\n### Feature Comparison Matrix\n\nUse when evaluating multiple approaches:\n\n```markdown\n## Options Analysis: [Decision]\n\n| Criteria | Option A | Option B | Option C |\n|----------|----------|----------|----------|\n| User benefit | [rating] | [rating] | [rating] |\n| Implementation effort | [rating] | [rating] | [rating] |\n| Maintenance burden | [rating] | [rating] | [rating] |\n| Platform consistency | [rating] | [rating] | [rating] |\n\n**Recommendation:** Option [X] because [reasons]\n```\n\n---\n\n## Red Flags to Watch For\n\n### UX Anti-Patterns\n\n| Anti-Pattern | Why It''s Bad | Better Approach |\n|--------------|--------------|-----------------|\n| Dead ends | User stuck with no clear next action | Always show next step or exit |\n| Hidden features | Users can''t find functionality | Progressive disclosure, clear navigation |\n| Inconsistent patterns | Same action works differently | Standardize interactions |\n| Modal overload | Too many interruptions | Inline feedback, bottom sheets |\n| Long forms | User fatigue, abandonment | Break into steps, save progress |\n| Missing feedback | User unsure if action worked | Confirm every action visibly |\n\n### Technical Anti-Patterns\n\n| Anti-Pattern | Why It''s Bad | Better Approach |\n|--------------|--------------|-----------------|\n| Logic in components | Fragmented implementations | Centralize in API/services |\n| Platform-specific APIs | Inconsistent data | Single API, platform-specific UI |\n| Hardcoded options | Sync drift between platforms | Shared constants files |\n| Missing loading states | User thinks app is broken | Show skeleton/spinner |\n| Silent failures | User doesn''t know error occurred | Show error with recovery action |\n\n---\n\n## Project-Specific References\n\n### Source of Truth Files\n\n| Purpose | File |\n|---------|------|\n| All data fields | `docs/data_inventory.md` |\n| Business rules | `docs/business_logic.md` |\n| Requirements | `docs/project_requirements.md` |\n| UI patterns | `docs/ui_patterns.md` |\n\n### Implementation Locations\n\n| Layer | Path |\n|-------|------|\n| Database schema | `web/supabase/migrations/` |\n| API endpoints | `web/src/app/api/` |\n| Web pages | `web/src/app/(app)/` |\n| Web components | `web/src/components/` |\n| Mobile screens | `mobile/app/` |\n| Mobile components | `mobile/components/` |\n| Shared constants (mobile) | `mobile/constants/options.ts` |\n| Shared constants (web) | `web/src/types/index.ts` |\n\n### Key API Endpoint Groups\n\n| Domain | Base Path | Purpose |\n|--------|-----------|---------|\n| Auth | `/api/auth/` | Login, register, verification |\n| Users | `/api/users/` | Profile CRUD, gallery |\n| Discovery | `/api/discover/` | Browse profiles, top matches |\n| Matches | `/api/matches/` | Like/pass, match management |\n| Conversations | `/api/conversations/` | Chat threads |\n| Messages | `/api/messages/` | Individual messages |\n| Events | `/api/events/` | Singles events |\n| Speed Dating | `/api/speed-dating/` | Virtual speed dating |\n| Groups | `/api/groups/` | Community groups |\n| Notifications | `/api/notifications/` | Push/in-app notifications |\n| Points | `/api/points/` | Rewards system |\n\n---\n\n## Handoff to Platform Skills\n\nAfter completing your analysis, the implementation is handled by:\n\n| Skill | Handles |\n|-------|---------|\n| `nextjs-app-router-expert` | Web pages, API routes |\n| `modern-web-design-expert` | Web UI patterns, CSS |\n| `ios-native-expert` | iOS implementation |\n| `android-native-expert` | Android implementation |\n| `supabase-expert` | Database, migrations, RLS |\n| `feature-parity-check` | Post-implementation verification |\n\n**Your plan should be detailed enough that these skills can execute without ambiguity.**\n\n---\n\n## Output Checklist\n\nBefore delivering a plan, verify:\n\n- [ ] Goal is clearly defined with success criteria\n- [ ] Data inventory gaps identified\n- [ ] API capabilities mapped\n- [ ] Current UI state documented\n- [ ] User flow mapped with entry/exit points\n- [ ] Gap analysis complete (add/modify/remove)\n- [ ] Infrastructure requirements specified\n- [ ] Implementation phases defined\n- [ ] Dependencies and risks identified\n- [ ] Specific enough for developers to execute\n"},"lastSynced":"2026-03-08T02:10:00.834Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing user experience planning and feature infrastructure design capabilities.","zh":"非常适合需要用户体验规划和功能基础设施设计能力的AI代理。","ja":"ユーザー体験計画と機能インフラストラクチャ設計能力が必要なAIエージェントに最適です。","ko":"사용자 경험 계획 및 기능 인프라 설계 기능이 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para agentes de IA que necesitan planificación de experiencia de usuario y capacidades de diseño de infraestructura de características.","fr":"Parfait pour les agents IA nécessitant une planification de l''expérience utilisateur et des capacités de conception d''infrastructure de fonctionnalités.","de":"Perfekt für KI-Agents, die Benutzererfahrungsplanung und Funktionen-Infrastruktur-Design-Fähigkeiten benötigen.","pt":"Perfeito para agentes de IA que precisam de planejamento de experiência do usuário e capacidades de design de infraestrutura de recursos.","ru":"Идеально подходит для агентов ИИ, которым необходимы планирование пользовательского опыта и возможности проектирования инфраструктуры функций.","ar":"مثالي لعمليات الوكيل الذكي التي تحتاج إلى تخطيط تجربة المستخدم وقدرات تصميم بنية الميزات."},"recommendation":{"en":"Empowers agents to create solid plans before implementation, determining what to build and why, handling feature planning and infrastructure plans across multiple platforms, including iOS, Android, and Web, using user flows and journey analysis.","zh":"能够让代理创建在实现之前的坚实计划，确定要构建什么以及为什么，并处理多个平台（包括iOS、Android和Web）的功能规划和基础设施计划，使用用户流程和旅程分析。","ja":"実装前に堅実な計画を作成するエージェントを可能にし、どの機能を構築するか、またなぜ構築するかを決定し、iOS、Android、Webなどの複数のプラットフォームの機能計画とインフラストラクチャ計画を、ユーザーフローとジャーニー分析を使用して処理します。","ko":"구현 전에 견고한 계획을 생성할 수 있는 에이전트를 가능하게 하며, 구축할 기능과 구축 이유를 결정하고, iOS, Android, Web 등을 포함한 여러 플랫폼의 기능 계획 및 인프라 계획을, 사용자 흐름 및 여정 분석을 사용하여 처리합니다.","es":"Habilita a los agentes a crear planes sólidos antes de la implementación, determinando qué construir y por qué, manejo de la planificación de características y planes de infraestructura en múltiples plataformas, incluyendo iOS, Android y Web, utilizando flujos de usuario y análisis de recorrido.","fr":"Permet aux agents de créer des plans solides avant la mise en œuvre, en déterminant ce qui doit être construit et pourquoi, en gérant la planification des fonctionnalités et les plans d''infrastructure sur plusieurs plateformes, y compris iOS, Android et Web, en utilisant les flux d''utilisateurs et l''analyse de parcours.","de":"Ermächtigt Agents, solide Pläne vor der Implementierung zu erstellen, indem sie bestimmen, was gebaut werden soll und warum, unter Berücksichtigung der Funktionsplanung und Infrastrukturpläne auf mehreren Plattformen, einschließlich iOS, Android und Web, unter Verwendung von Benutzerflüssen und Reiseanalysen.","pt":"Permite que os agentes criem planos sólidos antes da implementação, determinando o que construir e por quê, lidando com o planejamento de recursos e planos de infraestrutura em várias plataformas, incluindo iOS, Android e Web, usando fluxos de usuário e análise de jornada.","ru":"Наделяет агентов возможностью создавать прочные планы до реализации, определяя, что строить и почему, обрабатывая планирование функций и инфраструктурные планы на нескольких платформах, включая iOS, Android и Web, используя потоки пользователей и анализ путешествия.","ar":"يمنح الوكلاء إمكانية إنشاء خطط متينة قبل التنفيذ، وتحديد ما يتعين بناؤه ولماذا، ومعالجة تخطيط الميزات وخطط البنية التحتية عبر منصات متعددة، بما في ذلك iOS و Android والويب، باستخدام تدفقات المستخدم وتحليل الرحلة."},"useCases":{"en":["Planning new feature areas with cross-platform infrastructure plans","Evaluating and optimizing user journeys for better user experience","Identifying redundant or missing features in existing systems"],"zh":["规划具有跨平台基础设施计划的新功能区域","评估和优化用户旅程以获得更好的用户体验","识别现有系统中的冗余或缺失功能"],"ja":["クロスプラットフォームインフラストラクチャ計画を備えた新しい機能領域の計画","ユーザージャーニーを評価および最適化してより良いユーザ体験を実現","既存のシステムでの冗長または欠落している機能を特定"],"ko":["크로스 플랫폼 인프라 계획을 갖춘 새로운 기능 영역 계획","사용자 여정을 평가 및 최적화하여 더 나은 사용자 경험을 달성","기존 시스템에서 중복 또는 누락 된 기능 식별"],"es":["Planificar nuevas áreas de características con planes de infraestructura de varias plataformas","Evaluar y optimizar los recorridos del usuario para una mejor experiencia del usuario","Identificar características redundantes o faltantes en sistemas existentes"],"fr":["Planifier de nouvelles zones de fonctionnalités avec des plans d''infrastructure multi-plateformes","Évaluer et optimiser les parcours des utilisateurs pour une meilleure expérience utilisateur","Identifier les fonctionnalités redondantes ou manquantes dans les systèmes existants"],"de":["Planen neuer Funktionsbereiche mit Infrastrukturplänen für mehrere Plattformen","Bewerten und Optimieren von Benutzerreisen für eine bessere Benutzererfahrung","Identifizieren redundanter oder fehlender Funktionen in bestehenden Systemen"],"pt":["Planejamento de novas áreas de recursos com planos de infraestrutura cross-platform","Avaliação e otimização de jornadas de usuário para melhor experiência do usuário","Identificação de recursos redundantes ou ausentes em sistemas existentes"],"ru":["Планирование новых областей функций с планами инфраструктуры для нескольких платформ","Оценка и оптимизация путешествий пользователей для лучшего пользовательского опыта","Определение избыточных или отсутствующих функций в существующих системах"],"ar":["تخطيط مناطق ميزات جديدة مع خطط بنية تحتية متعددة المنصات","تقييم وتحسين رحلات المستخدمين من أجل expérience أفضل للمستخدم","تحديد الميزات الزائدة أو الناقصة في الأنظمة الحالية"]},"limitations":{"en":["Requires understanding of user experience principles","Platform-specific knowledge for iOS, Android, and Web may be necessary"],"zh":["需要了解用户体验原则","可能需要iOS、Android和Web的平台特定知识"],"ja":["ユーザー体験の原則を理解する必要がある","iOS、Android、Webなどのプラットフォーム固有の知識が必要になる可能性がある"],"ko":["사용자 경험 원칙을 이해해야 함","iOS, Android, Web 등의 플랫폼 특정 지식이 필요할 수 있음"],"es":["Requiere comprensión de los principios de experiencia de usuario","El conocimiento específico de la plataforma para iOS, Android y Web puede ser necesario"],"fr":["Nécessite une compréhension des principes d''expérience utilisateur","Les connaissances spécifiques à la plate-forme pour iOS, Android et Web peuvent être nécessaires"],"de":["Benötigt Verständnis der Benutzererfahrungsprinzipien","Plattformspezifisches Wissen für iOS, Android und Web kann erforderlich sein"],"pt":["Exige compreensão dos princípios de experiência do usuário","Conhecimento específico de plataforma para iOS, Android e Web pode ser necessário"],"ru":["Требует понимания принципов пользовательского опыта","Платформо-специфические знания для iOS, Android и Web могут быть необходимыми"],"ar":["يتطلب فهم مبادئ تجربة المستخدم","يمكن أن يكون معرفة محددة بالمنصة لiOS و Android والويب ضروريًا"]},"version":4},"contentHash":"65aba62cf1063337a4027c4427fafdf69622909149f1ebaddc54b53c621df5ef","qualityScore":57}');
