INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('armanisadeghi/real-singles/ux-architect', 'ux-architect', 'armanisadeghi', 'real-singles', 'community', 'ux-architect armanisadeghi real-singles community The ux-architect skill analyzes existing systems, understands user flows, and creates solid plans before implementation, benefiting developers and platform experts. It determines what to build and why, handling feature planning and infrastructure plans. ux-architect负责分析现有系统、理解用户流程并创建实施计划，利用AIエージェント技术优化用户体验 ux-architectは既存のシステムを分析し、ユーザーフローを理解し、実装計画を立てることで、AIエージェント技術を活用してユーザーエクスペリエンスを最適化します ux-architect는 기존 시스템을 분석하고 사용자 흐름을 이해하여 구현 계획을 수립하고, AI 에이전트 기술을 활용하여 사용자 경험을 최적화합니다 El UX Architect analiza sistemas existentes y crea planes sólidos antes de la implementación, determinando qué y por qué construir L''UX Architect analyse les systèmes existants et crée des plans solides avant la mise en œuvre, déterminant ce qui et pourquoi construire Der UX Architect analysiert bestehende Systeme und erstellt solide Pläne vor der Implementierung, um zu bestimmen, was und warum gebaut wird O UX Architect é responsável por planejar recursos e melhorar a jornada do usuário. Ele cria planos sólidos antes da implementação. ИИ Агенты в UX Architect помогают планировать функции и улучшать пользовательский опыт. Они создают прочные планы до реализации. معماري تجربة المستخدم يخطط الميزات ويتحسين رحلة المستخدم. يقوم بإنشاء خطط قوية قبل التنفيذ. how to use ux-architect what is ux-architect ux-architect alternative ux-architect vs competitors ux-architect install ux-architect setup guide ux-architect for AI agents ux-architect for feature planning ux-architect for platform experts ux-architect AIエージェント 用户体验设计 用户流分析 平台规划 基础设施设计 多平台支持 Analyzes existing systems to identify areas for improvement Understands user flows to create solid plans for feature development Determines what to build and why, handling feature planning Creates infrastructure plans that span multiple platforms, including iOS, Android, and Web Evaluates user journeys to identify what''s missing, redundant, or needs improvement Handles planning for new feature or feature areas ux-architect is a skill that analyzes existing systems, understands user flows, and creates plans for feature development and implementation across multiple platforms.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Superlend/superloop-core-contracts/semgrep-rule-variant-creator', 'community', 'Superlend', 'superloop-core-contracts', 'Superlend/superloop-core-contracts', 'semgrep-rule-variant-creator', 0, 0, 57, '2026-03-08T01:57:15.487Z', '2026-03-08T02:10:04.884Z', '66f2ad2ca1f61469ea0021f524c35d62b507341986db98fcacffdf67399795d2', '{"id":"Superlend/superloop-core-contracts/semgrep-rule-variant-creator","name":"semgrep-rule-variant-creator","description":{"en":"The semgrep-rule-variant-creator skill ports existing Semgrep rules to new target languages, ideal for polyglot codebases and universal vulnerability patterns. It benefits developers working with multiple languages.","zh":"Semgrep 规则变体创建器可以帮助开发者将现有的 Semgrep 规则移植到新语言，实现适用性分析和测试驱动验证","ja":"Semgrep ルール変種作成ツールは、開発者が Semgrep ルールを新しい言語に移植し、適応性分析とテスト駆動の検証を実施できるようにします","ko":"Semgrep 규칙 변형 생성기는 개발자가 Semgrep 규칙을 새로운 언어로 변환하고, 적합성 분석 및 테스트 주도적 검증을 수행할 수 있도록 도와줍니다","es":"semgrep-rule-variant-creator permite portar reglas de Semgrep a nuevos lenguajes de programación con facilidad","fr":"semgrep-rule-variant-creator permet de porter les règles Semgrep vers de nouveaux langages de programmation de manière efficace","de":"semgrep-rule-variant-creator ermöglicht das einfache Portieren von Semgrep-Regeln auf neue Programmiersprachen","pt":"O semgrep-rule-variant-creator permite portar regras Semgrep existentes para novos idiomas alvo com análise de aplicabilidade e validação orientada a testes","ru":"ИИ Агент semgrep-rule-variant-creator позволяет перенести существующие правила Semgrep в новые целевые языки с помощью анализа применимости и тестирования","ar":"الوكيل الذكي semgrep-rule-variant-creator يسمح بنقل القواعد الحالية Semgrep إلى لغات جديدة مع تحليل التطبيق والتحقق الموجه بالاختبار"},"seo":{"title":{"en":"semgrep-rule-variant-creator: Porting Guide for AI Agents","zh":"Semgrep 规则变体创建器设置指南","ja":"Semgrep ルール変種作成ツールのベストプラクティス","ko":"Semgrep 규칙 변형 생성기 사용법","es":"Guía de configuración de semgrep-rule-variant-creator par...","fr":"Guide de démarrage rapide pour l''outil semgrep-rule-varia...","de":"Einrichtungsleitfaden für semgrep-rule-variant-creator al...","pt":"Guia de Configuração do semgrep-rule-variant-creator para...","ru":"Настройка ИИ Агента semgrep-rule-variant-creator для Разр...","ar":"دليل إعداد semgrep-rule-variant-creator للמطورين"},"description":{"en":"Unlock seamless rule porting with semgrep-rule-variant-creator. Learn how to port existing Semgrep rules to new languages and expand coverage across polyglot...","zh":"使用 Semgrep 规则变体创建器，轻松将现有的 Semgrep 规则移植到新语言，实现适用性分析和测试驱动验证","ja":"AIエージェントを使用して、Semgrep ルールを新しいターゲット言語に移植し、適応性分析とテスト駆動の検証を実施します","ko":"AI 도구를 사용하여 Semgrep 규칙을 새로운 언어로 변환하고, 적합성 분석 및 테스트 주도적 검증을 수행합니다","es":"Aprende a utilizar semgrep-rule-variant-creator para portar reglas de Semgrep a nuevos lenguajes de programación con análisis de aplicabilidad y validación b...","fr":"Découvrez comment utiliser semgrep-rule-variant-creator pour porter les règles Semgrep vers de nouveaux langages de programmation avec analyse d''applicabilit...","de":"Erfahren Sie, wie Sie semgrep-rule-variant-creator einsetzen, um Semgrep-Regeln auf neue Programmiersprachen mit Anwendbarkeitsanalyse und testgetriebener Va...","pt":"Aprenda a portar regras Semgrep existentes para novos idiomas alvo com análise de aplicabilidade e validação orientada a testes","ru":"Узнайте, как перенести существующие правила Semgrep в новые целевые языки с помощью анализа применимости и тестирования","ar":"تعلم كيفية نقل القواعد الحالية Semgrep إلى لغات جديدة مع تحليل التطبيق والتحقق الموجه بالاختبار"},"definition":{"en":"semgrep-rule-variant-creator is a skill that ports existing Semgrep rules to new target languages with applicability analysis and test-driven validation.","zh":"Semgrep 规则变体创建器是一种工具，用于将现有的 Semgrep 规则移植到新语言","ja":"Semgrep ルール変種作成ツールは、Semgrep ルールを新しい言語に移植するためのツールです","ko":"Semgrep 규칙 변형 생성기는 Semgrep 규칙을 새로운 언어로 변환하는 도구입니다","es":"semgrep-rule-variant-creator es una herramienta de agente de IA que permite portar reglas de Semgrep a nuevos lenguajes de programación","fr":"semgrep-rule-variant-creator est un outil d''agent IA qui permet de porter les règles Semgrep vers de nouveaux langages de programmation","de":"semgrep-rule-variant-creator ist ein KI-Tool, das das Portieren von Semgrep-Regeln auf neue Programmiersprachen ermöglicht","pt":"O semgrep-rule-variant-creator é uma ferramenta que permite criar variantes de regras Semgrep para diferentes idiomas","ru":"ИИ Агент semgrep-rule-variant-creator - это инструмент, который позволяет создавать варианты правил Semgrep для разных языков","ar":"الوكيل الذكي semgrep-rule-variant-creator هو أداة تسمح بإنشاء متغيرات لقواعد Semgrep للغات المختلفة"},"features":{"en":["Ports existing Semgrep rules to new target languages","Performs applicability analysis for rule validation","Supports test-driven validation for ensured accuracy","Expands rule coverage across polyglot codebases","Creates language-specific variants of universal vulnerability patterns","Translates rules between languages with equivalent constructs"],"zh":["支持将 Semgrep 规则移植到多种语言","实现适用性分析和测试驱动验证","可以创建语言特定的漏洞模式变体","支持在多语言代码库中扩展规则覆盖范围"],"ja":["Semgrep ルールを複数の言語に移植することが可能","適応性分析とテスト駆動の検証を実施","言語特有の脆弱性パターン変種を作成可能","マルチ言語コードベースでのルールカバレッジの拡張をサポート"],"ko":["Semgrep 규칙을 여러 언어로 변환하는 기능","적합성 분석 및 테스트 주도적 검증을 수행","언어 특有的 취약성 패턴 변형을 생성","다중 언어 코드베이스에서 규칙 적용 범위를 확장"],"es":["Portar reglas de Semgrep a nuevos lenguajes de programación","Crear variantes de reglas para lenguajes específicos","Análisis de aplicabilidad para garantizar la compatibilidad","Validación basada en pruebas para asegurar la precisión","Ampliar la cobertura de reglas en codebases políglotas","Traducir reglas entre lenguajes con constructos equivalentes"],"fr":["Porter les règles Semgrep vers de nouveaux langages de programmation","Créer des variantes de règles pour des langages spécifiques","Analyse d''applicabilité pour garantir la compatibilité","Validation basée sur des tests pour assurer la précision","Étendre la couverture des règles dans les codebases polyglottes","Traduire les règles entre les langages avec des constructeurs équivalents"],"de":["Semgrep-Regeln auf neue Programmiersprachen übertragen","Erstellen von Regelsvarianten für spezifische Sprachen","Anwendbarkeitsanalyse zur Gewährleistung der Kompatibilität","Testgetriebene Validierung zur Sicherstellung der Genauigkeit","Erweiterung der Regelabdeckung in polyglotten Codebasen","Übersetzen von Regeln zwischen Sprachen mit äquivalenten Konstrukten"],"pt":["Portar regras Semgrep existentes para novos idiomas alvo","Criação de variantes de regras para diferentes idiomas","Análise de aplicabilidade para garantir a compatibilidade","Validação orientada a testes para garantir a qualidade","Expansão da cobertura de regras em codebases poliglotas"],"ru":["Перенос существующих правил Semgrep в новые целевые языки","Создание вариантов правил для разных языков","Анализ применимости для обеспечения совместимости","Тестирование для обеспечения качества","Расширение покрытия правил в полиглотных кодбазах"],"ar":["نقل القواعد الحالية Semgrep إلى لغات جديدة","إنشاء متغيرات لقواعد للغات المختلفة","تحليل التطبيق لضمان التوافق","التحقق الموجه بالاختبار لضمان الجودة","توسيع تغطية القواعد في قواعد بيانات متعددة اللغات"]},"keywords":{"en":["how to use semgrep-rule-variant-creator","semgrep-rule-variant-creator setup guide","semgrep-rule-variant-creator alternative","semgrep-rule-variant-creator vs Semgrep","porting Semgrep rules to new languages","polyglot codebase management","universal vulnerability pattern creation","test-driven validation for Semgrep rules","applicability analysis for rule porting"],"zh":["Semgrep 规则变体创建器","AI 工具","规则移植","适用性分析","测试驱动验证","语言特定漏洞模式","多语言代码库"],"ja":["Semgrep ルール変種作成ツール","AIエージェント","ルール移植","適応性分析","テスト駆動の検証","言語特有の脆弱性パターン","マルチ言語コードベース"],"ko":["Semgrep 규칙 변형 생성기","AI 도구","규칙 변환","적합성 분석","테스트 주도적 검증","언어 특有的 취약성 패턴","다중 언어 코드베이스"],"es":["semgrep-rule-variant-creator","agentes de IA para desarrollo","herramientas de IA para programación","reglas de Semgrep","portar reglas a nuevos lenguajes","análisis de aplicabilidad","validación basada en pruebas","codebases políglotas","traducir reglas entre lenguajes"],"fr":["semgrep-rule-variant-creator","agents IA pour le développement","outils IA pour la programmation","règles Semgrep","porter les règles vers de nouveaux langages","analyse d''applicabilité","validation basée sur des tests","codebases polyglottes","traduire les règles entre les langages"],"de":["semgrep-rule-variant-creator","KI-Tools für die Entwicklung","KI-Agents für die Programmierung","Semgrep-Regeln","Regeln auf neue Programmiersprachen übertragen","Anwendbarkeitsanalyse","testgetriebene Validierung","polyglotte Codebasen","Regeln zwischen Sprachen übersetzen"],"pt":["semgrep-rule-variant-creator","regras Semgrep","portar regras","criar variantes","análise de aplicabilidade","validação orientada a testes","codebases poliglotas","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["ИИ Агент semgrep-rule-variant-creator","правила Semgrep","перенос правил","создание вариантов","анализ применимости","тестирование","полиглотные кодбазы","разработка программного обеспечения","инструменты разработки"],"ar":["الوكيل الذكي semgrep-rule-variant-creator","قواعد Semgrep","نقل قواعد","إنشاء متغيرات","تحليل التطبيق","التحقق الموجه بالاختبار","قواعد بيانات متعددة اللغات","تطوير البرمجيات","أدوات التطوير"]}},"owner":"Superlend","repo":"superloop-core-contracts","repoPath":"Superlend/superloop-core-contracts","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.487Z","topics":[],"category":"community","skillMd":{"name":"semgrep-rule-variant-creator","description":"Creates language variants of existing Semgrep rules. Use when porting a Semgrep rule to specified target languages. Takes an existing rule and target languages as input, produces independent rule+test directories for each language.","bodyPreview":"# Semgrep Rule Variant Creator\n\nPort existing Semgrep rules to new target languages with proper applicability analysis and test-driven validation.\n\n## When to Use\n\n**Ideal scenarios:**\n- Porting an existing Semgrep rule to one or more target languages\n- Creating language-specific variants of a universal vulnerability pattern\n- Expanding rule coverage across a polyglot codebase\n- Translating rules between languages with equivalent constructs\n\n## When NOT to Use\n\nDo NOT use this skill for:\n- Creat","body":"# Semgrep Rule Variant Creator\n\nPort existing Semgrep rules to new target languages with proper applicability analysis and test-driven validation.\n\n## When to Use\n\n**Ideal scenarios:**\n- Porting an existing Semgrep rule to one or more target languages\n- Creating language-specific variants of a universal vulnerability pattern\n- Expanding rule coverage across a polyglot codebase\n- Translating rules between languages with equivalent constructs\n\n## When NOT to Use\n\nDo NOT use this skill for:\n- Creating a new Semgrep rule from scratch (use `semgrep-rule-creator` instead)\n- Running existing rules against code\n- Languages where the vulnerability pattern fundamentally doesn''t apply\n- Minor syntax variations within the same language\n\n## Input Specification\n\nThis skill requires:\n1. **Existing Semgrep rule** - YAML file path or YAML rule content\n2. **Target languages** - One or more languages to port to (e.g., \"Golang and Java\")\n\n## Output Specification\n\nFor each applicable target language, produces:\n```\n<original-rule-id>-<language>/\n├── <original-rule-id>-<language>.yaml     # Ported Semgrep rule\n└── <original-rule-id>-<language>.<ext>    # Test file with annotations\n```\n\nExample output for porting `sql-injection` to Go and Java:\n```\nsql-injection-golang/\n├── sql-injection-golang.yaml\n└── sql-injection-golang.go\n\nsql-injection-java/\n├── sql-injection-java.yaml\n└── sql-injection-java.java\n```\n\n## Rationalizations to Reject\n\nWhen porting Semgrep rules, reject these common shortcuts:\n\n| Rationalization | Why It Fails | Correct Approach |\n|-----------------|--------------|------------------|\n| \"Pattern structure is identical\" | Different ASTs across languages | Always dump AST for target language |\n| \"Same vulnerability, same detection\" | Data flow differs between languages | Analyze target language idioms |\n| \"Rule doesn''t need tests since original worked\" | Language edge cases differ | Write NEW test cases for target |\n| \"Skip applicability - it obviously applies\" | Some patterns are language-specific | Complete applicability analysis first |\n| \"I''ll create all variants then test\" | Errors compound, hard to debug | Complete full cycle per language |\n| \"Library equivalent is close enough\" | Surface similarity hides differences | Verify API semantics match |\n| \"Just translate the syntax 1:1\" | Languages have different idioms | Research target language patterns |\n\n## Strictness Level\n\nThis workflow is **strict** - do not skip steps:\n- **Applicability analysis is mandatory**: Don''t assume patterns translate\n- **Each language is independent**: Complete full cycle before moving to next\n- **Test-first for each variant**: Never write a rule without test cases\n- **100% test pass required**: \"Most tests pass\" is not acceptable\n\n## Overview\n\nThis skill guides the creation of language-specific variants of existing Semgrep rules. Each target language goes through an independent 4-phase cycle:\n\n```\nFOR EACH target language:\n  Phase 1: Applicability Analysis → Verdict\n  Phase 2: Test Creation (Test-First)\n  Phase 3: Rule Creation\n  Phase 4: Validation\n  (Complete full cycle before moving to next language)\n```\n\n## Foundational Knowledge\n\n**The `semgrep-rule-creator` skill is the authoritative reference for Semgrep rule creation fundamentals.** While this skill focuses on porting existing rules to new languages, the core principles of writing quality rules remain the same.\n\nConsult `semgrep-rule-creator` for guidance on:\n- **When to use taint mode vs pattern matching** - Choosing the right approach for the vulnerability type\n- **Test-first methodology** - Why tests come before rules and how to write effective test cases\n- **Anti-patterns to avoid** - Common mistakes like overly broad or overly specific patterns\n- **Iterating until tests pass** - The validation loop and debugging techniques\n- **Rule optimization** - Removing redundant patterns after tests pass\n\nWhen porting a rule, you''re applying these same principles in a new language context. If uncertain about rule structure or approach, refer to `semgrep-rule-creator` first.\n\n## Four-Phase Workflow\n\n### Phase 1: Applicability Analysis\n\nBefore porting, determine if the pattern applies to the target language.\n\n**Analysis criteria:**\n1. Does the vulnerability class exist in the target language?\n2. Does an equivalent construct exist (function, pattern, library)?\n3. Are the semantics similar enough for meaningful detection?\n\n**Verdict options:**\n- `APPLICABLE` → Proceed with variant creation\n- `APPLICABLE_WITH_ADAPTATION` → Proceed but significant changes needed\n- `NOT_APPLICABLE` → Skip this language, document why\n\nSee [applicability-analysis.md]({baseDir}/references/applicability-analysis.md) for detailed guidance.\n\n### Phase 2: Test Creation (Test-First)\n\n**Always write tests before the rule.**\n\nCreate test file with target language idioms:\n- Minimum 2 vulnerable cases (`ruleid:`)\n- Minimum 2 safe cases (`ok:`)\n- Include language-specific edge cases\n\n```go\n// ruleid: sql-injection-golang\ndb.Query(\"SELECT * FROM users WHERE id = \" + userInput)\n\n// ok: sql-injection-golang\ndb.Query(\"SELECT * FROM users WHERE id = ?\", userInput)\n```\n\n### Phase 3: Rule Creation\n\n1. **Analyze AST**: `semgrep --dump-ast -l <lang> test-file`\n2. **Translate patterns** to target language syntax\n3. **Update metadata**: language key, message, rule ID\n4. **Adapt for idioms**: Handle language-specific constructs\n\nSee [language-syntax-guide.md]({baseDir}/references/language-syntax-guide.md) for translation guidance.\n\n### Phase 4: Validation\n\n```bash\n# Validate YAML\nsemgrep --validate --config rule.yaml\n\n# Run tests\nsemgrep --test --config rule.yaml test-file\n```\n\n**Checkpoint**: Output MUST show `All tests passed`.\n\nFor taint rule debugging:\n```bash\nsemgrep --dataflow-traces -f rule.yaml test-file\n```\n\nSee [workflow.md]({baseDir}/references/workflow.md) for detailed workflow and troubleshooting.\n\n## Quick Reference\n\n| Task | Command |\n|------|---------|\n| Run tests | `semgrep --test --config rule.yaml test-file` |\n| Validate YAML | `semgrep --validate --config rule.yaml` |\n| Dump AST | `semgrep --dump-ast -l <lang> <file>` |\n| Debug taint flow | `semgrep --dataflow-traces -f rule.yaml file` |\n\n\n## Key Differences from Rule Creation\n\n| Aspect | semgrep-rule-creator | This skill |\n|--------|---------------------|------------|\n| Input | Bug pattern description | Existing rule + target languages |\n| Output | Single rule+test | Multiple rule+test directories |\n| Workflow | Single creation cycle | Independent cycle per language |\n| Phase 1 | Problem analysis | Applicability analysis per language |\n| Library research | Always relevant | Optional (when original uses libraries) |\n\n## Documentation\n\n**REQUIRED**: Before porting rules, read relevant Semgrep documentation:\n\n- [Rule Syntax](https://semgrep.dev/docs/writing-rules/rule-syntax) - YAML structure and operators\n- [Pattern Syntax](https://semgrep.dev/docs/writing-rules/pattern-syntax) - Pattern matching and metavariables\n- [Pattern Examples](https://semgrep.dev/docs/writing-rules/pattern-examples) - Per-language pattern references\n- [Testing Rules](https://semgrep.dev/docs/writing-rules/testing-rules) - Testing annotations\n- [Trail of Bits Testing Handbook](https://appsec.guide/docs/static-analysis/semgrep/advanced/) - Advanced patterns\n\n## Next Steps\n\n- For applicability analysis guidance, see [applicability-analysis.md]({baseDir}/references/applicability-analysis.md)\n- For language translation guidance, see [language-syntax-guide.md]({baseDir}/references/language-syntax-guide.md)\n- For detailed workflow and examples, see [workflow.md]({baseDir}/references/workflow.md)\n"},"lastSynced":"2026-03-08T02:10:04.884Z","agentAnalysis":{"suitability":{"en":"Perfect for Code Security Agents needing to port Semgrep rules across multiple programming languages.","zh":"非常适合需要将 Semgrep 规则移植到多种编程语言的代码安全代理。","ja":"Code Security Agents が Semgrep ルールを複数のプログラミング言語に移植する必要がある場合に最適です。","ko":"코드 보안 에이전트가 Semgrep 규칙을 여러 프로그래밍 언어로 이식해야 하는 경우에 적합합니다.","es":"Perfecto para Agentes de Seguridad de Código que necesitan portar reglas de Semgrep a través de múltiples lenguajes de programación.","fr":"Parfait pour les agents de sécurité de code qui ont besoin de porter des règles Semgrep à travers plusieurs langages de programmation.","de":"Perfekt für Code-Sicherheitsagenten, die Semgrep-Regeln über mehrere Programmiersprachen portieren müssen.","pt":"Perfeito para Agentes de Segurança de Código que precisam portar regras Semgrep em várias linguagens de programação.","ru":"Идеально подходит для агентов безопасности кода, которым необходимо переносить правила Semgrep на несколько языков программирования.","ar":"مثالي لعمليات وكيلات أمن الكود التي تحتاج إلى نقل قواعد Semgrep عبر عدة لغات برمجة."},"recommendation":{"en":"Empowers agents to port existing Semgrep rules to new target languages with proper applicability analysis and test-driven validation, leveraging universal vulnerability patterns and supporting polyglot codebases through languages with equivalent constructs.","zh":"赋予代理在新的目标语言中移植现有的 Semgrep 规则的能力，具有适用性分析和测试驱动验证，利用通用漏洞模式，并支持通过具有等效构造的语言来支持多语言代码库。","ja":"エージェントが新しい対象言語に既存の Semgrep ルールを移植する能力を提供し、適応可能性分析とテスト駆動検証を実行し、汎用的な脆弱性パターンを利用し、同等の構造を持つ言語を介してマルチ言語コードベースをサポートします。","ko":"에이전트가 새로운 대상 언어로 기존 Semgrep 규칙을 이식할 수 있는 기능을 제공하며, 적합성 분석 및 테스트 주도 유효성 검사를 제공하고, 범용 취약성 패턴을 활용하며, 동등한 구성을 가진 언어를 통해 다중 언어 코드베이스를 지원합니다.","es":"Habilita a los agentes a portar reglas de Semgrep existentes a nuevos lenguajes de destino con un análisis de aplicabilidad adecuado y validación basada en pruebas, aprovechando patrones de vulnerabilidad universales y admitiendo codebases políglotas a través de lenguajes con constructos equivalentes.","fr":"Permet aux agents de porter des règles Semgrep existantes vers de nouveaux langages cibles avec une analyse d''applicabilité appropriée et une validation basée sur des tests, en exploitant des modèles de vulnérabilité universels et en prenant en charge des bases de code polyglottes à travers des langages avec des constructeurs équivalents.","de":"Ermächtigt Agenten, bestehende Semgrep-Regeln auf neue Ziel-Sprachen mit angemessener Anwendbarkeitsanalyse und testgetriebener Validierung zu portieren, indem sie universelle Schwachstellenmuster nutzen und polyglotte Codebases durch Sprachen mit äquivalenten Konstrukten unterstützen.","pt":"Habilita os agentes a portar regras Semgrep existentes para novos idiomas alvo com análise de aplicabilidade adequada e validação orientada a testes, aproveitando padrões de vulnerabilidade universais e suportando repositórios de código poliglotas por meio de linguagens com construtos equivalentes.","ru":"Наделяет агентов возможностью переносить существующие правила Semgrep на новые целевые языки с помощью надлежащего анализа применимости и тестирования, используя универсальные закономерности уязвимостей и поддерживая полиглотные кодовые базы посредством языков с эквивалентными конструкциями.","ar":"تمكّن الوكلاء من نقل قواعد Semgrep الحالية إلى لغات الهدف الجديدة مع تحليل الملاءمة المناسب والتحقق الموجه بالاختبار، واستخدام أنماط الضعف الشاملة ودعم مخازن الشفرة متعددة اللغات من خلال اللغات ذات البنيات المكافئة."},"useCases":{"en":["Porting existing Semgrep rules to new target languages","Creating language-specific variants of universal vulnerability patterns","Expanding rule coverage across polyglot codebases","Translating rules between languages with equivalent constructs"],"zh":["将现有的 Semgrep 规则移植到新的目标语言","创建通用漏洞模式的语言特定变体","扩展规则覆盖范围到多语言代码库","在具有等效构造的语言之间翻译规则"],"ja":["既存の Semgrep ルールを新しい対象言語に移植する","汎用的な脆弱性パターンの言語特定バリアントを作成する","マルチ言語コードベース全体でルールのカバレッジを拡大する","同等の構造を持つ言語間でルールを翻訳する"],"ko":["기존 Semgrep 규칙을 새로운 대상 언어로 이식하는 것","범용 취약성 패턴의 언어별 변형을 생성하는 것","다중 언어 코드베이스에서 규칙 범위를 확장하는 것","동등한 구성 요소를 가진 언어 간에 규칙을 번역하는 것"],"es":["Portar reglas de Semgrep existentes a nuevos lenguajes de destino","Crear variantes específicas de lenguaje de patrones de vulnerabilidad universales","Ampliar la cobertura de reglas en codebases políglotas","Traducir reglas entre lenguajes con constructos equivalentes"],"fr":["Porter des règles Semgrep existantes vers de nouveaux langages cibles","Créer des variantes spécifiques de langage de modèles de vulnérabilité universels","Étendre la couverture des règles dans des bases de code polyglottes","Traduire des règles entre langages avec des constructeurs équivalents"],"de":["Bestehende Semgrep-Regeln auf neue Ziel-Sprachen portieren","Sprachspezifische Varianten von universellen Schwachstellenmustern erstellen","Regelabdeckung in polyglotten Codebases erweitern","Regeln zwischen Sprachen mit äquivalenten Konstrukten übersetzen"],"pt":["Portar regras Semgrep existentes para novos idiomas alvo","Criar variantes linguísticas específicas de padrões de vulnerabilidade universais","Ampliar a cobertura de regras em repositórios de código poliglotas","Traduzir regras entre linguagens com construtos equivalentes"],"ru":["Перенос существующих правил Semgrep на новые целевые языки","Создание языково-специфических вариантов универсальных закономерностей уязвимостей","Расширение охвата правил в полиглотных кодовых базах","Перевод правил между языками с эквивалентными конструкциями"],"ar":["نقل قواعد Semgrep الحالية إلى لغات الهدف الجديدة","إنشاء متغيرات لغة محددة لأنماط الضعف الشاملة","توسيع تغطية القواعد في مخازن الشفرة متعددة اللغات","ترجمة القواعد بين اللغات ذات البنيات المكافئة"]},"limitations":{"en":["Not suitable for creating new Semgrep rules from scratch","Requires existing Semgrep rules to port or translate"],"zh":["不适合从头开始创建新的 Semgrep 规则","需要现有的 Semgrep 规则来移植或翻译"],"ja":["新しい Semgrep ルールをスクラッチから作成するのに適していない","移植または翻訳するために既存の Semgrep ルールが必要"],"ko":["새로운 Semgrep 규칙을 처음부터 만들기에는 적합하지 않음","이식 또는 번역하기 위해 기존 Semgrep 규칙이 필요"],"es":["No es adecuado para crear nuevas reglas de Semgrep desde cero","Requiere reglas de Semgrep existentes para portar o traducir"],"fr":["N''est pas adapté pour créer de nouvelles règles Semgrep à partir de zéro","Nécessite des règles Semgrep existantes pour les porter ou les traduire"],"de":["Nicht geeignet, um neue Semgrep-Regeln von Grund auf zu erstellen","Benötigt bestehende Semgrep-Regeln, um sie zu portieren oder zu übersetzen"],"pt":["Não é adequado para criar novas regras Semgrep do zero","Requer regras Semgrep existentes para portar ou traduzir"],"ru":["Не подходит для создания новых правил Semgrep с нуля","Требует существующих правил Semgrep для переноса или перевода"],"ar":["لا يصلح لإنشاء قواعد Semgrep جديدة من الصفر","يتطلب قواعد Semgrep الحالية لنقلها أو ترجمتها"]},"version":4},"contentHash":"66f2ad2ca1f61469ea0021f524c35d62b507341986db98fcacffdf67399795d2","qualityScore":57}');
