INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Superlend/superloop-core-contracts/semgrep-rule-variant-creator', 'semgrep-rule-variant-creator', 'Superlend', 'superloop-core-contracts', 'community', 'semgrep-rule-variant-creator Superlend superloop-core-contracts community The semgrep-rule-variant-creator skill ports existing Semgrep rules to new target languages, ideal for polyglot codebases and universal vulnerability patterns. It benefits developers working with multiple languages. Semgrep 规则变体创建器可以帮助开发者将现有的 Semgrep 规则移植到新语言，实现适用性分析和测试驱动验证 Semgrep ルール変種作成ツールは、開発者が Semgrep ルールを新しい言語に移植し、適応性分析とテスト駆動の検証を実施できるようにします Semgrep 규칙 변형 생성기는 개발자가 Semgrep 규칙을 새로운 언어로 변환하고, 적합성 분석 및 테스트 주도적 검증을 수행할 수 있도록 도와줍니다 semgrep-rule-variant-creator permite portar reglas de Semgrep a nuevos lenguajes de programación con facilidad semgrep-rule-variant-creator permet de porter les règles Semgrep vers de nouveaux langages de programmation de manière efficace semgrep-rule-variant-creator ermöglicht das einfache Portieren von Semgrep-Regeln auf neue Programmiersprachen O semgrep-rule-variant-creator permite portar regras Semgrep existentes para novos idiomas alvo com análise de aplicabilidade e validação orientada a testes ИИ Агент semgrep-rule-variant-creator позволяет перенести существующие правила Semgrep в новые целевые языки с помощью анализа применимости и тестирования الوكيل الذكي semgrep-rule-variant-creator يسمح بنقل القواعد الحالية Semgrep إلى لغات جديدة مع تحليل التطبيق والتحقق الموجه بالاختبار how to use semgrep-rule-variant-creator semgrep-rule-variant-creator setup guide semgrep-rule-variant-creator alternative semgrep-rule-variant-creator vs Semgrep porting Semgrep rules to new languages polyglot codebase management universal vulnerability pattern creation test-driven validation for Semgrep rules applicability analysis for rule porting Semgrep 规则变体创建器 AI 工具 规则移植 适用性分析 测试驱动验证 语言特定漏洞模式 多语言代码库 Ports existing Semgrep rules to new target languages Performs applicability analysis for rule validation Supports test-driven validation for ensured accuracy Expands rule coverage across polyglot codebases Creates language-specific variants of universal vulnerability patterns Translates rules between languages with equivalent constructs semgrep-rule-variant-creator is a skill that ports existing Semgrep rules to new target languages with applicability analysis and test-driven validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('madebyaris/spec-kit-command-cursor/sdd-evolve', 'community', 'madebyaris', 'spec-kit-command-cursor', 'madebyaris/spec-kit-command-cursor', 'sdd-evolve', 0, 0, 57, '2026-03-08T01:57:15.492Z', '2026-03-08T02:10:08.441Z', 'cadfe57301e1a0ebf63878dcf03d26e79fbae1a7571e0b62154c218c5e0c7d92', '{"id":"madebyaris/spec-kit-command-cursor/sdd-evolve","name":"sdd-evolve","description":{"en":"The sdd-evolve skill helps developers keep specifications in sync with implementation discoveries, turning ideas into actionable tasks for Cursor IDE. It benefits developers by providing a structured approach to handling new requirements and technical constraints.","zh":"SDD Evolve 是一个用于Cursor IDE的SDD工具包，通过/specify、/plan、/tasks将想法转化为规范、计划和可执行任务","ja":"SDD Evolveは、Cursor IDE用のSDDツールキットです。/specify、/plan、/tasksを使用して、アイデアを仕様、計画、実行可能なタスクに変換します","ko":"SDD Evolve는 Cursor IDE용 SDD 툴킷으로 /specify, /plan, /tasks를 통해 아이디어를 사양, 계획 및 실행 가능한 작업으로 전환합니다","es":"sdd-evolve es una herramienta para mantener las especificaciones en sincronía con los descubrimientos durante la implementación","fr":"sdd-evolve est un outil pour garder les spécifications à jour avec les découvertes de l''implémentation","de":"sdd-evolve ist ein Tool, um Spezifikationen mit Implementierungserkenntnissen in Einklang zu halten","pt":"O SDD Evolve é uma ferramenta de desenvolvimento de software que ajuda a manter especificações em sincronia com descobertas de implementação","ru":"SDD Evolve - это инструмент разработки программного обеспечения, который помогает поддерживать спецификации в синхронизации с открытиями реализации","ar":"SDD Evolve هو أداة تطوير البرمجيات التي تساعد على الاحتفاظ بمواصفات متزامنة مع اكتشافات التنفيذ"},"seo":{"title":{"en":"sdd-evolve: Setup Guide for AI Agents | SDD Toolkit","zh":"SDD Evolve Setup Guide - Cursor IDE.ai工具","ja":"SDD Evolve ベストプラクティ