INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('madebyaris/spec-kit-command-cursor/sdd-evolve', 'sdd-evolve', 'madebyaris', 'spec-kit-command-cursor', 'community', 'sdd-evolve madebyaris spec-kit-command-cursor community The sdd-evolve skill helps developers keep specifications in sync with implementation discoveries, turning ideas into actionable tasks for Cursor IDE. It benefits developers by providing a structured approach to handling new requirements and technical constraints. SDD Evolve 是一个用于Cursor IDE的SDD工具包，通过/specify、/plan、/tasks将想法转化为规范、计划和可执行任务 SDD Evolveは、Cursor IDE用のSDDツールキットです。/specify、/plan、/tasksを使用して、アイデアを仕様、計画、実行可能なタスクに変換します SDD Evolve는 Cursor IDE용 SDD 툴킷으로 /specify, /plan, /tasks를 통해 아이디어를 사양, 계획 및 실행 가능한 작업으로 전환합니다 sdd-evolve es una herramienta para mantener las especificaciones en sincronía con los descubrimientos durante la implementación sdd-evolve est un outil pour garder les spécifications à jour avec les découvertes de l''implémentation sdd-evolve ist ein Tool, um Spezifikationen mit Implementierungserkenntnissen in Einklang zu halten O SDD Evolve é uma ferramenta de desenvolvimento de software que ajuda a manter especificações em sincronia com descobertas de implementação SDD Evolve - это инструмент разработки программного обеспечения, который помогает поддерживать спецификации в синхронизации с открытиями реализации SDD Evolve هو أداة تطوير البرمجيات التي تساعد على الاحتفاظ بمواصفات متزامنة مع اكتشافات التنفيذ how to use sdd-evolve sdd-evolve setup guide sdd-evolve alternative sdd-evolve vs cursor ide what is sdd-evolve sdd-evolve install sdd-evolve tutorial sdd-evolve for ai agents sdd-evolve and cursor ide integration SDD Evolve Cursor IDE AI工具 SDD工具包 开发效率 规范计划 可执行任务 Discovery Refinement Addition Modifica Categorizes discoveries into refinement, addition, or modification of existing requirements Supports the /specify, /plan, and /tasks commands for turning ideas into actionable tasks Enables developers to keep specifications in sync with implementation discoveries Handles edge cases not included in the original specification Refines requirements based on technical constraints discovered during development Integrates with Cursor IDE for streamlined development workflows sdd-evolve is a SDD toolkit for Cursor IDE that enables developers to specify, plan, and create tasks from ideas, ensuring that specifications align with implementation discoveries.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rorpage/weather-api/compare-weather', 'community', 'rorpage', 'weather-api', 'rorpage/weather-api', 'compare-weather', 0, 0, 57, '2026-03-08T01:57:15.500Z', '2026-03-08T02:10:18.221Z', '2b1575f188dd88f239c90a5542ff3208c8e05d5f733ae6d49b11911bf3ea4f3c', '{"id":"rorpage/weather-api/compare-weather","name":"compare-weather","description":{"en":"The compare-weather skill is a Vercel API that queries multiple weather sources, generated using GitHub Copilot, benefiting developers who need to compare weather across different airports.","zh":"compare-weather 是一个 Vercel API，用于查询多个天气源，支持多个机场的天气比较","ja":"compare-weather は、複数の天気情報源を照会する Vercel API で、複数の空港の天気を比較することができます","ko":"compare-weather는 다중 날씨 소스를 조회하는 Vercel API로서 다중 공항의 날씨를 비교할 수 있습니다","es":"La API de comparación de clima de Vercel consulta múltiples fuentes de clima y permite comparar el clima en diferentes aeropuertos","fr":"L''API de comparaison météo de Vercel interroge plusieurs sources de météo et permet de comparer la météo dans différents aéroports","de":"Die Wettervergleichs-API von Vercel Abfragen mehrere Wetterquellen und ermöglicht den Vergleich des Wetters an verschiedenen Flughäfen","pt":"O compare-weather é uma API Vercel que consulta múltiplas fontes de clima para comparar condições climáticas em diferentes aeroportos, utilizando GitHub Copilot para geração de código.","ru":"Compare-weather — это API Vercel, запрашивающая несколько источников погоды для сравнения погодных условий в различных аэропортах, с использованием GitHub Copilot для генерации кода и ИИ Агентов","ar":"compare-weather هي واجهة برمجة تطبيقات Vercel التي تستفسر عدة مصادر جوية لمقارنة الأحوال الجوية في المطارات المختلفة، باستخدام GitHub Copilot لإنشاء الكود وأدوات الذكاء الاصطناعي"},"seo":{"title":{"en":"compare-weather: API Setup Guide for AI Agents","zh":"compare-weather 设置指